/* Текст «Фауста» с отсылками. Подключается как скрипт, чтобы работать и при открытии с диска. */
window.DOCS = window.DOCS || {};
window.DOCS['faust'] = "\u003c!DOCTYPE html\u003e\n\u003chtml lang=\"ru\"\u003e\u003chead\u003e\u003cmeta charset=\"utf-8\"\u003e\u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\"\u003e\n\u003ctitle\u003eФауст — с отсылками\u003c/title\u003e\n\u003cstyle\u003e\n:root{--bg:#fbf8f2;--fg:#222;--muted:#777;--acc:#7a3b12;--btn:#e9dccb;--btnh:#7a3b12}\nbody{margin:0;background:var(--bg);color:var(--fg);font:18px/1.55 Georgia,\"Times New Roman\",serif}\nmain{max-width:760px;margin:0 auto;padding:40px 24px 120px}\nh1{font-size:34px;text-align:center;margin:10px 0 4px}\n.sub{text-align:center;color:var(--muted);margin-bottom:40px}\nh2{font-size:24px;text-align:center;margin:48px 0 18px;color:var(--acc)}\nh2.part{font-size:28px;letter-spacing:.04em;text-transform:uppercase;margin-top:70px}\n.l{white-space:pre-wrap;min-height:1em}\n.gap{height:.8em}\na.ref{position:relative;display:inline-block;min-width:1.5em;padding:0 .35em;margin:0 .15em;border-radius:9px;background:var(--btn);color:var(--acc);font:600 12px/1.6 system-ui,sans-serif;text-align:center;text-decoration:none;vertical-align:super;cursor:pointer;transition:background .15s,color .15s;scroll-margin:40vh 0}\na.ref.blk{vertical-align:middle;margin:0 .5em 0 0;border:1px dashed var(--acc)}\na.ref:hover,a.ref:focus{background:var(--btnh);color:#fff;outline:none}\na.ref::after{content:attr(data-tip);position:absolute;left:50%;bottom:calc(100% + 6px);transform:translateX(-50%);width:max-content;max-width:320px;padding:4px 8px;border-radius:6px;background:#2b2b2b;color:#fff;font:500 12px/1.35 system-ui,sans-serif;white-space:normal;text-align:left;pointer-events:none;opacity:0;visibility:hidden;transition:opacity .12s;z-index:10}\na.ref:hover::after,a.ref:focus::after{opacity:1;visibility:visible}\n.flash{animation:flash 1.8s ease-out}\n@keyframes flash{0%,30%{box-shadow:0 0 0 4px #f2b84b;background:#f2b84b;color:#000}100%{box-shadow:0 0 0 0 transparent}}\n#notes{margin-top:100px;border-top:3px double var(--acc);padding-top:20px}\n#notes h3{font-size:19px;color:var(--acc);margin:40px 0 10px}\n.note{background:#fff;border:1px solid #e5dccd;border-radius:10px;padding:14px 18px;margin:14px 0;font-size:16px;scroll-margin-top:20px}\n.note .hd{display:flex;gap:10px;align-items:baseline;color:var(--muted);font:13px system-ui,sans-serif}\n.note .num{background:var(--acc);color:#fff;border-radius:9px;padding:1px 8px;font-weight:700}\n.note .q{font-style:italic;margin:6px 0 8px;font-size:17px}\n.note p{margin:6px 0}\n.note .src{font-weight:600;color:#333}\n.note .nodes{margin-top:8px;font:12px system-ui,sans-serif;color:var(--muted)}\n.note .chip{display:inline-block;margin:2px 4px 0 0;padding:1px 8px;border-radius:10px;background:#f1e8da;color:#5a4a37}\n.note .chip.end{background:#2ea043;color:#fff}\na.back{display:inline-block;margin-top:8px;padding:3px 12px;border-radius:14px;background:var(--btn);color:var(--acc);font:600 13px system-ui,sans-serif;text-decoration:none}\na.back:hover{background:var(--btnh);color:#fff}\n\u003c/style\u003e\u003c/head\u003e\u003cbody\u003e\u003cmain\u003e\u003ch1\u003eИоганн Гете. Фауст\u003c/h1\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"sub\"\u003eПеревод: Б. Пастернак\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eПосвящение\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы снова здесь, изменчивые тени,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня тревожившие с давних пор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайдется ль наконец вам воплощенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли остыл мой молодой задор?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вы, как дым, надвинулись, виденья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТуманом мне застлавши кругозор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛовлю дыханье ваше грудью всею\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ возле вас душою молодею.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы воскресили прошлого картины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБылые дни, былые вечера.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдали всплывает сказкою старинной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбви и дружбы первая пора.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПронизанный до самой сердцевины\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТоской тех лет и жаждою добра,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ всех, кто жил в тот полдень лучезарный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпять припоминаю благодарно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм, не услышать следующих песен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКому я предыдущие читал.\u003ca class=\"ref\" id=\"r1\" href=\"#n1\" data-tip=\"№1 \u0026#183; Поэзия и правда (Гёте)\"\u003e1\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаспался круг, который был так тесен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШум первых одобрений отзвучал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНепосвященных голос легковесен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, признаюсь, мне страшно их похвал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА прежние ценители и судьи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРассеялись, кто где, среди безлюдья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я прикован силой небывалой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК тем образам, нахлынувшим извне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭоловою арфой прорыдало\u003ca class=\"ref\" id=\"r2\" href=\"#n2\" data-tip=\"№2 \u0026#183; Одиссея (Гомер); Эолова арфа (Кольридж) и др.\"\u003e2\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНачало строф, родившихся вчерне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в трепете, томленье миновало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ слезы лью, и тает лед во мне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНасущное отходит вдаль, а давность,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриблизившись, приобретает явность.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eТеатральное вступление\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДиректор театра, поэт и комический актер.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДиректор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы оба, средь несчастий всех\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня дарившие удачей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь, с труппою моей бродячей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой мне прочите успех?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой зритель в большинстве неименитый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ нам опора в жизни — большинство.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтолбы помоста врыты, доски сбиты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ каждый ждет от нас невесть чего.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе подымают брови в ожиданье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаранее готовя дань признанья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ всех их знаю и зажечь берусь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо в первый раз объят такой тревогой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя у них не избалован вкус,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни прочли неисчислимо много.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб сразу показать липом товар,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНовинку надо ввесть в репертуар.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто может быть приятней многолюдства,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда к театру ломится народ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, в ревности дойдя до безрассудства,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак двери райские, штурмует вход?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет четырех, а ловкие проныры,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛоктями в давке пробивая путь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак к пекарю за хлебом, прут к кассиру\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ рады шею за билет свернуть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВолшебник и виновник их наплыва,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэт, сверши сегодня это диво.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэт\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе говори мне о толпе, повинной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ том, что пред ней нас оторопь берет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна засасывает, как трясина,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗакручивает, как водоворот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, уведи меня на те вершины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда сосредоточенность зовет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТуда, где божьей созданы рукою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбитель грез, святилище покоя.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто те места твоей душе навеют,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПускай не рвется сразу на уста.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМечту тщеславье светское рассеет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПятой своей растопчет суета.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть мысль твоя, когда она созреет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредстанет нам законченно чиста.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаружный блеск рассчитан на мгновенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА правда переходит в поколенья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКомический актер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольно про потомство мне долбили.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б потомству я дарил усилья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто потешал бы нашу молодежь?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ согласье с веком быть не так уж мелко.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВосторги поколенья — не безделка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа улице их не найдешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот, кто к капризам публики не глух,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтносится к ней без предубежденья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем шире наших слушателей круг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем заразительнее впечатленье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС талантом человеку не пропасть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоедините только в каждой роли\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоображенье, чувство, ум и страсть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ юмора достаточную долю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДиректор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА главное, гоните действий ход\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивей, за эпизодом эпизод.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодробностей побольше в их развитье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб завладеть вниманием зевак,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вы их победили, вы царите,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы самый нужный человек, вы маг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы хороший сбор доставить пьесе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй требуется сборный и состав.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ всякий, выбрав что-нибудь из смеси,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУйдет домой, спасибо вам сказав.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗасуйте всякой всячины в кормежку:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНемножко жизни, выдумки немножко,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам удается этот вид рагу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолпа и так все превратит в окрошку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ дать совет вам лучший не могу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэт\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКропанье пошлостей — большое зло.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы этого совсем не сознаете.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБездарных проходимцев ремесло,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак вижу я, у вас в большом почете.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДиректор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня упрек ваш, к счастью, миновал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ расчете на столярный матерьял\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы подходящий инструмент берете.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗадумались ли вы в своей работе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКому предназначается ваш труд?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдни со скуки на спектакль идут,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругие, пообедав до отвала,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА третьи, ощущая сильный зуд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлеснуть сужденьем, взятым из журнала.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак шляются толпой по маскарадам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз любопытства, на один момент,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК нам ходят дамы щегольнуть нарядом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез платы за ангажемент.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСобою упоенный небожитель,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпуститесь вниз на землю с облаков!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоближе присмотритесь: кто ваш зритель?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн равнодушен, груб и бестолков.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн из театра бросится к рулетке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли в объятья ветреной кокетки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА если так, я не шутя дивлюсь:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК чему без пользы мучить бедных муз?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалите в кучу, поверху скользя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто подвернется, для разнообразья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзбытком мысли поразить нельзя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак удивите недостатком связи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо что случилось с вами? Вы в экстазе?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэт\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтупай, другого поищи раба!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо над поэтом власть твоя слаба,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб он свои священные права\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз-за тебя смешал преступно с грязью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем сердце трогают его слова?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагодаря ли только громкой фразе?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСозвучный миру строй души его —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот этой тайной власти существо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда природа крутит жизни пряжу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вертится времен веретено,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй все равно, идет ли нитка глаже,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли с задоринками волокно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто придает, выравнивая прялку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда разгон и плавность колесу?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто вносит в шум разрозненности жалкой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАккорда благозвучье и красу?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто с бурею сближает чувств смятенье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто грусть роднит с закатом у реки?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧьей волею цветущее растенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа любящих роняет лепестки?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто подвиги венчает? Кто защита\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогам под сенью олимпийских рощ?\u003ca class=\"ref\" id=\"r3\" href=\"#n3\" data-tip=\"№3 \u0026#183; Илиада (Гомер); Теогония (Гесиод)\"\u003e3\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто это?\u0026#160;— Человеческая мощь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ поэте выступившая открыто.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКомический актер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоспользуйтесь же ей по назначенью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаймитесь вашим делом вдохновенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак, как ведут любовные дела.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак их ведут? Случайно, спрохвала.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДружат, вздыхают, дуются,\u0026#160;— минута,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругая, и готовы путы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазмолвка, объясненье,\u0026#160;— повод дан,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам отступленья нет, у вас роман.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредставьте нам такую точно драму.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз гущи жизни загребайте прямо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе каждый сознает, чем он живет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто это схватит, тот нас увлечет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ заквашенную небылицу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодбросьте истины крупицу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ будет дешев и сердит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапиток ваш и всех прельстит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда-то цвет отборной молодежи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридет смотреть на ваше откровенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ будет черпать с благодарной, дрожью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто подойдет ему под настроенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе сможет глаз ничей остаться сух.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе будут слушать, затаивши дух.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ плакать и смеяться, не замедлив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСумеет тот, кто юн и желторот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто вырос — тот угрюм и привередлив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКому еще расти,\u0026#160;— тот все поймет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэт\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда верни мне возраст дивный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда все было впереди\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вереницей беспрерывной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеснились песни из груди.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тумане мир лежал впервые,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, чуду радуясь во всем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСрывал цветы я полевые,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПовсюду, росшие кругом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда я нищ был и богат,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖив правдой и неправде рад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВерни мне дух неукрощенный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДни муки и блаженства дни,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖар ненависти, пыл влюбленный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДни юности моей верни!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКомический актер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, друг мой, молодость тебе нужна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда ты падаешь в бою, слабея;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда спасти не может седина\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вешаются девочки на шею;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда на состязанье беговом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы должен первым добежать до цели;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда на шумном пире молодом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы ночь проводишь в танцах и веселье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо руку в струны лиры запустить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС которой неразлучен ты все время,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не утратить изложенья нить\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тобой самим свободно взятой теме,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак раз тут в пользу зрелые лета,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА изреченье, будто старец хилый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК концу впадает в детство,\u0026#160;— клевета,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо все мы дети до самой могилы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДиректор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольно болтовни салонной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе нам любезности плести.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем зря отвешивать поклоны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМогли б мы к путному прийти.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто ждет в бездействии наитий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрождет их до скончанья дней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ поэзии греметь хотите?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо-свойски расправляйтесь с ней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вам сказал, что нам во благо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы и варите вашу брагу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез разговоров за котел!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДень проморгали, день прошел, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУпущенного не вернете.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛовите на ходу, в работе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУдобный случай за хохол.\u003ca class=\"ref\" id=\"r4\" href=\"#n4\" data-tip=\"№4 \u0026#183; Палатинская антология (Посидипп); Басни (Федр)\"\u003e4\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотрите, на немецкой сцене\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРезвятся кто во что горазд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажите,\u0026#160;— бутафор вам даст\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе нужные приспособленья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотребуется верхний свет, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы жгите, сколько вам угодно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ стихии огненной, и водной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ прочих недостатка нет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ дощатом этом — балагане\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы можете, как в мирозданье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПройдя все ярусы подряд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСойти с небес сквозь землю в ад.\u003ca class=\"ref\" id=\"r5\" href=\"#n5\" data-tip=\"№5 \u0026#183; Франкфуртская мистерия Страстей; Великий театр мира (Кальдерон)\"\u003e5\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r6\" href=\"#n6\" data-tip=\"№6 \u0026#183; Книга Иова; Разговоры с Гёте (Эккерман)\"\u003e6\u003c/a\u003eПролог на небе\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподь, небесное воинство, потом Мефистофель. Три архангела.\u003ca class=\"ref\" id=\"r7\" href=\"#n7\" data-tip=\"№7 \u0026#183; Книга Товита; Книга пророка Даниила и др.\"\u003e7\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРафаил\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ пространстве, хором сфер объятом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой голос солнце подает,\u003ca class=\"ref\" id=\"r8\" href=\"#n8\" data-tip=\"№8 \u0026#183; О небе (Аристотель); Государство (Платон) и др.\"\u003e8\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвершая с громовым раскатом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредписанный круговорот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДивятся ангелы господни,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОкинув взором весь предел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в первый день, так и сегодня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезмерна слава божьих дел.\u003ca class=\"ref\" id=\"r9\" href=\"#n9\" data-tip=\"№9 \u0026#183; Книга Бытия\"\u003e9\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГавриил\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с непонятной быстротою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнизу вращается Земля,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа ночь со страшной темнотою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ светлый полдень круг деля.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ море пеной волн одето,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в камни пеной бьет прибой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ камни с морем мчит планета\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо кругу вечно за собой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМихаил\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ бури, все попутно руша\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все обломками покрыв,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо в вольном море, то на суше\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезумствуют наперерыв.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ молния сбегает змеем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дали застилает дым.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо мы, господь, благоговеем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред дивным промыслом твоим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе втроем\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы, ангелы твои господни,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОкинув взором весь предел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоем, как в первый день, сегодня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХвалу величью божьих дел.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК тебе попал я, боже, на прием,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб доложить о нашем положенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот почему я в обществе твоем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ всех, кто состоит тут в услуженье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо если б я произносил тирады,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ангелов высокопарный лик,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя бы насмешил я до упаду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда бы ты смеяться не отвык.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ о планетах говорить стесняюсь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ расскажу, как люди бьются, маясь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБожок вселенной, человек таков,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКаким и был он испокон веков.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн лучше б жил чуть-чуть, не озари\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго ты божьей искрой изнутри.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн эту искру разумом зовет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с этой искрой скот скотом живет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрошу простить, но по своим приемам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн кажется каким-то насекомым.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолулетя, полускача,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн свиристит, как саранча.\u003ca class=\"ref\" id=\"r10\" href=\"#n10\" data-tip=\"№10 \u0026#183; Книга Чисел; Псалтирь\"\u003e10\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если б он сидел в траве покоса\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ во все дрязги не совал бы носа!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ это все? Опять ты за свое?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь жалобы да вечное нытье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак на земле все для тебя не так?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, господи, там беспросветный мрак,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ человеку бедному так худо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто даже я щажу его покуда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы знаешь Фауста?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн доктор?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн мой раб.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, странно этот эскулап\u003ca class=\"ref\" id=\"r11\" href=\"#n11\" data-tip=\"№11 \u0026#183; Пифийская ода III (Пиндар); Мифологическая библиотека (Аполлодор)\"\u003e11\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСправляет вам повинность божью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ чем он сыт, никто не знает тоже.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн рвется в бой, и любит брать преграды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ видит цель, манящую вдали,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ требует у неба звезд в награду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лучших наслаждений у земли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ век ему с душой не будет сладу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК чему бы поиски ни привели.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн служит мне, и это налицо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ выбьется из мрака мне в угоду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда садовник садит деревцо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлод наперед известен садоводу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоспоримте! Увидите воочью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ вас я сумасброда отобью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНемного взявши в выучку свою.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо дайте мне на это полномочья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни тебе даны. Ты можешь гнать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока он жив, его по всем уступам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто ищет — вынужден блуждать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПристрастья не питая к трупам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасибо должен вам сказать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне ближе жизненные соки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРумянец, розовые щеки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКотам нужна живая мышь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх мертвою не соблазнишь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн отдан под твою опеку!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, если можешь, низведи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ такую бездну человека,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб он тащился позади.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы проиграл наверняка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧутьем, по собственной охоте\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн вырвется из тупика.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоспорим. Вот моя рука,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ скоро будем мы в расчете.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы торжество мое поймете,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда он, ползая в помете,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖрать будет прах от башмака,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак пресмыкается века\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗмея, моя родная тетя.\u003ca class=\"ref\" id=\"r12\" href=\"#n12\" data-tip=\"№12 \u0026#183; Книга Бытия\"\u003e12\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда ко мне являйся без стесненья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаким, как ты, я никогда не враг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз духов отрицанья ты всех мене\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБывал мне в тягость, плут и весельчак.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз лени человек впадает в спячку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтупай, расшевели его застой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВертись пред ним, томи, и беспокой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ раздражай его своей горячкой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Обращаясь к ангелам.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы ж, дети мудрости и милосердья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбуйтесь красотой предвечной тверди.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто борется, страдает и живет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть в вас любовь рождает и участье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо эти превращенья в свой черед\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНемеркнущими мыслями украсьте.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНебо закрывается. Архангелы расступаются.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (один)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак речь его спокойна и мягка!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы ладим, отношений с ним не портя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрекрасная черта у старика\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак человечно думать и о черте.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2 class=\"part\"\u003eЧасть первая\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eНочь\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТесная готическая комната со сводчатым потолком.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст без сна сидит в кресле за книгою на откидной подставке.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ богословьем овладел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад философией корпел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЮриспруденцию долбил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ медицину изучил.\u003ca class=\"ref\" id=\"r13\" href=\"#n13\" data-tip=\"№13 \u0026#183; История о докторе Иоганне Фаусте (Шпис); Трагическая история доктора Фауста (Марло)\"\u003e13\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако я при этом всем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл и остался дураком.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ магистрах, в докторах хожу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ за нос десять лет вожу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУчеников, как буквоед,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолкуя так и сяк предмет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо знанья это дать не может,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ этот вывод мне сердце гложет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя я разумнее многих хватов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВрачей, попов и адвокатов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх точно всех попутал леший,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ ж и пред чертом не опешу,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо и себе я знаю цену,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе тешусь мыслию надменной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто светоч я людского рода\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вверен мир моему уходу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе нажил чести и добра\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не вкусил, чем жизнь остра.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ пес с такой бы жизни взвыл!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ к магии я обратился,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб дух по зову мне явился\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тайну бытия открыл.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб я, невежда, без конца\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе корчил больше мудреца,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА понял бы, уединясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВселенной внутреннюю связь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПостиг все сущее в основе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не вдавался в суесловье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО месяц, ты меня привык\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВстречать среди бумаг и книг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ночных моих трудах, без сна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ углу у этого окна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если б тут твой бледный лик\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ последний раз меня застиг!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если бы ты с этих пор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВстречал меня на высях гор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде феи с эльфами в тумане\u003ca class=\"ref\" id=\"r14\" href=\"#n14\" data-tip=\"№14 \u0026#183; О забавах придворных (Вальтер Мап); Немецкая мифология (Гримм) и др.\"\u003e14\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИграют в прятки на поляне!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам, там росой у входа в грот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б смыл учености налет!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо как? Назло своей хандре\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще я в этой конуре,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде доступ свету загражден\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦветною росписью окон!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде запыленные тома\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНавалены до потолка;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде даже утром полутьма\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт черной гари ночника;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде собран в кучу скарб отцов.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаков твой мир! Твой отчий кров!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ для тебя еще вопрос,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткуда в сердце этот страх?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ты все это перенес\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в заточенье не зачах,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда насильственно, взамен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивых и богом данных сил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебя средь этих мертвых стен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкелетами ты окружил?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВстань и беги, не глядя вспять!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА провожатым в этот путь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТворенье Нострадама взять\u003ca class=\"ref\" id=\"r15\" href=\"#n15\" data-tip=\"№15 \u0026#183; Центурии (Нострадамус)\"\u003e15\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаинственное не забудь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ты прочтешь в движенье звезд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто может в жизни проистечь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС твоей души спадет нарост,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ты услышишь духов речь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх знаки, сколько ни грызи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе пища для сухих умов.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, духи, если вы вблизи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтветьте мне на этот зов!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Открывает книгу и видит знак макрокосма.)\u003ca class=\"ref\" id=\"r16\" href=\"#n16\" data-tip=\"№16 \u0026#183; Оккультная философия (Агриппа); Великая астрономия (Парацельс) и др.\"\u003e16\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой восторг и сил какой напор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо мне рождает это начертанье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ оживаю, глядя на узор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вновь бужу уснувшие желанья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто из богов придумал этот знак?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакое исцеленье от унынья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДает мне сочетанье этих линий!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасходится томивший душу мрак.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе проясняется, как на картине.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот мне кажется, что сам я — бог\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вижу, символ мира разбирая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВселенную от края и до края.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь понятно, что мудрец изрек:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Мир духов рядом, дверь не на запоре,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо сам ты слеп, и все в тебе мертво.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмойся в утренней заре, как в море,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОчнись, вот этот мир, войди в него\u0026#187;.\u003ca class=\"ref\" id=\"r17\" href=\"#n17\" data-tip=\"№17 \u0026#183; Небесные тайны (Сведенборг); О небесах, о мире духов и об аде (Сведенборг)\"\u003e17\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Рассматривает внимательно изображение.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ каком порядке и согласье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдет в пространствах ход работ!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, что находится в запасе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ углах вселенной непочатых,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо тысяча существ крылатых\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоочередно подает\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДруг другу в золотых ушатах\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вверх снует и вниз снует.\u003ca class=\"ref\" id=\"r18\" href=\"#n18\" data-tip=\"№18 \u0026#183; Книга Бытия; Золотая цепь Гомера (Кирхвегер)\"\u003e18\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот зрелище! Но горе мне:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь зрелище! С напрасным стоном,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрирода, вновь я в стороне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред твоим священным лоном!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, как мне руки протянуть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК тебе, как пасть к тебе на грудь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрильнуть к твоим ключам бездонным!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(С досадою перевертывает страницу и видит знак земного духа.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ больше этот знак люблю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне дух Земли родней, желанней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагодаря его влиянью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ рвусь вперед, как во хмелю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда, ручаюсь головой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГотов за всех отдать я душу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ твердо знаю, что не струшу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ свой час крушенья роковой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКлубятся облака,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛуна зашла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотух огонь светильни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДым! Красный луч скользит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВкруг моего чела.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА с потолка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБросая в дрожь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПахнуло жутью замогильной!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖеланный дух, ты где-то здесь снуешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯвись! Явись!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак сердце ноет!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС какою силою дыханье захватило!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе помыслы мои с тобой слились!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯвись! Явись!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯвись! Пусть это жизни стоит!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Берет книгу и произносит таинственное заклинание.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВспыхивает красноватое пламя, в котором является дух.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто звал меня?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (отворачиваясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУжасный вид!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаклял меня своим призывом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНастойчивым, нетерпеливым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот…\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвой лик меня страшит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолил меня к нему явиться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУслышать жаждал, увидать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ сжалился, пришел и, глядь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ испуге вижу духовидца!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу что ж, дерзай, сверхчеловек!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде чувств твоих и мыслей пламя?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ж, возомнив сравняться с нами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы к помощи моей прибег?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ это Фауст, который говорил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо мной, как равный, с превышеньем сил?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ здесь, и где твои замашки?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо телу бегают мурашки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы в страхе вьешься, как червяк?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, дух, я от тебя лица не прячу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто б ни был ты, я, Фауст, не меньше значу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в буре деяний, в житейских волнах,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ огне, в воде,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда, везде,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ извечной смене\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмертей и рождений.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ — океан,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ зыбь развитья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ткацкий стан\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС волшебной нитью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде, времени кинув сквозную канву,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивую одежду я тку божеству.\u003ca class=\"ref\" id=\"r19\" href=\"#n19\" data-tip=\"№19 \u0026#183; Этика (Спиноза); Псалтирь\"\u003e19\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО деятельный гений бытия,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрообраз мой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО нет, с тобою схож\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь дух, который сам ты познаешь,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе я!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Исчезает.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (сокрушенно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе ты?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак кто же?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, образ и подобье божье,\u003ca class=\"ref\" id=\"r20\" href=\"#n20\" data-tip=\"№20 \u0026#183; Книга Бытия\"\u003e20\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ даже с ним,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ним, низшим, несравним!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаздается стук в дверь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот принесла нелегкая! В разгар\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВидений этих дивных — мой подручный!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсю прелесть чар рассеет этот скучный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесносный, ограниченный школяр!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит Вагнер в спальном колпаке и халате, с лампою в руке. Фауст с неудовольствием поворачивается к нему.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростите, не из греческих трагедий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы только что читали монолог?\u003ca class=\"ref\" id=\"r21\" href=\"#n21\" data-tip=\"№21 \u0026#183; Аттическая трагедия (Эсхил, Софокл, Еврипид)\"\u003e21\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсмелился зайти к вам, чтоб в беседе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ вас взять декламации урок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб проповедник шел с успехом в гору,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть учится паренью у актера.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, если проповедник сам актер,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак наблюдается с недавних пор.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы век проводим за трудами дома\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ только в праздник видим мир в очки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак управлять нам паствой незнакомой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда мы от нее так далеки?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде нет нутра, там не поможешь по\u0026amp;#769;том.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦена таким усильям медный грош.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь проповеди искренним полетом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаставник в вере может быть хорош.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА тот, кто мыслью беден и усидчив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКропает понапрасну пересказ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаимствованных отовсюду фраз,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе дело выдержками ограничив.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн, может быть, создаст авторитет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСреди детей и дурней недалеких,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо без души и помыслов высоких\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивых путей от сердца к сердцу нет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо много значит дикция и слог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ чувствую, еще я в этом плох.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУчитесь честно достигать успеха\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ привлекать благодаря уму.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА побрякушки, гулкие, как эхо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодделка и не нужны никому.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда всерьез владеет что-то вами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе станете вы гнаться за словами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА рассужденья, полные прикрас,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем обороты ярче и цветистей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаводят скуку, как в осенний час\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВой ветра, обрывающего листья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, господи, но жизнь-то недолга,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА путь к познанью дальний. Страшно вчуже:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ так уж ваш покорнейший слуга\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПыхтит от рвенья, а не стало б хуже!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИной на то полжизни тратит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб до источников дойти,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлядишь,\u0026#160;— его на полпути\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУдар от прилежанья хватит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПергаменты не утоляют жажды.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКлюч мудрости не на страницах книг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто к тайнам жизни рвется мыслью каждой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ своей душе находит их родник.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако есть ли что милей на свете,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем уноситься в дух былых столетий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ умозаключать из их работ,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак далеко шагнули мы вперед?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО да, конечно, до самой луны!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе трогайте далекой старины.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам не сломить ее семи печатей.\u003ca class=\"ref\" id=\"r22\" href=\"#n22\" data-tip=\"№22 \u0026#183; Откровение Иоанна Богослова\"\u003e22\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то, что духом времени зовут,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсть дух профессоров и их понятий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый эти господа некстати\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа истинную древность выдают.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак представляем мы порядок древний?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак рухлядью заваленный чулан,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА некоторые еще плачевней\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак кукольника старый балаган.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо мненью некоторых, наши предки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе люди были, а марионетки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо мир! Но жизнь! Ведь человек дорос,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб знать ответ на все свои загадки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто значит знать? Вот, друг мой, в чем вопрос.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа этот счет у нас не все в порядке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНемногих, проникавших в суть вещей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ раскрывавших всем души скрижали,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСжигали на кострах и распинали,\u003ca class=\"ref\" id=\"r23\" href=\"#n23\" data-tip=\"№23 \u0026#183; Евангелие от Матфея; Приговор Яну Гусу (1415) и др.\"\u003e23\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак вам известно, с самых давних дней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо мы заговорились, спать пора.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставим спор, уже довольно поздно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, кажется, не спал бы до утра\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все бы с вами толковал серьезно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо завтра пасха, и в свободный час\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасспросами обеспокою вас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ знаю много, погружен в занятья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо знать я все хотел бы без изъятья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (один)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОхота надрываться чудаку!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн клада ищет жадными руками\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, как находке, рад, копаясь в хламе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбому дождевому червяку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн смел нарушить тишину угла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде замирал я, в лица духов глядя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа этот раз действительно хвала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБеднейшему из всех земных исчадий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, верно, помешался бы один,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б он в дверь ко мне не постучался.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот призрак был велик, как исполин,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я, как карлик, перед ним терялся.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, названный подобьем божества,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозмнил себя и вправду богоравным.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНасколько в этом ослепленье явном\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ переоценил свои права!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ счел себя явленьем неземным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПронизывающим, как бог, творенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРешил, что я светлей, чем серафим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСильней и полновластнее, чем гений.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ возмездие за это дерзновенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ уничтожен словом громовым.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы вправе, дух, меня бесславить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ мог тебя прийти заставить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо удержать тебя не мог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ испытал в тот миг высокий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакую мощь, такую боль!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы сбросил вниз меня жестоко,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ людскую темную юдоль.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак быть с внушеньями и снами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС мечтами? Следовать ли им?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто трудности, когда мы сами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебе мешаем и вредим!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы побороть не в силах скуки серой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам голод сердца большей частью чужд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мы считаем праздною химерой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, что превыше повседневных нужд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивейшие и лучшие мечты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ нас гибнут средь житейской суеты.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ лучах воображаемого блеска\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы часто мыслью воспаряем вширь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ падаем от тяжести привеска,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт груза наших добровольных гирь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы драпируем способами всеми\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвое безводье, трусость, слабость, лень.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам служит ширмой состраданья бремя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ совесть, и любая дребедень.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда все отговорки, все предлог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб произвесть в душе переполох.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо это дом, то дети, то жена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо страх отравы, то боязнь поджога,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо только вздор, но ложная тревога,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо выдумка, но мнимая вина.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой я бог! Я знаю облик свой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ червь слепой, я пасынок природы,\u003ca class=\"ref\" id=\"r24\" href=\"#n24\" data-tip=\"№24 \u0026#183; Книга Иова; Псалтирь\"\u003e24\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый пыль глотает пред собой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ гибнет под стопою пешехода.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе в прахе ли проходит жизнь моя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь этих книжных полок, как в неволе?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе прах ли эти сундуки старья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ эта рвань, изъеденная молью?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтак, я здесь все нужное найду?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь, в сотне книг, прочту я утвержденье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто человек терпел всегда нужду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ счастье составляло исключенье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, голый череп посреди жилья!\u003ca class=\"ref\" id=\"r25\" href=\"#n25\" data-tip=\"№25 \u0026#183; Гамлет (Шекспир); Святой Иероним в келье (Дюрер)\"\u003e25\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа что ты намекаешь, зубы скаля?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто твой владелец, некогда, как я,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИскавший радости, блуждал в печали?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе смейтесь надо мной деленьем шкал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕстествоиспытателя приборы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, как ключи к замку, вас подбирал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо у природы крепкие затворы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо, что она желает скрыть в тени\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаинственного своего покрова,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе выманить винтами шестерни,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи силами орудья никакого.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе тронутые мною черепки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАлхимии отцовой пережитки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вы, исписанные от руки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ копотью покрывшиеся свитки!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б лучше расточил вас, словно мот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем изнывать от вашего соседства.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаследовать достоин только тот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто может к жизни приложить наследство.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо жалок тот, кто копит мертвый хлам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто миг рождает, то на пользу нам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо отчего мой взор к себе так властно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТа склянка привлекает, как магнит?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ моей душе становится так ясно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто лунный свет в лесу разлит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБутыль с заветной жидкостью густою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТянусь с благоговеньем за тобою!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тебе я чту венец исканий наш.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз сонных трав настоянная гуща,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмертельной силою, тебе присущей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСегодня своего творца уважь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзгляну ли на тебя — и легче муки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дух ровней; тебя возьму ли в руки\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВолненье начинает убывать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе шире даль, и тянет ветром свежим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ к новым дням и новым побережьям\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗовет зеркальная морская гладь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлетает огненная колесница,\u003ca class=\"ref\" id=\"r26\" href=\"#n26\" data-tip=\"№26 \u0026#183; Четвёртая книга Царств\"\u003e26\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я готов, расправив шире грудь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа ней в эфир стрелою устремиться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК неведомым мирам направить путь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, эта высь, о, это просветленье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостоин ли ты, червь, так вознестись?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпиною к солнцу стань без сожаленья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС земным существованьем распростись.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНабравшись духу, выломай руками\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВрата, которых самый вид страшит!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа деле докажи, что пред богами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРешимость человека устоит!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто он не дрогнет даже у преддверья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлухой пещеры, у того жерла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде мнительная сила суеверья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКостры всей преисподней разожгла.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаспорядись собой, прими решенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя бы и ценой уничтоженья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожалуй-ка, наследственная чара,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ты на свет из старого футляра.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ много лет тебя не вынимал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИграя радугой хрустальных граней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБывало, радовала ты собранье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ каждый залпом чару осушал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа этих торжествах семейных гости\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтихами изъяснялись в каждом тосте.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы эти дни напомнил мне, бокал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас сказать я речи не успею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапиток этот действует скорее,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ медленней струя его течет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн дело рук моих, моя затея,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот я пью его душою всею\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо славу дня, за солнечный восход.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Подносит бокал к губам.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКолокольный звон и хоровое пенье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор ангелов\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХристос воскрес!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПреодоление\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмерти и тления\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлавьте, селение,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПашня и лес.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРека гудящих звуков отвела\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт губ моих бокал с отравой этой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверное, уже колокола\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХристову пасху возвестили свету\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в небе ангелы поют хорал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый встарь у гроба ночью дал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНачало братству нового завета.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор мироносиц\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт посторонних\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТело укрыли.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе в благовоньях,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ гроб положили.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод пеленами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКамня плита.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет в них пред нами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБольше Христа.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор ангелов\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХристос воскрес!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрехопадения,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмерти и тления\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлед с поколения\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмыт и исчез.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛикующие звуки торжества,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем вы раздаетесь в этом месте?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГудите там, где набожность жива,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА здесь вы не найдете благочестья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь чудо — веры лучшее дитя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не сумею унестись в те сферы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткуда радостная весть пришла.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя и ныне, много лет спустя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы мне вернули жизнь, колокола,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в памятные годы детской веры,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда вы оставляли на челе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой поцелуй в ночной тиши субботней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВаш гул звучал таинственней во мгле,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолитва с уст срывалась безотчетной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ убегал на луговой откос,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакая грусть меня обуревала!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ плакал, упиваясь счастьем слез,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мир во мне рождался небывалый.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тех пор в душе со светлым воскресеньем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвязалось все, что чисто и светло.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОно мне веяньем своим весенним\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС собой покончить ныне не дало.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ возвращен земле. Благодаренье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа это вам, святые песнопенья!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор учеников\u003ca class=\"ref\" id=\"r27\" href=\"#n27\" data-tip=\"№27 \u0026#183; Евангелие от Матфея; Евангелие от Марка и др.\"\u003e27\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмерти раздавлена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПопрана злоба:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНовопреставленный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВышел из гроба.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть он в обители\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа облаками,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмя учителя\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС учениками.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыстоим преданно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе превращенья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам заповедано\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто ученье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор ангелов\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХристос воскрес!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПасха Христова\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС нами, и снова\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖизнь до основы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся без завес.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудьте готовы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСбросить оковы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСилой святого\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлова его,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТленья земного,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСна гробового,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС сердца любого,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС мира всего.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eУ ворот\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолпы гуляющих направляются за город.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесколько подмастерьев\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда такой толпой?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругие\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ стрелковый тир лесной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервые\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА мы ватагой к мельничной запруде.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдин из подмастерьев\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа гать ступайте. Вот где красота.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторой подмастерье\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДалекий путь. Неважные места.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз второй группы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты куда?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТретий подмастерье\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТуда, куда и люди.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧетвертый\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаких, как возле замка в слободе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи девушек, ни пива нет нигде.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ первый сорт задиры и скандалы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПятый\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак у тебя опять, у хвастуна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо их побоям чешется спина?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ этим сыт надолго до отвала.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлужанка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, лучше я пойду домой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругая служанка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверно, он за тополями теми.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервая\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА мне в нем интерес какой?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн за тобой таскается все время,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я, как дура, радуйся на вас,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда вдвоем пускаетесь вы в пляс.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторая\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСегодня, кажется, он не один.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ним, помнишь, тот кудрявчик господин.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГляди, девчонка под руку с девчонкой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ну-ка за обеими вдогонку!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, брат, покрепче пиво и табак\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа девочки — на это я мастак.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДевушка-горожанка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМогу сказать, студенты-кавалеры!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ удивляюсь, как не стыдно им.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ барышень хорошие манеры,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни же липнут к горничным простым.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторой студент  (первому)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа не беги ты! Видишь, сзади две,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ обе из порядочного дома.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдна из них с соседями в родстве,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ потому мы шапочно знакомы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаскланяемся с ними, подойдем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ совершим прогулку вчетвером.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервый студент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, брат, одно стесненье эта знать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ отдаю служанкам предпочтенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТа, что в субботу будет подметать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсех лучше приголубит в воскресенье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорожанин\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБеда нам с новым бургомистром.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн все решает с видом быстрым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА пользой нашей пренебрег.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДела все хуже раз от разу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ настоятельней приказы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ непосильнее налог.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНищий  (поет)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы, судари мои и дамы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПошли господь вам много лет!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодайте нищему у храма,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ голоден и не одет!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ день праздничного ликованья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРука дающего легка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе откажите в подаянье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ пожалейте старика!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторой горожанин\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо праздникам нет лучше развлеченья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем толки за стаканчиком вина,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в Турции далекой, где война,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСражаются друг с другом ополченья.\u003ca class=\"ref\" id=\"r28\" href=\"#n28\" data-tip=\"№28 \u0026#183; Хроники австро-турецких войн; О войне против турка (Лютер)\"\u003e28\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодходишь у трактирщика к окну\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ смотришь — по реке идут баркасы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ после, дома, отходя ко сну,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагословляешь миролюбье часа.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТретий горожанин\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ тоже так смотрю, сосед.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть у других неразбериха,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПередерись хотя весь свет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа только б дома было тихо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаруха  (девушкам-горожанкам)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, ягодки-красавицы мои!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлаз не отвесть от вашего наряда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем чураетесь ворожеи?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ раздобыть сумею, что вам надо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервая девушка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАгата, что ты! Постыдись греха!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри встречных заговаривать с колдуньей!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна мне будущего жениха\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНедавно показала в новолунье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторая девушка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мне, в хрустальном шаре. Он солдат,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь удальцов, бросающихся в сечу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тех пор по сторонам бросаю взгляд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, сколько ни ищу, нигде не встречу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСолдаты\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРвы, частоколы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтены, ограды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖенского пола\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГордые взгляды\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред осадой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе устоят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРади награды\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБьется солдат.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред началом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсякой атаки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред привалом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрубят вояки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШтурмы с паденьем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖенщин и стен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот что мы ценим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрочее — тлен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРади награды\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБьется солдат.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУтром уходит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДальше отряд.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст и Вагнер.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРастаял лед, шумят потоки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛуга зеленеют под лаской тепла.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗима, размякнув на припеке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ суровые горы подальше ушла.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОттуда она крупою мелкой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабрасывает зеленя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо солнце всю ее побелку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмывает к середине дня.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе хочет цвесть, росток и ветка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо на цветы весна скупа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вместо них своей расцветкой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПестрит воскресная толпа.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзгляни отсюда вниз с утеса\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа городишко у откоса.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри, как валит вдаль народ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз старых городских ворот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсем хочется вздохнуть свободней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе рвутся вон из толкотни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ день воскресения господня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоскресли также и они.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни восстали из-под гнета\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКонур, подвалов, верстаков,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРемесленных оков без счета,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНависших крыш и чердаков,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ высыпали на прогулку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз хмурящейся тьмы церквей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз узенького закоулка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ растеклись ручьев живей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ бросились к речным причалам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ рыщут лодки по реке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тяжело грести усталым\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГребцам в последнем челноке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо горке ходят горожане,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни одеты щегольски,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА в отдаленье на поляне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ деревне пляшут мужики.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак человек, я с ними весь:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вправе быть им только здесь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрогулка с вами на свободе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриносит честь и пользу мне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо от забав простонародья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДержусь я, доктор, в стороне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК чему б крестьяне ни прибегли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тотчас драка, шум и гам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх скрипки, чехарда, и кегли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ крик невыносимы нам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрестьяне  (под липою; пляски и пение)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлясать отправился пастух,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОделся, разрядился впух,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦветов в камзол натыкал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод липой шла уж кутерьма,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКружились пары без ума,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкрипач вовсю пиликал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротискиваясь в этот круг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтолкнулся с девушкой пастух\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРумяною и свежей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ та ему, скользя из рук:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Пожалуйста, без этих штук!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе надо быть невежей!\u0026#187;\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, на нее взглянув в упор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтал девушку кружить танцор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ зашумели юбки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все нежней за туром тур\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШептался с нею балагур,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе вымолив уступки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Как только врать не надоест!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольно из-за вас невест\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПропало по ошибке!\u0026#187;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо недотрогу в уголок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн понемногу уволок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт скрипача и скрипки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтарик\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне, доктор, поручил народ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам благодарность принести.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы оказали нам почет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе погнушавшись к нам прийти.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУченость ваша у крестьян\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрославлена и всем видна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот полный доверху стакан,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сколько капель в нем вина,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть столько же счастливых дней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам бог прибавит к жизни всей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖелаю здравья вам в ответ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ теченье столь же многих лет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНарод обступает их.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтарик\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтрадно вспомнить в светлый день,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак жертвовали вы собой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля населенья деревень\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ дни черной язвы моровой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИного только потому\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУжасный миновал конец,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто нам тогда избыть чуму\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПомог покойный ваш отец.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас не пугал ее очаг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ — юноша еще тогда —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходили вы к больным в барак\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ выходили без вреда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа близость с братиею низшей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХранила вас десница свыше.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХрани вас господи и впредь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб не давали нам болеть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам следует благодарить\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТого, кто всех учил любить.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Проходит с Вагнером дальше.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы можете всем этим быть горды.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак вы любимы деревенским людом!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБольшое счастье — пожинать плоды\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпособностей, не сгинувших под спудом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы появились — шапки вверх летят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНикто не пляшет, пораженный чудом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас пропускают, выстроившись в ряд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще немного,\u0026#160;— позовут ребят\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ станут перед вами на колени,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак пред святыней, чтимою в селенье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавай дойдем до этой крутизны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ там присядем. Часто я, бывало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа той скале сидел средь тишины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВесь от поста худой и отощалый.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛомая руки, я мольбой горел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб бог скорей избавил нас от мора\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ положил поветрию предел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак уповал и верил я в ту пору!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ для меня насмешкою звучит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТех тружеников искреннее слово.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт их речей охватывает стыд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ за себя и за дела отцовы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтец мой, нелюдим-оригинал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсю жизнь провел в раздумьях о природе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн честно голову над ней ломал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя и по своей чудной методе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАлхимии тех дней забытый столп,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн запирался с верными в чулане\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с ними там перегонял из колб\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоединенья всевозможной дряни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам звали \u0026#171;лилиею\u0026#187;\u003ca class=\"ref\" id=\"r29\" href=\"#n29\" data-tip=\"№29 \u0026#183; Триумфальная колесница антимония (Василий Валентин); Двенадцать ключей (Василий Валентин) и др.\"\u003e29\u003c/a\u003e серебро,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Львом\u0026#187; — золото, а смесь их — связью в браке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолученное на огне добро,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Царицу\u0026#187;, мыли в холодильном баке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ нем осаждался радужный налет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюдей лечили этой амальгамой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе проверяя, вылечился ль тот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто обращался к нашему бальзаму.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва ли кто при этом выживал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак мой отец своим мудреным зельем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо мной средь этих гор и по ущельям\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСамой чумы похлеще бушевал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ каково мне слушать их хваленья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда и я виной их умерщвленья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сам отраву тысячам давал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКорить себя решительно вам нечем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей была заслуга ваша в том,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто вы воспользовались целиком\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУменьем, к вам от старших перешедшим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля сыновей отцовский опыт свят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни его всего превыше ставят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВаш сын ведь тоже переймет ваш взгляд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ после новое к нему прибавит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлажен, кто вырваться на свет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадеется из лжи окружной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ том, что известно, пользы нет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдно неведомое нужно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо полно вечер омрачать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоей тоскою беспричинное.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри: закат свою печать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНакладывает на равнину.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДень прожит, солнце с вышины\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУходит прочь в другие страны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем мне крылья не даны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ним вровень мчаться наустанно!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа горы в пурпуре лучей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаглядывался б я в полете\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на серебряный ручей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ вечерней темной позолоте.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпасный горный перевал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе останавливал бы крыльев.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ море бы пересекал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвиженье этих крыл усилив.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б зари вечерней свет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрозил погаснуть в океане,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б налегал дружнее вслед\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ нагонял его сиянье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ соседстве с небом надо мной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС днем впереди и ночью сзади,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ реял бы над водной гладью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖаль, нет лишь крыльев за спиной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо всем знаком порыв врожденный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда-то ввысь, туда, в зенит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда из синевы бездонной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеснь жаворонка зазвенит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли когда вверху над бором\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПарит орел, или вдали\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсенним утренним простором\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК отлету тянут журавли.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на меня капризы находили,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо не припомню я таких причуд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня леса и нивы не влекут,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ зависти не будят птичьи крылья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоя отрада — мысленный полет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо книгам, со страницы на страницу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗимой за чтеньем быстро ночь пройдет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТепло по телу весело струится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА если попадется редкий том,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт радости я на\u0026amp;#769; небе седьмом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы верен весь одной струне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не задет другим недугом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо две души живут во мне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ обе не в ладах друг с другом.\u003ca class=\"ref\" id=\"r30\" href=\"#n30\" data-tip=\"№30 \u0026#183; Федр (Платон); Послание к Римлянам\"\u003e30\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдна, как страсть любви, пылка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ жадно льнет к земле всецело,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругая вся за облака\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак и рванулась бы из тела.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если бы не в царстве грез,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА в самом деле вихрь небесный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня куда-нибудь унес\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ мир новой жизни неизвестной!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если б плащ волшебный взяв,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б улетал куда угодно! —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне б царских мантий и держав\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМилей был этот плащ походный.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе призывайте лучше никогда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСуществ, живущих в воздухе и ветре.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни распространители вреда,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмертей повальных, моровых поветрий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо демон севера\u003ca class=\"ref\" id=\"r31\" href=\"#n31\" data-tip=\"№31 \u0026#183; Оккультная философия (Агриппа); О действии демонов (Пселл)\"\u003e31\u003c/a\u003e заладит дуть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ нас проймет простудою жестокой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо нам пойдет сушить чахоткой грудь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТомительное веянье востока,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо с юга из пустыни суховей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас солнечным ударом стукнет в темя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо запад целой армией дождей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПовадится нас поливать все время.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе доверяйте духам темноты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРоящимся в ненастной серой дымке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакими б ангелами доброты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи притворялись эти невидимки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПойдемте, впрочем. На землю легла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНочная сырость, нависает мгла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХорош по вечерам уют домашний!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа что, однако, вы вперили взор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ смотрите как вкопанный в упор?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаметил, черный пес бежит по пашне?\u003ca class=\"ref\" id=\"r32\" href=\"#n32\" data-tip=\"№32 \u0026#183; История о докторе Иоганне Фаусте (Шпис); Правдивые истории о докторе Фаусте (Фиценцер) и др.\"\u003e32\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавно заметил. Что же из того?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто он? Ты в нем не видишь ничего?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбыкновенный пудель, пес лохматый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоих хозяев ищет по следам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКругами, сокращая их охваты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе ближе подбирается он к нам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, если я не ошибаюсь, пламя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа ним змеится по земле полян.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе вижу. Просто пудель перед нами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА этот след — оптический обман.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак он плетет вкруг нас свои извивы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМагический их смысл не так-то прост.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе замечаю. Просто пес трусливый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧужих завидев, поджимает хвост.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе меньше круг. Он подбегает. Стой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы видите, не призрак — пес простой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВорчит, хвостом виляет, лег на брюхо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, как у псов, и не похож на духа.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе бойся! Смирно, пес! За мной! Не тронь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабавный пудель. И притом — огонь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивой такой, понятливый и бойкий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоноску знает, может делать стойку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОброните вы что-нибудь — найдет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа брошенною палкой в пруд нырнет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, он не оборотень, дело ясно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК тому же, видно, вышколен прекрасно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСерьезному ученому забавно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИметь собаку с выучкой исправной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПес этот, судя по его игре,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверно, у студентов был в муштре.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходят в городские ворота.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eРабочая комната Фауста\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит Фауст с пуделем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставил я поля и горы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОкутанные тьмой ночной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткрылось внутреннему взору\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо лучшее, что движет мной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ душе, смирившей вожделенья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвершается переворот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна любовью к провиденью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбовью к ближнему живет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПудель, уймись и по комнате тесной не бегай!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолно ворчать и обнюхивать дверь и порог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу-ка —\u0026#160; за печку и располагайся к ночлегу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПраво, приятель, на эту подушку бы лег.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОчень любезно нас было прыжками забавить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ поле, на воле, уместна твоя беготня.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь тебя просят излишнюю резвость оставить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУгомонись и пойми: ты в гостях у меня.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда в глубоком мраке ночи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКаморку лампа озарит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе только в комнате рабочей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в сердце как бы свет разлит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ слышу разума внушенья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ возрождаюсь и хочу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрипасть к источникам творенья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК живительному их ключу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПудель, оставь! С вдохновеньем минуты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг охватившим меня невзначай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесовместимы ворчанье и лай.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБолее свойственно спеси надутой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛаять на то, что превыше ее.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазве и между собачьих ухваток\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВодится этот людской недостаток?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПудель! Оставь беготню и вытье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вновь безволье, и упадок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вялость в мыслях, и разброд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак часто этот беспорядок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа просветленьем настает!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПаденья эти и подъемы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в совершенстве мне знакомы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт них есть средство искони:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛекарство от душевной лени —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБожественное откровенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсесильное и в наши дни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсего сильнее им согреты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтраницы Нового завета.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот, кстати, рядом и они.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ по-немецки все Писанье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХочу, не пожалев старанья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУединившись взаперти,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак следует перевести.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Открывает книгу, чтобы приступить к работе.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;В начале было Слово\u0026#187;.\u0026#160;С первых строк\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗагадка. Так ли понял я намек?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь я так высоко не ставлю слова,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб думать, что оно всему основа.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;В начале Мысль была\u0026#187;. Вот перевод.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн ближе этот стих передает.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодумаю, однако, чтобы сразу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе погубить работы первой фразой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМогла ли мысль в созданье жизнь вдохнуть?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Была в начале Сила\u0026#187;. Вот в чем суть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо после небольшого колебанья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ отклоняю это толкованье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ был опять, как вижу, с толку сбит:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;В начале было Дело\u0026#187;\u003ca class=\"ref\" id=\"r33\" href=\"#n33\" data-tip=\"№33 \u0026#183; Евангелие от Иоанна; О даре языков (Гердер)\"\u003e33\u003c/a\u003e — стих гласит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли ты хочешь жить со мною,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо чтоб без воя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто за возня?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПонял ты, пудель? Смотри у меня!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКроме того, не лай, не балуй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОчень ты, брат, беспокойный малый.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдному из нас двоих\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридется убраться из стен моих.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, так возьми на себя этот шаг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНечего делать. Вот дверь. Всех благ!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо что я вижу! Вот так гиль!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто это, сказка или быль?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой пудель напыжился, как пузырь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все разбухает ввысь и вширь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн может до потолка достать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, это не собачья стать!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ нечисть ввел себе под свод!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаскрыла пасть, как бегемот,\u003ca class=\"ref\" id=\"r34\" href=\"#n34\" data-tip=\"№34 \u0026#183; Книга Иова; О кознях бесов (Вейер)\"\u003e34\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОгнем глазища налиты, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТварь из бесовской мелкоты.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСовет, как пакость обуздать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Ключ Соломона\u0026#187;\u003ca class=\"ref\" id=\"r35\" href=\"#n35\" data-tip=\"№35 \u0026#183; Ключ Соломона\"\u003e35\u003c/a\u003e\u0026#160;может дать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДухи  (в сенях)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдин из нас в ловушке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо внутрь за ним нельзя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаш долг помочь друг дружке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа дверью лебезя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВертитесь втихомолку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб нас пронюхал бес\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ к нам в дверную щелку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа радостях пролез.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУзнав, что есть подмога\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ он в родном кругу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн ринется к порогу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы все пред ним в долгу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб зачураться от собаки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсть заговор четвероякий!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСаламандра, жгись,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУндина, вейся,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСильф, рассейся,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКобольд, трудись!\u003ca class=\"ref\" id=\"r36\" href=\"#n36\" data-tip=\"№36 \u0026#183; Книга о нимфах, сильфах, пигмеях и саламандрах (Парацельс)\"\u003e36\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто слышит впервые\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПро эти стихии,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх свойства и строй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой заклинатель?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКропатель пустой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаздуй свое пламя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСаламандра!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазлейся ручьями,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУндина!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСильф, облаком взмой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИнкуб,\u0026#160;домовой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ хозяйственном хламе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто нужно, отрой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз первоматерий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет в нем ни одной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе стало ни больно, ни боязно зверю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазлегся у двери, смеясь надо мной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаклятья есть строже,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоганая рожа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПостой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы выходец бездны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриятель любезный?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот что без утайки открой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот символ святой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в дрожь тебя кинет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак страшен он вашей всей шайке клятой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГляди-ка, от ужаса шерсть он щетинит!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлазами своими\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБесстыжими, враг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрочтешь ли ты имя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсилишь ли знак\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесотворенного,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеизреченного,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС неба сошедшего, в лето Пилатово\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНашего ради спасенья распятого?\u003ca class=\"ref\" id=\"r37\" href=\"#n37\" data-tip=\"№37 \u0026#183; Никео-Цареградский Символ веры; Книга Исход и др.\"\u003e37\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа печку оттеснен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн вверх растет, как слон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГотовый, словно дым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо потолку расплыться.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛожись к ногам моим\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа эту половицу!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ сделать все могу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще с тобой, несчастный!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ троицей сожгу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя триипостасной!\u003ca class=\"ref\" id=\"r38\" href=\"#n38\" data-tip=\"№38 \u0026#183; Афанасиев Символ веры; Первый Никейский собор и др.\"\u003e38\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа это сила есть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоверь, у чародея.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (входит, когда дым рассеивается, из-за печи в одежде странствующего студента)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто вам угодно? Честь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредставиться имею.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот, значит, чем был пудель начинен!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкрывала школяра в себе собака?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтвешу вам почтительный поклон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, вы меня запарили, однако!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ты зовешься?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМелочный вопрос\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ устах того, кто безразличен к слову,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо к делу лишь относится всерьез\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ смотрит в корень, в суть вещей, в основу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако специальный атрибут\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ вас обычно явствует из кличек:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМушиный царь, обманщик, враг, обидчик,\u003ca class=\"ref\" id=\"r39\" href=\"#n39\" data-tip=\"№39 \u0026#183; Четвёртая книга Царств; Евангелие от Матфея и др.\"\u003e39\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотря как каждого из вас зовут:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы кто?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧасть силы той, что без числа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТворит добро, всему желая зла.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНельзя ли это проще передать?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ дух, всегда привыкший отрицать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с основаньем: ничего не надо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет в мире вещи, стоящей пощады.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТворенье не годится никуда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтак, я то, что ваша мысль связала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС понятьем разрушенья, зла, вреда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот прирожденное мое начало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоя среда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы говоришь, ты — часть, а сам ты весь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтоишь передо мною здесь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ верен скромной правде. Только спесь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюдская ваша с самомненьем смелым\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебя считает вместо части целым.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ — части часть, которая была\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда-то всем и свет произвела.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвет этот — порожденье тьмы ночной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ отнял место у нее самой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн с ней не сладит, как бы ни хотел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго удел — поверхность твердых тел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн к ним прикован, связан с их судьбой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь с помощью их может быть собой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ есть надежда, что, когда тела\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазрушатся, сгорит и он дотла.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак вот он в чем, твой труд почтенный!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе сладив в целом со вселенной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы ей вредишь по мелочам?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ безуспешно, как я ни упрям.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМир бытия — досадно малый штрих\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСреди небытия пространств пустых,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако до сих пор он непреклонно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМои нападки сносит без урона.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ донимал его землетрясеньем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожарами лесов и наводненьем, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ хоть бы что!\u0026#160;Я цели не достиг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ море в целости и материк.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА люди, звери и порода птичья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМори их не мори, им трын-трава.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлодятся вечно эти существа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ жизнь всегда имеется в наличье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИной, ей-ей, рехнулся бы с тоски!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ земле, в воде, на воздухе свободном\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗародыши роятся и ростки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ сухом и влажном, теплом и холодном.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе завладей я областью огня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМестечка не нашлось бы для меня.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтак, живительным задаткам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроизводящим все кругом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбъятый зависти припадком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрозишь ты злобно кулаком?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ж ты поинтересней дела\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебе, сын ночи, не припас?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОб этом надо будет зрело\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодумать в следующий раз.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь позвольте удалиться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрощай, располагай собой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнакомый с тем, что ты за птица,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрошу покорно в час любой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтупай. В твоем распоряженье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОкно, и дверь, и дымоход.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в некотором затрудненье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне выйти в сени не дает\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФигура под дверною рамой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы испугался пентаграммы?\u003ca class=\"ref\" id=\"r40\" href=\"#n40\" data-tip=\"№40 \u0026#183; Оккультная философия (Агриппа); Архидоксы магии (Парацельс) и др.\"\u003e40\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКаким же образом тогда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВошел ты чрез порог сюда?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак оплошал такой пройдоха?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсмотритесь. Этот знак начертан плохо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаружный угол вытянут в длину\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ оставляет ход, загнувшись с края.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажи-ка ты, нечаянность какая!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак, стало быть, ты у меня в плену?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе мог предугадать такой удачи!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМог обознаться пудель на бегу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо с чертом дело обстоит иначе:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вижу знак и выйти не могу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо почему не лезешь ты в окно?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧертям и призракам запрещено\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаружу выходить иной дорогой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем внутрь вошли; закон на это строгий.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, так законы есть у вас в аду?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот надо будет что иметь в виду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа случай договора с вашей братьей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбого обязательства принятье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля нас закон со всеми наряду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы не меняем данных обещаний.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоговорим при будущем свиданье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа этот раз спешу я и уйду.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще лишь миг, и я потом отстану:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДва слова только о моей судьбе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ как-нибудь опять к тебе нагряну,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда и предадимся ворожбе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь пусти меня!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо это странно!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь я не расставлял тебе сетей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы сам попался и опять, злодей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе дашься мне, ушедши из капкана.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСогласен. Хорошо. Я остаюсь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, в подтвержденье дружеского чувства,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем временем развлечь тебя берусь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ покажу тебе свое искусство.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоказывай, что хочешь, но гляди —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь скуки на меня не наведи.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы больше извлечешь сейчас красот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа час короткий, чем за долгий год.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНезримых духов тонкое уменье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗахватит полностью все ощущенья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвой слух и нюх, а также вкус и зренье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ осязанье — все наперечет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГотовиться не надо. Духи тут\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тотчас исполнение начнут.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДухи\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРухните, своды\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКаменной кельи!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС полной свободой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХлынь через щели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолубизна!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тесные кучи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСбились вы, тучи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ваши разрывы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотрит тоскливо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвезд глубина.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам в притяженье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВечном друг к другу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМчатся по кругу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДухи и тени,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеба сыны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭта планета\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ зелень одета.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНивы и горы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛетом в уборы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОблечены.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе — в оболочке:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервые почки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРедкие ветки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГнезда, беседки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ шалаши.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсюду секреты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлезы, обеты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзятье, отдача\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖаркой, горячей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрастной души.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тою же силой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак из давила\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСок винограда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПенною бурей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХлещет в чаны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак с верхотурья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорной стремнины\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМощь водопада\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсею громадой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалит в лощину\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа валуны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь на озерах\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗарослей шорох,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛес величавый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРопот дубравы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРек рукава.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто поупрямей —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВверх по обрыву,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто с лебедями —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВплавь по заливу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа острова.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаннею ранью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ до захода —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПесни, гулянье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ хороводы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНебо, трава.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ поцелуи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапропалую,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ упоенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСамозабвенья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ синева.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн спит! Благодарю вас несказанно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго вы усыпили, мальчуганы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ваш концерт — вершина мастерства.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, не тебе ловить чертей в тенета!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб глубже погрузить его в дремоту,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДружней водите, дети, хоровод.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА этот знак — для грызуна работа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго мне крыса сбоку надгрызет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖдать избавительницы не придется:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж слышу я, как под полом скребется.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарь крыс, лягушек и мышей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКлопов, и мух, и жаб, и вшей\u003ca class=\"ref\" id=\"r41\" href=\"#n41\" data-tip=\"№41 \u0026#183; Книга Исход; Евангелие от Матфея и др.\"\u003e41\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе велит сюда явиться\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ выгрызть место в половице,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда я сверху масла капну.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж крыса тут как тут внезапно!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, живо! Этот вот рубец.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще немного, и конец.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГотово! Покидаю кров.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпи, Фауст, мирно. Будь здоров!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (просыпаясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе вовремя я сном забылся.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в дураках. Пока я спал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне в сновиденье черт явился\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ пудель от меня сбежал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eРабочая комната Фауста\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст и Мефистофель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпять стучится кто-то. Вот досада!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойдите. Кто там?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто я.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойди ж.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаклятье повторить три раза надо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойди.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот ты меня и лицезришь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ убежден, поладить мы сумеем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сообща твою тоску рассеем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри, как расфрантился я пестро.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз кармазина с золотою ниткой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКамзол в обтяжку, на плечах накидка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа шляпе петушиное перо,\u003ca class=\"ref\" id=\"r42\" href=\"#n42\" data-tip=\"№42 \u0026#183; Немецкая мифология (Гримм); Handw\u0026#246;rterbuch des deutschen Aberglaubens\"\u003e42\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА сбоку шпага с выгнутым эфесом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ — хочешь знать?\u0026#160;— вот мнение мое:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСам облекись в такое же шитье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы в одежде, свойственной повесам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзведать после долгого поста,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто означает жизни полнота.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ любом наряде буду я по праву\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТоску существованья сознавать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ слишком стар, чтоб знать одни забавы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ слишком юн, чтоб вовсе не желать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто даст мне свет, чего я сам не знаю?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Смиряй себя!\u0026#187; — Вот мудрость прописная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзвечный, нескончаемый припев,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторым с детства прожужжали уши,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНравоучительною этой сушью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам всем до тошноты осточертев.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ утром просыпаюсь с содроганьем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ чуть не плачу, зная наперед,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто день пройдет, глухой к моим желаньям,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в исполненье их не приведет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНамек на чувство, если он заметен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНедопустим и дерзок чересчур:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗлословье все покроет грязью сплетен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тысячью своих карикатур.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ночь меня в покое не оставит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва я на постели растянусь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня кошмар ночным удушьем сдавит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я в поту от ужаса проснусь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБог, обитающий в груди моей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВлияет только на мое сознанье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа внешний мир, на общий ход вещей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе простирается его влиянье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне тяжко от неполноты такой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ жизнь отверг и смерти жду с тоской.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмерть — посетитель не ахти какой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлажен, к кому она в пылу сраженья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвенчанная лаврами, придет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКого сразит средь вихря развлечений\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли в объятьях девушки найдет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри виде духа кончить с жизнью счеты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ был вчера на радостях не прочь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, если я не ошибаюсь, кто-то\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе выпил яда именно в ту ночь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ придачу ко всему ты и шпион?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не всеведущ, я лишь искушен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если мне в тот миг разлада\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл дорог благовеста гул\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с детства памятной отрадой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМою решимость пошатнул,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ проклинаю ложь без меры\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ изворотливость без дна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС какою в тело, как в пещеру,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ нас душа заключена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ проклинаю самомненье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторым ум наш обуян,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ проклинаю мир явлений,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбманчивых, как слой румян.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ обольщенье семьянина.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДетей, хозяйство и жену,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ наши сны, наполовину\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеисполнимые, кляну.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКляну Маммона, власть наживы,\u003ca class=\"ref\" id=\"r43\" href=\"#n43\" data-tip=\"№43 \u0026#183; Евангелие от Матфея; Евангелие от Луки\"\u003e43\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРастлившей в мире все кругом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКляну святой любви порывы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ опьянение вином.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ шлю проклятие надежде,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереполняющей сердца,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо более всего и прежде\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКляну терпение глупца.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор духов  (незримо)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, бездна страданья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ море тоски!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧудесное зданье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазбито в куски.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы градом проклятий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго расшатал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорюй об утрате\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПогибших начал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо справься с печалью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоспрянь, полубог!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПострой на обвале\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой новый чертог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо не у пролома,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА глубже, в груди,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой дом по-другому\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь возведи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНастойчивей к цели\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНасущной шагни\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ песни веселья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ пути затяни.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМои малютки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх прибаутки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазумное их слово\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе по летам толково.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни тебя зовут\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРвануться вон из пут\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мрака кабинета\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ простор большого света.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставь заигрывать с тоской своей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТочащею тебя, как коршун злобный.\u003ca class=\"ref\" id=\"r44\" href=\"#n44\" data-tip=\"№44 \u0026#183; Прикованный Прометей (Эсхил); Теогония (Гесиод)\"\u003e44\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ни плоха среда, но все подобны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ человек немыслим без людей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не зову тебя к простолюдинам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы повидней компанию найдем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть средь чертей я сам не вышел чином,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайдешь ты пользу в обществе моем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавай столкуемся друг с другом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб вместе жизни путь пройти.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагодаря моим услугам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе будешь ты скучать в пути.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА что ты требуешь в уплату?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСочтемся после, время ждет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧерт даром для меньшого брата\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ пальцем не пошевельнет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоговоримся, чтоб потом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе заносить раздора в дом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе со мною будет здесь удобно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ буду исполнять любую блажь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа это в жизни тамошней, загробной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы тем же при свиданье мне воздашь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я к загробной жизни равнодушен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тот час, как будет этот свет разрушен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тем светом я не заведу родства.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ сын земли. Отрады и кручины\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИспытываю я на ней единой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тот горький час, как я ее покину,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне все равно, хоть не расти трава.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ до иного света мне нет дела,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак тамошние б чувства ни звались,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе любопытно, где его пределы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ есть ли там, в том царстве, верх и низ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем легче будет, при таком воззренье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе войти со мною в соглашенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа это, положись на мой обет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ дам тебе, чего не видел свет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто можешь ты пообещать, бедняга?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам, близоруким, непонятна суть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтремлений к ускользающему благу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы пищу дашь, не сытную ничуть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДашь золото, которое, как ртуть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеж пальцев растекается; зазнобу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторая, упав к тебе на грудь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж норовит к другому ушмыгнуть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДашь талью карт, с которой, как ни пробуй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИгра вничью и выигрыш не в счет;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДашь упоенье славой, дашь почет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУспех, недолговечней метеора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дерево такой породы спорой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто круглый год день вянет, день цветет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня в тупик не ставит порученье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе это есть в моем распоряженье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо мы добудем, дай мне только срок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВернее и полакомей кусок.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть мига больше я не протяну,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тот самый час, когда в успокоенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрислушаюсь я к лести восхвалений,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли предамся лени или сну,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли себя дурачить страсти дам, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПускай тогда в разгаре наслаждений\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне смерть придет!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗапомним!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо рукам!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва я миг отдельный возвеличу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВскричав: \u0026#171;Мгновение, повремени!\u0026#187; —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе кончено, и я твоя добыча,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мне спасенья нет из западни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда вступает в силу наша сделка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда ты волен,\u0026#160;— я закабален.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда пусть станет часовая стрелка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо мне раздастся похоронный звон.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмей в виду, я это все запомню.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе бойся, я от слов не отступлюсь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ отчего бы стал я вероломней?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь если в росте я остановлюсь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧьей жертвою я стану, все равно мне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ нынче ж на ученом кутеже\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвое доверье службой завоюю,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы ж мне черкни расписку долговую,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб мне не сомневаться в платеже.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе, педанту, значит, нужен чек\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ веры не внушает человек?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо если клятвы для тебя неважны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак можешь думать ты, что клок бумажный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПустого обязательства клочок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУдержит жизни бешеный поток?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаоборот, средь этой быстрины\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще лишь чувство долга только свято.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСознание того, что мы должны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолкает нас на жертвы и затраты.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто значит перед этим власть чернил?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня смешит, что слову нет кредита,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА письменности призрак неприкрытый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсех тиранией буквы подчинил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ж ты в итоге хочешь? Рассуди,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПером, резцом иль грифелем, какими\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧертами, где мне нацарапать имя?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа камне? На бумаге? На меди?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем ты горячишься? Не дури.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛистка довольно. Вот он наготове.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзволь тут расписаться каплей крови.\u003ca class=\"ref\" id=\"r45\" href=\"#n45\" data-tip=\"№45 \u0026#183; История о докторе Иоганне Фаусте (Шпис); Золотая легенда (Иаков Ворагинский) и др.\"\u003e45\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот вздор! Но будь по-твоему: бери.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакие-то ходульные условья!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКровь, надо знать, совсем особый сок.\u003ca class=\"ref\" id=\"r46\" href=\"#n46\" data-tip=\"№46 \u0026#183; Книга Левит; Второзаконие\"\u003e46\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвы, тебя я не надую.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ — твой, тебе принадлежу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаз обещаю к платежу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебя и жизнь свою пустую,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторой я не дорожу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем только я кичиться мог?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВеликий дух миропорядка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПришел и мною пренебрег.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрирода для меня загадка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ на познанье ставлю крест.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть вспомню книги — злоба ест.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтныне с головой нырну\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ страстей клокочущих горнило,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо всей безудержностью пыла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ пучину их, на глубину!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ горячку времени стремглав!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ разгар случайностей с разбегу!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ живую боль, в живую негу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ вихрь огорчений и забав!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть чередуются весь век\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСчастливый рок и рок несчастный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ неутомимости всечасной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебя находит человек.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо всех приманок снят запрет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, жаждой радостей терзаем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСрывая удовольствий цвет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе будь застенчивым кисляем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРви их смелее,\u0026#160;— мой совет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, право, ты неподражаем:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО радостях и речи нет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей о буре, урагане,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУгаре страсти разговор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тех пор как я остыл к познанью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ людям руки распростер.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ грудь печалям их открою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ радостям — всему, всему,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все их бремя роковое,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе беды на себя возьму.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ теченье многих тысяч лет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖую я бытия галет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо без изжоги и отрыжки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНельзя переварить коврижки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВселенная во весь объем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоступна только провиденью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ бога светозарный дом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы в беспросветной тьме живем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам, людям, дал он во владенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧередованье ночи с днем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я осилю все.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПохвально.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо жизнь, к несчастью, коротка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА путь до совершенства дальний,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНужна помощника рука.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозьми поэта на подмогу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть щедро он тебе привьет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе доблести по каталогу:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБесстрашье льва, оленя ход,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрасть итальянца, твердость шведа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго рецепту ты последуй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак претворить в одну черту\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвуличие и прямоту.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗатем со страстью первозданной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть влюбит он тебя по плану.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе мыслимое охвати,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтань микрокосмом во плоти.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто я такое, если я венца\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУсилий человеческих не стою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК которому стремятся все сердца?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы — то, что представляешь ты собою.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадень парик с мильоном завитков,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПовысь каблук на несколько вершков.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы — это только ты, не что иное.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтак, напрасно я копил дары\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюдской премудрости с таким упорством?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ ничего своим усердьем черствым\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобиться не сумел до сей поры.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи на\u0026amp;#769; волос не стал я боле крупен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМир бесконечности мне недоступен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы в близорукости не одинок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак смотрите вы все на это дело.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА нужен взгляд решительный и смелый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока в вас тлеет жизни огонек.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБольшой ли пользы истиной достигнешь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто, скажем, выше лба не перепрыгнешь?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, каждый получил свою башку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой зад, и руки, и бока, и ноги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо разве не мое, скажи, в итоге,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, из чего я пользу извлеку?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКупил я, скажем, резвых шестерню.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе я ли мчу ногами всей шестерки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда я их в карете разгоню?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэтому довольно гнить в каморке!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбъедем мир! Я вдаль тебя маню!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрось умствовать! Схоластика повадки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапоминают ошалевший скот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый мечется кругом в припадке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА под ногами сочный луг цветет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда ж махнем?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда глаза глядят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей оставим этот каземат.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДался тебе твой каменный застенок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде отдаешь ты силы за бесценок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ моришь скукой взрослых и ребят!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольно! Лучше предоставь собрату\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВодотолченье в ступе. Решено.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТого, что лучше всякого трактата,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРебятам ты не скажешь все равно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудента, кстати, вижу я в окно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас я занят. Он пришел не в пору.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ заменю тебя. Он ждет давно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в дом пущу его из коридора.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай шапку мне свою и балахон.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Переодевается.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, кажется, хорош в твоем костюме?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь все предоставим остроумью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы на минут пятнадцать выйди вон\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ позаботься о дорожных сборах.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст уходит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (один, в длинной одежде Фауста)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМощь человека, разум презирай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый более тебе не дорог!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай ослепленью лжи зайти за край,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ты в моих руках без отговорок!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНрав дан ему отчаянный и страстный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо всем он любит бешенство, размах.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт радостей земли он ежечасно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСрывается куда-то впопыхах.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ жизнь изведать дам ему в избытке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в грязь втопчу, и тиной оплету.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн у меня пройдет всю жуть, все пытки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсю грязь ничтожества, всю пустоту!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн будет пить — и вдоволь не напьется,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн будет есть,\u0026#160;— и он не станет сыт,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ если бы он не был черту сбыт,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн все равно пропал и не спасется.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит студент.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ здесь с недавних пор и рад\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа человека бросить взгляд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСнискавшего у всех признанье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кем гордятся горожане.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДушевно тронут и польщен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаких, как я, здесь легион.\u003ca class=\"ref\" id=\"r47\" href=\"#n47\" data-tip=\"№47 \u0026#183; Евангелие от Марка; Евангелие от Луки\"\u003e47\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы осмотрелись тут отчасти?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрошу принять во мне участье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля знанья не щадя души,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ к вам приехал из глуши.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня упрашивала мать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак далеко не уезжать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я мечтал о вашей школе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, здесь вы разовьетесь вволю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажу со всею прямотой:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне хочется уже домой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт здешних тесных помещений\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа мысль находит помраченье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКругом ни травки, ни куста,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь сумрак, шум и духота.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт грохота аудиторий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ глохну и с собой в раздоре.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут только в непривычке суть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ матери не сразу грудь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБерет глупыш новорожденный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА после не отнять от лона.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак все сильней когда-нибудь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы будете к наукам льнуть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо если с первого же шага\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо мне отбили эту тягу?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаметили вы или нет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПризвание и факультет?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б стать хотел большим ученым\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ овладеть всем потаенным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто есть на небе и земле.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕстествознаньем в том числе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ж, правильное направленье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе дело будет в вашем рвенье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ рад и телом и душой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВесь год работать напряженно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо разве будет грех большой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГулять порой вакационной?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУпотребляйте с пользой время,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУчиться надо по системе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСперва хочу вам в долг вменить\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа курсы логики ходить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВаш ум, нетронутый доныне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа них приучат к дисциплине,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб взял он направленья ось,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе разбредаясь вкривь и вкось.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто вы привыкли делать дома\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдиным махом, наугад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак люди пьют или едят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам расчленят на три приема\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на субъект и предикат.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ мозгах, как на мануфактуре,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсть ниточки и узелки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосылка не по той фигуре\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрозит запутать челноки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа тьму оставшихся вопросов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозьмется вслед за тем философ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ объяснит, непогрешим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак подобает докам тертым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто было первым и вторым\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ стало третьим и четвертым.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, даже генезис узнав\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаинственного мирозданья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вещества живой состав,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивой не создадите ткани.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо всем подслушать жизнь стремясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпешат явленья обездушить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабыв, что если в них нарушить\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдушевляющую связь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо больше нечего и слушать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Encheiresis naturae\u0026#187;\u003ca class=\"ref\" id=\"r48\" href=\"#n48\" data-tip=\"№48 \u0026#183; Institutiones chemiae (Шпильман); Elementa chemiae (Бургаве)\"\u003e48\u003c/a\u003e\u0026#160;— вот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак это химия зовет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе понял вас ни в малой доле.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоймете волею-неволей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля этого придется впредь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ редукции понатореть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКлассифицируя поболе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧас от часу не легче мне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ словно голова в огне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще всем этим не пресытясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа метафизику возьмитесь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридайте глубины печать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТому, чего нельзя понять.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасивые обозначенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас выведут из затрудненья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо более всего режим\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНалаженный необходим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтсидкою часов учебных\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобьетесь отзывов хвалебных.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХорошему ученику\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНельзя опаздывать к звонку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаучивайте на дому\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТекст лекции по руководству.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУчитель, сохраняя сходство,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВесь курс читает по нему.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все же с жадной быстротой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаписывайте мыслей звенья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто эти откровенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПродиктовал вам дух святой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ это знаю и весьма\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦеню значение письма.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзображенное в тетради\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ вас, как в каменной ограде.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой же факультет избрать?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаконоведом мне не стать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот поприще всех бесполезней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут крючкотворам лишь лафа.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСедого кодекса графа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак груз наследственной болезни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИной закон из рода в род\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт деда переходит к внуку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн благом был, но в свой черед\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтал из благодеянья мукой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся суть в естественных правах.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА их и втаптывают в прах.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, мне юристом не бывать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ отношусь к ним с нелюбовью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтдамся лучше богословью.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО нет, собьетесь со стези!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаука эта — лес дремучий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе видно ничего вблизи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИсход единственный и лучший:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрофессору смотрите в рот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ повторяйте, что он врет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасительная голословность\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзбавит вас от всех невзгод,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоможет обойти неровность\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в храм бесспорности введет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДержитесь слов.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, но словам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь соответствуют понятья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем в них углубляться вам?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСовсем ненужное занятье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБессодержательную речь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда легко в слова облечь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз голых слов, ярясь и споря,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозводят здания теорий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСловами вера лишь жива.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак можно отрицать слова?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростите, я вас отвлеку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я расспросы дальше двину:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе скажете ли новичку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мне смотреть на медицину?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТри года обученья — срок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо совести, конечно, плевый.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б многого достигнуть мог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмей я твердую основу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (про себя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ выдохся как педагог\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ превращаюсь в черта снова.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Вслух.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмысл медицины очень прост.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот общая ее идея:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе в мире изучив до звезд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе за борт выбросьте позднее.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем трудить мозги напрасно?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВаляйте лучше напрямик.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто улучит удобный миг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот и устроится прекрасно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы стройны и во всей красе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВаш вид надменен, взгляд рассеян.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ того невольно верят все,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто больше всех самонадеян.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтупайте к дамам в будуар.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни — податливый товар.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх обмороки, ахи, охи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдышки и переполохи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛечить возьмитесь не за страх —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все они у вас в руках.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы так почтенны в их оценке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХозяйничайте ж без стыда,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак наклоняясь к пациентке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак жаждет кто-нибудь года.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИсследуя очаг недуга,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРукой проверьте, сердцеед.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе слишком ли затянут туго\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа страждущей ее корсет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот эта область неплоха.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь гораздо ближе мне вы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеория, мой друг, суха,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо зеленеет жизни древо.\u003ca class=\"ref\" id=\"r49\" href=\"#n49\" data-tip=\"№49 \u0026#183; Книга Бытия; Книга Притчей Соломоновых\"\u003e49\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт вас я просто как в чаду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вновь когда-нибудь приду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПослушать ваши рассужденья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы сделали б мне одолженье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУжель ни с чем идти домой?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ воспоминанье о приеме\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставьте росчерк ваш в альбоме.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе откажусь. Вот вам автограф мой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Делает надпись в альбоме и возвращает его студенту.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтудент  (читает)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eEritis sicut Deus, scientes bonum et malum.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Почтительно закрывает альбом и откланивается.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗмеи, моей прабабки, следуй изреченью.\u003ca class=\"ref\" id=\"r50\" href=\"#n50\" data-tip=\"№50 \u0026#183; Книга Бытия\"\u003e50\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодобье божие утратив в заключенье!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит Фауст.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда же мы теперь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ любой поход.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ большой и малый свет. И ты не хмурься!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС каким восторгом после всех экскурсий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы сдашь по этим странствиям зачет!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако, видишь, я длиннобород.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва ли пользу принесет поездка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне стыдно малости своей средь блеска\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ легкомыслия недостает.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в жизни не умел усвоить лоска\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в обществе застенчивей подростка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотрешься меж людьми и, убежден,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУсвоишь независимость и тон.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо как мы пустимся в поездку эту?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде лошади, где кучер, где карета?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ расстелю пошире пелерину\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ предоставлю моему плащу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо воздуху унесть нас на чужбину.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС большим узлом тебя я не пущу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вещество такое берегу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб к небу подняло нас, как пушинку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоздравить с жизнию тебя могу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторая тебе еще в новинку.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r51\" href=\"#n51\" data-tip=\"№51 \u0026#183; Фрески Погреба Ауэрбаха; История о докторе Иоганне Фаусте (Шпис)\"\u003e51\u003c/a\u003eПогреб Ауэрбаха в Лейпциге\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКомпания веселящихся гуляк.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНикто не пьет? Притихло пенье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе слышно смеха? Чур вас, чур!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРебята просто загляденье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА скисли хуже мокрых кур.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоя вина. Над чем смеяться?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы здесь за главного паяца.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош  (выливая стакан вина ему на голову)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак вот тебе!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ, лоботряс!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь сам ты требуешь проказ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез ссор! Зачинщиков — долой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПошире грудь! Шуми и пой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаткнуть бы паклей уши. Оглушил!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОрет, горластый, не жалея сил!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа то и баса интервал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб содрогался весь подвал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКому не нравится,\u0026#160;— тех вон!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТа-ри-ра-ра!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТа-ри-ра-ра!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРев глоток и стаканов звон.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Поет.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсей Римскою империей Священной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы долго устоим ли во вселенной?\u003ca class=\"ref\" id=\"r52\" href=\"#n52\" data-tip=\"№52 \u0026#183; О состоянии Германской империи (Пуфендорф)\"\u003e52\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДрянь песня, политический куплет!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагодарите бога, обормоты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто до империи вам дела нет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ что другие есть у вас заботы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ рад, что я не государь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не имперский секретарь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА просто выпивший растяпа.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо так как нужен нам главарь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ предлагаю выбрать папу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПорядком, утвержденным встарь.\u003ca class=\"ref\" id=\"r53\" href=\"#n53\" data-tip=\"№53 \u0026#183; Хроника Мартина Опавского; Поэзия и правда (Гёте)\"\u003e53\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош  (поет)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоловей ты мой, звеня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзвейся к небосклону,\u003ca class=\"ref\" id=\"r54\" href=\"#n54\" data-tip=\"№54 \u0026#183; Schwing dich auf, Frau Nachtigall (народная песня); Ambraser Liederbuch\"\u003e54\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоей милке от меня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтнеси поклоны.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНикаких вам милок!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС милками шабаш!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОчень ты уж пылок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоевода наш!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Поет.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрюк с дверей! Кругом ни зги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрюк с дверей! Его шаги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДверь на крюк! Скорей! Беги!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа что такая девушкам хвала?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто в них нашли вы, бабьи подголоски?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостаточно я знаю их дела:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбманщицы они и вертихвостки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть попадется в образе козла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоей подружке черт на перекрестке!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть тихим вечерком, когда она\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ окошко глазки делает мужчинам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй с Блоксберга проблеет сатана\u003ca class=\"ref\" id=\"r55\" href=\"#n55\" data-tip=\"№55 \u0026#183; Blockes-Berges Verrichtung (Преториус); Немецкая мифология (Гримм)\"\u003e55\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Спокойной ночи\u0026#187; голосом козлиным!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС хорошим парнем девка холодна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн больно прост для этой крови рыбьей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не поклоны, я ей окна выбью!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер  (ударяя кулаком по столу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВниманье! Тише, господа!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ знаю жизнь, и я замечу:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВлюбленные пришли сюда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОзнаменуем нашу встречу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот песня на новейший лад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодтягивайте все подряд.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Поет.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВодилась крыса в погребке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПиталась ветчиною,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак Лютер, с салом на брюшке\u003ca class=\"ref\" id=\"r56\" href=\"#n56\" data-tip=\"№56 \u0026#183; Портреты Лютера (Кранах); Застольные речи (Лютер)\"\u003e56\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ два пальца толщиною.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодсыпали ей мышьяку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ впала тут она в тоску,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак от любви несчастной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор  (с присвистом)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак от любви несчастной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна обшмыгала углы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбегала канавы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзгрызла стены и полы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь пуще жгла отрава.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе помогали ей прыжки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПришлось ей присмиреть с тоски,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак от любви несчастной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак от любви несчастной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда, вбежав средь бела дня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа кухню из подвала,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез жизни крыса у огня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБарахтаясь, упала.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавай кухарка хохотать:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Пришел тебе капут, видать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак от любви несчастной!\u0026#187;\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак от любви несчастной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот дурни! Рады горло драть!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНашли хорошую кантату\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО том, как крыс уничтожать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС каких ты пор за них ходатай?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн с горя тоже хвост поджал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлешивец этот толстобрюхий!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой случай сразу он узнал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ словах о крысе и стряпухе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходят Фауст и Мефистофель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы входим, видишь, первым делом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ кабак к гулякам очумелым.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе унывать — важней всего,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА тут что день, то торжество.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь с неба не хватают звезд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо веселятся до упаду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак малые котята рады,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВертясь весь день, ловить свой хвост.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНемного надо для веселья:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавали б в долг из кабака\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа оставалась бы легка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаутро голова с похмелья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНовоприезжие,\u0026#160;— смотрите,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ — час, не больше, по прибытье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх удивленье выдает.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, из какой-нибудь трущобы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА Лейпциг — маленький Париж.\u003ca class=\"ref\" id=\"r57\" href=\"#n57\" data-tip=\"№57 \u0026#183; Поэзия и правда (Гёте)\"\u003e57\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа здешних всех налет особый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз тысячи нас отличишь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА эти из каких же мест?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ поднесу им по стакану\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, только угощать их стану,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУзнаю все про их приезд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне думается, из господ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВид несговорчивый и чванный.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаведомые шарлатаны.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу да!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВниманье! Видит бог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ подниму их на зубок.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (Фаусту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧерт рядом, а на то нет смётки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть прямо их хватай за глотки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдорово, господа.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС хорошим днем!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Про себя, взглянув искоса на Мефистофеля.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн на ногу одну как будто хром.\u003ca class=\"ref\" id=\"r58\" href=\"#n58\" data-tip=\"№58 \u0026#183; Немецкая мифология (Гримм); Илиада (Гомер)\"\u003e58\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНельзя ли к вам подсесть? Хоть заведенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе может, кажется, хвастнуть вином,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам ваше общество вознагражденье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы слишком прихотливый человек.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе вы ли, в Риппах въехав на ночлег,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС Иванушкою-дурачком видались?\u003ca class=\"ref\" id=\"r59\" href=\"#n59\" data-tip=\"№59 \u0026#183; Саксонские студенческие словари XVIII в.\"\u003e59\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы с ним сегодня утром повстречались.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ чуть я не забыл его приказ:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтвезть поклон родне просил он нас.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Кланяется Фрошу.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер  (тихо)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто, съел?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ рот пальца не клади, откусит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, погоди! Так напущусь, что струсит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы слышали, спускаясь в погребок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак пели вы до нашего прихода.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля пенья здесь прекрасный потолок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазносят звуки гулко эти своды.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажите, часом, вы не виртуоз?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбитель, но почти что безголос.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак спойте что-нибудь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не в ударе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я готов.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз песен поновей!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы прямо из Испанских Пиреней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтраны хороших вин и нежных арий.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Поет.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖил-был король державный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС любимицей блохой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС блохой? Вот это так! Хвалю, хвалю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлоха — прямая пара королю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (поет)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖил-был король державный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС любимицей блохой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн был ей друг исправный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗащитник неплохой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ объявил он знати:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Портному прикажу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй сшить мужское платье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак первому пажу\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПортному не забудьте приказать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод страхом смерти соблюдать порядок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКроить по мерке и не припускать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб на блохе сидело все без складок.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (поет)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот блоха в одежде,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся в бархате, в шелку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвезда, как у вельможи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ шпага на боку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСенаторского чина\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтличья у блохи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС блохой весь род блошиный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроходит на верхи.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ всех следы на коже,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо жаловаться страх,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть королева тоже\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ укусах и прыщах.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлохи не смеют трогать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе боится двор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА мы блоху под ноготь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кончен разговор!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор  (с ликованием)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА мы блоху под ноготь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кончен разговор.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот это песня! Браво!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоре блохам!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ нас им верховодить не дано.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНацелился, поймал, и — смерть пройдохам!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа здравствует свобода и вино!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ за свободу выпил бы не споря,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа ваши вина смех один и горе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе сметь так выражаться! Клевета!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБоюсь обидеть этим принципала,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то б я дал отведать вам сорта\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз собственного нашего подвала.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе бойтесь. Я заглажу ваш конфуз.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы вино определить на вкус,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ должен им наполнить рот до нёба.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэтому полней давайте пробы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИначе ошибиться я боюсь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер  (тихо)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСомненья нет, что эти люди с Рейна.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБурава нет ли?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА на что он вам?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж разве бочки у дверей питейной?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот сверла в ящике и всякий хлам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (взявши бурав, Фрошу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакого же вина вам выпить любо?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак вас понять? Ваш выбор так велик?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто что захочет — и получит вмиг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер  (Фрошу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты уже облизываешь губы?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда мне рейнского. Я патриот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХлебну, что нам отечество дает.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (высверливая дыру в столе перед Фрошем)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНемного воску для заделки дыр!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы видите, он фокусник, факир.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (Брандеру)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вам чего?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШампанского, пожалуй.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб пена через край бежала.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель буравит. Один из гостей, сделав восковые пробки, затыкает отверстия.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем во всем чуждаться иноземцев?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсть и у них здоровое зерно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФранцузы не компания для немцев,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо можно пить французское вино.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель  (видя, что Мефистофель приближается к его месту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ кислых вин не пью. Моя лоза\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолжна всех слаще быть в саду хозяйском.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (буравит)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда что скажете вы о токайском?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, честно посмотрите нам в глаза.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы нас хотите просто околпачить?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа как бы я осмелился дурачить\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаких больших, значительных людей?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтак, извольте сами мне назначить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто вам угодно из моих питей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто знаете, но только поскорей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (со странными телодвижениями)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВиноград тяжел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ рогат козел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуст, листок, лоза и ствол\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько разветвленья смол,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак и деревянный стол.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗахотеть, и из досок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХлынет виноградный сок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто чудо, ткань жива,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе кругом полно родства,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, пробки вон, и пейте на здоровье!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе  (вытаскивают пробки; требуемое каждым вино льется в стаканы)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, чудный ключ-ручей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТекущий из щелей!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи капли не пролейте, вот условье!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни пьют еще по стакану.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе  (поют)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаздолье и блаженство нам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в луже свиньям пятистам!\u003ca class=\"ref\" id=\"r60\" href=\"#n60\" data-tip=\"№60 \u0026#183; Евангелие от Марка\"\u003e60\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (Фаусту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри, как разошелся этот сброд!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУйдем, мне надоело в этом месте.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, нет, понаблюдаем этих бестий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокамест распояшется народ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо нечаянности Зибель плещет вино наземь. Оно загорается.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОгонь! Из ада пламя! Караул!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (заклиная пламя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтихия милая, смири разгул!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Обращаясь к обществу.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, это лишь чистилищное пламя.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставьте ваши фигли-мигли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы ваш обман насквозь постигли!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожалуйста, нас не морочь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШел подобру бы лучше прочь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы вам фиглярских выкрутас\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе спустим в следующий раз!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолчать, пивная кадь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, помело,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще грубьянит, подлое мурло!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ нас с ним будет коротка расправа!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер вынимает пробку из стола, оттуда вырывается огонь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАй-ай, горю! Горю!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПостой, лукавый!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, вот ты, значит, кто! Бей колдуна!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБей! Голова его оценена.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВынимают ножи и бросаются на Мефистофеля.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (предостерегающе)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт дурмана с беленой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод туманной пеленой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь вы и в стране иной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе останавливаются, глядя в удивлении друг на друга.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе как во сне! Где я? Чудесный край!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДушистый виноград! Лицо приблизьте.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ хоть охапками его хватай!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак гроздья отягчают листья!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Хватает Зибеля за нос. Другие делают то же самое и подымают ножи.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (по-прежнему)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРассейтесь, чары столбняка!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в памяти у вас останусь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Исчезает вместе с Фаустом. Оставшиеся отскакивают в разные стороны.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто это?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоя щека?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер  (Зибелю)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА мы друг друга держим за нос?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодай мне стул. Мне тяжело.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ падаю. Всего свело.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ все-таки бы знать хотел:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто тут все это означало?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде негодяй? Найду нахала,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж больше не уйдет он цел!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ видел, как он в дверь подвала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВерхом на бочке улетел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ как без ног, и сердце бьется.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Оборачивается к столу.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА что, вино из дырок льется?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗибель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, надувательство одно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФрош\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА кажется, что пил вино.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрандер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу вот. А виноград откуда?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАльтмайер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, как теперь не верить в чудо?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r61\" href=\"#n61\" data-tip=\"№61 \u0026#183; Zauberey (гравюра Михаэля Герра)\"\u003e61\u003c/a\u003eКухня ведьмы\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа огне низкого очага стоит большой котел. В подымающихся над ним парах мелькают меняющиеся призраки. У котла мартышка-самка снимает пену и смотрит, чтобы котел не перекипел. Мартышка-самец с детенышами сидят рядом и греются. Стены и потолок кухни увешаны странными принадлежностями ведьминого обихода.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня тошнит, и вянут уши.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе этой тарабарской чушью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт грустных дум меня отвлечь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе старой бабе и кликуше\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне три десятка сбросить с плеч.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ если у самой природы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет средства мне вернуть покой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо нет моей хандре исхода\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ нет надежды никакой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы снова рассуждаешь здраво.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсть средство посильней питья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо то — особая статья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва ль оно тебе по нраву.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто это?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпособ без затрат,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез ведьм и бабок долго выжить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозделай поле или сад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозьмись копать или мотыжить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗамкни работы в тесный круг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайди в них удовлетворенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсю жизнь кормись плодами рук,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкотине следуя в смиренье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВставай с коровами чуть свет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотей и не стыдись навоза —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя на восемьдесят лет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОмолодит метаморфоза.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖить без размаху? Никогда!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе пристрастился б я к лопате,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК покою, к узости понятий.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот, значит, в ведьме и нужда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем нам обращаться к бабе?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПитья б ты сам сварить не мог?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКухарничать не мой конек.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ навожу мосты над хлябью.\u003ca class=\"ref\" id=\"r62\" href=\"#n62\" data-tip=\"№62 \u0026#183; Немецкие саги (братья Гримм)\"\u003e62\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГотовить вытяжку из трав —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТруд непомерного терпенья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеобходим спокойный нрав,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб выждать много лет броженья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут к месту кропотливый дар,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредмет по-женски щепетилен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть черт учил варить отвар,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо сам сварить его бессилен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Заметив зверей.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзгляни на миленьких зверей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот горничная. Вот лакей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Зверям.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХозяйки, видно, нет в квартире?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвери\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна на пире.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХвать вьюшку за скобу —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ фюить в трубу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе шляется по ассамблеям?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвери\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока мы лапы греем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ты зверенышей нашел?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСама нелепость и безвкусье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапрасно! С ними я провел\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧасы приятнейших дискуссий.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Зверям.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто, малыши, у вас кипит?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой попахивает пищей?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвери\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПохлебкою для братьи нищей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, так у вас широкий сбыт!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСамец  (приблизившись к Мефистофелю и подлизываясь к нему)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСыграем в очко,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то нелегко\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа тощий желудок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА выставишь грош,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДеньгу зашибешь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОкрепнет рассудок.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще бы! Выиграв в лото,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы будешь счастлив как никто!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДетеныши, играя, выкатывают на середину комнаты большой шар.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСамец\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот шар земной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак заводной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКубарь негромкий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнутри дупло.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн, как стекло,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПустой и ломкий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот здесь пятно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсвещено,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА здесь потемки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой сын, постой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоей судьбой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ жизнью шутишь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаскатишь зря,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет кубаря,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не закрутишь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем тут несколько решет?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСамец  (снимая решето)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСквозь лубяной их переплет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебя преступник выдает.\u003ca class=\"ref\" id=\"r63\" href=\"#n63\" data-tip=\"№63 \u0026#183; Идиллии (Феокрит); Адагии (Эразм Роттердамский) и др.\"\u003e63\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Подбегает к самке и заставляет ее посмотреть сквозь решето.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖена уж вора уличила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа страшно вслух назвать громилу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (приближаясь к огню)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА для чего горшок?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСамец и самка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой дурачок!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕму невдомек\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКотла примененье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоршка назначенье!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДурной ответ,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вы — нахалы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСамец\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот веник вместо опахала,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСадитесь, вот вам табурет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Предлагает Мефистофелю сесть.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (глядевший тем временем в зеркало, то приближаясь к нему, то удаляясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто этот облик неземной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВолшебным зеркалом наводит?\u003ca class=\"ref\" id=\"r64\" href=\"#n64\" data-tip=\"№64 \u0026#183; Христовомыслящий (Пфицер); Илиада (Гомер)\"\u003e64\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбовь, слетай туда со мной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткуда этот блеск исходит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто эта женщина вдали?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУменьшится ли расстоянье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИль образ на краю земли\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда останется в тумане?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ неужели не обман,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ что-то вправду есть на свете,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак бесподобный этот стан,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ голова, и руки эти?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще бы! Бог, трудясь шесть дней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на седьмой воскликнув \u0026#171;браво\u0026#187;,\u003ca class=\"ref\" id=\"r65\" href=\"#n65\" data-tip=\"№65 \u0026#183; Книга Бытия\"\u003e65\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМог что-нибудь создать на славу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокаместь полюбуйся ей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я почище грез твоих\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе сокровище добуду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ счастлив будет тот жених,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто раздобудет это чудо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст по-прежнему смотрит в зеркало.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель, дотягиваясь и обмахиваясь веником, продолжает:\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, как король, на вас взираю с трона.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот скипетр мой, и только нет короны.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвери  (проделывавшие между тем странные телодвижения, с криком несут Мефистофелю расщепившуюся надвое корону)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКорону сдави,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ поту, на крови\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкрепи, словно клеем.\u003ca class=\"ref\" id=\"r66\" href=\"#n66\" data-tip=\"№66 \u0026#183; Дело об ожерелье (1785); Великий Кофта (Гёте)\"\u003e66\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Неловкими движениями разваливают корону и прыгают с ее обломками.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот мы скорбим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ прозой вопим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в рифму умеем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (перед зеркалом)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПропал! Я как в бреду.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (указывая на зверей)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ тоже, кажется, с ума сойду.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвери\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА если меж строк\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсть смысла намек,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда нам удача.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (как выше)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ страстию объят горячей!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУйдем отсюда поскорей!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (в прежнем положении)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗверюги эти, истины не пряча,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть откровенней многих рифмачей!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо недосмотру самки котел перекипает. В пламени, которое выкидывает наружу, в кухню с диким воем спускается ведьма.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАй-ай-ай-ай!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗеваешь, негодяйка?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолучишь нагоняй!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОшпарила хозяйку!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВода из шайки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУходит через край!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Заметив Фауста и Мефистофеля.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА это кто,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКопыл вам в бок?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто вас позвал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК нам на порог?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вам скандал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧинить не дам!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа шум и гам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОгнем обдам!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Сунув шумовку в котел, обрызгивает всех воспламеняющейся жидкостью. Звери визжат.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (ручкой веника бьет посуду)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мы содом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроизведем —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ поделом!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмей в виду!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе в прах, все вдрызг!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ, василиск!\u003ca class=\"ref\" id=\"r67\" href=\"#n67\" data-tip=\"№67 \u0026#183; Естественная история (Плиний); Физиолог\"\u003e67\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодымешь визг!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не твою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосуду бью, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ под твою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПляшу дуду!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма отступает в ярости и ужасе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе узнаешь? А я могу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтереть, как твой прямой владыка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС лица земли тебя, каргу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС твоею обезьяньей кликой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабыла красный мой камзол?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтоишь с небрежным равнодушьем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред моим пером петушьим?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе видишь, кто к тебе пришел?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлепа, простите за прием!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо что ж не вижу я копыта?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде вороны из вашей свиты?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрощаю. В промахе твоем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВиновна долгая разлука.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО том не пророню ни звука.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе в мире изменил прогресс.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак быть? Меняется и бес.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАрктический фантом не в моде,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогтей ты не найдешь в заводе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРога исчезли, хвост исчез.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС копытом вышел бы скандал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б по форме современной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ от подъема до колена\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебе гамаш не заказал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма  (приплясывая)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ просто обворожена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас видя, душка-сатана!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайди другие имена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА это мне вредит во мненье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто вредного в его значенье?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть в мифологию оно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавным-давно занесено,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо стало выражать презренье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗлодеи — разговор иной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТех чтут, но плохо с сатаной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы можешь звать меня бароном,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я, как всякий князь и граф,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа то имея больше прав,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоржусь своим гербом исконным.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Делает неприличный жест.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма  (смеясь во все горло)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХа-ха-ха-ха! Года идут,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вы все тот же шелапут!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (Фаусту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе эти ведьмы льнут ко мне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУчись, как с ними обходиться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем я могу вам пригодиться?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНужда у нас в твоем вине,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо не в таком, что в обращенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА старого изготовленья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакое действует вдвойне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот есть немножко во флаконе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПонюхайте, какой букет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь оно совсем без вони.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ пью. Налить и вам, сосед?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Тихо Мефистофелю.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧужому вредно, если не пивал:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУложит с непривычки наповал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕму не повредит и штоф,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе только то, что тут в стакане.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧерти свой круг, тверди чуранье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ чашу полни до краев.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма со странными движениями проводит круг и ставит в него разные предметы. Горшки и миски начинают звенеть в музыкальном согласии. Ведьма достает большую книгу, ставит мартышек в середину круга, кладет книгу одной из них на спину, а другим дает в руки горящие факелы. Кивает Фаусту, чтобы он подошел.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (Мефистофелю)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто за раденье обезьянье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖестикуляция, кривлянье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ знаю цену этой лжи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК чему мне это все, скажи?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрофесьональная забава\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВрачующей. Не будь к ней строг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть думает, что без приправы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДействителен не будет сок.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Убеждает Фауста вступить в круг.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма  (напыщенно декламируя по книге)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы из одной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДесятку строй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА двойку скрой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО ней не вой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай тройке ход,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб стала чёт,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ты богач.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧетверку спрячь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО ней не плачь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА пять и шесть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС семеркой свесть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ до восьми\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх подыми.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДевятка — кон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДесятку — вон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот ведьмина таблица умноженья.\u003ca class=\"ref\" id=\"r68\" href=\"#n68\" data-tip=\"№68 \u0026#183; Оккультная философия (Агриппа)\"\u003e68\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаруха бредит в исступленье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО дорогой мой, погоди,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе это лишь еще цветочки!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще что будет впереди!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ книгу изучил до точки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все ж, представь, ни в зуб толкнуть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСогласие противоречий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля головы моей овечьей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНепроницаемая муть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВеками ведь, за годом год,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз тройственности и единства\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТворили глупые бесчинства\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ городили огород.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА мало ль вычурных систем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозникло на такой основе?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлупцы довольствуются тем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто видят смысл во всяком слове.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма  (продолжая)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаук зерно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПогребено\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод слоем пыли.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто не мудрит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем путь открыт\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез их усилий.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, кажется, с ума сойду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт этих диких оборотов!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто сотня идиотов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорланит хором ерунду.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольно, мудрая сивилла!\u003ca class=\"ref\" id=\"r69\" href=\"#n69\" data-tip=\"№69 \u0026#183; Энеида (Вергилий); Сивиллины книги\"\u003e69\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНалей-ка другу пополней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГляди, он не младенец хилый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн и по этой части сила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМагистр всех пьяных степеней.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма с видом священнодействия наливает питье в чашку. Когда Фауст подносит его к губам, оно загорается.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Фаусту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПей, пей от сердца полноты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокуда чувства оживятся!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы с дьяволом самим на \u0026#171;ты\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе ли пламени бояться?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма размыкает круг. Фауст выходит из него.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ дорогу! Двигайся, не стой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПомочь душою рада всею.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (ведьме)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ Вальпургиеву ночь с тобой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобром сквитаться я сумею.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот песенка, мурлычьте в нос,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб пользу эликсир принес.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПойдем, нельзя без моциона.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы должен весь пропреть насквозь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся суть наливки потогонной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб тело жару набралось.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрогулка действие ускорит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы будешь словно возрожден,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда тебя всего разморит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриятной ленью Купидон.\u003ca class=\"ref\" id=\"r70\" href=\"#n70\" data-tip=\"№70 \u0026#183; Метаморфозы (Овидий); Золотой осёл (Апулей)\"\u003e70\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе торопи меня, указчик!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт зеркала мне не уйти.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставь! Ты женщин всех образчик\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвидишь скоро во плоти.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(В сторону.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлотнув настойки, он Елену\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо всех усмотрит непременно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eУлица\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст. Маргарита проходит мимо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРад милой барышне служить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНельзя ли мне вас проводить?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ и не барышня и не мила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДойду без спутников домой, как шла.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Увернувшись, уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО небо, вот так красота!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в жизни не видал подобной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак неиспорченно-чиста\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ как насмешливо-беззлобна!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБагрянец губ, румянец щек,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ их вовеки не забуду!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесмело покосилась вбок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотупив взор,\u0026#160;— какое чудо!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА как ответила впопад!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, это прелесть, это клад!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит Мефистофель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСведи меня с той девушкой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС которой?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторую я на углу настиг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна сейчас лишь вышла из собора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде отпустил грехи ей духовник.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ исповедь подслушал, в ту же пору\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа нею тайно прошмыгнувши вслед.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй исповедоваться нет причины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна, как дети малые, невинна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ у меня над нею власти нет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй более четырнадцати лет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы судишь, как какой-то селадон.\u003ca class=\"ref\" id=\"r71\" href=\"#n71\" data-tip=\"№71 \u0026#183; Астрея (д\u0026#39;Юрфе)\"\u003e71\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвидят эти люди цвет, бутон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тотчас же сорвать его готовы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе в мире создано для их персон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля них нет в жизни ничего святого.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНельзя так, милый. Больно ты востер.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапрасный труд, мой милый гувернер.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ обойдусь без этих наставлений.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вот что заруби-ка на носу:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ эту ненаглядную красу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ своих объятьях нынче унесу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли расторгну наше соглашенье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто можно сделать в однодневный срок?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы для встреч изобрести предлог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ то я попросил бы две недели.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудь семь часов покоя мне даны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б не нуждался в кознях сатаны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб совратить столь молодое зелье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы говоришь, как сластолюб француз,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрошу меня не торопить, однако.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе понимаю, право, что за вкус\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ глотанье наспех лакомства, без смаку?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриятно то, что отдаляет цель:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУлыбки, вздохи, встречи у фонтана,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПечаль томленья,\u0026#160;— словом, канитель,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторою всегда полны романы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой аппетит и без того хорош.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, не шутя, горячку надо сбавить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДитя ты это силой не возьмешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут надо изловчаться и лукавить.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай что-нибудь мне от нее. Хоть брошь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ее груди, подвязку с ног, наколку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСведи меня тайком в ее светелку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорее! Не вводи меня в беду!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, если это правда страсть такая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто умолять приходится в бреду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСегодня же, мгновенья не теряя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в комнату ее тебя сведу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ней свидеться? Обнять ее?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО нет!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна пойдет наведаться к соседке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты упиться сможешь на разведке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМечтой о месте будущих побед.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас же и пойдем?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, слишком рано.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодарок для нее достать успей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодарок? Обязательно достану.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн понимает, как подъехать к ней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь много старых кладов близ церквей.\u003ca class=\"ref\" id=\"r72\" href=\"#n72\" data-tip=\"№72 \u0026#183; История о докторе Иоганне Фаусте (Шпис)\"\u003e72\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзгляну я, все ль они еще сохранны.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eВечер\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаленькая опрятная комната. Маргарита заплетает косу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б дорого дала, открой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне кто-нибудь, кто тот чужой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ незнакомца важный вид.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн, надо думать, родовит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то б так смело и беспечно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе говорил он с первой встречной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель и Фауст.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойди, не бойся ничего.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (после некоторого молчания)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставь меня здесь одного.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (оглядывая комнату)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПорядок у нее какой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (осматриваясь кругом)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбимой девушки покой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвятилище души моей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа мирный лад меня настрой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоею тишиной обвей!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНевозмутимость, тишь да гладь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольство жизнью трудовой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКладут на все свою печать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНалет неизгладимый свой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Бросается в кожаное кресло у постели.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, кресло дедов, патриарший трон!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак гомозились, верно, ребятишки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВокруг тебя, когда семьи патрон\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь опускался в старческой одышке?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА внучка отделялась от кружка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолпившихся пред елкою товарок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ целовала руку старика\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ признательность за святочный подарок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО девушка, как близок мне твой склад!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи пятнышка кругом! Как аккуратно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазложен по столу узорный плат\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ как песком посыпан под опрятно!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы превратила скромный уголок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРукою чудотворною в чертог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА здесь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Открывает полог кровати.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ весь охвачен чудной дрожью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧасами бы стоял я здесь один,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа ложе глядя и на балдахин,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде созданный природой ангел божий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСначала развивался, как дитя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ подрастал, играя и шутя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вдруг, созрев душевно и телесно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтал воплощеньем красоты небесной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты зачем пришел сюда?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаким ты не был никогда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем ты взволнован? Чем терзаем?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, Фауст, ты неузнаваем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДыханье мира и добра\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмерило твои влеченья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеужто наши настроенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоздушных веяний игра?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б она, не чая зла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас бы в комнату вошла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ каком бы страхе и смущенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы бросился бы на колени!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (входя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивее вон! Она войдет сейчас.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБежим! Дай кину взгляд в последний раз!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри, как тяжела шкатулка эта.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы девушке ее поставим в шкаф.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ней драгоценности и самоцветы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна с ума сойдет, их увидав.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут безделушки для твоей вострушки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА дети ой как падки на игрушки!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА честно ль это?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот так оборот!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, может быть, присвоить хочешь ящик?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСказал бы это наперед,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы меня избавить от хлопот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда ты добродетели образчик.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Ставит шкатулку в шкаф и запирает дверцу.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБашку ломаешь для его персоны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз кожи лезешь вон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА он,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК возлюбленной стремящийся влюбленный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтоит как пень,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто в свой учебный день\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМетафизическую дребедень\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖует в лекцьонном зале полусонно!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорее прочь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУходят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит Маргарита с лампой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в спальне тяжело дышать!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Отворяет окно.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА на дворе не жарко, тихо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей бы воротилась мать!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне кажется, что неспроста\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакая в доме духота.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакая я еще трусиха!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Начинает раздеваться и напевает.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКороль жил в Фуле дальней,\u003ca class=\"ref\" id=\"r73\" href=\"#n73\" data-tip=\"№73 \u0026#183; География (Страбон); Георгики (Вергилий) и др.\"\u003e73\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кубок золотой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХранил он, дар прощальный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозлюбленной одной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда он пил из кубка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОглядывая зал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн вспоминал голубку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ слезы проливал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в смертный час тяжелый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемель он отдал тьму\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаследнику престола,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА кубок — никому.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо свитой в полном сборе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн у прибрежных скал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ своем дворце у моря\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрощальный пир давал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кубок свой червонный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсушенный до дна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн бросил вниз с балкона,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде выла глубина.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тот миг, когда пучиной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл кубок поглощен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПришла ему кончина,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ больше не пил он.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Отпирает шкаф, чтобы повесить платье, и замечает шкатулку.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткуда этот милый сундучок?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак он здесь очутился? Просто чудо!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ шкаф замкнула, помню, на замок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверно, мать взяла его в залог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКому-нибудь давая денег в ссуду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вот и ключ. Что может быть внутри?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткрою-ка. В том нет греха большого,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО господи! Смотри-ка ты, смотри,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ отроду не видела такого!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУбор знатнейшей барыне под стать!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз золота и серебра изделья!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКому б они могли принадлежать?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, только бы примерить ожерелье!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Надевает драгоценности и становится перед зеркалом.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, мне б такую парочку серег!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ них сразу кажешься гораздо краше.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто толку в красоте природной нашей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда наряд наш беден и убог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз жалости нас хвалят в нашем званье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся суть в кармане,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе — кошелек,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА нам, простым, богатства не дал бог!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eНа прогулке\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст прохаживается, погруженный в раздумье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК нему подходит Мефистофель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПостылые! Исчадья преисподней!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне жаль, что нет ругательств попригодней.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа что с тобой? Что у тебя за вид?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя какая муха укусила?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б чертыхался на чем свет стоит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда бы не был сам нечистой силой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот сумасшедший! Что за кипяток!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе горячись! Здоровье б поберег!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодумай, у попа шкатулка наша!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе это Маргаритина мамаша.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь глянула — и на пол чуть не бах,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакой напал на богомолку страх.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна благочестивая матрона.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо праздникам поет святым каноны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез промаха ее наводит нюх,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде чистый скрыт и где нечистый дух.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмекнула, поглядев на изобилье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто невидали этой не святили,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ говорит: \u0026#171;Дитя, не тронь серег.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеправое имущество не впрок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожертвуем-ка эти украшенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаступнице небесной в приношенье\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДочь смотрит на каменьев перелив\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ думает: \u0026#171;Ужель так нечестив\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДаритель и его проступок грубый?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДареному коню не смотрят в зубы\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл совещаться вызван капеллан,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ он одобрил материнский план.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Вы приняли разумное решенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМир вашей добродетельной душе:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто жадность победил, тот в барыше.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА церковь при своем пищеваренье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлотает государства, города\u003ca class=\"ref\" id=\"r74\" href=\"#n74\" data-tip=\"№74 \u0026#183; Памфлеты Ульриха фон Гуттена; Масленичные игры (Ганс Сакс) и др.\"\u003e74\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ области без всякого вреда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНечисто или чисто то, что дарят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна ваш дар прекрасно переварит\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак и всеядец ростовщик еврей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ главный королевский казначей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗатем, минуты не промешкав,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПремного умиленный поп\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБраслеты, цепь и кольца сгреб,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак горсть каких-нибудь орешков,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа женщин милости небес\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПризвал и был таков, исчез.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА Гретхен?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС места не встает.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокоя ларчик не дает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ неизвестность беспокоит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто тот даритель-доброхот?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВесь день сидит, догадки строит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня томит ее печаль.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостань ей что-нибудь другое,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПропажи первого не жаль.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля вас, конечно, все пустое.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот мой план: веди подкоп\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбходный под ее соседку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА Гретхен снова в гардероб\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦепочку сунь или браслетку!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, милостивый государь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст уходит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВлюбленных мания — подарки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть небо все ему обшарь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа звезды для его сударки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r75\" href=\"#n75\" data-tip=\"№75 \u0026#183; Масленичные игры (Ганс Сакс)\"\u003e75\u003c/a\u003eДом соседки\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта  (одна)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрости господь, мой муженек\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖеною бедной пренебрег!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоломенной вдовою вяну,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА сам уплыл за океаны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА видит бог, я ль не жена?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбила и была верна.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Плачет.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНебось уж помер на чужбине!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИметь бы справку о кончине.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит Маргарита.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, Марта!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен, что с тобой?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт ужаса дрожат поджилки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа полке ящик костяной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в нем сокровищ, как в копилке!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВещей в шкатулке без числа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолней, чем первая была!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы матери не говори,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то раздаст в монастыри.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот ларчик, полюбуйтесь им!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта  (принаряжая Маргариту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, куколка! Ах, херувим!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи в сад, ни в церковь, вот в чем горе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНельзя пойти в таком уборе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПочаще забегай тайком.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУже и то тебе забава\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред зеркалом в добре таком\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть-чуть покрасоваться павой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам смотришь — праздник. День за днем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы осмелеем понемножку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаденем брошку, цепь, сережку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с гору матери наврем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто мог бы ларчики принесть?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеладное тут что-то есть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлышен стук в дверь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе матушка ль моя за мной?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта  (посмотревши в дверной глазок)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой-то господин чужой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожалуйте.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит Мефистофель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростите, дамы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто к вам я вваливаюсь прямо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Почтительно отступает перед Маргаритой.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ к Марте Швердтлейн.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС кем имею честь?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ — Марта Швердтлейн.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (тихо Марте)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРад знакомство свесть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я не вовремя, понятно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗастал вас с барышнею знатной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБеседе не хочу мешать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ к вам зайду потом опять.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДитя, убором и осанкой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы гостю кажешься дворянкой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО нет, я из простой семьи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы снисходительны сверх меры,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА украшенья не мои.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто украшенья? Тон, манеры —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот дело в, чем! А что наряд?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак мне остаться? Как я рад!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС чем вы пришли?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростите за суровость,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне горько выступать посланцем бед:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт мужа вам нерадостная новость,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн, умирая, вам послал привет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн умер? Жизнь моя, мое спасенье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ упаду! Какое потрясенье!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе надо, дорогая, унывать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПозвольте вам о муже рассказать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе дай мне бог любви изведать силу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУтрата милого меня б убила.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБояться горя — счастия не знать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто можете о муже вы сказать?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго хранит Антоний Падуанский\u003ca class=\"ref\" id=\"r76\" href=\"#n76\" data-tip=\"№76 \u0026#183; Золотая легенда (Иаков Ворагинский); Базилика Сант-Антонио в Падуе\"\u003e76\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ своей часовне тихой и святой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ земле церковной он по-христиански\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПохоронен под каменной плитой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВещей он не давал для передачи?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь просьбу долго жить, а наипаче\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо муже справить триста панихид.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот все, что передать вам надлежит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак, ни колечка мне, ни медальона,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторые любой мастеровой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ котомке бережет для нареченной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ недоест, а принесет домой?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСударыня, я вижу, как вам трудно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне жалко вас, но муж ваш не был мот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн денег не транжирил безрассудно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо на него свалился град невзгод.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой бедняк! И как любил жену!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго не раз я в церкви помяну.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри склонностях таких благоговейных\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы созданы для радостей семейных.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, я вступлю еще не скоро в брак,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтоль ранним свадьбам нет у нас примера.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу что ж, так заведите кавалера.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа зависть будет счастлив тот смельчак,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый сделает к вам первый шаг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ нас по этой части строг обычай.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, в мире нет на этот счет различий.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак муж скончался?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосередь двора.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ навозе лежа, на гнилой соломе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ находился у его одра.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн каялся, и вспоминал о доме,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ отошел, желая всем добра.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн плакался: \u0026#171;Сознаться тяжело,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебе я мерзок на краю могилы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто бросил так жену и ремесло!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если бы она меня простила!\u0026#187;\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта  (плача)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ лишь добром бедняжку помяну.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗато все зло он ставил вам в вину.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакие выдумки! Какие басни!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак врать пред смертью! Есть ли что ужасней?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверно, бредя от упадка сил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапраслину на вас он возводил:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Да, не был я бездельником, зевакой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМинуты с ней покоя я не знал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлодил детей и хлеб ей добывал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа все не мог ей угодить, однако,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ корку черствую свою жевал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОглядываясь на нее с опаской\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА про мою любовь к нему и ласку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПро все мои тревоги он забыл?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, он их помнил и благодарил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Я о семье молился,\u0026#160;— он сказал, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тот день, как наш корабль из Мальты вышел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверно, бог мою мольбу услышал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ судно нам турецкое послал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа нем везли султану часть казны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ храбро вел себя при абордаже;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда делить мы стали деньги вражьи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХороший куш урвал я для жены\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуш?.. Почему ж?.. А что с ним сделал муж?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, денежки те — поминай как звали.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ Неаполе одна из добрых душ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак нежно занялась им на привале,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто, испуская свой последний дух,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе позабыл и он ее услуг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот так всегда он! Все для потаскух!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХватило, значит, денег для подачек?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА мной, детьми пожертвовал растратчик!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак шашням не мешал его недуг?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗато вот и пришел ему каюк.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа вашем месте траурное платье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ с год бы проносил и с этих пор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодумал бы о новом кандидате.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе подвернется вновь такой бобер.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн был добряк и дурачок влюбленный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСама сердечность, искренность сама.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда бы не шатанье, не притоны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе девки, не игорные дома!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, это недостаток мелкий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверное, и он спускал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам ваши женские проделки?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа равенстве таких начал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я б руки у вас искал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак вам не стыдно, шутнику!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (про себя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть я и черт, а утеку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока на слове не поймали,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак надо быть с ней начеку!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Маргарите.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак в сердце нет еще печали?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак вас понять?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (про себя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДитя, дитя!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Вслух.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрощайте!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС богом!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе шутя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО муже бы достать бумагу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде погребен, когда, бедняга,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ эти сведенья в печать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля верности потом отдать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПризнанье очевидцев двух\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостаточно для справки устной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотите, явится мой друг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ подтвердит рассказ мой грустный?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрошу!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА барышня придет?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриятель мой отличный малый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбъездил свет, весьма бывалый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля дома честь его приход.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри нем я постыжусь являться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудь он и принц, не вам стесняться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтак, сегодня вечерком\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы вас в саду обоих ждем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eУлица\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст и Мефистофель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, как дела? Идут на лад?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы пламенем объят и в горе?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна твоею будет вскоре.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПойдем к соседке Марте в сад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКума заведомая сводня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ Гретхен будет там сегодня.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу что ж, прекрасно. Очень рад.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо и от нас услуг хотят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак что ж, услуга за услугу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаверим ей своей рукой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто в Падуе в земле святой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПочиет прах ее супруга.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХорош! И нам в такую даль!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eSancta simplicitas!\u003ca class=\"ref\" id=\"r77\" href=\"#n77\" data-tip=\"№77 \u0026#183; Tragedia Johannis Huss (Агрикола); Хроники Констанцского собора\"\u003e77\u003c/a\u003e\u0026#160;Да что ты?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакая в том тебе забота?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДашь подпись, вот и вся печаль.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, неприемлем этот шаг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодумайте, какой святоша!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоныне, господин хороший,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы ложных не давал присяг?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА доказательства твои\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО боге, мире, бытии?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз этого инвентаря\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПреподносил ты небылицы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС уверенностью очевидца,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА между нами говоря,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО Марты Швердтлейн мертвом муже\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы знаешь, кажется, не хуже.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, как всегда, софист и лжец.\u003ca class=\"ref\" id=\"r78\" href=\"#n78\" data-tip=\"№78 \u0026#183; Софист (Платон); Горгий (Платон) и др.\"\u003e78\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗато ты — чести образец\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ завтра это обнаружишь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда головку Гретхен вскружишь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дашь ей верности обет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсем сердцем дам ей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпору нет!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ примешься чистосердечно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвердить, что чувство будет вечно!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПримусь, конечно,\u0026#160;— вот ответ,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с чистой совестью, конечно!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, как ты глуп! Когда, чуть жив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебя не помня, все забыв,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНазвать хочу я наудачу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтихию чувств, слепой порыв,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ слов ищу, и чуть не плачу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вечным сгоряча зову\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой сон небесный наяву,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеужто я других дурачу?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все ж я прав.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, целиком!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСдаюсь. Тебя не переспоришь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВертя так ловко языком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы доводами всех уморишь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ согласиться принужден:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы нужен мне, вот твой резон.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eСад\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита под руку с Фаустом и Марта с Мефистофелем прогуливаются по саду.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, это только ваша доброта,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто вы так снисходительно нестроги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеняя в путешествии места,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбезны вы со встречными в дороге.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоя незанимательная речь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе может вас ни капельки увлечь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдин лишь взгляд, один лишь голос твой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДороже мне всей мудрости земной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Целует ей руку.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа что вы, право, руки целовать!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь кожа у меня так огрубела.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТружусь, минуты не сижу без дела.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ требует порядка в доме мать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроходят дальше.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак вы в разъездах, стало быть, всегда?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроклятое занятие такое.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрелою мчишься через города\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ни в одном нельзя пожить в покое.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо молодости все нам нипочем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвищи в кулак да по дорогам рыскай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда ж к концу подступит дело близко,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе сладко доживать холостяком.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредставишь это, сердце жить не радо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#160;Об этом вовремя подумать надо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроходят дальше.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, с глаз долой, из сердца вон небось?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы вежливы, вот все и объясненье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ вас друзей ученых тьма, хоть брось.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ с ними не могу идти в сравненье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоверь, мой ангел, то, что мы зовем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУченостью, подчас одно тщеславье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУжель?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, как в неведенье своем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНевинность блещет, как алмаз в оправе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе помышляя о своей цене,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоих достоинств ни во что не ставя!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть миг вниманья подарите мне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я всегда вас помнить буду вправе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ты все дома?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБольше все одна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя у нас хозяйство небольшое,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСноровка в доме все равно нужна:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы без служанки, я стираю, мою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГотовлю, подметаю, шью, все — я.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозни и спешки, только б с ног не сбиться.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ матушка строга: насчет шитья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна сама большая мастерица!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе то чтоб находились мы в нужде,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорее мы с достатком горожане.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтец семье оставил состоянье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сад, и домик малый в слободе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь я не тружусь чуть свет спросонку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак год назад:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ солдатах брат\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ умерла сестренка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то я отдавала все ребенку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо рада б муки все вернуть назад\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа милый детский взгляд.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзгляд, вероятно, херувима,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдинственно с твоим сравнимый!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСестра на свет явилась в страшный год\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтцовой смерти. Я была ей няней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМать поручила мне за ней уход,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСама ж тогда лежала без сознанья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы думали, что и она умрет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКормить дитя в теченье этих дней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда нельзя и думать было ей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ молоком с водой сестру вскормила.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на моих руках, всегда со мной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна росла, смеялась и шалила.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ это было радостью живой?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо временами я теряла силы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтояла ночью рядом колыбель.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроснусь, чуть двинется она, бывало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСестре дам молока, возьму в постель,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА если этого крикунье мало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПойду качать, закутав в одеяло,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ноги оттопчу до хромоты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА поутру на рынке, у плиты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли за постирушкой у корыта\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПочувствуешь себя такой разбитой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗато как сладок съеденный кусок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак дорог отдых и как сон глубок!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроходят дальше.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеисправимые холостяки!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак обратить вас в истинную веру?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК такой учительнице, для примера,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОхотно б я пошел в ученики.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда нельзя ль вам в душу заглянуть?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ вас есть на примете кто-нибудь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоя жена да угол, говорят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДороже царств и каменных палат.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ говорю о склонности взаимной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе встречные в пути гостеприимны.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, вы не поняли. Я знать хочу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСерьезных чувств вы в прошлом не таите?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в жизни с женщинами не шучу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх нет, меня понять вы не хотите!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, каюсь, глуп. Однако в меру сил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбвеобильность вашу оценил.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроходят дальше.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО радость ты моя! Так ты сейчас\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня узнала с первого же взгляда?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКонечно. И потупилась, смутясь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрости же, что тебя я подстерег\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ то утро за церковною оградой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе ставь мне этой вольности в упрек.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне это непривычно, и сперва\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ было растерялась от смущенья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь на меня до этого молва\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще ни разу не бросала тени.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМое ли, думала я, поведенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнушило вам столь вольные слова?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверно, я нарушила приличье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто представляюсь легкою добычей!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПризнаться, я предвидеть не могла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто я сама возьму вас под защиту,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на себя была за то сердита,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто строже вас в душе не распекла.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО милая!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ну…\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Срывает ромашку и обрывает один за другим лепестки.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы что, букет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли венок плетешь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, так, пустое.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, что же ты?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе смейтесь надо мною!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Шепчет.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто шепчешь ты?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита  (вполголоса)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе любит. Любит. Нет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО прелесть ты моя!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита  (продолжает)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе любит. Любит!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе любит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Обрывая последний лепесток, громко и радостно.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбит!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбит! Да, мой свет!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГаданье этот узел пусть разрубит!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн любит, любит, вот цветка ответ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВмести, постигни это торжество!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вся дрожу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе бойся ничего!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть этот взгляд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ рук пожатье скажут\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО необъятном том,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред чем слова — ничто,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО радости, которая нам свяжет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСердца.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, да, навеки без конца!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКонец — необъяснимое понятье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПечать отчаянья, проклятья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ гнев творца.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита сжимает ему руки, вырывается и убегает. Фауст не сразу приходит в себя и, овладев собою, идет за нею.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта  (приближаясь из глубины)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмеркается.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ нам домой пора.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вас не отпустила бы так скоро\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо своего двора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо городок наш страшная дыра,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНачнутся разговоры.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь у людей другого дела нет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак наблюдать через заборы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда и с кем пошел сосед.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА наша пара?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн юркнул в тьму\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа нею вслед.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн благосклонен к ней.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна — к нему.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак создан свет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eБеседка в саду\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита вбегает, прячется за дверь и, прижавши палец к губам, смотрит через щель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдет!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (входя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы прячешься, лиса! Постой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Целует ее.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита  (обнимая его и возвращая ему поцелуй)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДушою вся твоя, любимый мой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель стучится.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (топая ногами)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто там?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвои!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвинья!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПора расстаться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта  (входя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, правда, сударь, поздно, час ночной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНельзя ли проводить мне вас домой?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО нет! Что скажет мать?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак мне убраться?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСчастливо оставаться!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ добрый час!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДо скорого свиданья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст и Мефистофель уходят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПросто диво,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда он устремляет мысль свою!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я пред ним в смущении стою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсему поддакиваю торопливо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все же в толк никак я не возьму,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем я могла понравиться ему?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eЛесная пещера\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (один)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПресветлый дух, ты дал мне, дал мне все,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО чем просил я. Ты не понапрасну\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛицом к лицу явился мне в огне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы отдал в пользованье мне природу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДал силу восхищаться ей. Мой глаз\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе гостя дружелюбный взгляд без страсти, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я могу до самого нутра\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаглядывать в нее, как в сердце друга.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы предо мной проводишь череду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивых существ и учишь видеть братьев\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо всем: в зверях, в кустарнике, в траве.\u003ca class=\"ref\" id=\"r79\" href=\"#n79\" data-tip=\"№79 \u0026#183; Идеи к философии истории человечества (Гердер); Этика (Спиноза)\"\u003e79\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда ж бушует буря в темной чаще\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, рушась наземь, вековая ель\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛомает по пути стволы и сучья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ грохоту паденья вторит даль,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодводишь ты меня к лесной пещере,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ там, в уединенной тишине,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДаешь мне внутрь себя взглянуть, как в книгу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тайны увидать и тьмы чудес.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вижу месяц, листья в каплях, сырость\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа камне скал и на коре дерев,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тени движущихся туч похожи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа чудищ первобытной старины.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ясно мне тогда, что совершенства\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне не дано. В придачу к тяге ввысь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторая роднит меня с богами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДан низкий спутник мне. Я без него\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе обойдусь, наперекор бесстыдству,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС которым обращает он в ничто\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой жребий и твое благословенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн показал мне чудо красоты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗажег во мне и раздувает пламя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я то жажду встречи, то томлюсь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТоскою по пропавшему желанью.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит Мефистофель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажи, какой анахорет!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасается в лесу под елью!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли спасенья от безделья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПовеселее, что ли, нет?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА у тебя других нет дел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак докучать мне неотлучно?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШучу. Я спорить не хотел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе время препираться скучно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, брат, ворчун и нелюдим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть разорвись ему в угоду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдно лишь наказанье с ним.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет от него житья-проходу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще \u0026#171;спасибо\u0026#187; говорить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ты пристал ко мне, как муха?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО сын земли! Хочу спросить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто б делал ты без злого духа?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе спас ли я тебя вполне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт философского угара?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не благодаря ли мне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы не сошел с земного шара?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак что ж ты разгонять тоску\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗасел совой под тенью граба\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ варишься в своем соку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПитаясь воздухом, как жаба?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, как в тебе еще, заметно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСидит ученый кабинетный!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б ты ведал, сколько сил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ черпаю в глуши лесистой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз зависти одной, нечистый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы б эту радость отравил.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот неземное наслажденье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНочь промечтать средь гор, в траве,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак божество, шесть дней творенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбняв в конечном торжестве!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПостигнуть все под небосводом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо всем сродниться и потом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС высот свалиться кувырком —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда, сказал бы мимоходом,\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(с презрительным жестом)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо этого простейший стыд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне выговорить не велит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакая грязь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакая грязь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся кровь от ярости зажглась:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак твой стыдливый слух тревожит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва я прямо назову\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо, без чего по существу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоя стыдливость жить не может!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу что же, лги и лицемерь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНасколько совести хватает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако вот о чем теперь:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ своей конурке Гретхен тает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна в тоске, она одна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна в тебе души не чает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТобой жива, тобой полна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе любовь, как ширь разлива,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез удержу, без берегов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА сам ты присмирел трусливо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ руки умывать готов!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем созерцать, как за опушкой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМерцает хор ночных светил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы б приунывшую подружку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа жар любви вознаградил!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна в окошко наблюдает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак тянут тучи без числа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дни и ночи распевает:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Когда б я ласточкой была!\u0026#187;\u003ca class=\"ref\" id=\"r80\" href=\"#n80\" data-tip=\"№80 \u0026#183; Wenn ich ein V\u0026#246;glein w\u0026#228;r (народная песня); Народные песни (Гердер)\"\u003e80\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна то шутит, то ненастье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТуманит детские черты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе глаза по большей части\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаплаканы до красноты.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗмея! Змея!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (про себя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, вижу я,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто клюнуло, душа моя!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСгинь, искуситель окаянный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО ней ни слова, негодяй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ чувственного урагана,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУснувшего, не пробуждай!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА девочку терзает страх,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ты остыл к ней и в бегах.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде б ни был я, в какие бы пределы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи скрылся я, она со мной слита,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я завидую Христову телу:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго касаются ее уста.\u003ca class=\"ref\" id=\"r81\" href=\"#n81\" data-tip=\"№81 \u0026#183; Постановления IV Латеранского собора; Постановления Тридентского собора и др.\"\u003e81\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вспомнил пастбище средь роз\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ланей, символы желанья.\u003ca class=\"ref\" id=\"r82\" href=\"#n82\" data-tip=\"№82 \u0026#183; Песнь Песней\"\u003e82\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрочь, сводник!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы меня до слез\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмешишь потоком этой брани.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоздав мальчишек и девчонок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСам бог раскрыл глаза с пеленок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа этот роковой вопрос.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ж растерялся ты? Вперед!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя свиданье с милой ждет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА не палач, не эшафот!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, даже к ней упав на грудь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в неге заключив в объятье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мне забыть, как зачеркнуть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе беду, мое проклятье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкиталец, выродок унылый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ сею горе и разлад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак с разрушительною силой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛетящий в пропасть водопад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА рядом девочка в лачуге\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа горном девственном лугу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ словно тишина округи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся собрана в ее кругу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, видишь, мне, злодею, мало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто скалы с места я сдвигал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ камни тяжестью обвала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ песок и щебень превращал!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще мне надобно, подонку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе в угоду, палачу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасстроить светлый мир ребенка!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей же к ней, в ее уют!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть незаметнее пройдут\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМгновенья жалости пугливой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в пропасть вместе с ней с обрыва\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, оступившись, полечу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпять кипит, опять в обиде!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтупай утешь ее, глупец!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ смятенье выхода не видя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы думаешь: всему конец?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы был всегда храбрец мужчина,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак что ж ты пятишься назад?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто оробел ты, дурачина,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда тебе сам черт не брат?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eКомната Гретхен\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен  (одна за прялкой)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто сталось со мною?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ словно в чаду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМинуты покоя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебе не найду.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть он отлучится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабьюсь, как в петле,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я не жилица\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа этой земле.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ догадках угрюмых\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрожу, чуть жива,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСумятица в думах,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ огне голова.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто сталось со мною?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ словно в чаду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМинуты покоя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебе не найду.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГляжу, цепенея,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧасами в окно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаботой моею\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе заслонено.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вижу я живо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоходку его,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ стан горделивый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ глаз колдовство.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, слух мой чаруя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТечет его речь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ жар поцелуя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрозит меня сжечь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто сталось со мною?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ словно в чаду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМинуты покоя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебе не найду.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде духу набраться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб страх победить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРвануться, прижаться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРуками обвить?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б все позабыла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ним наедине,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя б это было\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПогибелью мне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r83\" href=\"#n83\" data-tip=\"№83 \u0026#183; Этика (Спиноза); Записки Кестнера о Гёте и др.\"\u003e83\u003c/a\u003eСад Марты\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита и Фауст.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПообещай мне, Генрих!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, что в моих руках!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак обстоит с твоею верой в бога?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы добрый человек, каких немного,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо в деле веры просто вертопрах.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставь, дитя! У всякого свой толк.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы дорога мне, а за тех, кто дорог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ жизнь отдам, не изощряясь в спорах.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, верить по Писанию твой долг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой долг?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eAx, уступи хоть на крупицу!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвятых даров ты, стало быть, не чтишь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ чту их.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо одним рассудком лишь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тайн святых не жаждешь приобщиться.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы в церковь не ходил который год?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы в бога веришь ли?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО милая, не трогай\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаких вопросов. Кто из нас дерзнет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтветить, не смутясь: \u0026#171;Я верю в бога\u0026#187;?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА отповедь схоласта и попа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа этот счет так искренне глупа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто кажется насмешкою убогой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак ты не веришь, значит?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе коверкай\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРечей моих, о свет моих очей!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто на поверку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазум чей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСказать осмелится: \u0026#171;Я верю\u0026#187;?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧье существо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысокомерно скажет: \u0026#171;Я не верю\u0026#187;?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ него,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоздателя всего,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпоры\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсего: меня, тебя, простора\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ самого себя?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли над нами неба нет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли земли нет под ногами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ звезд мерцающее пламя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа нас не льет свой кроткий свет?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлаза в глаза тебе сейчас\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе я ль гляжу проникновенно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не присутствие ль вселенной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНезримо явно возле нас?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак вот, воспрянь в ее соседстве,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПочувствуй на ее свету\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСуществованья полноту\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ это назови потом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбовью, счастьем, божеством.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет подходящих соответствий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ нет достаточных имен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе дело в чувстве,\u0026#160;а названье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь дым, которым блеск сиянья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез надобности затемнен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПочти что в этих выраженьях\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак и священник говорит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе это так. Но я в сомненьях.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОб этом целый свет твердит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбое сердце, кто как может,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак на душу господь положит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак что же мне бояться слов?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы прав как будто поначалу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА присмотреться — свет Христов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя затронул очень мало.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДитя мое!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе разберу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем друг твой мне не по нутру.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак так?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ чем ваше кумовство?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак можешь ты терпеть его?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНикто еще во мне так живо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе возбуждал вражды брезгливой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак твой противный компаньон.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО милочка, не страшен он!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри нем я разом холодею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ с прочими людьми в ладу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо так же, как душою всею\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ твоего прихода жду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак я чураюсь лиходея.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрости господь мои слова,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда пред ним я не права.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ж делать, уж такой чудила.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ с ним бы дружбы не водила!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва он в дверь, как всех буравит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго коварный, острый взор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн так насмешлив и хитер\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ни во что людей не ставит!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто он любви вовек не ведал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак бы написано на нем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне радость в обществе твоем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда ж ты с ним и мы втроем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБоюсь, как он бы нас не предал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, чуткость ангельских догадок!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн мне непобедимо гадок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ соседстве этого шута\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНейдет молитва на уста,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ даже кажется, мой милый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто и тебя я разлюбила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакая в сердце пустота!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут верх врожденной неприязни.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо мне пора домой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПостой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть раз нельзя ли без боязни\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПобыть часочек мне с тобой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрудь с грудью и душа с душой?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eAx, если б я спала одна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСегодня ночью, веришь слову,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б не задвинула засова.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо рядом дремлет мать вполсна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда бы нас она застала,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б тут же замертво упала!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, вздор! Вот с каплями флакон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНемного их накапай в воду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай выпить ей, и до восхода\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе охватит крепкий сон.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы у меня не знал отказа.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА эти капли без вреда?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б не дал их тебе тогда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть я тебя увижу, сразу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе рада сделать для тебя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе я, кажется, любя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак много отдала в прошедшем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто жертвовать уж больше нечем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (входя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу что, ушла твоя овца?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодслушивал?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУзнал немало.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя, как старого глупца,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДевица вере обучала?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, вера — важная статья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля девушек властолюбивых:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз женихов благочестивых\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыходят смирные мужья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроклятый изверг, не греши!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе ль понять, как в детской вере\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй страшно будущей потери\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоей загубленной души!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе это, братец, только так,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты поверил и размяк?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, помесь грязи и огня!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна, заметь, физьономистка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ раскумекала меня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо-видимому, очень близко.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУм плутовской давно смекнул,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто хват я или Вельзевул.\u003ca class=\"ref\" id=\"r84\" href=\"#n84\" data-tip=\"№84 \u0026#183; Евангелие от Матфея\"\u003e84\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак ночью?..\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто тебе за дело?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдна отзывчивость всецело.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eУ колодца\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен и Лизхен с кувшинами.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛизхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы новости слыхала о Варваре?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет. Редко вижу я кого в глаза.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛизхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСивилла рассказала на базаре.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, доигралась эта егоза!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА гонор был какой у этой твари!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа что с ней?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛизхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНос заткни, тяжелый дух!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДве жизни в ней, и ест и пьет за двух.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛизхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоделом! Открылось в эти числа.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА как она на парне висла!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрипомни танцы, и гульбу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ громкую их похвальбу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВертелась с ним неосторожно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ саду, в распивочной, в пирожной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебя считала краше всех,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоображала, что не грех\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодарки брать от бедокура,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ним разводила шуры-муры.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабаловался молодец.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот и девичеству конец.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖаль бедную!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛизхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖалеешь ты?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА безотлучно день за прялкой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПросиживать до темноты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам не было с тобою жалко?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем временем она тайком\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХодила к своему миленку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТоски не ведала с дружком.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь за это ветрогонка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтведает епитимьи:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаденет девка власяницу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа эти подвиги свои.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн должен был на ней жениться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛизхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайди такого дурака!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапутал, да и дал стречка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ то: не клином свет сошелся!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн плохо с нею обошелся.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛизхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрак не спасет от срамоты:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа свадьбе парни ей цветы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСорвут со свадебной фаты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА девки перед дверью дома\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНасыплют отрубей с соломой.\u003ca class=\"ref\" id=\"r85\" href=\"#n85\" data-tip=\"№85 \u0026#183; Веймарский уголовный свод; Докладная записка Гёте об отмене церковного покаяния и др.\"\u003e85\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен  (возвращаясь домой)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак смело хмурила я брови,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак предавалась я злословью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак я строга была, когда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлучалась с девушкой беда!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак из избы тогда надменно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧужой я выносила сор!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак не жалела слов, позор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзобличая откровенно!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вдруг какая перемена!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСама не лучше я сестер.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда я скроюсь с этих пор?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда я сделанное дену?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо то, что сердце завлекло,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак сильно было и светло!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eНа городском валу\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e[46]  \u0026lt;#_ftn46\u0026gt;\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ углублении крепостной стены изваяние скорбящей божией матери, перед нею цветы в кувшинах. Гретхен ставит свои цветы к прочим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК молящей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой лик скорбящий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСклони в неизреченной доброте,\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС кручиной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотря на сына,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростертого в мученьях на кресте,\u003ca class=\"ref\" id=\"r86\" href=\"#n86\" data-tip=\"№86 \u0026#183; Stabat Mater Dolorosa; Евангелие от Луки\"\u003e86\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ очи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозведши\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа помощию отчей в вышине!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто знает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак тают\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо капле силы у меня внутри?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь пред тобой я вся как на ладони.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, пожалей меня и благосклонней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа муку и беду мою воззри!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде шумно, людно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДышать мне трудно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоднять глаза на посторонних срам,\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА дома волю\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлезам от боли\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДаю, и сердце рвется пополам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ эти цветики в букете\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлезами облила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда сегодня на рассвете\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх для тебя рвала.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня застало солнце в спальной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавным-давно без сна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ думою своей печальной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыла пробуждена.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпаси меня от мук позора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛицо ко мне склоня!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдиная моя опора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУслышь, услышь меня!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r87\" href=\"#n87\" data-tip=\"№87 \u0026#183; Гамлет (Шекспир); Разговоры с Гёте (Эккерман)\"\u003e87\u003c/a\u003eНочь. Улица перед домом Гретхен\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалентин, солдат, брат Гретхен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалентин\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗайду, бывало, пить в подвал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ слышу, как иной бахвал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасписывает наобум\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвою властительницу дум.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ девушки на свете нет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасивей, чем его предмет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ тихо сяду, как вошел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ локти положу на стол,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ бороды курчавлю край,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока болтает краснобай.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотом стакан свой подыму\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ говорю в ответ ему:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Кому какая по нутру, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ выпью за свою сестру.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакую девушку в стране\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоставишь с Гретхен наравне?\u0026#187;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ прекращается вранье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе чокаются за нее,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмолкают разом хвастуны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ видят, что посрамлены.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь все по-другому здесь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть на стену от злобы лезь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТерпеть, чтоб каждое дрянцо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМогло бросать тебе в лицо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНамеки, колкости, кивки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвусмысленности и смешки!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА чем мерзавцев этих мне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа месте припереть к стене,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда их сплетни не навет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в их словах обмана нет?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто за канальи там вдвоем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодкрадываются тайком?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоди любезник сестрин тут?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни живыми не уйдут.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходят Фауст и Мефистофель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДрожа от веянья прохлады\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ озаряя сумрак плит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеугасимая лампада\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ соборной ризнице горит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакой же мрак во мне точь-в-точь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак эта полутьма и ночь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА у меня позыв другой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой-то зуд страстей угарных,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак по ночам весенним вой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКотов на лестницах пожарных.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь я бродяга и шатун\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ славу о себе упрочу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпять Вальпургиевой ночью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА завтра ведь ее канун.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда по праву кутерьма\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сходит целый свет с ума.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА выйдет ли из-под земли\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот клад, светящийся вдали?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж у поверхности покрышка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам не придется долго рыть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНабита золотом кубышка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМозги б ты лучше понатужил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ раздобыл жемчужин нить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб милой Гретхен подарить.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ там и жемчуг обнаружил.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрекрасно. К девушке под кров\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХодить мне больно без даров.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапрасно! Выгоду свою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПреследуй в жизни безвозмездно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас я Гретхен песнь спою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод кровом этой ночи звездной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб девушка попалась в сеть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО нравственности буду петь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Поет под гитару.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмиряя дрожь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем под нож,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКатринхен, к милому идешь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ гибели не видишь?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть он хорош,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть он пригож, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы девушкой к нему войдешь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо девушкой не выйдешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн для проказ,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе обручась,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозьмет что надобно от вас,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ — с богом, до свиданья!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА нужен глаз,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа все отказ,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб честь осталась про запас\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДо самого венчанья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалентин  (выступая вперед)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКого ты пеньем манишь, крысолов?\u003ca class=\"ref\" id=\"r88\" href=\"#n88\" data-tip=\"№88 \u0026#183; Немецкие саги (братья Гримм); Хроники города Гамельна\"\u003e88\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас расправлюсь я с тобой, нечистый!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСперва гитару на двадцать кусков,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА после сокрушу и гитариста!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСломал гитару вдребезги мою.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалентин\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вам обоим череп раскрою.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (Фаусту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмелее, доктор! Шпагу вон! Вперед!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТесни его. Прижмись ко мне вплотную.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоли смелей, он целым не уйдет!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе отступай! Я хорошо фехтую.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалентин\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак отражай!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу что ж, и отразим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалентин\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА если так ударю?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭка штука!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалентин\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ бьюсь как будто с дьяволом самим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот уже он перешиб мне руку!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (Фаусту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоли!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалентин  (падая)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПропал!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесчастному капут.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь, пока не поздно, надо скрыться.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас людей на помощь позовут.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС полицией не трудно сговориться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругое дело уголовный суд.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУходят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта  (у окна)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаружу все!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен  (у окна)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОгня! Огня!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭй, караул! Разбой, резня!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНарод\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВон труп, взгляни сюда!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта  (выходя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛови убийц! Держи и бей!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен  (выходя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто здесь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНарод\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСын матери твоей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО боже, вот беда!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалентин\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ умираю,\u0026#160;— сказ простой, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не увижу дня.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе войте, бабы, надо мной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПослушайте меня.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе обступают его.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще ты, Гретхен, молода,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ где тебе понять, куда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедет твой глупый нрав.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, шлюхой ставши невзначай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо правилам теперь гуляй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа все есть свой устав.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрат! Господи! Не убивай!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалентин\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы к богу всуе не взывай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто свершено, то свершено,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто будет, будет все равно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь ты начала с одним,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА после перейдешь к другим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда ж до дюжины дойдет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтолпится город у ворот.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда на свет родится стыд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще он от народа скрыт,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго таят во тьме ночей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадвинув шапку до ушей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго не видно, и тогда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго прикончить не беда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо не по дням, а по часам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРастет и выпирает срам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ чем чудовищнее грех,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем больше на виду у всех.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ твердо знаю: дни придут,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда тебя весь честный люд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ стар и мал, исчадье тьмы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧураться будут, как чумы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы будешь направлять стопы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ обход, подальше от толпы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе не даст проступок твой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлистать в цепочке золотой\u003ca class=\"ref\" id=\"r89\" href=\"#n89\" data-tip=\"№89 \u0026#183; Полицейские регламенты Франкфурта (Kleiderordnungen)\"\u003e89\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в кружевном воротнике\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтплясывать на пикнике.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы будешь находить ночлег\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь оборванцев и калек.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ если милостивый бог\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростит по смерти твой порок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы смыть не сможешь на земле\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКлейма проклятья на челе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам каяться теперь под стать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА не проклятья изрыгать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалентин\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, сводня, жалко, мочи нет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСломал бы я тебе хребет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа все грехи бы искупил.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО брат мой, вынести нет сил!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалентин\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе плачь, сказал я, брось тужить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМинувшего не воротить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы мне сама из-за угла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУдар бесчестьем нанесла.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ честь солдатскую свою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ душу богу отдаю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Умирает.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eСобор\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦерковная служба с органом и пением. Гретхен в толпе народа. Позади нее злой дух.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗлой дух\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИначе, Гретхен, бывало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНевинно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы к алтарю подходила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧитая молитвы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо растрепанной книжке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС головкою, полной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаполовину богом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаполовину\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабавами детства!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде ты витаешь?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто тебя мучит?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолишь у бога\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУпокоения матери,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо твоей вине уснувшей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНавеки без покаянья?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧья кровь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ тебя на пороге?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто бьется под сердцем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаполняя тебя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСодроганьем?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпять они,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе те же, те же думы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНикак от них,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНикак не отвяжусь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eDies irae, dies illa\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eSolvet saeclum in favilla.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвуки органа.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗлой дух\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНастиг тебя гнев господень!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрубный глас раздается!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазверзаются гробы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ из пепла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуша твоя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодымается\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа вечные муки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУйти, уйти!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОрган и пенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеснят дыханье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва стою.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eJudex ergo cum sedebit\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eQuidquid latet, adparebit,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eNil inultum remanebit.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ задохнусь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак давят своды!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК дверям! К проходу!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ чувств лишусь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗлой дух\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрячься — не скроешь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГреха и позора.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоздуха? Света?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх больше не будет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоре!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eQuid sum miser tunc dicturus?\u003ca class=\"ref\" id=\"r90\" href=\"#n90\" data-tip=\"№90 \u0026#183; Dies irae\"\u003e90\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eQuem patronum rogaturus,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eCum vix justus sit securus?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗлой дух\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПраведные отвращают\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛицо от тебя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротянуть тебе руку, погибшей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБоятся.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eQuid sum miser tunc dicturus?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ падаю!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоседка! Вашу склянку!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Падает в обморок.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r104\" href=\"#n104\" data-tip=\"№104 \u0026#183; Веймарская театральная критика о Бёттигере\"\u003e104\u003c/a\u003eВальпургиева ночь\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоры Гарца близ деревень Ширке и Эленд.\u003ca class=\"ref\" id=\"r91\" href=\"#n91\" data-tip=\"№91 \u0026#183; Путевые дневники Гёте о Гарце; Письмо Цельтеру (1812) и др.\"\u003e91\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст и Мефистофель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы б не прельстился добрым метловищем?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я бы прокатился на козле.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам далеко, и мы еще порыщем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокамест ноги носят по земле,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще я пешеход неутомимый.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУменьшив путь, пропустим много мимо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ самой прогулке радость ходоку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ для того пошел пешком по скалам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в руки взял дорожную клюку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы внимать лавинам и обвалам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж дышит по-весеннему береза,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ даже веселее ель глядит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУжель весна тебя не молодит?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, у меня в душе стоят морозы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я люблю и стужу и буран.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК тому ж ущербный месяц сквозь туман\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛьет тусклый свет с угрюмым видом скряги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи зги не видно, и при каждом шаге —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред тобой, негадан и неждан,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтвол дерева, и камни, и коряги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ у блуждающего огонька\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпрошу, как лучше нам пройти к вершине.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ горах нет лучшего проводника.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот сам он, кстати, легок на помине.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе откажи, чем даром тратить пламя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам посветить и вверх взобраться с нами.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлуждающий огонек\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе прекословлю никогда природе:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ двигаться зигзагами привык,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда с оглядкой, а не напрямик.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе подражай двуногому отродью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВаляй во имя черта по прямой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИначе я задую пламень твой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлуждающий огонек\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы кто-то здесь из признанных владык.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ подчиняюсь вам беспрекословно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо ведь сегодня тут ночной содом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеровный свет мой неповинен в том,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто нам тут выпадает путь неровный.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст, Мефистофель и Блуждающий огонек  (поочередно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПуть лежит по плоскогорью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас встречает неизвестность.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто край фантасмагорий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОчарованная местность.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлубже в горы, глубже в горы!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧудеса! Деревья бора\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкачут в чехарде средь луга\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧерез головы друг друга.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоры нагибают спины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб перемахнуть вершины.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМелких волн курчавя гребни,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРучеек бежит по щебню.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто мурлычет он ворчливо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДень и ночь без перерыва?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбвиненье ли в измене\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПенят бешено каменья?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтзвук ли времен счастливых\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлышен в этих переливах?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ о том, что память прячет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭхо, вспоминая, плачет?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереклички стай совиных\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтзываются в долинах.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлышен, далью повторенный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХохот филина бессонный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМесяц осветил тропинку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлещет ящерицы спинка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо-гадючьи, змей проворней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасползлись под нами корни,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА над нами, пальцы скрючив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВиснет путаница сучьев.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТемный лес оплел дорогу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЩупальцами осьминога,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кишмя-кишит под мхами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазномастными мышами.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА светящиеся мушки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВьются на его опушке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКучами, несметным скопом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОгненным калейдоскопом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо скажите мне по чести,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе стоим ли мы на месте?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМожет, все, что есть в природе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗакружившись в хороводе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМчится, пролетая мимо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы же сами недвижимы?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУхватись за мой камзол.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВидишь, в недрах гор взошел\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарь Маммон на свой престол.\u003ca class=\"ref\" id=\"r92\" href=\"#n92\" data-tip=\"№92 \u0026#183; Потерянный рай (Мильтон); Евангелие от Матфея\"\u003e92\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСветовой эффект усилен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаревом его плавилен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак облик этих гор громаден!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак он окутан до вершин\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНенастной тьмой глубоких впадин\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мглой лесистых котловин!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак угольщики, черномазы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкопившиеся в них пары,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто это клубы газа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз огнедышащей горы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ правда, языком багряным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБросаясь к облакам седым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь пламя борется с туманом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ пробивается сквозь дым.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВон искры отлетают блесткой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВон в виде крупного зерна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вот скала у перекрестка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся доверху озарена!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаммон залить не поскупился\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИллюминацией чертог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ рад, что ты сюда явился.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж начался гостей приток.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкопленья шумного кортежа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтолкнут меня с тропы проезжей!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей за что-нибудь схватись,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то сорвешься с кручи вниз.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа курганы лег туман,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗавывает ураган.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГул и гомон карнавала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаспугал сычей и сов.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВетер, главный запевала,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе щадит красы лесов.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ расселины полны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВорохами бурелома\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ обломками сосны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак развалинами дома,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСброшенного с крутизны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все ближе, ближе вой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУлюлюканье и пенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрашного столпотворенья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМчащегося в отдаленье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа свой шабаш годовой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьмы  (хором)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа Брокен ведьмы тянут в ряд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОвес взошел, ячмень не сжат.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам Уриан, князь мракобесья,\u003ca class=\"ref\" id=\"r93\" href=\"#n93\" data-tip=\"№93 \u0026#183; Словарь Аделунга; Немецкая мифология (Гримм)\"\u003e93\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасуется у поднебесья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо воздуху летит отряд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКозлы и всадницы смердят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолос\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаруха Баубо мчит к верхушке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВерхом на супоросой хрюшке.\u003ca class=\"ref\" id=\"r94\" href=\"#n94\" data-tip=\"№94 \u0026#183; Протрептик (Климент Александрийский); Описание Эллады (Павсаний)\"\u003e94\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКолдунье и свинье почет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВперед за бабкою, вперед!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсей кавалькадой верховых,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧертовок, ведьм и лешачих!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолос\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткуда ты?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругой голос\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт Ильзенштейна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛесной тропою чародейной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК сове наведалась в дупло,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТа как надулась, и пошло!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТретий голос\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсвободи проезд, не мешкай!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторой голос\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодумаешь, какая спешка!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа не пыхти ты, не потей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вся в следах твоих когтей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьмы  (хором)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНельзя ли чуть порасторопней?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак в давке сжали, что хоть лопни!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе тыкай вилами в живот!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗадушите в утробе плод!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКолдуны  (половина хора)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолзут мужчины, как улитки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА видите, как бабы прытки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде пахнет злом, там бабий род\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУходит на версту вперед.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругая половина\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще довольно это спорно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ваша баба ни проворна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе мужчина, хоть и хром,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпередит одним прыжком.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолос  (сверху)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожалуйте к нам наверх с плеса!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолос  (снизу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас взберемся на утесы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы вымылись водой холодной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗато и дочиста бесплодны.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОба хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтих ветер. Месяц со звездой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПропал за облачной грядой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы ж вихрем огненным летим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ веселимся, и галдим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолос  (снизу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтой! Стой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолос  (сверху)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто там за образина\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗовет меня со дна теснины?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолос  (снизу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне хочется со всей гурьбой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрошу вас взять меня с собой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа триста лет я еле-еле\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаружу выполз из ущелья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОба хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСядь на козла, садись на шест,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа вилах соверши свой въезд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо знай: ты попадешь туда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСегодня или никогда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолуведьма  (внизу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС начала дня я семеню,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА их никак не догоню.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дома маета внизу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ до хребта не доползу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьмы  (хором)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВтиранье ускоряет прыть,\u003ca class=\"ref\" id=\"r95\" href=\"#n95\" data-tip=\"№95 \u0026#183; Золотой осёл (Апулей); Молот ведьм (Крамер и Шпренгер)\"\u003e95\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРвань может парусом служить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСадись в корыто, и айда!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСегодня или никогда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОба хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда ж у ног увидим кряж,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпустится весь поезд наш,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРассядемся всем нашим роем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолпой своей хребет покроем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Садятся на землю.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСрамниц, страшилищ всяких, рож!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА крик какой, какой галдеж!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоистине живой пример\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМегер и фурий без манер.\u003ca class=\"ref\" id=\"r96\" href=\"#n96\" data-tip=\"№96 \u0026#183; Эвмениды (Эсхил); Энеида (Вергилий)\"\u003e96\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне руку в свалке протяни, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас разлучат средь толкотни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде ты?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (издали)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ здесь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНашел едва.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВступлю в хозяйские права.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭй, рвань, с дороги свороти\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дайте дьяволу пройти!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавай-ка, доктор, вон из давки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ этой дикой тесноты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереберемся под кусты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мирно посидим на травке.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, у тебя все парадоксы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа Брокен совершить подъем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда весь ад на шабаш стекся,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб тут сидеть особняком!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ враг таких больших компаний,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мне милее у костра\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНочные толки на поляне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я б взошел на верх бугра.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам весь ваш цвет в разгаре пьянства,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе дьявольское атаманство.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сатана у самых круч\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКо многим тайнам держит ключ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам и загадок новый узел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, царедворцы не по мне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня б их вид переконфузил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавай побудем в тишине.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь в маленьком кружке интимном\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсть место тонкостям взаимным.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь, видишь ли, полутемно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ это лучше полусвета.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа старых ведьмах домино,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолоденькие же раздеты.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудь с ними ради этикета\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбезен, так заведено.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, слышишь,\u0026#160;— музыка давно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак им играть не опротивит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда так зверски все фальшивят?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо пусть в разброде струнный хор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоставим пары для кадрили.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто скажешь ты? Какой простор!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКругом до самых дальних гор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПылает за костром костер.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы видишь зрелище обилья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТанцоров, пьяниц и обжор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайди, где лучше бы кутили.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы выступишь как сатана\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли в обличье колдуна?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б предпочел инкогнито огласке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо принято встречаться на пиру\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри орденах, в открытую, без маски.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ нас не носят ордена Подвязки,\u003ca class=\"ref\" id=\"r97\" href=\"#n97\" data-tip=\"№97 \u0026#183; Устав ордена Подвязки (1348)\"\u003e97\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМое копыто больше ко двору.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой знак отличья оползла улитка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй и тебя пронюхать удалось.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаиться здесь — бесплодная попытка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь сразу видят каждого насквозь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПройдемся вдоль костров по этим скатам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы будешь женихом, я буду сватом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(К группе старичков вокруг полупотухшего костра.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто вы засели здесь в тени ракит?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоближе к поколенью молодому!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам в середине спор вовсю кипит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтмалчиваться можно ведь и дома.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГенерал\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтоишь за честь и гордость наций,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак вдруг на них находит стих:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНароды вероломней граций\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ любят только молодых.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМинистр\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе изолгались, вот в чем горе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБылой уклад невозвратим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокамест были мы в фаворе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВек был взаправду золотым.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазбогатевший делец\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мы ловить умели случай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мы хватали через край,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг все закрылось черной тучей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ славные деньки прощай.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПисатель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК чему писать большие книги,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда их некому читать?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперешние прощелыги\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмеют только отрицать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (вдруг на вид страшно состарившись)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе день ли скоро Страшного суда?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак погляжу на этих я каналий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся бочка вытекла, на дне бурда, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНевольно мысль приходит о финале.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьма-старьевщица\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭй, судари, а ну-ка к нам!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСговорчивее нет торговки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаким приличным господам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой хлам продам я по дешевке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи на каких торгах земли\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобра такого не найдете.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе то, что тут лежит в пыли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбломки эти и лохмотья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесчастье людям принесли.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь все клинки от крови ржавы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа рюмках — отпечатки губ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС остатками былой отравы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКолечком каждым душегуб\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадругивался над невинной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь нет ни одного ножа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый не вонзили в спину\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз мести или грабежа.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу что ты вынесла на рынок?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь это заваль, старина!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет у тебя, кума, новинок?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь иные времена.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ публика, и самый торг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ярмарка — один восторг!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК вершине двинулся поток.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПихаешь в бок, сбивают с ног.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто там?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛилит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа мой вопрос,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожалуйста, ответь мне прямо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервая жена Адама.\u003ca class=\"ref\" id=\"r98\" href=\"#n98\" data-tip=\"№98 \u0026#183; Алфавит Бен-Сиры; Зогар\"\u003e98\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВесь туалет ее из кос.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстерегись ее волос:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна не одного подростка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСгубила этою прической.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВон две сидят. Я — к молодой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты ступай к другой, седой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредставимся сейчас же им\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ танцевать их пригласим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (танцуя с молодою)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ видел яблоню во сне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа ветке полюбились мне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДва спелых яблока в соку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ влез за ними по суку.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасавица\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам Ева-мать внушила страсть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРвать яблоки в садах и красть.\u003ca class=\"ref\" id=\"r99\" href=\"#n99\" data-tip=\"№99 \u0026#183; Книга Бытия\"\u003e99\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо эту сторону плетня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсть яблоки и у меня.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (танцуя со старухою)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ видел любопытный сон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтвол дерева был расщеплен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакою складкой шла кора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто мне понравилась дыра.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаруха\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбезник с конскою ногой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы — волокита продувной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГотовьте подходящий кол,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб залечить дуплистый ствол.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроктофантасмист  \u0026#160;(Задопровидец)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроклятая, безмозглая орда!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоказано как будто всесторонне:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ духов нет конечностей. Тогда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак можете ходить вы в котильоне?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасавица  (танцуя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто взъелся он на наш невинный бал?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (танцуя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗавистник и дурак, вот и пристал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн просто глуп, как дважды две четыре,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все не по нутру ему, придире.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь в пересудах он находит вкус,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сам как бы ходячий комментарий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК делам, к словам, к вещам, ко всякой твари,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК тому, что с вами в паре я кружусь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроктофантасмист\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы тут еще? Ведь я сказал вам: сгиньте!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ наш просвещенный век я слишком тих.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ природе нет кикимор и шишиг!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ж вы толчетесь в этом лабиринте\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в Тегеле на чердаках моих\u003ca class=\"ref\" id=\"r100\" href=\"#n100\" data-tip=\"№100 \u0026#183; Статья Николаи о фантазмах (1799)\"\u003e100\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбосновались в виде домовых?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасавица\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак терпят скучных приставал таких!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроктофантасмист\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, духи, это вам в лицо скажу:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСегодня я не одержал победы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я еще раз как-нибудь приеду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ уж тогда конец вам положу!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТанцы продолжаются.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе пощажу ни сил своих, ни дней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб извести поэтов и чертей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас он в лужу сядет для поправки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн гнев смиряет, охлаждая зад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоставленные к копчику пиявки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт вида духов дух его целят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Фаусту, переставшему танцевать.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ж даму упустил ты в заключенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ почему упорно так молчишь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, изо рта у ней во время пенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг выпрыгнула розовая мышь.\u003ca class=\"ref\" id=\"r101\" href=\"#n101\" data-tip=\"№101 \u0026#183; Blockes-Berges Verrichtung (Преториус); Немецкие саги (братья Гримм)\"\u003e101\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу что ж, не каждое ведь лыко в строку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагодари, что мышка не сера,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не горюй об этом так глубоко!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗатем…\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, что ж?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзгляни на край бугра.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефисто, видишь, там у края\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТень одинокая такая?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна по воздуху скользит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемли ногой не задевая.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ девушки несчастный вид\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, как у Гретхен, облик кроткий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА на ногах ее — колодки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем смотреть на тот курган?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь это призрак, истукан\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз тех видений и иллюзий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВблизи которых стынет кровь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожалуйста, не прекословь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНебось ты слышал о Медузе?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокойница, которой глаз\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРука родная не закрыла!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, это тело Гретхен милой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторая мне отдалась!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут колдовской обычный трюк:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе видят в ней своих подруг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ты бела, как ты бледна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоя краса, моя вина!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ красная черта на шейке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто бы по полотну\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтбили ниткой по линейке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКайму, в секиры ширину.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй голову срубил Персей.\u003ca class=\"ref\" id=\"r102\" href=\"#n102\" data-tip=\"№102 \u0026#183; Теогония (Гесиод); Метаморфозы (Овидий) и др.\"\u003e102\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна снимается, как крышка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля обезглавленной ловчей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрать иногда ее под мышку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем ты растравляешь боль?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри, как шумно на поляне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в Пратере во дни гулянья.\u003ca class=\"ref\" id=\"r103\" href=\"#n103\" data-tip=\"№103 \u0026#183; Топография Вены (Пратер)\"\u003e103\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеатр приехал на гастроль.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПовеселить тебя позволь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто тут дают?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eSеrvibilis  \u0026#160;(Подлиза)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас начнут премьеру\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСедьмую, между прочим, за сезон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеатр привержен к новостям без меры.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако перейдемте в павильон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдет любительское обозренье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ любительском к тому же исполненье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ тоже труд любителей делю:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ поднимать им занавес люблю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэтому я должен удалиться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа Брокене и место этой птице.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r108\" href=\"#n108\" data-tip=\"№108 \u0026#183; Описание путешествия по Германии и Швейцарии (Николаи); Статья Штольберга против Богов Греции и др.\"\u003e108\u003c/a\u003e\u003ca class=\"ref blk\" id=\"r105\" href=\"#n105\" data-tip=\"№105 \u0026#183; Сон в летнюю ночь (Шекспир); Буря (Шекспир) и др.\"\u003e105\u003c/a\u003eСон в Вальпургиеву ночь,\u003c/h2\u003e\n\u003cdiv class=\"l\"\u003eили Золотая свадьба Оберона и Титании\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИнтермедия\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДиректор театра\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы сегодня отдохнем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМидинга потомки!\u003ca class=\"ref\" id=\"r106\" href=\"#n106\" data-tip=\"№106 \u0026#183; На смерть Мидинга (Гёте)\"\u003e106\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСценой будет все кругом —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоры, скал обломки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗолотая свадьба — плод\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолстолетья в браке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо и так за годом год\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадо жить без драки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОберон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДухи, духи, вот пароль\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНашего союза:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Королева и король\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбновляют узы\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПук\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС Пуком — кобольдов толпа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаленькие дети,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо выделывают па\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛучше, чем в балете.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАриэль\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ поднес свирель ко рту.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвуков благородство\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокоряет красоту\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ смирит уродство.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОберон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасторгайте гименей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВременами, семьи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы жить еще тесней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстальное время.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТитания\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли в браке двое злюк,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадо в час досужий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтослать жену на юг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на север мужа.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОркестр тутти  (fortissimo)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКомары, и мошкара,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сверчки-горланы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБаритоны, тенора —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаши меломаны.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоло\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа горой, надув пузырь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаиграл волынщик,\u003ca class=\"ref\" id=\"r107\" href=\"#n107\" data-tip=\"№107 \u0026#183; Дьявол, играющий на волынке (гравюра Шёна); Handw\u0026#246;rterbuch des deutschen Aberglaubens\"\u003e107\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдешних сборищ богатырь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлупостей зачинщик.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесложившийся дух\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ из гадов двух гибрид\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ синтезе каком-то\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа живую нитку сшит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак строфа экспромта.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПарочка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРадостно вдвоем плестись\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо лугам вприпрыжку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо ведь ты без крыльев ввысь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе взлетишь, трусишка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбопытный путешественник\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто правда или сон?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ глазам не верю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнаменитый Оберон\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредо мной у двери.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОртодокс\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОберон хоть без рогов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе же черт в итоге,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак и все в конце концов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГреческие боги.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСеверный художник\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ набрасываю суть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасками скупыми,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо и я когда-нибудь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПобываю в Риме.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПурист\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьм хотя и весел круг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо нецеломудрен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько, например, у двух\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНос едва припудрен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолодая ведьма\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПудру на лицо и лиф\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадо престарелым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ ж красуюсь, все раскрыв,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбнаженным телом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМатрона\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы б вели напрасно спор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО вопросах плоти.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы ж, голубка, до тех пор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаживо сгниете.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКапельмейстер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМушки к голенькой летят\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не смотрят в ноты.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько все пошло на лад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСбились все со счета.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФлюгер  \u0026#160;(поворачиваясь в одну сторону)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСливки общества, верхи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько званым место.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзбранные женихи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛучшие невесты!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Поворачиваясь в другую сторону.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПровались в тартарары\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроходимцы-гости.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА не то я сам с горы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПровалюсь со злости!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКсении\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛязгом ножниц на ремне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДайте насекомым\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТуш исполнить сатане\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ его знакомым.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГеннингс\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадрываются сверчки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак, что вянут уши,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ считают, чудаки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто у них есть души.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМузагет\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ пришел на юбилей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ застрял до часу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьмы севера милей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДевственниц Парнаса.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБывший гений своего времени\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ у немцев есть ступень\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысшего паренья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто брокенская сень\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа заре весенней.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбопытный путешественник\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто так злится, не пойму,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподин сердитый?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВидно, чудятся ему\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь иезуиты.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖуравль\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто так чист душою всей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот не загрязнится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛовлей рыбы у чертей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗамутив водицу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСветский человек\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем фальшивей пустосвят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем с ним спор бесцельней:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДаже брокенский разврат\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля него молельня.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТанцор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе литавры ль вдалеке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСловно гром грохочут?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто цапли в тростнике\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ унисон гогочут.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТанцмейстер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГляньте на коротыша\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кувалду эту!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА туда же антраша,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПа и пируэты!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкрипач\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли бы волынщик смолк,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКаждый этой ночью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь друг друга бы, как волк,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазорвал на клочья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДогматик\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, критикой меня не сбить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаз черт есть вид объекта,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо, значит, надо допустить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто он и сам есть некто.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдеалист\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ — содержанье бытия\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ всех вещей начало.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо если этот шабаш — я,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо лестного тут мало.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРеалист\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРеальность жизни — мой кумир.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто может быть бесспорней?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСегодня, впрочем, внешний мир\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне неприемлем в корне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСупернатуралист\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ здесь не просто ротозей:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО выводах заботясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДо ангелов я от чертей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДойду путем гипотез.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкептик\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабыли, так попутал черт,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде зад у них, где перед.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, только тот во взглядах тверд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто ничему не верит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКапельмейстер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКомары и мошкара,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗахотели взбучки?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВправду ли вы мастера\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли недоучки?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛовкачи\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУслужаем второпях\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНашим мы и вашим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМожно — пляшем на ногах,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВверх ногами пляшем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНедалекие\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаши лучшие деньки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗакатились к черту.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзносились башмаки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ штаны протерты.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлуждающие огни\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа болотах дух несвеж.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас поздравить не с чем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДаже мы средь вас, невеж,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоспитаньем блещем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПадающая звезда\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ лежу от вас на пядь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа навозной куче.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе поможете ли встать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы звезде падучей?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолстяки\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭй, посторонись, плотва,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМелюзга, младенцы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыступают существа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлотных корпуленций.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПук\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолстокожие, как слон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛежебоки, сидни!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПук, причудливый, как сон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНынче всех солидней.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАриэль\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, кто с крыльями, за мной!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоздух тих и влажен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХолм за просекой лесной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРозами усажен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОркестр  (pianissimo)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрояснился небосклон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТени отступили,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМгла рассеялась, как сон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазлетелась пылью.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eПасмурный день. Поле\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст и Мефистофель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдна, в несчастье, в отчаянье! Долго нищенствовала — и теперь в тюрьме! Под замком, как преступница, осужденная на муки,\u0026#160;— она, несравненная, непорочная! Вот до чего дошло!\u0026#160;И ты допустил, ты скрыл это от меня, ничтожество, предатель! Можешь торжествовать теперь, бесстыжий, и в дикой злобе вращать своими дьявольскими бельмами! Стой и мозоль мне глаза своим постылым присутствием! Под стражей! В непоправимом горе! Отдана на расправу духам зла и бездушию человеческого правосудия! А ты тем временем увеселял меня своими сальностями и скрывал ужас ее положения, чтобы она погибла без помощи.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна не первая.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтыдись, чудовище!\u0026#160;Вездесущий дух, услышь меня! Верни это страшилище в его прежнюю собачью оболочку, в которой он бегал, бывало, передо мною ночами, сбивая с ног встречных и кладя им лапы на плечи. Возврати ему его излюбленный вид, чтобы он ползал передо мною на брюхе и я топтал его, презренного, ногами!\u0026#160;Не первая!\u0026#160;Слышишь ли ты, что говоришь? Человек не мог бы произнести ничего подобного! Точно мне легче от того, что она не первая, что смертных мук прежних страдалиц было недостаточно, чтобы искупить грехи всех будущих! Меня убивают страдания этой единственной, а его успокаивает, что это участь тысяч.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу вот опять мы полезли на стену, ну вот мы снова у точки, где кончается человеческое разумение! Зачем водиться с нами, если мы так плохи? Хочет носиться по воздуху — и боится головокружения! Кто к кому привязался — мы к тебе или ты к нам?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе скалься так плотоядно! Мне тошно!\u0026#160;Неизъяснимо великий дух, однажды явившийся мне, ты знаешь сердце мое и душу, зачем приковал ты меня к этому бесстыднику, который радуется злу и любуется чужой гибелью?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы кончил?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпаси ее или берегись! Страшнейшее проклятье на голову твою на тысячи лет!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не могу разбить ее оков, не могу взломать двери ее темницы! \u0026#171;Спаси ее!\u0026#187; Кто погубил ее, я или ты?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст дико смотрит по сторонам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы тянешься за молниями, громовержец?\u003ca class=\"ref\" id=\"r109\" href=\"#n109\" data-tip=\"№109 \u0026#183; Илиада (Гомер); Метаморфозы (Овидий)\"\u003e109\u003c/a\u003e Счастье, что они не даны тебе, смертному! Уничтожить несогласного — какой простой выход из затруднения!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоставь меня к ней! Она должна выйти на волю!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА опасность, которой ты себя подвергаешь? Отчего мы бежали? В городе свежа еще память о пролитой тобою крови. Над местом убийства реют духи мщенья, подстерегающие возврат убийцы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто еще ты мне скажешь? Пусть обрушится на тебя вселенная, чудовище! Перенеси меня к ней, сказано тебе, и освободи ее!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу вот что. Я доставлю тебя туда. Но ведь не все на земле и небе в моих силах! Вот что я могу сделать. Я усыплю смотрителя. Завладей ключами и выведи ее из темницы своими силами. Я буду стеречь снаружи, волшебные кони будут со мною, я умчу вас подальше. Это в моей власти.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ путь немедля!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eНочь в поле\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст и Мефистофель проносятся на вороных конях.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем они к лобному месту летят?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе знаю, что с ними со всеми.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мечутся стаей вперед и назад.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакое уж ведьмино племя.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКадят перед плахой, кропят эшафот.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВперед без оглядки! Вперед!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eТюрьма\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст со связкой ключей перед железной дверцей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСжимается от боли сердце,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрудь скорбью мира стеснена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа этою железной дверцей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи в чем невинная, она.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы медлишь, ты войти не смеешь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ней встретиться лицом к лицу?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивей! Пока ты цепенеешь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы близишь жизнь ее к концу!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Берется за замок.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолос внутри\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб вольнее гулять,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзвела меня мать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ отец-людоед\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбглодал мой скелет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ меня у бугра\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗакопала сестра\u003ca class=\"ref\" id=\"r110\" href=\"#n110\" data-tip=\"№110 \u0026#183; О можжевеловом дереве (сказка); Детские и семейные сказки (братья Гримм)\"\u003e110\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоловою к ключу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вспорхнула весной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСерой птичкой лесной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лечу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (отворяя дверь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй невдомек, что я сломал засов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ слышу песнь ее и шум шагов.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Входит в камеру.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита  (прячась на подстилке)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдут за мною! Скоро под топор!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (вполголоса)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолчи, мы увезем тебя и спрячем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита  (у него в ногах)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудь милостив! Смягчи свой приговор!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы спящих сторожей разбудишь плачем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Старается разбить ее цепи.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита  (на коленях)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто дал тебе, мучитель мой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВласть надо мною, бесталанной?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай до утра дожить! Постой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКазнь завтра ведь! Что ж ты так рано\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа мной врываешься сюда?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Встает.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ молода, я молода\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ умираю так нежданно!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо был моей красы расцвет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна меня и погубила.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо мной был милый, ныне нет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпал венок, увял букет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе жми меня с такою силой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА лучше б от могилы спас!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ зла тебе не причинила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя я вижу в первый раз.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак эту боль мне превозмочь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас пойду, лишь миг отсрочь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б грудью покормила дочь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне дали ночь проплакать с нею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА утром отняли, злодеи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ говорят,\u0026#160;— мои дела,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСама-де в лес ее снесла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в сказке есть про двух малюток.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вся дрожу от этих шуток\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ оттого невесела.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (на коленях перед нею)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвой милый рядом и мгновенно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсвободит тебя из плена.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита  (падая рядом с ним на колени)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей вдвоем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа колени станем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ к небу взовем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред святым изваяньем!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри, под стенами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтой темницы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсеми огнями\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАд дымится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ смеха раскаты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго, супостата!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (громко)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГретхен! Гретхен!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита  (прислушиваясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо голос друга, как когда-то!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасенье! Наше место свято!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Вскакивает. Цепи падают.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе страшно ничего ничуть!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУшам поверить я не смею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде он? Скорей к нему на шею!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей, скорей к нему на грудь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСквозь мрак темницы неутешный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСквозь пламя адской тьмы кромешной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ улюлюканье и вой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн крикнул \u0026#171;Гретхен!\u0026#187;, милый мой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ тут.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита  (обнимая его)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы тут? О, повтори!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн тут! Он тут! Он все исправит!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде ужас завтрашней зари?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде смерть? Меня не обезглавят!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ спасена!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в мыслях у того угла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде встретила тебя впервые.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот сад и деревца кривые,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде с Мартой я тебя ждала.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (с поспешностью)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдем! Идем!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавай в покое\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПобуду миг один с тобою!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Прижимается к нему.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпеши!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКругом ни души.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы дорого заплатим\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа то, что время тратим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазлуки срок был невелик,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты от ласк совсем отвык\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ холоден к моим объятьям!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто мне с тобой такая жуть?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы разучился целоваться!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБывало, станем обниматься,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ страшно,\u0026#160;— разорвется грудь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вдруг — какой-то холод, муть!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦелуй меня! Ах, ты так вял,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя сама я поцелую!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Обнимает его.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой ты равнодушный стал!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде растерял ты страсть былую?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы мой был. Кто тебя украл?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Отворачивается от него.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой друг, теперь одно: в дорогу!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо имя наших жарких нег\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРешись скорее на побег!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей со мною из острога!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита  (поворачиваясь к нему)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо это правда ты? Ей-богу?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, да!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ты взломал засов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ подошел к моей постели?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе не страшно в подземелье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС такой, как я? И неужели\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы выпустить меня готов?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпеши! Уж начало светать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУсыпила я до смерти мать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДочь свою утопила в пруду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБог думал ее нам на счастье дать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА дал нам на беду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы здесь? И это не во сне?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе время я в бреду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы не ушел? Дай руку мне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО милая рука!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо в чем она? Ах, узнаю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна в крови слегка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВину твою мы скрыть должны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, шпагу убери свою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВложи ее в ножны.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто было — поросло быльем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпеши! Мы пропадем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстанься в живых, желанный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз всех нас только ты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ соблюдай сохранно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМогильные цветы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы выкопай лопатой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТри ямы на склоне дня:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля матери, для брата\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ третью для меня.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМою копай сторонкой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНевдалеке клади\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ приложи ребенка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТесней к моей груди.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ с дочкою глубоко\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗасну, прижавшись к ней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖаль, не с тобою сбоку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС отрадою моей!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо все теперь иначе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть то же все на вид,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне нет с тобой удачи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ холод твой страшит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдем! Доверься, не тяни!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа волю?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВон из западни!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам смерть моя настороже\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтоит средь поля на меже.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам спать без просыпу я лягу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ больше не ступлю ни шагу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо как же, Генрих? Ты — домой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой свет?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если бы мне за тобой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВослед!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДверь настежь! Только захоти!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНельзя и некуда идти,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа если даже уйти от стражи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто хуже участи бродяжьей?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС сумою по чужим одной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШататься с совестью больной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда с оглядкой, нет ли сзади\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВрагов и сыщиков в засаде!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда я остаюсь с тобой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей! Скорей!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпаси свою бедную дочь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрочь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдоль по обочине рощ,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧерез ручей, и оттуда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВлево с гнилого мостка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК месту, где из пру\u0026amp;#769;да\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысунулась доска.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДрожащего ребенка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда всплывет голова,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХватай скорей за ручонку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна жива, жива!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпомнись! Только лишь шаг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ прочь неволя и страх!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо каждый миг нам дорог.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, только б пройти пригорок!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа камушке том моя мать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Мороз подирает по коже!),\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа камушке том моя мать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСидит у придорожья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна кивает головой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБолтающейся, неживой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТяжелою от сна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй никогда не встать. Она\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтарательно усыплена\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля нашего веселья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда у нас была весна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде вы теперь, те времена?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда вы улетели?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаз не добром,\u0026#160;— тебя, мой ангел милый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридется унести отсюда силой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, принужденья я не потерплю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе стискивай меня ты так ужасно!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ чересчур была всегда безгласна.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж брезжит день. Любимая, молю!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, это день. День смерти наступил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ думала, что будет он днем свадьбы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если бы все это раньше знать бы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе говори, что ты у Гретхен был.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦветы с моей косынки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСорвут, и, хоть плясать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНельзя на вечеринке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы свидимся опять.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа улице толпа и гомон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ площади их не вместить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот стали в колокол звонить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот уж жезл судейский сломан.\u003ca class=\"ref\" id=\"r111\" href=\"#n111\" data-tip=\"№111 \u0026#183; Каролина (1532); Материалы суда над Сусанной Брандт\"\u003e111\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне крутят руки на спине\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тащат силою на плаху.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе содрогаются от страха\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ждут, со мною наравне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне предназначенного взмаха\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ последней, смертной тишине!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем я дожил до такой печали!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (в дверях)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБегите, или вы пропали.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе эти пререканья невпопад!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж светится полоска небосклона,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кони вороные под попоной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОзябли, застоялись и дрожат.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто это вырос там из-под земли?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн за моей душой пришел, презренный!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо стены божьего суда священны!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорее прочь уйти ему вели!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы будешь жить! Живи! Ты жить должна!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ покоряюсь божьему суду.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИди за мною, или я уйду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМое ведь дело, знаешь, сторона.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМаргарита\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпаси меня, отец мой в вышине!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы ангелы, вокруг меня, забытой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвятой стеной мне станьте на защиту!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, Генрих, страх внушаешь мне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсуждена на муки!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолос свыше\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасена!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (Фаусту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей за мною!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Исчезает с Фаустом.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолос Маргариты  (из тюрьмы, замирая)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГенрих! Генрих!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2 class=\"part\"\u003eЧасть вторая\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2 class=\"part\"\u003eАкт первый\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r116\" href=\"#n116\" data-tip=\"№116 \u0026#183; Божественная комедия (Данте); Государство (Платон) и др.\"\u003e116\u003c/a\u003eКрасивая местность\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст лежит на цветущем лугу. Он утомлен, неспокоен и старается уснуть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСумерки. В воздухе порхает хоровод маленьких прелестных духов.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАриэль  (пение под аккомпанемент эоловых арф)\u003ca class=\"ref\" id=\"r112\" href=\"#n112\" data-tip=\"№112 \u0026#183; Буря (Шекспир)\"\u003e112\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько первый дождь цветочный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтягчит весенний сад\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ луга травою сочной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗеленея, заблестят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭльфов маленьких участье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсем в беде уделено,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо заслугам ли несчастье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли без вины оно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПаря над спящим чередой воздушной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУймите, как всегда великодушно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго души страдающей разлад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРассейте ужас, сердцем не изжитый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмягчите угрызений жгучий яд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНочь на четыре четверти разбита,\u003ca class=\"ref\" id=\"r113\" href=\"#n113\" data-tip=\"№113 \u0026#183; Всеобщая история (Полибий); Краткое изложение военного дела (Вегеций)\"\u003e113\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУпотребите с пользой все подряд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасположив его на мягком дерне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРосой забвенья сбрызните чело.\u003ca class=\"ref\" id=\"r114\" href=\"#n114\" data-tip=\"№114 \u0026#183; Государство (Платон); Энеида (Вергилий)\"\u003e114\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПускай разляжется он попросторней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ отдохнет, пока не рассвело.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе пожалейте сил, чтоб душу эту\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВернуть окрепшею святому свету.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор  (пение поодиночке, попарно и в других сочетаниях)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТишина благоуханна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУбывает духота.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗатуманились поляны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаступает темнота.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпойте песенку, как детям,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТреволненья прочь гоня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ глазам усталым этим\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗатворите двери дня.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНочь пришла и разместила\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБережно звезду к звезде.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯрко искрятся светила\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ темном небе и воде,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа поверхности озерной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ черной горной вышине,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ печатью миротворной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлещет месяц на волне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтошли часы мытарства,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ веселья час забыт.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВремя — лучшее лекарство,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВерь тому, что предстоит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред тобою край лесистый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорный благодатный край.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВолны нивы серебристой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбещают урожай.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаберись желаний новых,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВстретив солнечный восход.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСон держал тебя в оковах,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСбрось с себя его налет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодражать другим не надо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ бояться неудач:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПобеждает все преграды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто понятлив и горяч.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрашный шум свидетельствует о приближении солнца.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАриэль\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлышите, грохочут Оры!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько духам слышать впору,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак гремят ворот затворы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред новорожденным днем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФеба четверня рванула,\u003ca class=\"ref\" id=\"r115\" href=\"#n115\" data-tip=\"№115 \u0026#183; Илиада (Гомер); Метаморфозы (Овидий)\"\u003e115\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвет приносит столько гула!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУши оглушает гром,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлепнет глаз, дрожат ресницы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШумно катит колесница,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмертным шум тот не знаком.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБойтесь этих звуков. Бойтесь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе застали б вас врасплох.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы не оглохнуть, скройтесь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнутрь цветов, под камни, в мох.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпять встречаю свежих сил приливом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаставший день, плывущий из тумана.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в эту ночь, земля, ты вечным дивом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ ног моих дышала первозданно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы пробудила вновь во мне желанье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТянуться вдаль мечтою неустанной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ стремленье к высшему существованью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбъятый мглою мир готов раскрыться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть обозначившись зарею ранней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ лесу на все лады щебечут птицы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСинеют прояснившиеся дали,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОвраг блестящей влагою дымится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сонная листва на перевале\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорит, росинками переливая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокамест капли наземь не упали.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе превращается в сиянье рая.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА там, в горах, седые великаны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУже румянцем вспыхнули по краю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни встречают день завидно рано,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА к нам он приближается позднее.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот луч сбежал на горные поляны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот он спустился ниже, пламенея,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот снизился еще одной ступенью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот солнце показалось! Я не смею\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоднять глаза из страха ослепленья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак обстоит с желаньями. Недели\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы день за днем горим от нетерпенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вдруг стоим, опешивши, у цели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесоразмерной с нашими мечтами.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы светоч жизни засветить хотели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнезапно море пламени пред нами!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто это? Жар любви? Жар неприязни?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас может уничтожить это пламя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот мы опускаем взор с боязнью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК земле, туманной в девственном наряде,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде краски смягчены разнообразней.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, солнце, ты милей, когда ты — сзади.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПередо мной сверканье водопада.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ восхищен, на это чудо глядя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВода шумит, скача через преграды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРождая гул и брызгов дождь ответный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ яркой радуге окрестность рада,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторая игрою семицветной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзменчивость возводит в постоянство,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо выступая слабо, то заметно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ обдает прохладою пространство.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ней — наше зеркало. Смотри, как схожи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДушевный мир и радуги убранство!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТа радуга и жизнь — одно и то же.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eИмператорский дворец\u003ca class=\"ref\" id=\"r117\" href=\"#n117\" data-tip=\"№117 \u0026#183; Золотая булла (1356); Новая хроника (Виллани) и др.\"\u003e117\u003c/a\u003e\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТронная зала. Государственный совет в ожидании императора. Трубы. Входят придворные всякого рода, великолепно одетые. Император восходит на трон, справа от него становится астролог.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПривет вам всем. Вы в полном сборе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз дальних мест сошлись у трона.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМудрец уж занял пост исконный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо нет шута на наше горе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДворянский сын\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн нес ваш шлейф, и вдруг, бедняжка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа лестнице упал врастяжку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГуляку вынесли. Пузан\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКондрашкой хвачен или пьян.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругой дворянский сын\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо старому шуту мгновенно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПреемник вызвался на смену.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНарядом — щеголь, но урод\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакой, что оторопь берет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред ним у цели вожделенной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкрестил секиры караул,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа вот он: мимо прошмыгнул.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (на коленях перед троном)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ненавистно и желанно?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто нужно и не нужно нам?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто изгнано и под охраной?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто и сокровище и хлам?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред кем в душе дрожат вельможи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кем пренебрегают вслух?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто жмется к твоему подножью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВерней и ниже всяких слуг?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь в ребусах нет недостатка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы лучше дай нам их разгадку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКо мне стеклась вся эта знать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдни загадки задавать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкончался шут мой приближенный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмени покойного у трона.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель всходит по ступеням трона и становится слева.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРопот толпы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот новый шут — нам всем капут —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБолтлив и смел — на шею сел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот был как чан —\u0026#160; пропал пузан, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА этот — жердь и тощ, как смерть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы в добрый час сошлись у трона,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМогу порадовать собранье:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК нам звезды неба благосклонны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ нам сулят преуспеянье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо точно ль совещаться надо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ портить скукой и досадой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриготовленья к маскараду?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот этого я не пойму.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо раз вы заседать решили,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ неохоту пересилю\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ слушаюсь. Быть по сему.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКанцлер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаисияннейшая добродетель\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВенчает императора. Лишь он,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВерховной справедливости владетель,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсуществляет право и закон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь он творит на свете правосудье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторого так ждут и молят люди.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвы, все это попусту! К чему\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуше беззлобье, широта уму,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРуке готовность действовать и воля,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда в горячке зла и своеволья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБольное царство мечется в бреду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ порождает за бедой беду?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь выглянь из дворцового окна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТяжелым сном представится страна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, что ты сможешь в ней окинуть оком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаходится в падении глубоком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредавшись беззаконьям и порокам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот скот угнал, тот спит с чужой женой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз церкви утварь тащат святотатцы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПреступники возмездья не боятся\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ даже хвастают своей виной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ суде стоят истцы дрожа.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСудья сидит на возвышенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА рядом волны мятежа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРастут и сеют разрушенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо там, где все горды развратом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПонятия перемешав,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам правый будет виноватым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА виноватый будет прав.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе стало ничего святого.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе разбрелись и тянут врозь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасшатываются основы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторыми все создалось.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ честный человек слабеет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак все кругом развращено.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда судья карать не смеет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС преступником он заодно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(После некоторого молчания.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ дело мрачно описал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо ведь еще мрачней развал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда враждуя меж собою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе ищут, на кого б напасть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолжна добычею разбоя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтать императорская власть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНачальник военных сил\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе стало мирного приюта,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВезде усобицы и смуты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНужна жестокая борьба,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА власть верховная слаба.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМещане в городской ограде\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ рыцарь в крепости средь гор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтсиживаются в засаде,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОказывая нам отпор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНетерпелив солдат наемный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ требует уплаты в срок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе будь за нами долг огромный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе б разбежались наутек.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо берегись дразнить наймита.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе тронь осиного гнезда!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни разграбят города,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм отданные под защиту.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо многих землях бунт в разгаре,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА где не буйствуют низы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе замечают государи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад ними виснущей грозы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКазначей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПришел конец союзным взносам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ денег никаким насосом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь в казну не накачать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИссяк приток подушных сборов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ нас что город, то и норов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ своевольничает знать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь в любом владенье княжьем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХозяйничает новый род.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВластителям мы рук не свяжем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругим раздавши столько льгот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз партий, как бы их ни звали,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпоры мы не создадим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам так же чужды их печали,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мы и наши нужды им.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКому теперь какое дело,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы гвельф, или ты гибеллин?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоя рубашка ближе к телу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе за себя, всяк господин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ всех желанье стать богаче,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа всех дверях замок висячий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо пусто в нашем сундуке.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотритель дворца\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я в таком же тупике.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть экономией мы бредим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы прямо к разоренью едем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе знают меры повара.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОлени, зайцы, гуси, куры,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоставки свежею натурой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе убывают для двора.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗато вина, к несчастью, мало.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде в прежние года, бывало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереполняли нам подвалы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго отборные сорта,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь не то что мелководье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА нет вина совсем в заводе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе выпили их благородья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот — ни капли, пустота.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПускай откроет магистрат\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой погреб нашей пьющей знати.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть напиваются и, кстати,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ управе под столами спят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред всеми я один в ответе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я ростовщику-жиду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак много задолжал в году,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто по своей бюджетной смете\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКонцов с концами не сведу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт недокорму чахнут свиньи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХозяйство все по швам трещит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпим на заложенной перине\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ даже хлеб едим в кредит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор  (после некоторого раздумья)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА у тебя нет жалоб, шут?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА место ли сомненьям тут?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакие жалобы возможны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь этой пышности надежной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда держава так прочна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда твои войска готовы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазбить любые вражьи ковы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда усердия полна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрудолюбивая страна?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь неба ясного такого\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакая буря нам страшна?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРопот толпы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез мыла лезет, егоза.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмеет пыль пускать в глаза.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА врать-то, врать-то как горазд!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ знаю, он проект подаст.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ каждого — своя беда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь денег нет, и в них нужда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх с полу не поднять, мы знаем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз-под земли их откопаем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ горах есть золото в избытке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод зданьями зарыты слитки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы спросишь, кто отроет клад?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПытливый дух с природой в лад.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКанцлер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух и природа — не для христиан.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот где ты уязвим и досягаем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы нечестивцев на кострах сжигаем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа эти лжеученья и обман.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрирода — грех. Дух — сатана. И оба\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРодят сомненья, недоверье, злобу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ нас все по-другому. Основанье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмперии, ее святой оплот —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуховное и рыцарское званье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм власть в стране, им земли и почет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗато крестьянин бестолков\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ горожане без рассудка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ пляшут под чужую дудку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезумцев и еретиков.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы в заговоре с ними всеми,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ты проник под этот свод,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрикрывшись дерзостью острот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб заронить неверья семя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь этих избранных господ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУзнал ученого ответ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто не по вас — того и нет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто не попало в ваши руки\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротивно истинам науки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧего ученый счесть не мог\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо заблужденье и подлог.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе помогают нам беседы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы действуй, а не проповедуй.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто пользы от вниканья в суть?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет денег, ты их и добудь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобуду больше, чем нужда,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРуками голыми добуду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛегко, без всякого труда,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся трудность только в том, откуда?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ века нашествий и невзгод,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда огни пожаров тлели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасаясь бегством, в подземелья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСносил сокровища народ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак будет век, так было в Риме.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, что зарыто в землю встарь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо, вместе с землями твоими,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвое по праву, государь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКазначей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШут разбирается в законе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемля принадлежит короне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКанцлер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ мечтах о золотой казне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе попадитесь к сатане.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотритель дворца\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя б я и в грехах увяз,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПополню кладовых запас.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНачальник военных сил\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДурак неглуп. Откуда клад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе станет спрашивать солдат.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА если вам сомнительно немного,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот человек: спросите астролога.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн изучил небесные тела.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть скажет вам, как на небе дела.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРопот толпы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСошлись у трона руки греть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ людям расставляют сеть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто шут нашепчет на ушко,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМудрец объявит широко.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАстролог  (говорит по подсказке Мефистофеля)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам солнце блещет золотом в лазури,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа деньги служит вестником Меркурий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе возрасты Венера привлекла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ утром нам и вечером мила.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛуна чем недоступней, тем капризней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКровавый Марс угроза нашей жизни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЮпитер краше всех. Сатурн не мал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо малым кажется. Его металл\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе остальные весом превзошел\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дешев, потому что так тяжел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСойдется солнце с месяцем вдвоем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ золото сольется с серебром, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа свете ничему препятствий нет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе рады, достижим любой предмет:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРоскошный сад, отделанный чертог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриязнь красавицы, румянец щек.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак их достать? Ученый человек\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДаст средства к достиженью этих нег.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть он и на два голоса вещал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо ими ничего не доказал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРопот толпы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ слушать лень их дребедень.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВрать мастера, и песнь стара.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлыхал сто раз. Вот и весь сказ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн шарлатан, и все — обман.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе веря дивному открытью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы рады отшутиться все,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО мандрагорах вздор твердите\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ глупости о черном псе.\u003ca class=\"ref\" id=\"r118\" href=\"#n118\" data-tip=\"№118 \u0026#183; Иудейская война (Иосиф Флавий); Естественная история (Плиний) и др.\"\u003e118\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо надо ль поминать о бесе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кто за пятку ловит вас,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда, теряя равновесье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы падаете оступясь?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемля — источник сил глубокий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ свойств таинственных запас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз почвы нас пронзают токи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеотличимые на глаз.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда на месте не сидится\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кости ноют и мозжат\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли сведет вам поясницу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛомайте пол, под вами клад.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРопот толпы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧего-то заломило бок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ палец на ноге затек.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКорежит, локоть онемел\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, кажется, в спине прострел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак, значит, если он не врет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут золота — невпроворот.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак к делу, к делу, пустомеля!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе увернешься все равно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде своды этих подземелий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ это золотое дно?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа время я сложу державу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сам займусь копаньем ям,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо если ты надул, лукавый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроваливай ко всем чертям!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТуда я сам найду дорогу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо если б знали вы, как много\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогатств, забытых по углам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВаляется и ждет владельца!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг вывернет у земледельца\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКубышку золотую плуг;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо всей бесхитростностью, вдруг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСелитру роя на задворках,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайдет бедняк червонцы в свертках\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в страхе выронит из рук.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ж нам сказать про знатока?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот, кто охотится за кладом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзломает своды тайника\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ спустится в соседство с адом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧерез проломы потолка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБокалы, рюмки из рубина,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРяды как жар горящих блюд!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тут же редкостные вина\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго отведыванья ждут.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВино б могло за долгий срок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо капле вытечь из бочонка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо винный камень твердой пленкой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГнилые бочки обволок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе эти перлы виноделья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ эти перстни, ожерелья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНедаром покрывает тьма.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦенить их в блеске дня — не диво,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайти их — требует ума.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак напряги свой ум пытливый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ плугом вытащи на свет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКубышку, полную монет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВпотьмах, когда все кошки серы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе верю я в твои аферы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотемки — истине во вред.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозьми лопату сам, владыка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя возвысит сельский труд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКопай, и под твоей мотыгой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтада златых тельцов сверкнут.\u003ca class=\"ref\" id=\"r119\" href=\"#n119\" data-tip=\"№119 \u0026#183; Книга Исход\"\u003e119\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда в лице твоей любезной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазряженной во все цвета,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСойдутся в блеске ночи звездной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМогущество и красота.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей! Довольно рассуждений!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАстролог  (по-прежнему)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмерь, властитель, нетерпенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть празднество пройдет сперва.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе тем забита голова.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРассеянным житьем досужим\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДаров небес мы не заслужим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто блага ждет, пусть будет благ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ своих желаньях и делах.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто хочет пить — пусть гроздья давит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто ждет чудес — пусть чудо славит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ забавах время проведем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред наступающим постом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кутерьмою беспечальной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаполним праздник карнавальный.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрубы. Все расходятся.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм не понять, как детям малым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто счастье не влетает в рот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б философский камень дал им,\u003ca class=\"ref\" id=\"r120\" href=\"#n120\" data-tip=\"№120 \u0026#183; Алхимические трактаты Арнольда из Виллановы, Луллия и Василия Валентина\"\u003e120\u003c/a\u003e —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФилософа недостает.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r130\" href=\"#n130\" data-tip=\"№130 \u0026#183; Энеида (Вергилий); Мифологическая библиотека (Аполлодор)\"\u003e130\u003c/a\u003e\u003ca class=\"ref blk\" id=\"r133\" href=\"#n133\" data-tip=\"№133 \u0026#183; Триумфы (Петрарка); Триумфальное шествие Максимилиана I и др.\"\u003e133\u003c/a\u003e\u003ca class=\"ref blk\" id=\"r128\" href=\"#n128\" data-tip=\"№128 \u0026#183; Теогония (Гесиод); Описание Эллады (Павсаний)\"\u003e128\u003c/a\u003e\u003ca class=\"ref blk\" id=\"r129\" href=\"#n129\" data-tip=\"№129 \u0026#183; Теогония (Гесиод); Государство (Платон)\"\u003e129\u003c/a\u003eМаскарад\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбширный зал с примыкающими комнатами, украшенный для маскарада.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь не тевтонской пляской смерти\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас встретят ряженые черти,\u003ca class=\"ref\" id=\"r122\" href=\"#n122\" data-tip=\"№122 \u0026#183; Образы смерти (Гольбейн); Росписи Пляски смерти\"\u003e122\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь жизнерадостнее тон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ дни римского коронованья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа Альпами край ликованья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМонархом нашим в виде дани\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК державе присоединен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ папы туфлю лобызая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн с императорским венцом\u003ca class=\"ref\" id=\"r123\" href=\"#n123\" data-tip=\"№123 \u0026#183; Ordo Romanus XIV; Хроники императорских коронаций\"\u003e123\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПривез другой подарок края —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКолпак дурацкий с бубенцом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тех пор, благодаря фиглярству\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереродившись целиком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы прячем светское коварство\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод скоморошьим колпаком.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вот и гости вереницей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроходят в дом из цветника.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще дурачествам пока\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам не приходится учиться:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы от рожденья, где случится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазыгрываем дурака.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСадовницы  (пение под мандолину)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб блеснуть на вечеринке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЩегольством своих обнов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолодые флорентинки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоявились мы на зов.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы набросили на челки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТонкий шелковый покров,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ локонах у нас наколки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз искусственных цветов.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолговечен цвет поддельный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВремя не берет его,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе завянет в срок недельный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРук усердных мастерство.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа цветы пошли обрезки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВместе сшитые тесьмой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ теперь явились в блеске\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСимметричности самой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы привлечь умеем чувство\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не пропадем в тени,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотому что суть искусства\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖенской сущности сродни.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу-ка, что у вас, затейниц?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДайте бросить взгляд один\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа самих вас, коробейниц,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на внутренность корзин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеспроста в аллеях рощиц\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтолько шумной тесноты:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС миловидностью разносчиц\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМогут спорить их цветы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСадовницы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько не торгуйтесь с нами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы сговорчивы с любым\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ крылатыми словами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКаждый дар сопроводим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОливковая ветвь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВетвь с плодами, я при этом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе завидую букетам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНенавистна мне вражда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ по всей своей природе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоплощенье плодородья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМиролюбья и труда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ могу наверняка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПригодиться для венка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВенок из золотых колосьев\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДар Цереры дамам статным\u003ca class=\"ref\" id=\"r124\" href=\"#n124\" data-tip=\"№124 \u0026#183; Фасты (Овидий); Метаморфозы (Овидий)\"\u003e124\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредлагаю в волоса.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмесь полезного с приятным\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаилучшая краса.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтранный венок\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС мальвою бумажной сходство,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз сухого мха листва,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМода терпит сумасбродства\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не любит естества.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтранный букет\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмени мне Теофраст\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДать не мог бы и не даст.\u003ca class=\"ref\" id=\"r125\" href=\"#n125\" data-tip=\"№125 \u0026#183; Исследование о растениях (Теофраст); О причинах растений (Теофраст)\"\u003e125\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРедкостные единицы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько могут мной плениться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо в прическу и на грудь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК моднице какой-нибудь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМожет быть, попасть случится.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВызов\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть искусственность пародий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкромности наперекор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСледует крикливой моде\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ причудой тешит взор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаплетая в кудерьки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗолотые лепестки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПочки роз\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы же скрылись притаясь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСчастлив, кто отыщет нас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРозы ждут начала лета,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто время их расцвета.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ это время с ними в лад\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДышат клятвы и обеты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ огнем любви согреты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСердце, чувство, ум и взгляд.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ крытых зеленых аллеях садовницы со вкусом раскладывают свой товар.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСадовники  (пение под аккомпанемент теорб)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлеск цветов доступен глазу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ о них шумит молва.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА плодов не хвалят сразу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе отведавши сперва.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзявши что-нибудь на пробу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на выбор надкусив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОцените вкус особый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВишен, персиков и слив.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРозы могут быть воспеты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть распустится их кисть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯблоко же и поэту\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадо перед тем разгрызть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПродавщицы, станьте с нами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоместив под общий кров\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРядом с нашими плодами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВашу выставку цветов.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ свежей зелени беседок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь расставленных красот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКаждый сыщет напоследок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПочку, лист, цветок и плод.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод звуки гитар и теорб обе группы продолжают раскладывать свой товар на продажу гуляющим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМать и дочь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМать\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДочка, чуть ты родилась,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧепчик обновила.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лицом ты удалась,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ фигуркой милой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тебе я, дочь моя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогатейшего в мужья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ мыслях находила.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоды шли, за годом год,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолные заботы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазлетелся хоровод\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖенихов без счета.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы плели им сеть интриг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвали их на бал, пикник,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтавили тенета.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыли фанты и лото\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишнею затеей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе повис из них никто\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ тебя на шее.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть сегодня не глупи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на танцах подцепи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМужа-ротозея.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК матери и дочери подходят подруги. Завязывается громкий задушевный разговор. Являются рыбаки и птицеловы с сетями, удочками и ветками, намазанными клеем для ловли птиц. Они и девушки гоняются друг за другом, перебрасываясь веселыми шутками.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДровосеки  (входят грубо и развязно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе прочь сойдите\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС дороги ровной!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы валим бревна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаскаем доски.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри переноске\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСшибем, смотрите!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗато бесспорно:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез нас и дюжей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаботы черной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗамерзли б в стужу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то и хуже,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вы позорно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо мы вас греем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеплее шубы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда потеем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы, дроворубы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолишинели\u003ca class=\"ref\" id=\"r126\" href=\"#n126\" data-tip=\"№126 \u0026#183; Комедия дель арте; Итальянское путешествие (Гёте)\"\u003e126\u003c/a\u003e  \u0026#160;\u0026#160;(нескладно-придурковато)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы дурачины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто гнете спину,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА мы умнее,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе трудим шеи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ наши тряпки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНашивки, шапки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС горбами всеми\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНичуть не бремя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВстаем с постели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивем в безделье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС простонародьем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо рынкам бродим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредлога ищем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вдруг засвищем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтолпотворенье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСодом! Смятенье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА мы в тревоге\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавай бог ноги!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, как с пожара,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАйда с базара!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыть может, плохо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто мы — причина\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереполоха?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам все едино!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПаразиты  (льстиво и корыстно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы, дровоколы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС рукой тяжелой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы, углевозы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез вас нам — слезы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто б приживалу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПерепадало\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт принципала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ доброхота\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа смех, остроты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПозор, бесчестье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ горы лести,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа исполненье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго желаний\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез дров в чулане?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо жгут поленья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрещат камины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе жизнь — малина!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа кухне варят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПекут и жарят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ под котлами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБушует пламя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ рад сластена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда дворовый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз кухни вносит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГостям здоровый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКусок жаркого\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ произносит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой увлеченный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТост за патрона.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПьяный  (в приподнятых чувствах)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоле нашей не препятствуй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе мне братья, все друзья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеснь моя — мое богатство,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВольный воздух — жизнь моя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыпьем! Что вы присмирели?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа раздолье, за веселье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвинь стаканом о стакан,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНепонятливый чурбан!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт дражайшей половины\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВылетел я кувырком.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНазвала меня скотиной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ гороховым шутом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭй, шуты и пустомели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыпьем! Что вы присмирели?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвинь стаканом о стакан!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы-то пьян, а я не пьян.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ скажу вам без утайки:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне в трактире счет открыт.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ хозяина, хозяйки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ служанки пью в кредит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу так двинем всей артелью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа раздолье, за веселье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак, чтоб зазвенел стакан!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаклоняй пониже жбан.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсякому своя дорога,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ у всякого свой вкус,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА лежачего не трогай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли я под стол свалюсь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыпьем, братцы, друг за друга\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ еще полней нальем!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо уже храпит пьянчуга,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРастянувшись под столом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд объявляет о приходе поэтов разных направлений, певцов природы, придворных стихослагателей и прославителей рыцарства. В давке соискателей никто не дает друг другу говорить. Только один протискивается вперед с немногими словами.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСатирик\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ был бы счастья полон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б по прямодушью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ всем пришелся солон\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ правдой резал уши.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПевцы кладбищ и полуночи просят извинения. В данный момент они отвлечены интереснейшей беседой с одним новопоявившимся вампиром,\u003ca class=\"ref\" id=\"r127\" href=\"#n127\" data-tip=\"№127 \u0026#183; Ночные думы (Юнг); Элегия на сельском кладбище (Грей) и др.\"\u003e127\u003c/a\u003e из чего в будущем может развиться новый род поэзии. Герольд принимает это к сведению. Он вызывает к ряженым представительниц греческой мифологии. Они костюмированы по современному, не теряя своих особенностей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрации\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАглая\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖизнь даря, в ее даянье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВкладывайте обаянье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГегемона\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбаяния печатью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаделяйте восприятье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕфросина\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбаятельней всего\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагодарных существо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПарки\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАтропос\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ пришла к вам прясть, старуха,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖизни нить, мое изделье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМного требуется духу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа кручением кудели.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНить кручу я мягче воска,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе щадя своих усилий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы лен, смягченный ческой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе рвался на мотовиле.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь, в пиру, не выходите\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз границ, жалеть придется!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПомните про тонкость нити,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеретянете — порвется.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКлото\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНожницы в распоряженье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне даны — такой позор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПринесло нам поведенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаршей из моих сестер.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУдлиняла без скончанья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрозябание калек,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖизни, полной обещаний,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУкорачивала век.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо и я ведь с молодежью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДопускала произвол.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб держать себя построже,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпрячу ножницы в чехол.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсем даю сегодня волю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрезвым или во хмелю,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсем прощаю, всем мирволю\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ко всем благоволю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛахезис\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне, как более смышленой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеру соблюдать дано.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПостоянно, неуклонно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВертится веретено.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНабегая на катушку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНить должна за ниткой течь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ им не даю друг дружку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбогнать и пересечь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай себе я миг свободы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГибелью я заплачу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНамотавши дни на годы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ мотки сдаю ткачу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВошедших женщин вид неузнаваем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя бы изучили вы античность.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод ласковостью внешней скрыта личность,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторой с вами мы не разгадаем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни красивы, молоды и чинны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто это — фурии, никто не скажет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриблизьтесь к ним, и вам они покажут\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗмеиный нрав под маской голубиной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК их чести, впрочем, здесь они сегодня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде каждый недостатком щеголяет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОвечками себя не выставляют,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вслух зовутся карою господней.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФурии\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАлекто\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы — фурии и не хотим таиться.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо мы вас усыпим. Наш голос вкрадчив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мы, по-женски с вами посудачив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзведем на ваших милых небылицы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы скажем, что они — кокетки, лживы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНехороши ни кожею, ни рожей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто если вы жених, избави боже,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПомолвку надо привести к разрыву.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы пред невестами вас оклевещем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы скажем: \u0026#171;Перед вашим обрученьем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн говорил другим о вас с презреньем\u0026#187;,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вас поссорим карканьем зловещим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМегера\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИгрушки это! Дай им пожениться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я несоответствием пустячным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИспорчу жизнь счастливым новобрачным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазличны времена, несхожи лица.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда желанья с разумом боролись,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольство не спасает от фантазий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ привычном счастье есть однообразье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай людям солнце — захотят на полюс.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ парами людей губить умею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи разу пальцем жертв своих не тронув.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ подсылаю в дом молодоженов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНочами злого духа Асмодея.\u003ca class=\"ref\" id=\"r131\" href=\"#n131\" data-tip=\"№131 \u0026#183; Книга Товита; Вавилонский Талмуд\"\u003e131\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТизифона\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеч и яд, а не злословье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодобают каре грозной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКаждый рано или поздно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа измену платит кровью.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде ты был в тот миг, в ту пору,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак предательство лелеял?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы пожнешь, что ты посеял,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе помогут уговоры.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли даже за бесчестье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМир простит и не осудит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Кто неверен, жить не будет!\u0026#187;\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКамни вопиют о мести.\u003ca class=\"ref\" id=\"r132\" href=\"#n132\" data-tip=\"№132 \u0026#183; Книга пророка Аввакума; Евангелие от Луки\"\u003e132\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭй, расступись! Не вашего разряда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯвилась в маске новая шарада.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвешанная тканями гора\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК нам движется, ввалившись со двора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС клыками, с хоботом, под балдахином,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗагадка, но с ключом к живым картинам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа шее сидя у слона верхом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм правит сверху женщина жезлом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругая, стоя на его хребте,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпокойно, властно блещет в высоте.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДве пленницы шагают по бокам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦепями скованные по рукам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдна, томясь, на волю рвется вон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругая ничего не замечает\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вольною в душе себя считает.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть не таят от нас своих имен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ скажут, что они изображают.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБоязнь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвечи, факелы, лампады\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТочно снятся наяву.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ бежать отсюда б рада,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько цепи не порву.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть смеются зубоскалы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне насмешка не страшна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсем, что в жизни угрожало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ сейчас окружена.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМилый друг мне вырыл яму,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРядом тоже западня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСзади прячется тот самый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто хотел убить меня.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрочь от них куда угодно!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо повсюду смерть грозит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли б я была свободна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе равно мне путь закрыт.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадежда\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдравствуйте, мои сестрицы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрячете под маской лица?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗавтра, сняв наряды эти,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы покажетесь пред всеми\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ вашем настоящем свете.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВерьте, сестры, будет время,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез цветных огней, не в маске,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтанет жизнь сама как в сказке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРадостная задушевность\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУподобит труд гулянью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПревратив существованье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ праздничную повседневность.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо трудясь, то отдыхая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо все вместе, то отдельно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазойдемся мы по краю\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобровольно и бесцельно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе откроют нам объятья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто бы ни был, все равно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛучшее из вероятии\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСбыться где-нибудь должно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазумность\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт Надежды и Боязни\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтступите в глубь прохода.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХудших нет бичей и казней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧеловеческого рода.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ слона-гиганта с башней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПалочкой вожу по залу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо от пагубы всегдашней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтих в цепи заковала.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖенщина же на вершине,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростирающая крылья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредставляет ту богиню,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВласть которой всюду в силе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСветлая богиня дела,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПреодолевая беды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлещет славой без предела,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ зовут ее Победой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗоило-Терсит\u003ca class=\"ref\" id=\"r134\" href=\"#n134\" data-tip=\"№134 \u0026#183; Илиада (Гомер); Десять книг об архитектуре (Витрувий)\"\u003e134\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПостойте, я сейчас вас всех\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазделаю тут под орех.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ первой из почтенных дам\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПобеде этой я задам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазмер ее орлиных крыл\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБедняжке голову вскружил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй кажется, что ей всегда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолжны сдаваться города.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня до исступленья злит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБесстыдство тех, кто знаменит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвижу славу, злость берет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаслуги, подвиги, почет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, все б перевернул вверх дном,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмешав, как в зеркале кривом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, вот ты как, паршивый пес?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот я тебя, горбун, жезлом!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвернулся, негодяй, клубком.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо где ж он? Вместо горбуна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь куча мокрая одна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна свивается в кольцо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ превращается в яйцо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо лопается пополам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯйцо — и открывает нам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнутри пустого пузыря\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГадюку и нетопыря.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолзком гадюка на пустырь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа ней на крыльях нетопырь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб узы вновь восстановить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б не хотел там третьим быть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРопот толпы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧасть уже пустилась в пляс.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ хочу уйти сейчас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДухи носятся кругом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНечисть залетает в дом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе задев едва волос,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто-то мимо пронеслось.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто-то бросилось меж ног.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоднялся переполох.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСгублен бал. Испорчен пир.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто дело тех проныр.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ пред каждым маскарадом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпытным герольдским взглядом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроверяю у портала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриглашенных к карнавалу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб негаданно-нежданно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе прокрался гость незваный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо в раскрытые окошки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗалетают эльфы-крошки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ рассеять наважденье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ бессилен, к сожаленью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли невозможно было\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ горбуне узнать Зоила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто тогда сказать про группу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ колонного уступа?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ бы должен был по чину\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбъяснить вам смысл картины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, обняв изображенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСам нуждаюсь в объясненье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто взаправду там такое?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНикого не беспокоя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз передней в залу мчится\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧетвернею колесница.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЮноша, не глядя, правит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКони никого не давят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ туманною картиной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в волшебном фонаре,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвезды движутся в гостиной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУтонувшей в серебре.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКолесница предо мной!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасступитесь! Страшно!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик-возница\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкакуны, убавьте прыти!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой полет остановите.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВерные своей породе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧувствуйте мои поводья!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто место всех священней:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтите это помещенье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКруг поклонников теснится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбступивши колесницу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВеря, что герольд опишет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо, что видит он и слышит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай, герольд, в своем разборе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбъясненье аллегорий.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто выше разуменья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпишу лишь впечатленье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик-возница\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак начни.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез дальних слов:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолод ты, красив, здоров.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗелен ты, пострел, лукавец,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо созрел на взгляд красавиц,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА как вырастешь, вконец\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудешь горем их сердец.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик-возница\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДальше облик мой черти,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы на правильном пути.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо молниям в глазах и по сверканью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКамней в кудрях, сравнимых с тьмой ночной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо ниспадающей небрежно ткани,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнизу обшитой красною каймой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы сам еще ужимкою веселой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа девушку невинную похож,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо скоро к девушкам поступишь в школу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ жизни азбуку у них пройдешь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик-возница\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой, по-твоему, седок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак важно смотрит с этих дрог?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн кажется царем щедрот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ потому восторг законен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсех тех, к кому он благосклонен:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн им, что может, раздает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА сам становится богаче,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем больше жертвует в раздаче.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик-возница\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакого описанья мало.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодробней! Это лишь начало.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостойного не описать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо круглоликость, полнокровье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо губы, полные здоровья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо показавшаяся прядь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз-под роскошного тюрбана,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо одеянье, стройность стана!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА о величье что сказать?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ узнаю в нем властелина.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик-возница\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн — Плутус,\u0026#160;он — богатства бог\u003ca class=\"ref\" id=\"r135\" href=\"#n135\" data-tip=\"№135 \u0026#183; Плутос (Аристофан); Теогония (Гесиод)\"\u003e135\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ прибыл к вам не без причины\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ваш императорский чертог.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажи, ты сам тут для чего?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик-возница\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ — творчество, я — мотовство,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэт, который достигает\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысот, когда он расточает\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе собственное существо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ тоже сказочно богат.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем был бы Плутус без поэтов?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ для его балов, банкетов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНезаменимый, редкий клад.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе пристало хвастовство,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо покажи и мастерство.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик-возница\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде щелкать пальцами я буду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоявятся сокровищ груды.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Пощелкивая пальцами.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот жемчуг, шею им украсьте,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот гребешки, а вот запястья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот женский золотой венец,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вот вам несколько колец.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ огоньки куда попало\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазбрасываю я по залу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолпою кинулись к добыче.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосередине, в толкотне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБросает в сотню рук возничий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвои подарки, как во сне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо это — плутовские штуки:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть схватят драгоценность в руки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе внезапно нет как нет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыла браслетка, где браслет?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто думал, что на самом деле\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВладеет ниткой жемчугов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСжимает вместо ожерелья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорсть копошащихся жуков:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдни с жужжаньем вверх взлетают,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругие бабочек хватают.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто ждал несметного добра,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрезвеет от мечтаний сразу:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе речи мальчика — проказы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ золото все — мишура.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик-возница\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд, ты мастер объявлять,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакие темы и предметы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзобразил переодетый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо слаб в их сущность проникать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто спорить нам? Без ссор и крика\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ обращусь к тебе, владыка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Повернувшись к Плутусу.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажи, не мне ль ты поручил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧетверки этой резвый пыл?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБывало, только скажешь: \u0026#171;Двигай!\u0026#187; —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУже летит моя квадрига.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ пальму первенства в езде\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе я ли добывал везде?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе я ль бросался в сотни стычек?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе за тебя ль я войны вел\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, счастья твоего добытчик,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе венок лавровый сплел?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлутус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе это ясно без того.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакие могут быть сомненья?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы — дух от духа моего,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоих желаний исполненье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, знаешь, как я ни богат,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты богаче во сто крат,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мне венок, тобой сплетенный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДороже золотой короны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто спрашивать? Ответ один:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоржусь тобой, любимый сын.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик-возница  (к толпе)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад вами я своей рукой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазлил огонь священный мой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн в виде легких диадем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад этим вьется и над тем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ голову за головой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВенчает вспышкой огневой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо редко-редко где на миг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзовьется ярко вверх язык,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то, еще не разгорясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМигнет и гаснет в тот же час.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБабья болтовня\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе — ложь — четверка и рыдван,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозница — главный шарлатан.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА позади него другой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПетрушка с высохшей ногой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоща! Щипи его иль нет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не почувствует, скелет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТощий\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодальше, подлое бабье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы — наказание мое.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ звался Скупостью, пока\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖена стояла у горшка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХозяйство множилось в те дни:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе в дом, а из дому — ни-ни!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУжель не доблесть, а порок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто я копил, что я берег?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо с женщинами перемена:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКопить теперь несовременно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь у баб, как у банкротов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖеланий больше, чем расчетов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ муж, влезающий в долги,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа положении слуги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто сбережет жена, припрятав,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе для любовников и сватов.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабыта честь, потерян стыд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС утра до ночи дом открыт.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ скряга сам, и я за скряг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ за мужчин, я бабам враг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАтаманша\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе враки, враки, что ни скажет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС драконами водись, дракон!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМужей нам только взбудоражит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб в гроб вогнали бедных жен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖенщины в толпе\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоронье пугало! Клюка!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПаяц! Калека изможденный!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе бойтесь ничего. Драконы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз деревяшки и картона.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛупи их! Дай им тумака!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолчать! К порядку! Я сумею\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖезлом… но уж не нужен он:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВорочая драконьей шеей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолзут чудовищные змеи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзяв крыльями большой разгон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОгнем из пасти пышут звери,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе кинулись в смятенье к двери,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗал пуст, порядок водворен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлутус сходит с колесницы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБог Плутус мановеньем рук\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВелит драконам снять сундук\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ Тощего зовет спуститься\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвиженьем царственной десницы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе сделано. Нельзя понять,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак быстро сняли эту кладь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлутус  (вознице)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь избавлен ты от груза.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛети на волю, без обузы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКруг помыслов твоих не тут,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь давки масок и причуд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо там, где, в ясности, один\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы друг себе и господин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам, в одиночестве, свой край\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобра и красоты создай.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик-возница\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ том царстве, как посол твой полномочный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ буду выражать твой мир заочно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь мы сродни. Где ты — там полнота,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде я — там счастья высшая черта.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто людям предпочесть? Тебя, обилье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли меня, воображенья крылья?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТе, что с тобой, не ведают труда,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТе, что со мною, заняты всегда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне скрытничество ни к чему не служит:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДохну — меня дыханье обнаружит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрощай! Ты волю мне даешь. Я рад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо лишь шепни, и я примчусь назад.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Удаляется так же, как появился.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлутус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь пора с сокровищ снять запоры.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзмахнем жезлом и в руки их получим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСундук открылся. Медные амфоры\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолны до края золотом текучим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКороны, цепи, кольца и булавки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТекут и тают, раскалясь от плавки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБеспорядочные крики толпы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотрите, золота струя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеретечет через края!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСосуды плавятся, и вслед\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРулоны золотых монет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДукатов новеньких игра,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак из монетного двора.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПустите! Денег сколько! Страсть!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеужто дать им так пропасть?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот деньги, на полу лежат,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозьми, и будешь ты богат,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА лучше сзади подойдем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ завладеем сундуком.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот дурачье! Какой сундук?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь это — маскарадный трюк.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут в шутку все, а вы всерьез.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак вам и дали денег воз!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля вас не то что медный грош,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВид фишки чересчур хорош!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам разве видимость понять?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам все бы пальцами хватать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСреди примет, поверий, грез\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавно ль у вас на правду спрос?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдетый Плутусом, скорей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрюзгливых скопище рассей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлутус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпять твой жезл мне будет впрок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай мне его на малый срок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ кончик в пламя окунул.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКричите, маски, караул!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот наконечника металл\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУже накаливаться стал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ здесь стою средь вас в кругу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе подходите, обожгу!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрики и давка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивьем сгорим и пропадем!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасайся все! Бегом, бегом!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда, куда! Назад, назад!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж искры мне в лицо летят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРубашку посох мне прожег.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНазад! Отхлынь, людской поток!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если б крылья я имел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей подальше б улетел!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлутус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе в сторону оттеснены\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, вижу, не обожжены.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолпы наплыв\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстановив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ место, чтоб сдержать орду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНезримым кругом обведу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасибо. Мы б могли пропасть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы разум выказал и власть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлутус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХвалиться рано. Погоди.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВолнений много впереди.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкряга\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа всех отсюда брошу взгляд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивой стеною стали лица,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде что урвать, чем поживиться,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСуются дамы в первый ряд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь я еще не сдан в архив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в женщинах еще разборчив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, рожу надлежаще скорчив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБываю весел и игрив.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако как шумит народ!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСреди такого многолюдства\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБолтать друг с другом — безрассудство.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПущу телодвиженья в ход.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ если не помогут жесты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ слиткам золота, как тесту,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбую видимость придам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда понятную глазам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак этот испитой костяк\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще к тому же и остряк?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн, как для лепки матерьял,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеж пальцев золото размял,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКатает, комкает, крошит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридал комкам бесстыдный вид\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тычет всем наперебой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрик, суматоха, женский вой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред женщинами, не стыдясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн всячески разводит грязь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам надо выгнать из дворца\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезнравственного наглеца.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я не помирюсь со злом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока не пну его жезлом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлутус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпасности не видит он.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда безвыходность заставит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн глупости свои оставит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНужда сильнее, чем закон.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСумятица и пенье\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ долине с гор бежит рекой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез удержу поток людской.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВеликий Пан их божество.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВатага чествует его.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто Паном на балу одет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзвестен только им секрет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлутус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне ведомо, кто вы и он.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в эту тайну посвящен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ все узнал из первых рук\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вас пущу охотно в круг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУдачи смелому почину!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто чуду вверился — тот прав,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть кинулся бы, как в пучину,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозможностей не рассчитав.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДикое пенье\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбманчив неженок убор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА мы толпой скатились с гор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗакалены и горячи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыносливые силачи.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФавны\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭй, фавны, в пляс,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВесельчаки!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ кудрях у вас\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛиства, венки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, прячась в них, торчит легко\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть заостренное ушко.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкуластый и курносый вид\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУспехам фавна не вредит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротянет лапу он и, глядь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдет с красивейшей плясать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСатир\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА сзади делает прыжок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСатир со всех козлиных ног.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн, словно серна, сухопар,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроворен, жилист и поджар.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн дышит воздухом высот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлядит, как человек живет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ презирает быт долин,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДетей, и женщин, и мужчин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни во тьму погружены,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА он посмотрит с крутизны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ видит — мир пред ним открыт\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ весь ему принадлежит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГномы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы, карлики, бежим, толпясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе парами, а все зараз.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабот у гномов — вороха.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа нас кафтанчики из мха,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри каждом — лампа горняка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВеличиной со светляка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь кутерьмы и толчеи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХлопочем мы, как муравьи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто к домовым нас причислял,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА кто зовет: \u0026#171;хирурги скал\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗатем, что мы в любви к труду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорам пускаем кровь — руду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, правда, сколько горных жил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа век свой каждый отворил!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриветом добрым: \u0026#171;В добрый час!\u0026#187;\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод землю провожают нас,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в этом правда есть своя:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХорошим людям мы — друзья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо нашим золотом из гор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоспользуется сводник, вор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖелезо наше попадет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ распоряженье воевод,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе мы виной, само собой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто гонят войско на убой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе чуткий к заповедям трем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУже бессовестен во всем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут наша общая беда,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вы терпите, господа.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВеликаны\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ долинах Гарца поделом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы дикими людьми слывем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа силу, наготу и рост,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа то, что каждый, нравом прост,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ручищу взял сосновый ствол\u003ca class=\"ref\" id=\"r136\" href=\"#n136\" data-tip=\"№136 \u0026#183; Герб Брауншвейг-Люнебурга; Вильдеманнсталеры и др.\"\u003e136\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ бедра листьями оплел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТелохранители, каких\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет и у римских пап самих.\u003ca class=\"ref\" id=\"r137\" href=\"#n137\" data-tip=\"№137 \u0026#183; История Швейцарской гвардии\"\u003e137\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНимфы  (хором, окружив великого Пана)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот бог полян,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛесных берлог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВселенной бог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВеликий Пан.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы окружим его кольцом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазвеселим и развлечем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн — добрый бог, хотя и строг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ любит смех и топот ног.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн смотрит ночи напролет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа голубой небесный свод,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА днем, когда наперерыв\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖурчат ручьи и он сонлив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе в робости замрет кругом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва забудется он сном.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБоится дунуть ветерок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не шелохнется листок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ лесной тиши — полдневный зной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТравою пахнет и сосной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтупают нимфы, как в чаду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ засыпают на ходу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо каждый ужасом объят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть голоса его раскат\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ лесу прокатится как гром.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе — наутек, и все вверх дном!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПанический безумный страх\u003ca class=\"ref\" id=\"r138\" href=\"#n138\" data-tip=\"№138 \u0026#183; Идиллии (Феокрит); Стратегемы (Полиэн) и др.\"\u003e138\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаходит на людей в боях,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХрабрейших повергая в прах.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПочет тому, кто наш оплот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ столько страху задает.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДепутация гномов  (великому Пану)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК жилкам золота в граните,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК залежам железных руд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВместо путеводной нити\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГному дан волшебный прут.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГном ушел под землю, в гроты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ вечный мрак, под корни пня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы ты свои щедроты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаздавал при блеске дня.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы поблизости открыли\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНовый чудный ключ средь скал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзливающий в обилье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо, о чем ты не мечтал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрояви о нем заботу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОвладей им и присвой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК пользе мира все, чего ты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи коснулся бы рукой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлутус  (к герольду)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавай-ка запасемся хладнокровьем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСобытий мы с тобой не остановим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакой неотвратимый час пришел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроизойдет ужаснейшая драма.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе будут отрицать ее упрямо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты ее запишешь в протокол.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд  (дотронувшись до жезла, который Плутус не выпускает из рук)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот с гномами подходит Пан\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзглянуть на огненный фонтан.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧерез расселины края\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзлетает пламени струя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, спрятавшись назад в подкоп,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыбрасывает новый сноп.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА Пан, нагнувшись над огнем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБеспечно смотрит в водоем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖемчужно пенится каскад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ брызги в сторону летят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрижав к краям колодца грудь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПан хочет глубже заглянуть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг, отвязавшись, борода\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ Пана падает туда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто Пан?\u0026#160;— является вопрос,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаз подбородок без волос.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, поднеся ко рту ладонь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУкрывшись, смотрит Пан в огонь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНежданно новая беда:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбугленная борода,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще не догорев дотла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛетит обратно из жерла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ рассыпается, упав\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа плечи Пана и рукав.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорит венок, горит костюм,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОжоги, стоны, крики, шум!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСбегаются, чтоб затоптать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоспламененной пакли прядь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо все сильней и все дружней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗмеятся языки огней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ маски слепо, наугад\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРвут платье, мечутся, горят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУжель не ложь, не клевета\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо, что течет из уст в уста?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУжели и такую весть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам ночь должна была принесть?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, это правда. Страшный слух\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсех завтра облетит вокруг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто думать и поверить мог?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ императора ожог!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн сильно мучится от ран.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак, значит, вот кто этот Пан!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроклятье тем, кто кучей всей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ одеждах из сухих ветвей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроизвели здесь толкотню\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ подвели его к огню.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, резвой юности года,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде мера шуткам и проказам?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМогущество, когда, когда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоединишь ты с властью разум?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе в пламени, цветник и сад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лес вдали огнем объят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дом, от лестничных перил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДо стен и кровельных стропил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКонец, отрезаны пути,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ никому нас не спасти.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбразчик роскоши былой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК заре рассыплется золой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлутус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас достаточно пугали.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть покой наступит в зале.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосохом ударю в пол,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы гул кругом пошел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоздух, принеси нам в дар\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВольных нив холодный пар.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлушайтесь меня, туманы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтзовитесь с океана\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа моей тревоги зов!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа столбы и перекрытья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеленою расстелите\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстужающий покров.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТучи от речного яра,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛивнями излейтесь ниц.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто зарево пожара\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПревратите в блеск зарниц.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоджигателям бесстыжим\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы ответим чернокнижьем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r121\" href=\"#n121\" data-tip=\"№121 \u0026#183; Документы о системе Джона Ло; Век Людовика XV (Вольтер) и др.\"\u003e121\u003c/a\u003eСад для гулянья\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВосход солнца. Император, окруженный двором. Перед ним на коленях Фауст и Мефистофель, одетые прилично, без крикливости.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрости пожар наш мнимый, государь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор  (знаком приказывая им встать)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроказничай почаще так, штукарь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ очутился в круге подожженном\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вдруг почувствовал себя Плутоном.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНочь, скалы, по зубцам известняков\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеребегали змейки огоньков,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ языками вверх со дна провала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС чередованьем пламя вылетало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоединяясь у своих высот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ подобный куполу горящий свод.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ видел толпы подданных, рядами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротискивавшихся ко мне сквозь пламя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ проходах меж горящих колоннад\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл так неузнаваем маскарад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто царством саламандр мне двор казался,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я себе царем их представлялся.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, ты их царь. Ты правильно сказал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы — царь всех элементов и начал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы испытал огня повиновенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде на море всего сильней волненье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНырни на дно,\u003ca class=\"ref\" id=\"r139\" href=\"#n139\" data-tip=\"№139 \u0026#183; Учение о цвете (Гёте)\"\u003e139\u003c/a\u003e\u0026#160;— стеной отвесных вод\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСойдется вкруг тебя водоворот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСквозь столб воды кайма волны лазурной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо дна тебе покажется пурпурной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде ты ни стой, куда ни отходи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе будешь в центре, все посереди.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВезде дворцы. Где ни поставишь ноги,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВслед за тобой потянутся чертоги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПройдешь сквозь стен живую череду —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все найдешь в движенье, все в ходу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМорские дива, словно за стеклом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбступят круг, очерченный жезлом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереползет дракон, хребет сутуля;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо смехом ты посмотришь в пасть акуле.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам будет как на танцах толчея,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо сдержит всех заветная струя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа исключеньем самых милых с виду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ твой тайный круг заглянут нереиды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзметет Фетида раковинок пласт\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ новому Пелею руку даст,\u003ca class=\"ref\" id=\"r140\" href=\"#n140\" data-tip=\"№140 \u0026#183; Илиада (Гомер); Свадьба Пелея и Фетиды (Катулл) и др.\"\u003e140\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на Олимпа высь за облаками…\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтихией воздуха владейте сами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДетей влекут воздушные края.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, государь, земля — давно твоя.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоею тысячей одною ночью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожалуйста, всегда нас так же потчуй.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудь, как Шехеразада, плодовит\u003ca class=\"ref\" id=\"r141\" href=\"#n141\" data-tip=\"№141 \u0026#183; Тысяча и одна ночь\"\u003e141\u003c/a\u003e —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ никогда не будешь мной забыт.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлучайся под рукою постоянно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда я к вечеру от дел устану.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотритель дворца  (торопливо войдя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе чаял я дожить до этой чести:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя порадовать такою вестью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой повелитель, это сон, мечта:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОплачены, подумай, все счета!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я освобожден от верховодства\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРостовщиков и не боюсь банкротства!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ на верху блаженства! Кончен ад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ словно на седьмое небо взят!\u003ca class=\"ref\" id=\"r142\" href=\"#n142\" data-tip=\"№142 \u0026#183; Второе послание к Коринфянам; Вавилонский Талмуд\"\u003e142\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНачальник военных сил  (так же поспешно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛандскнехтам дан задаток в счет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоходов будущих вперед.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезмерен радости масштаб\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСолдат, трактирщиков и баб.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак дышат все легко! Какие лица!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИсчезли складки. Каждый суетится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпеша вбежать другим наперерез.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКазначей  (неожиданно появившись)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпроси вот их, вершителей чудес.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолг канцлера отчет о том представить.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКанцлер  (медленно приближаясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ рад. Ты можешь старика поздравить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот лист, где бедствий тяжкая пора\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНавек избыта росчерком пера.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Читает.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбъявлено: означенный купон\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦеною в тысячу имперских крон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБумаге служат в качестве заклада\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ нас в земле таящиеся клады.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва их только извлекут на свет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОплачен будет золотом билет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут жульничество кроется, подлог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто нашу подпись здесь подделать мог?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаказан ли мошенник злополучный?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКазначей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы подписал билет собственноручно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда, одетый Паном на балу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстановился с канцлером в углу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы с ним для нужд общественного блага\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя просили подписать бумагу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ эту подпись короля вчера\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазмножили несчетно мастера.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб сделать дело доброе мгновенным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы отпечатали по разным ценам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБилеты казначейские в дукат,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА также в десять, тридцать, пятьдесят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВосторг на улицах неописуем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вместе с населеньем мы ликуем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри имени твоем уже и так\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдушевлялся радостью бедняк,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь, под казначейскою печатью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо имя стало знаком благодати.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вместо золота подобный сор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ уплату примут армия и двор?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ поражаюсь, но не протестую.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотритель дворца\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБеглянки разлетелись врассыпную.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБумажек не вернуть уж. Первый вал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВкатился с улиц в лавочки менял.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам разменяли каждую кредитку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа золото с положенною скидкой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ деньги потекли из кошелька\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК виноторговцу, в лавку мясника.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолмира запило, и у портного\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругая половина шьет обновы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ трактирах — людно, стук тарелок, чад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе: \u0026#171;Пьем за императора!\u0026#187; — кричат.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто выйдет на прогулку в парк из вас,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасавицу заметит у террас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПавлиньим веером прикрывши щеку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна на вас в полглаза взглянет сбоку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ждет от вас не блесток, не острот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе красных слов, а несколько банкнот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы носите их в боковом кармане,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ сердца, как любовное посланье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда солдату отягчал кушак\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗапас в него зашитых звонких денег.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНасколько легче вес таких бумаг!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ молитвенник засунет их священник.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрости, что я в картину широты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВношу такие мелкие черты.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоя земля таит без пользы тьму\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСокровищ, не известных никому.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМысль самого высокого полета\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе может охватить богатств без счета.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВосторженный мечтатель и фантаст\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПонятья никогда о них не даст,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо дальновидный риска не боится\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в безграничность верит без границы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС билетами всегда вы налегке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни удобней денег в кошельке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни вас избавляют от поклажи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри купле ценностей и их продаже.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПонадобится золото, металл\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмеется в запасе у менял,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА нет у них, мы землю ковыряем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ весь бумажный выпуск покрываем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаходку на торгах распродаем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ погашаем полностью заем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпять мы посрамляем маловера,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе хором одобряют нашу меру,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с золотым чеканом наравне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБумага укрепляется в стране.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагополучьем край обязан вам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо мере сил я равным вам воздам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДаю вам на храненье наши недра,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаведуйте статьею этой щедрой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазметьте на поверхности земли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде надо рыть, где клады залегли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдвоем казной заведуя, без шума\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКопите государственные суммы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы у нас в гармонии одной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлились подземный мир и мир земной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКазначей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне очень нравится, что казначею\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы в помощь назначаешь чародея.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит с Фаустом.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ дам подарки всем, кто сообщит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа что он этот дар употребит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПаж  (принимая подарок)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ зачащу к знакомым на пирушки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругой паж  (так же)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦепочку и кольцо куплю подружке.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКамергер  (так же)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗапью еще сильнее, но с разбором.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругой камергер  (так же)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСыграю в кости с новеньким партнером.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТитулованный землевладелец  (рассудительно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ замок выкуплю из ипотек.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругой титулованный  (так же)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ средства округлю на весь свой век.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ думал вызвать вас на подвиг новый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, хоть осыпь вас золотым дождем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы остаетесь прежними во всем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС неисправимой старою основой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШут  (появляясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут благ раздача? Дайте мне хоть грош.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы снова ожил? Ты его пропьешь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШут\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ листках волшебных ничего не смыслю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвы, я дураку их и отчислю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШут\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот падают еще. Все это мне?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛови. Будь рад свалившейся казне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШут\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПять тысяч крон, вот дело ведь какое!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоскрес, мнимоумерший от запоя?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШут\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ воскресений всех не перечту.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ это ты от радости в поту?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШут\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажите, это деньги не на шутку?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, что для глотки надо и желудка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШут\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа них куплю я поле, дом и скот?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКонечно, лишь пусти их в оборот.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШут\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ рыбный пруд и луг с лесною чащей?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще бы! Как помещик настоящий.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШут\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереберусь сегодня ж на покой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (один)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть и дурак, а вместе ум какой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r144\" href=\"#n144\" data-tip=\"№144 \u0026#183; История о докторе Иоганне Фаусте (Шпис)\"\u003e144\u003c/a\u003e\u003ca class=\"ref blk\" id=\"r143\" href=\"#n143\" data-tip=\"№143 \u0026#183; Сравнительные жизнеописания (Плутарх); Разговоры с Гёте (Эккерман) и др.\"\u003e143\u003c/a\u003eТемная галерея\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст и Мефистофель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем мы в этих галереях?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНемало поводов вокруг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСреди гуляющих в аллеях\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля всяких выходок и штук.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаро, старо! Как ты неловок!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда найдешь ты что-нибудь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб с помощью таких уловок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт разговора увильнуть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПойми, я должен непременно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗакончить с блеском карнавал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я Париса и Елену\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа днях им вызвать обещал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМужчины олицетворенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лучшей женщины пример.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаш император в нетерпенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак я узнал из высших сфер.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе ждут. Об этом ежечасно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапоминает государь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИсполнить надо, дело ясно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодумай, поищи, пошарь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы обещанье дал напрасно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь дел своих ты упустил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем эти плутни завершатся.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаз ты людей обогатил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни желают развлекаться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНельзя так сразу, невзначай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС бухты-барахты. Это крупный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВопрос. Тут мы пред неприступной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТропой в предельно чуждый край.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлену вызвать — это шаг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпасный и немаловажный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе то что призрак благ бумажный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСозвать колдуний, ведьм — пустяк,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут я всегда к твоим услугам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо героини, как-никак,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь не чета моим подругам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпять завел свою шарманку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтец сомнений и помех.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе, чтоб веровать в успех,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе нужно новую приманку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДва-три заклятья прогнусавь —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вызовешь Елену въявь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯзычники живут в своем аду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ там чужой и дел их не веду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо средство есть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажи скорей, какое.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ эту тайну нехотя открою.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогини высятся в обособленье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт мира, и пространства, и времен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредмет глубок, я трудностью стеснен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо — Матери.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (испуганно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто? Матери?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ смятенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы сказанным как будто приведен?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа. Матери… Звучит необычайно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда такими и бывают тайны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа и нельзя иначе. Сам прикинь:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы называем нехотя богинь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вам непостижимы их глубины.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни нужны нам, ты тому причиной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде путь туда?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНигде. Их мир — незнаем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНехожен, девственен, недосягаем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖеланьям недоступен. Ты готов?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе жди нигде затворов и замков.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлоняясь без пути пустынным краем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы затеряешься в дали пустой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостаточно ль знаком ты с пустотой?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот новости! Такой вопрос излишен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ нем отголосок \u0026#171;кухни ведьмы\u0026#187; слышен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРешил тряхнуть ты этой стариной?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ по свету таскался, до истомы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУчил тщете, учился по-пустому,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух пустоты, надеюсь, схвачен мной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне также одиночество знакомо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда я стал судить трезвей, число\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюдей далеких вдвое возросло.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ отчаянье от их вражды, в унынье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ удалиться должен был в пустыню,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде, чтобы одному не одичать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ душу черту должен был продать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе это вздор. Есть даже в океане\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа что смотреть, не все пустая гладь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам видно, как не устает играть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоею жизнью волн чередованье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак плещутся дельфины, как в пучину\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлядится месяц, звезды, облака.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо в той дали, пустующей века,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы ничего не сыщешь, ни единой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпоры, чтоб на ней покоить взор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдин сквозной беспочвенный простор.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак врали новичкам жрецы мистерий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ святилище им преграждая вход,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо предо мною ты, наоборот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУслужливо распахиваешь двери\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ посылаешь в капище пустот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб с помощью изученных заклятий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРуками загребал тебе я жар.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я в твоем \u0026#171;ничто\u0026#187; надеюсь, кстати,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостать и всё посредством тех же чар.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХвалю тебя, пока нам не пришлось\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасстаться: черта знаешь ты насквозь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот ключ, ты видишь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖалкая вещица.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозьми. Не брезгуй малым. Пригодится.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн у меня растет в руках, горит!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе так он прост, как кажется на вид.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВолшебный ключ твой верный направитель\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри нисхожденье к Матерям в обитель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (содрогаясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри спуске к Матерям! Чем это слово\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрашнее мне удара громового?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот косность! Ты боишься новых слов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ хочешь слышать только повторенья?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПора бы не бояться пустяков\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ принимать любые превращенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпокойно, без боязни катастроф,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ни звучало б их обозначенье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не ищу покоя столбняка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпособность потрясаться — высока,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ непривычность чувства драгоценна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем, что роднит с безмерностью вселенной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда спустись! Или: \u0026#171;Направься ввысь\u0026#187;, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б мог сказать. Из мира форм рожденных\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ мир их прообразов перенесись.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ следы существований прекращенных,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавным-давно прервавшихся всмотрись.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, чтобы их держать на расстоянье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазмахивай своим ключом в тумане.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (воодушевленно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне ключ как бы вливает бодрость в тело.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрудь ширится, я рвусь смелее к делу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда увидишь жертвенник в огне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнай, кончен спуск, и ты на самом дне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред жертвенником Матери стоят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасхаживают, сходятся, сидят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак вечный смысл стремится в вечной смене\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт воплощенья к перевоплощенью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни лишь видят сущностей чертеж\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не заметят, как ты подойдешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда кидайся смело на огонь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с властностью ключом треножник тронь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзмахнув ключом, Фауст делает повелительное движение рукою.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (наблюдая его)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак. Хорошо. Потом свершай подъем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТреножник двинется вслед за ключом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока заметят Матери грабеж,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа крыльях счастья в зал ты попадешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы вызовешь средь общей кутерьмы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГероя с героинею из тьмы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВласть эта выпадает тем в удел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто похищенье совершить посмел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДым жертвенный посредством колдовства\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы превратим в два этих божества.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас что делать?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТопни раз ногой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри спуске, пред поднятием — в другой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст топает ногой и исчезает.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНасчет ключа все гладко ли сойдет?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВернется ль он? Не вышло бы хлопот.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eЯрко освещенные залы\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор и князья. Двор в оживленье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКамергер  (Мефистофелю)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы обещали с духами картину.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей! Не раздражайте властелина.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотритель дворца\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас он свиту спрашивал и двор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак мешкать — непочтение, позор.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТоварищ мой затем и заперся\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тиши уединенной кабинета.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотребуется сила знанья вся,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб чудо красоты представить свету.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторгающийся в эти тайники\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнать магию обязан мастерски.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотритель дворца\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне дела нет до этих областей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо государь велит начать скорей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлондинка  (Мефистофелю)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗимой я, сударь, недурна собой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо лето делает меня рябой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоричневые пятна эти — с детства.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе знаете ли от веснушек средства?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуша моя! При белизне такой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолгода быть пятнистой, как пантера,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИспортить может женщине карьеру.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы жабью слизь с лягушачьей икрой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПорядком вскипятите в полнолунье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ смажьте кожу майскою порой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВеснушки пропадут у вас в июне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрюнетка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе к вам попасть стремятся до сеанса.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ ногу отморозила. Ступня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтесняет в танцах и ходьбе меня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мне мешает делать реверансы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ наступлю ногой вам на подъем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрюнетка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИгривость не в характере моем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут не роман, и вам гнушаться нечем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо мы подобное подобным лечим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтопу — стопой,\u0026#160;спинным хребтом — хребет.\u003ca class=\"ref\" id=\"r145\" href=\"#n145\" data-tip=\"№145 \u0026#183; Органон врачебного искусства (Ганеман)\"\u003e145\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе надо ножкой двигать мне в ответ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрюнетка  (вскрикивая)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАй-ай! У вас нога грузней копыта!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗато и вред долой и боль забыта.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь пляшите вволю и с дружком\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбезничайте ножкой под столом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама  (проталкиваясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПустите! Я истерзана печалью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн был со мной вчера еще, не дале,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот — с другой, что он творит со мной!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн повернуться смел ко мне спиной!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСерьезный случай. Этим угольком\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИспачкайте рукав его камзола,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб не заметил, как-нибудь тайком.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго измучат совести уколы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вы, не запивая ни глотком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВесь этот уголь съешьте всухомятку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в ту же ночь он к вам придет украдкой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо тут не яд?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (возмущенно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбижусь напоследок!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоймите вы, как этот уголь редок!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн вынут из костра еретика\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мне доставлен был издалека.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПаж\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВлюбился я, а говорят — я мал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (в сторону)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖелающих совета полный зал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Пажу.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставьте молодых и их причуды.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля пожилых вы — лакомое блюдо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК Мефистофелю протискиваются другие.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе новые! Как разредить затор?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНачать им правду говорить в упор?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО Матери! Задавят! Помогите\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ Фауста скорее нам верните!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Осматриваясь кругом.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТускнеют свечи. Государь и двор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроследовали через коридор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаполнив пестрым множеством народа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУглы и сводчатые переходы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ собранье рыцарей вошли потом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНабив большую комнату битком.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОружье в нишах блещет, и на стены\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНавешаны ковры и гобелены.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь, обходясь без вызова волхвов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыходят духи сами из углов.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eРыцарский зал\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосле входа императора и двора. Слабое освещение.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ снова выступаю толмачом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо что разыгрывается на сцене,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе объясню сегодня нипочем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНастолько духи спутали явленья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот зрители расположились в зале,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ император впереди рядов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсматривает занавесей штоф\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС картинами прославленных баталий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе в сборе: государь, и двор, и знать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ скамьи сдвинуты на заднем плане,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде парочки, пугаясь заклинаний,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВпотьмах друг другу руки будут жать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмолкает разговор мужчин и дам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе духов ждут, рассевшись по местам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрубы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАстролог\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаш государь, молчавший до поры,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВелит скорее обратиться к драме.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтена, раздвинься! Врозь ползут ковры,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто бы их скатывает пламя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОборотясь изнанкою, драпри\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзображают сцены углубленье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМерцает свет таинственный внутри,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я уже стою на авансцене.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (высовываясь из суфлерской будки)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМое призванье — шепот, подговор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧерт — прирожденный, записной суфлер.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Астрологу.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, знающий планет пути и сроки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУловишь на лету мои намеки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАстролог\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМагическою силой древний храм\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа сцене в глубине показан нам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ как Атлант, подперший небо шеей,\u003ca class=\"ref\" id=\"r146\" href=\"#n146\" data-tip=\"№146 \u0026#183; Теогония (Гесиод); Одиссея (Гомер)\"\u003e146\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛегко несут постройку пропилеи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКолонн под ней неисчислимый лес,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя и двух хватило бы в обрез.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАрхитектор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот в чем античность? Мне она тогда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоей тяжеловесностью чужда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ противность этой грубости, невольно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа ум приходит свод остроугольный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри виде сети стрельчатых окон\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДушой я как бы к небу вознесен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАстролог\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа будет превознесена звезда,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторою нам этот час дарован.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа будет заклинаньем разум скован\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не теснит фантазии узда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтарайтесь увидать, что вам приятно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто невозможно, то и вероятно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст поднимается на сцену с другой стороны.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вот искатель счастия упрямый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ венке и одеянии жреца.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн доведет, что начал, до конца.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемля разверзлась, жертвенник из ямы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоднялся кверху в дыме фимиама,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПора священнодействие начать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо-видимому, можно счастья ждать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (величественно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы, Матери, царицы на престоле,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивущие в своей глухой юдоли\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсобняком, но не наедине.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад вашей головою в вышине\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПорхают жизни реющие тени,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда без жизни, и всегда в движенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, что прошло, стекается сюда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе бывшее желает быть всегда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы эти семена задатков голых\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазбрасываете по сторонам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо все концы пространств, всем временам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод своды дня, под ночи темный полог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдни вбирает жизнь в свою струю,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругие маг выводит к бытию\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, верой заражая, заставляет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвидеть каждого, что тот желает.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАстролог\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКлючом треножник тронул он, и гарь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКлубами мглы окутала алтарь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо это только видимая мгла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа деле это — духи без числа.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ них способность есть за пядью пядь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ земле шагами музыку рождать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх поступь — песнь, симфония, псалом, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе описать ни словом, ни пером.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСледы их приближенья ощутив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоют колонны, стены, свод, триглиф.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг юноша неписаной красы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыходит из туманной полосы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнимательней смотрите на кулисы:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы видите прекрасного Париса.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоявляется Парис.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ каком расцвете юношеских сил!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторая\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак персик свеж и несказанно мил!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТретья\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасивый рот с надутой верхней губкой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧетвертая\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы пить не прочь бы из такого кубка?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПятая\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХорош, хорош, хотя немного хмур.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШестая\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа и неповоротлив чересчур.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРыцарь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе царский сын, а пастушок топорный,\u003ca class=\"ref\" id=\"r147\" href=\"#n147\" data-tip=\"№147 \u0026#183; Мифологическая библиотека (Аполлодор); Героиды (Овидий)\"\u003e147\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез признаков учтивости придворной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругой рыцарь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолунагой, пожалуй, он — по мне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вот каков-то будет он в броне?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн сел. Какие гибкие движенья!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРыцарь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас так к нему и тянет на колени?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругая дама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРукой прелестно голову подпер.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКамергер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазлечься так при всех! Какой позор!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМужчина рад к чему-нибудь придраться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКамергер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред государем на полу валяться!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн вправе полагать, что он один.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКамергер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля грубостей не вижу я причин.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн хочет спать и засыпает сладко.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКамергер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ даже всхрапывает для порядка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолодая дама  (восхищенно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо что за примесь в ладан введена?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ веяньем ее освежена.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама постарше\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ у меня забилось сердце чаще.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ думаю, так дышит мальчик спящий.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожилая дама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред нами — распустившийся цветок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДушистый, как амброзии глоток.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоявляется Елена.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак вот она какая! Я бесстрастно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбуюсь ей. Она мне не опасна.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАстролог\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВладей я словом огненных поэм,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б все равно пред ней остался нем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна вошла, и мелко все на свете,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ей во славу создали столетья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто взглянет на нее — спален дотла.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлажен счастливец, чьей она была.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не ослеп еще? И дышит грудь?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой в меня поток сиянья хлынул!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНедаром я прошел ужасный путь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакую жизнь пустую я покинул!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тех пор как я тебе алтарь воздвиг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мир мне дорог, как впервые полон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВлекущ, доподлинен, неизглаголан!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть перестану я дышать в тот миг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак я тебя забуду и погрязну\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ обыденности прежней безобразной!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак бледен был когда-то твой двойник,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯвившийся мне в зеркале колдуньи!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн был мне подготовкой накануне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПреддверьем встречи, прелести родник!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДарю тебе все напряженье воли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, чем владею я и чем горю,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ чту твой образ и боготворю,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсю жизнь, и страсть, и бред, и меру боли.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (из суфлерской будки)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВладей собой, не выходи из роли.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожилая дама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтройна, крупна. А голова — мала.\u003ca class=\"ref\" id=\"r148\" href=\"#n148\" data-tip=\"№148 \u0026#183; Естественная история (Плиний)\"\u003e148\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолодая дама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНога несоразмерно тяжела.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДипломат\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКнягинь я знал. Наружность — мой конек.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна прекрасна с головы до ног.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридворный\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК заснувшему подходит шаловливо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ сравненье с ним она так некрасива!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэт\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн ею, как лучами, озарен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна — луна, а он — Эндимион.\u003ca class=\"ref\" id=\"r149\" href=\"#n149\" data-tip=\"№149 \u0026#183; Мифологическая библиотека (Аполлодор); Разговоры богов (Лукиан) и др.\"\u003e149\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэт\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДействительно, богиня, как в романе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК нему нагнулась, пьет его дыханье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦелует!\u0026#160;— С завистью смотрю туда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуэнья\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри всех? Особа эта без стыда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК мальчишке благосклонность!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТише, брат!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть делают виденья, что хотят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридворный\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроснулся он, и прочь она идет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС оглядкой! Я ведь знала наперед.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридворный\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн видит чудо и смущен немало.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй это не в диковинку: видала.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридворный\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот повернулась и идет к нему.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь научит, бедного, уму.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверно, первым, как и все мужчины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебя считает дурачок невинный.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРыцарь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак царственно строга и как стройна!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакая вольность! Как искушена!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПаж\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, быть бы этим юношею там!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридворный\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто б не хотел попасть в ее тенета?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСокровище ходило по рукам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС нее порядком стерлась позолота.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругая дама\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГуляла, видимо, лет с десяти.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРыцарь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть так, но я готов с большой охотой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрекрасные останки унести.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУченый\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСудить нельзя, увидев рост, осанку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена это или самозванка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНедостоверна видимость натуры\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ сравненье с данными литературы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо в древней Трое, говорит рассказ,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна старейшим по душе пришлась.\u003ca class=\"ref\" id=\"r150\" href=\"#n150\" data-tip=\"№150 \u0026#183; Илиада (Гомер)\"\u003e150\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтак, есть доводы со всех сторон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто это — настоящая Елена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК тому же совпаденье несомненно:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе молод я и тоже восхищен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАстролог\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе мальчик больше он. Шагнул вперед.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна напрасно рвется из объятий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриподнял на руки и, слов не тратя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУнесть намерен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДерзкий сумасброд!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстановись! Ни с места, одержимый!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы сам ведь ставишь эту пантомиму!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАстролог\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ понял наконец. Названье сцены,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак видно, \u0026#171;Похищение Елены\u0026#187;.\u003ca class=\"ref\" id=\"r151\" href=\"#n151\" data-tip=\"№151 \u0026#183; Похищение Елены (Колуф)\"\u003e151\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак \u0026#171;похищенье\u0026#187;? Разве я не в счет?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ разве не сжимаю ключ чудесный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС которым совершил я переход\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧрез ужасы пустыни неизвестной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ненадежность области другой?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь мир действительности без притворства.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь сам я стану твердою ногой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с духами вступлю в единоборство.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь собственный мой дух сплотит тесней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвоякий мир видений и вещей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасти ее! Не дать ей скрыться с глаз!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСчастливый случай вновь не повторится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе не вызвать в следующий раз.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО Матери, зову на помощь вас!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУзнав ее, нельзя с ней разлучиться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАстролог\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтой, Фауст, стой! Не помнит ни о чем!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСхватил ее, и расплылась фигура.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн юноши касается ключом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО Фауст! Ты нас всех погубишь сдуру!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзрыв. Фауст падает наземь. Духи обращаются в пар.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (взваливая Фауста на плечи)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу вот тебе! Какие недотроги!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, черту с дураком не по дороге.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТемнота. Переполох.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2 class=\"part\"\u003eАкт второй\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТесная готическая комната с высокими сводами,\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eкогда-то Фаустова, в том виде, в каком он ее оставил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз-за занавески выходит Мефистофель. Когда он ее отдергивает, оглядываясь назад, в глубине становится виден Фауст, лежащий без движения на старой прадедовской кровати.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛежи, несчастный, в забытьи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКого ошеломит Елена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтдаст ей помыслы свои\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ уж не вырвется из плена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХожу по комнате и в ней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВстречаю прежнюю картину.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаскраска окон лишь темней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа больше стало паутины.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе тут — до высохших чернил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБумаги и пера огрызка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторым Фауст закрепил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДиаволу свою расписку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ пере остался крови след\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак бы напоминаньем старым.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРеликвий редких кабинет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГордился б этим экземпляром.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ шуба на крюке цела, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в ней над новичком смеялся, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн, верно, до сего числа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ услышанном не разобрался.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСниму одежду на меху.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь только в одеянье этом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы можете с авторитетом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолоть любую чепуху.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо что ученому дано,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо черту не разрешено.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСнимает и встряхивает меховой плащ, из которого вылетают моль, кузнечики и прочие насекомые.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор насекомых\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС приездом, с приездом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаринный патрон:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоим появленьем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаш рой привлечен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы сеял нас редко\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧислом небольшим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тысячью тысяч\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь мы кишим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаинственно скрытен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛукавец и плут,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вши прямодушно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаружу ползут.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРад видеть этот молодой приплод.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы только сейте, урожай придет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще раз плащ встряхну. Поодиночке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзлетает моль из ветхой оболочки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖучки, букашки, живо по углам!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей запрячьтесь глубже в старый хлам!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ забытые глухие закоулки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа дно пустой рассохшейся шкатулки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМежду горшечных пыльных черепков,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ пергаменты, в глазницы черепов.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод этой гнилью и негодным ломом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕстественно водиться насекомым.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Надевает плащ.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНакину вновь я этот балахон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто важным званьем облечен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо мало называться принципалом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИметь студентов надо под началом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвонит в звонок, издающий гулкий пронзительный звук, от которого содрогаются стены и сами собой отворяются двери.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФамулус  \u0026#160;\u0026#160;(шатающейся походкой входит по длинному и темному коридору)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГул приводит в содроганье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛестницу и стены зданья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолньи блещут в окнах дома,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ трясется пол от грома.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод влияньем отголоска\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСверху сыплется известка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвери сами силой крена\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтворяются мгновенно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ Фауста былом наряде\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВеликан какой-то сзади\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодзывает, улыбаясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо от страха я шатаюсь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мне быть? Бежать? Остаться?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто грозит мне? Как дознаться?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (кивая ему)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойдите. Ваше имя — Никодим?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФамулус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДействительно. Молитву сотворим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, это мы оставим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФамулус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мне лестно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто имя вам мое небезызвестно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак, несмотря на возраст пожилой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще вы студиозус, милый мой?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИной к штудированью пристрастится\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ уж не знает этому границы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБольшое множество простых умов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивет постройкой карточных домов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя при жизни даже самый стойкий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоводит редко до конца постройку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо доктор Вагнер — разговор иной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУчитель ваш, прославленный страной, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдинственный ученый по призванью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый ежедневно множит знанья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивая любознательность к нему\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПритягивает слушателей тьму.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС вершины кафедры он объявляет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсему, что было раньше, пересмотр,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сам ключами, как апостол Петр,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемли и неба тайны отмыкает.\u003ca class=\"ref\" id=\"r152\" href=\"#n152\" data-tip=\"№152 \u0026#183; Евангелие от Матфея\"\u003e152\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе признают его ученый вес,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн затмевает остальных по праву.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ лучах его известности исчез\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоследний отблеск Фаустовой славы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФамулус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростите, сударь. Так судить нельзя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ ваше заблуждение рассею.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ни почетна доктора стезя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн выдается скромностью своею.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн свыкнуться не сможет никогда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС исчезновеньем славного предтечи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖдет возвращенья Фауста года\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ только жив мечтой об этой встрече.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы видите, в теченье многих лет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсталось все, как до его пропажи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоныне доктор Вагнер был на страже,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы всегда был заперт кабинет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо силой звезд свершен переворот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ слышал гром и видел молний вспышки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗамки слетели, лопнули задвижки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мы смогли попасть под этот свод.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде доктор сам? Нельзя ли мне к нему?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА может быть, я сам его приму.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФамулус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн затворился в строгости такой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто я боюсь смущать его покой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ теченье месяцев, вообразите,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрикован он к великому открытью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто в чистоте держал свой гардероб,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтал грязен и чумаз, как углекоп.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСам до бровей покрылся сажей черной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ воспалил глаза вздуваньем горна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак день и ночь, закрывшись на засов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн счастья ждет под музыку щипцов.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеужто он и от меня в затворе?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ ход его открытия ускорю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФамулус уходит. Мефистофель усаживается с важностью.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва успел до кресла доплестись,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнакомый гость откуда ни возьмись!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн — человек формации новейшей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, следовательно, нахал глупейший.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБакалавр  \u0026#160;(стремительно входя через коридор)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто я вижу? Сняты скрепы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС двери каменного склепа?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтало быть, конец гнездовью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПортившему столько крови\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолодому поколенью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДухом падали и тленья?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтены этой древней кладки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ разрушенье и упадке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛучше не соваться близко,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб не подвергаться риску.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМожно жертвой стать обвала, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтого недоставало.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУзнаю тебя, твердыня!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчиком я, рот разиня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлушал в этих же палатах\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдного из бородатых\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ за чистую монету\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПринимал его советы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе они мой ум невинный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабивали мертвечиной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖизнь мою и век свой тратя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа ненужные занятья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот один из них в приемной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкрылся в нише полутемной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБа! Никак он в том же платье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ этом меховом халате,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВидя, как еще я мал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн мне пыль в глаза пускал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак глубок его подлог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ тогда понять не мог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ нынешнее время — дудки!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе пройдут такие шутки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМилейший! Если Леты муть в разлитье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам памяти песком не затянула,\u003ca class=\"ref\" id=\"r153\" href=\"#n153\" data-tip=\"№153 \u0026#183; Энеида (Вергилий); Государство (Платон)\"\u003e153\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ ваш студент тех лет, успевший выйти\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз-под академической ферулы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в вас не замечаю перемены,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я переменился совершенно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРад, что пришли вы без заминки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ оценил вас в тот приход.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы бабочку уже в личинке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУгадываем наперед.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы радовались так по-детски\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоим кудрям и кружевам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо стрижка без косы, по-шведски,\u003ca class=\"ref\" id=\"r154\" href=\"#n154\" data-tip=\"№154 \u0026#183; История мужской моды 1790-х\"\u003e154\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдет гораздо больше вам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь философский абсолют\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе заносите в свой уют.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБакалавр\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПочтеннейший! Хоть мы на месте старом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗато у нас иные времена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвусмысленности не пройдут вам даром,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне сущность их теперь насквозь ясна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад мальчиком вы потешались вволю!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы б этих штук теперь не откололи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакой прием теперь недопустим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак неприятна правда молодым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда ее в лицо мы говорим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда-то нами вбитые начала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖизнь после подтверждает, что ни шаг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм кажется, что тут развитья знак:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Мы возмужали, мы народ бывалый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА наш учитель жалкий был дурак\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБакалавр\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей хитер, чем глуп. Где педагог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый бы сказать всю правду мог?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот лишнее приврет, а тот убавит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ детскую доверчивость обставит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак и всему, ученью есть свой срок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы перешли через его порог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ вас есть опыт, так что вам пора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо-моему, самим в профессора.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБакалавр\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе опыт, опыт! Опыт это вздор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗначенья духа опыт не покроет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе что узнать успели до сих пор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИскать не стоило и знать не стоит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ это с незапамятных времен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодозревал, и сам себе смешон.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБакалавр\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПризнать ошибку никогда не поздно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы — первый старец, мыслящий серьезно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеутомимо клада я искал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ находил лишь уголь да отвал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБакалавр\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь ваш лысый череп, на поверку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе лучше тех пустых под этажеркой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнай только вы, какой вы грубиян!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБакалавр\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь по-немецки вежлив лишь обман.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (постепенно подкативший свое передвижное кресло на авансцену, к публике)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредо мной тут затворяют двери.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрошу мне дать убежище в партере.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБакалавр\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБольшая дерзость — притязать на то,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб что-то значить, превратясь в ничто.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКлюч жизни — кровь, она родник здоровья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА что свежее юношеской крови?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКровь юноши — в цвету, она горит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ жизнь из жизни заново творит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКипит работа, дело создается,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ слабость перед силою сдается.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока полмира мы завоевали,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто делали вы? Планы сочиняли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроекты, кучи замыслов и смет!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, старость — это лихорадка, бред\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС припадками жестокого озноба.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть человеку стукнет тридцать лет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн, как мертвец, уже созрел для гроба.\u003ca class=\"ref\" id=\"r156\" href=\"#n156\" data-tip=\"№156 \u0026#183; О человеке (Гельвеций); Об уме (Гельвеций)\"\u003e156\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда и надо всех вас убивать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут черту больше нечего сказать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБакалавр\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ захочу, и черт пойдет насмарку.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (в сторону)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе подставит ножку он, не каркай.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБакалавр\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот назначенье жизни молодой:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМир не был до меня и создан мной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вывел солнце из морского лона,\u003ca class=\"ref\" id=\"r155\" href=\"#n155\" data-tip=\"№155 \u0026#183; Основа общего наукоучения (Фихте); Система трансцендентального идеализма (Шеллинг)\"\u003e155\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПустил луну кружить по небосклону,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДень разгорелся на моем пути,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемля пошла вся в зелени цвести,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в первую же ночь все звезды сразу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗажглись вверху по моему приказу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто, как не я, в приливе свежих сил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас от филистерства освободил?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда хочу, протаптываю след,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ пути мой светоч — внутренний мой свет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм все озарено передо мною,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то, что позади, объято тьмою.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтупай, чудак, про гений свой трубя!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто б сталось с важностью твоей бахвальской,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б ты знал: нет мысли мало-мальской,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторой бы не знали до тебя!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазлившиеся реки входят в русло.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе перебеситься суждено.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ конце концов, как ни бродило б сусло,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ итоге получается вино.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Молодежи в партере, которая не аплодирует.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа ваших лицах холода печать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ равнодушье вам прощаю, дети:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧерт старше вас, и чтоб его понять,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолжны пожить вы столько же на свете.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r158\" href=\"#n158\" data-tip=\"№158 \u0026#183; Елена (Еврипид); Мифологическая библиотека (Аполлодор) и др.\"\u003e158\u003c/a\u003e\u003ca class=\"ref blk\" id=\"r157\" href=\"#n157\" data-tip=\"№157 \u0026#183; О природе вещей (Парацельс); Труды И. Я. Вагнера и др.\"\u003e157\u003c/a\u003eЛаборатория в средневековом духе\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГромоздкие нескладные приборы для фантастических целей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер  (у горна)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧу! Колокол звонит! От звона\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриходят стены в содроганье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе может неопределенно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак долго длиться ожиданье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг — свет! Следы потемок стерты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвечением внутри реторты.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ней уголь живчиком трепещет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн, как карбункул, ярко блещет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мечет молнии нагрева\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо мрак, направо и налево.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот света белого игра!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак удержать его зарницы?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, боже, кто-то в дверь стучится.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (входя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПривет! Желаю вам добра.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер  (боязливо)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПривет вам в звездный час счастливый!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Тихо.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух затаите молчаливо:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриходит к завершенью славный труд.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (еще тише)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА чем же занимаетесь вы тут?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер  (шепотом)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСозданьем человека.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА скажите,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакую же влюбленную чету\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗапрятали вы в колбы тесноту?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО боже! Прежнее детей прижитье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля нас — нелепость, сданная в архив.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот нежный пункт, откуда жизнь, бывало\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС волшебной силою проистекала,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот изнутри теснившийся порыв,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТа самозарождавшаяся тяга,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторая с первейшего же шага\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрала и отдавалась и с собой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРоднила близкий мир, потом — чужой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе это выводом бесповоротным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтныне предоставлено животным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА жребий человека так высок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто должен впредь иметь иной исток.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Повернувшись к очагу.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВон, светится!\u0026#160;— надеяться уместно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто если в комбинации известной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз тысячи веществ составить смесь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Ведь именно в смешенье дело здесь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ человеческое вещество\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС необходимой долей трудолюбья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрогреть умело в перегонном кубе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобьемся мы в келейности всего.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Снова обращаясь к очагу.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвершается! И все прозрачней масса!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ убеждаюсь, что дождался часа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда природы тайную печать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам удалось сознательно сломать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагодаря пытливости привычной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ то, что жизнь творила органично,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы научились кристаллизовать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто долго жил — имеет опыт ранний\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ нового не ждет на склоне дней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в годы многочисленных скитаний\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВстречал кристаллизованных людей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер  (не отрывая глаз от колбы)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВскипает, светится, встает со дна:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРабота долгая завершена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам говорят \u0026#171;безумец\u0026#187; и \u0026#171;фантаст\u0026#187;,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, выйдя из зависимости грустной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС годами мозг мыслителя искусный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМыслителя искусственно создаст.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(В восхищении разглядывая колбу.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ стекле стал слышен нежной силы звон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСветлеет муть, сейчас все завершится.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ видом человечка восхищен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый в этой колбе шевелится.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧего желать? Сбылась мечта наук.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС заветной тайны сорваны покровы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнимание! Звенящий этот звук\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтал голосом и переходит в слово.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул  \u0026#160;\u0026#160;(внутри колбы, обращаясь к Вагнеру)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА, папенька! Я зажил не шутя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрижми нежней к груди свое дитя!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо — бережно, чтоб не разбилась склянка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот неизбежная вещей изнанка:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриродному вселенная тесна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИскусственному ж замкнутость нужна.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Обращаясь к Мефистофелю.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА, кум-хитрец! Ты в нужную минуту\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСюда явился к моему дебюту.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня с тобой счастливый случай свел:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока я есть, я должен делать что-то,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ руки чешутся начать работу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы б дельное занятье мне нашел.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдно лишь слово. Дай мне ключ к проблеме.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеснят меня вопросами все время.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот в чем я, например, не разберусь:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуша и тело слиты нераздельно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак отчего же тесный их союз\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе оградил их от вражды смертельной?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет! Слушай, лучше назови причину,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем не ладит с женщиной мужчина?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы этого вовек не объяснишь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вот работа для тебя, малыш.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакая?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (указывая на боковую дверь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот где докажи делами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой талант тебе особый дан.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер  (все время глядя на колбу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, право, ты прелестный мальчуган!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтворяется боковая дверь, за которою виден лежащий Фауст.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул  (удивленно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗначительно!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКолба выскальзывает из рук Вагнера и, летая над Фаустом, освещает его.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн бредит чудесами.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРой женщин раздевается в тени\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГустых деревьев у лесного пруда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасавицы на редкость все они,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдна же краше всех, и это чудо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз героинь или богинь, ногой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБолтает ясность влаги ледяной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВода ее прохладой обнимает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивое пламя стана остывает.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако чьи бушующие крылья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗеркальность водной глади возмутили?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБегут в испуге девушки. Одна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарица плеском не устрашена\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ видит с женским удовлетвореньем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарь-лебедь нежно льнет к ее коленям.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн робок, но становится смелей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все настойчивее жмется к ней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак вдруг туман окутывает дымом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрелестный берег и навес ветвей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад происшествием непостижимым.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткуда взял ты это, фантазер?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак мал еще и так уже остер!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе вижу ничего.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы — северянин,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ты родился в средние века.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвой мир попов и рыцарей — туманен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго окутывают облака.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак хочешь ты свободен быть и зорок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда тебе привычный сумрак дорог?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Осматриваясь.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУжасно в вашем каменном мешке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ загоне ум, и чувство в тупике.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроснется спящий, и в одно мгновенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тоски умрет у вас по пробужденье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛес, лебеди, красавиц нагота —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот сон его и вот его мечта.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак примирится он с таким жилищем?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУживчив я, но лучшего поищем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмчим его.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХорошее решенье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПошли приказом воина в сраженье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА девушку в веселый хоровод.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дело вмиг у них на лад пойдет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак и у нас. Я дело приурочу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК классической Вальпургиевой ночи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна сегодня. Вот и найден путь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПохитить спящего и окунуть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго в родной стихии средоточье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ слышу в первый раз об этом всем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВполне понятно. Что за удивленье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам ведом романтический фантом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо чтоб считаться истинною тенью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй надо быть классической притом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда же предстоит нам перелет?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня к собратьям древним не влечет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСеверо-запад — край обетованный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоих всех порываний, Сатана.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ нас на этот раз иные планы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЮго-восток — вот наша сторона.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам по равнине, обтекая скалы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТечет средь рощ извилистый Пеней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА выше — горы и следы камней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаринного и нового Фарсала.\u003ca class=\"ref\" id=\"r159\" href=\"#n159\" data-tip=\"№159 \u0026#183; Записки о гражданской войне (Цезарь); География (Страбон)\"\u003e159\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставь! Ни слова о веках борьбы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротивны мне тираны и рабы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть жизнь переиначат по-другому,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак снова начинают спор знакомый!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ никому не видно, что людей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМорочит тайно демон Асмодей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто бредят все освобожденьем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вечный спор их, говоря точней, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПорабощенья спор с порабощеньем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставь людей, их мятежи и вспышки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебя стараясь с детства отстоять,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтановятся мужчинами мальчишки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридумай, как нам спящего поднять?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсть средство у тебя, так посоветуй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА нет его, так предоставь мне это.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО Брокене я мог бы дать совет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо на язычестве для нас запрет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда пустым народом были греки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудили чувственное в человеке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрикрашенный их вымыслами грех\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСветлей и ярче северных утех.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ж мы предпримем?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ прекрасно знаю,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто если я такому шалопаю\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПро фессалийских ведьм шепну словцо, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУже соблазн какой-то налицо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (плотоядно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО фессалийских ведьмах? Любопытство\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавно к ним тянет, а не волокитство.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтдать им жизнь, о нет, но, скажем, ночь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля пробы, для знакомства я не прочь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда скорей пошире плащ раскинь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбвей себя и рыцаря мантильей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ткань, как прежде, заменив вам крылья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас унесет в заоблачную синь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСветя в пути, я полечу вперед.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвой долг тебя удержит дома.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНемало у тебя своих забот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧитай пергаментов старинных томы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоллекцьонируй образцы пород,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоединяй и систематизируй\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНачала главные живого мира,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроисхожденья жизни и души,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вещества загадку разреши.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА между тем я света часть объеду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоставлю точку, может быть, над \u0026#171;i\u0026#187;,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ это будет главная победа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа годы трудолюбия твои\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ даст тебе заслуженное право\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа отдых, долгий век, богатство, славу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы даже знанья скопишь кое в чем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ добродетель, пополам с грехом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрощай!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВагнер  (печально)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя я с грустью отпускаю\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ больше свидеться с тобой не чаю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак по словам двоюродного братца\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас мы вылетаем на Пеней.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(К зрителям.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ конце концов приходится считаться\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС последствиями собственных затей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eКлассическая Вальпургиева ночь\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФарсальские поля. Тьма\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭрихто\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа страшный праздник этой ночи сызнова\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПришла, как прежде, я, Эрихто мрачная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе столь, однако, мерзкая, как подлые\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэты лгут… Они не знают удержу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи в порицаньях, ни в хвалах… Белеется\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРавнины даль под серыми палатками.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУжасной ночи бредовое зрелище,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДо бесконечности ты повторяешься\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ будешь повторяться вновь… Владычества\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот не уступит никогда сопернику,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто крепок властью, силою захваченной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кто собой не в состоянье властвовать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот властвовать желает над соседями.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут был когда-то дан пример побоищем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак сильный налетает на сильнейшего,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак рвутся лепестки цветущей вольности\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ жесткий лавр венчает лоб властителя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПомпей Великий вспоминал здесь славные\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГода могущества, а Цезарь взвешивал\u003ca class=\"ref\" id=\"r160\" href=\"#n160\" data-tip=\"№160 \u0026#183; Фарсалия (Лукан)\"\u003e160\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадежды на успех в борьбе с соперником.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть знает мир, кто вышел победителем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх спор возобновится ночью нынешней.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБивачные костры, пары кровавые\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вкруг огней причудливые зарева.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалангой эллинской преданья строятся.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМелькают на свету, в дыму теряются\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДней баснословных сказочные образы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеполный, ясный месяц подымается\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ослабляет синий отблеск пламени,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСгоняя с поля прочь палаток призраки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто надо мной за метеор светящийся\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тело рядом с ним шарообразное?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ чую жизнь. Но подходить не следует\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК живому мне, я для живого гибельна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет пользы мне в живом, одно бесславие.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШар опустился. Уберусь-ка вовремя.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Удаляется.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоздухоплаватели в вышине.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОблетим еще раз с края\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМесто страшного сраженья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоле битвы, оживая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаполняют привиденья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в оконной амбразуре\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК рожам севера привык,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак при виде здешних фурий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе могу я стать в тупик.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот одна из их орясин\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыстро прочь от нас идет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО бедняжка, так ужасен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй, наверно, наш прилет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпусти на эту землю\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРыцаря, и тотчас он,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШумам этой почвы внемля,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудет ею воскрешен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (дотронувшись до земли)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, где она?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе знаем сами.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо расспроси между кострами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока не наступил рассвет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто к Матерям дерзнул забраться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТому уж нечего бояться\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ трудностей на свете нет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я участие приму.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоищем приключений в стане\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ разбредемся по поляне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо все концы по одному.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты б нам, малый, к сбору дал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоею колбою сигнал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот будет что моим призывом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтекло сильно звенит и светится.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ путь! К новым чудесам и дивам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (один)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, где она? Доведываться рано.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть шла она не этою поляной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПускай не эта именно река\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШумела ей волной из тростника,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПускай! Но этот воздух несказанный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй множил звук родного языка!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь Греция, и я в ее краю!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ эту почву ощутил мгновенно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСквозь тяжкий сон, мне сковывавший члены,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, встав с земли, я, как Антей, стою.\u003ca class=\"ref\" id=\"r161\" href=\"#n161\" data-tip=\"№161 \u0026#183; Мифологическая библиотека (Аполлодор); Фарсалия (Лукан)\"\u003e161\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть ждут там чудища и исполины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПойду на розыски к кострам равнины.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Удаляется.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eУ верхнего Пенея\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (останавливаясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа группы у огней смотреть мне тяжко:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет ни рубашки ни на ком, ни лифа.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе голы, все наружу, нараспашку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБесстыдны сфинксы, непристойны грифы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо спереди, то сзади, без прикрас\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХвосты и крылья тычут напоказ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо сути, правда, и у нас стыда нет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо древность лишней жизненностью ранит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо моде скрыть бы выпуклость фигур!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе это откровенно чересчур.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНародишко! Польщу им тем не мене,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак подобает гостю. Честь отдам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрекрасным дамам, выкажу почтенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПремудрым стариканам-гривачам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГриф  \u0026#160;\u0026#160;(гнусаво)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе гривачам, а грифам! Очень странно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам удружил, зачислив в стариканы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвучанием корней живут слова.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ них слышны грамматические свойства.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Грусть\u0026#187;, \u0026#171;грыжа\u0026#187;, \u0026#171;гроб\u0026#187; приводят нас в расстройство.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы не желаем этого родства.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК чему вдаваться в дебри лексикона?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрабеж — прямое существо грифона.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГриф  (тем же тоном)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКонечно! Кто хватает, тот и хват.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХватай именья, девушек, короны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ золото хватай, и ты — богат.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСудьба к хватающему благосклонна.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМуравьи  \u0026#160;\u0026#160;(огромного роста)\u003ca class=\"ref\" id=\"r162\" href=\"#n162\" data-tip=\"№162 \u0026#183; История (Геродот); Аримаспея (Аристей Проконнесский)\"\u003e162\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы \u0026#171;золото\u0026#187;, сказали? Целый клад\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкопили мы и заперли в ущелье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо аримаспы это подглядели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУкрали и над нами же трунят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрифы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы им покажем, жуликам пропащим!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАримаспы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо не сегодня. Нынче торжество.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА за ночь остальное мы растащим\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в этот раз добьемся своего.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (усевшись между сфинксами)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо мере сил я к месту привыкаю\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ даже ваши мысли понимаю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинкс\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы выдыхаем звуки грез едва,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вы их превращаете в слова.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо назовись, чтоб мы тебя узнали.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне имена различные давали.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажите, между прочим, с нами рядом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет путешественников-англичан?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни так любят изученье стран,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК полям сражений ездят, к водопадам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм подошел бы вид таких полян.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне также псевдоним был ими дан.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни меня назвали в старой пьесе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;The old Iniquity\u0026#187;\u003ca class=\"ref\" id=\"r164\" href=\"#n164\" data-tip=\"№164 \u0026#183; Чёрт — осёл (Бен Джонсон); Ричард III (Шекспир) и др.\"\u003e164\u003c/a\u003e с обычной спесью.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинкс\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо почему?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне это невдомек.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинкс\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы сведущ в звездах? Ты б прочесть не мог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто в их расположении таится?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (подняв глаза к небу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвезда сменяет на небе звезду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвет молодого месяца струится.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ славный у тебя приют найду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСогрей меня своею шкурой львицы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем нам уноситься в звездный край?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШараду иль загадку мне задай.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинкс\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы можешь сам задать ее успешно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь, собственно, ты — парадокс сплошной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы это то, в чем с силою одной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНуждаются и праведный и грешный:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдин, чтоб злу всегда сопротивляться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругой, чтоб злу всецело подпадать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе для того, чтоб Зевсу повод дать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПремило над обоими смеяться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервый гриф  (гнусаво)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне мерзок он!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторой гриф  (еще более в нос)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мне не по нутру.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОба\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМерзавец здесь совсем не ко двору.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (грубо)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ты — когтями, если не сильнее,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарапаться ногтями я умею.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПопробуй-ка!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинкс  (с женской лаской)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы можешь здесь остаться.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя потянет самого домой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам край родной, свои и домочадцы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА здесь, мне кажется, ты сам не свой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы привлекаешь верхней половиной!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо ужасаешь нижнею, звериной!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинкс\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛап наших испугался? Поделом!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПопался, старый? Так тебе и надо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ львицы в лапах на себя досадуй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ты без лап, с копытом, да и хром.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ вышине сирены\u0026#160;пробуют голоса.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакие птицы с пеньем забрались\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ приречный этот тополь у теченья?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинкс\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе вслушивайся лучше. Берегись.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХрабрейших погубило это пенье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, не путайтесь с презренным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтим сфинксовым отродьем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбратитесь к нам, сиренам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы красой всех превосходим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрели голосом выводим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинксы  (передразнивая сирен на тот же лад)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы заставьте их спуститься.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто они забились в листья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсяких коршунов когтистей?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь заслушайтесь,\u0026#160;— в награду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазорвут вас эти птицы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВылетевши из засады.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрочь раздоры! Рознь долой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть забьют одной струей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВолны радости земной:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДружно на воде, на суше\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГостю выкажем радушье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсею нашею семьей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ струн прекрасны перезвоны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ голоса не монотонны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо тем не менее напев\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдинственно лишь слух ласкает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА в душу мне не проникает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНисколько сердца не задев.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинксы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакое сердце? Слово слишком громко.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе сердце, а пустой горластый зев\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, может быть, старьевщика котомка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (подходя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак крупно все! Черты души громадной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь даже и в уродливом наглядны!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе мне кругом так много говорит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, кажется, удачу мне сулит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Посмотрев на сфинксов.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред ними некогда стоял Эдип.\u003ca class=\"ref\" id=\"r163\" href=\"#n163\" data-tip=\"№163 \u0026#183; Царь Эдип (Софокл); Мифологическая библиотека (Аполлодор)\"\u003e163\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Посмотрев на сирен.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт этих Одиссей чуть не погиб,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ пеньковых путах корчась.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Посмотрев на муравьев.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМуравьями\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРедчайший в мире клад зарыт был в яме.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Посмотрев на графов.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот клад вот эти грифы стерегли.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ какой величественной панораме\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБылое подымается вдали!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы прежде плюнул бы на этот сброд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ныне видишь тут родной свой угол.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто поиски возлюбленной ведет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот радуется виду встречных пугал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (сфинксам)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы, с женщинами сходные на глаз,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе видел ли Елены кто из вас?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинксы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаш род до дней Елены не восходит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУбил последних бабок Геркулес.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпроси Хирона.\u0026#160;Он в округе бродит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтупай к нему скорей наперерез.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМожем быть и мы полезны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК нам заехав на привал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНекогда Улисс любезный\u003ca class=\"ref\" id=\"r165\" href=\"#n165\" data-tip=\"№165 \u0026#183; Одиссея (Гомер)\"\u003e165\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМного нам порассказал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз услышанных историй\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы б не скрыли ничего,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли бы ты для того\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеребрался к нам на взморье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинкс\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГость, не поддавайся лжи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ обманщицам отпетым!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак Улисс, себя свяжи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо не цепью, а советом:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтыщи Хирона. Он\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ эти тайны посвящен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст удаляется.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (с недовольством)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто это, каркая сурово,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛетит с такою быстротой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто никакому птицелову\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ту кучу не попасть стрелой?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинкс\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтремительнее стрел Алкида,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ зимних бурь, и птичьих стай\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад нами мчатся стимфалиды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезвреден их вороний грай.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх клювы хищно крючковаты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА лапы словно у гусей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни нам родственники, сваты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ к нам летят станицей всей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА это что за свист злодейский?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинкс\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть эти гады не страшат.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо головы змеи Лернейской,\u003ca class=\"ref\" id=\"r166\" href=\"#n166\" data-tip=\"№166 \u0026#183; Мифологическая библиотека (Аполлодор); Мифологический словарь (Гедерих)\"\u003e166\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть много лет тому назад\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМечом отнятые от торса,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо старой памяти шипят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо что глазами ты уперся?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда кидаешь нежный взгляд?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам — ламии,\u0026#160;там привиденья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе пяль глаза в том направленье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то ведь сам не будешь рад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвернешь, оглядываясь, шею.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА впрочем, я держать не смею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтупай к ним, окунись в разврат.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни развязные особы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо льстивым ртом и медным лбом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, как сатировы зазнобы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПовсюду лезут напролом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я, вернувшись, сфинксов здесь застану?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинкс\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО да, конечно! Отправляйся к ним.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы, родом из Египта, невозбранно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУже тысячелетьями царим\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ высимся для вас подобьем вех,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб направлять луны и солнца бег.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы сидим у пирамид,\u003ca class=\"ref\" id=\"r167\" href=\"#n167\" data-tip=\"№167 \u0026#183; Естественная история (Плиний); История (Геродот) и др.\"\u003e167\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак судилище народов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ годы мира, войн, походов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСохраняя тот же вид.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eУ нижнего Пенея\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеней, окруженный ручьями и нимфами.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеней\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗашурши, камыш! Мне дорог\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТихий тростниковый шорох.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТополь, всколыхнись лениво,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСодрогнись листвою, ива,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тогда я вновь усну.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтзвук страшного чего-то,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБури иль переворота,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазогнал мою дремоту,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть и клонит вновь ко сну.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (подойдя к потоку)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС видимостью как бороться?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мне слух от вод отвлечь?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ рокоте их раздается\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧеловеческая речь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа ветвями — шуры-муры\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВолн и ветра-балагура.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНимфы  (Фаусту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсего будет лучше,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда постепенно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тени ты растянешь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУсталые члены.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакого покоя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда ты лишен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА мы б тебе пеньем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНавеяли сон.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь я не сплю, я наяву\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТех женщин вижу в отдаленье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все ж они как в сновиденье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я боюсь, что сон прерву.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мне знакомо их явленье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ точно видел их в былом!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо всех сторон через осоку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтекаются ручьи притока\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ один, удобный для купанья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлубокий, чистый водоем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ нем, отражаемая влагой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтоит и плавает ватага\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКупальщиц, царственных собой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни разбрасывают брызги,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ слышны плеск, и смех, и взвизги\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВеселой битвы водяной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостаточно мила картина.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем же я ее покину?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо ненасытен взор живой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ рвется дальше, под защиту\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКустарника, в котором скрыта\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарица за густой листвой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг, о прелесть! Горделиво\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛебеди плывут, залива\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯсности не колыхнув.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх скольженье — нежно, плавно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ у каждого державны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШея, голова и клюв.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо один, всю эту стаю\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмелостью опережая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКруто выгибает грудь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШумно раздувает перья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ к святилища преддверью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрямо пролагает путь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругие плавают в затоне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли бросаются в погоню\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа девушками всей толпой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, госпожу забыв, служанки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ испуге прячутся, беглянки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсецело заняты собой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНимфы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриложите ухо все\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь к земле, травой покрытой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлышу на речной косе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтзвук конского копыта.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнать бы только, кто так скор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто летит во весь опор?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКажется, земля трясется\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод галопом иноходца,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе верю сам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоим глазам!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакая встреча!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем я отвечу?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИскусный, пылкий всадник мчит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС конем он неразрывно слит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО конь и получеловек,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, все сказал мне твой разбег!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТобою может быть один\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФилиры знаменитый сын.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтой, стой, Хирон, и отзовись!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, что тебе?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстановись!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ мчусь без устали.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПостой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда возьми меня с собой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСадись. Начни свои расспросы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда тебе? Тебя б я мог\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеренести через поток\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС крутого этого откоса.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне все равно. Я — твой навек\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолжник, великий человек,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзрастивший целый род героев\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостоинством своих устоев,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКруг аргонавтов, с прочей всей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСемьей больших богатырей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе говори о воспитанье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыла Паллада скверной няней.\u003ca class=\"ref\" id=\"r168\" href=\"#n168\" data-tip=\"№168 \u0026#183; Теогония (Гесиод); Аргонавтика (Аполлоний Родосский) и др.\"\u003e168\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивут, урокам вопреки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоим умом ученики.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда приветствую врача,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый, всякий вред леча,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе травы изучил на свете\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сам еще во всем расцвете.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, в старину, признаюсь сам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмел я врачевать раненья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я теперь свое уменье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставил бабкам и попам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак человек большой, ты скромно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвиливаешь от похвал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто сам ты слишком мал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА подвиги других огромны.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты мне льстишь, как все льстецы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВтираясь в хаты и дворцы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо согласись: ты жил со всеми,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторых выдвинуло время,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ прожил жизнь, как полубог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсех испытавши камнем пробным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКого б из них назвать ты мог\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостойным самым и способным?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз аргонавтов был любой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогатырем на свой покрой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧего одним недоставало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо доблесть прочих возмещала.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасавцам Диоскурам в дар\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостался юношеский жар.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРешимость с остротою взгляда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоединяли Бореады.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмом, советом брал Язон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоклонницами окружен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда Орфей играл на лире,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДышалось всем и пелось шире.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ днем и ночью меж зыбей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКормилом управлял Линкей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ опасность дружно все бросались,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все друг другом восхищались.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПро Геркулеса ты забыл.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы боль мою разбередил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не видал богов. Ареса\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе видел, Феба и Гермеса,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда моим земным очам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредстал приравненный к богам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн явно сыном был монаршим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПленительный и молодой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмирялся он пред братом старшим\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лучших женщин был слугой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж не родит такого Гея\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ Геба ввысь не унесет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи статуи, ни эпопеи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНейдут в сравненье с ним в расчет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, он у всех выходит хуже,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем у тебя. Не откажи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ после слов о лучшем муже\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО лучшей женщине скажи.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНичтожна женщин красота,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезжизненная зачастую.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоистину прекрасна та,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто и приветлива, чаруя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивая грация мила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеотразима, не надменна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакою именно была,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда я вез ее, Елена.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы вез ее?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, на загривке.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я на этой же спине!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, сведений твоих обрывки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсю голову вскружили мне!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна, вскочив, взялась за гриву,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ты. За прядь моих волос.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вне себя! О, я счастливый!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ весь теряюсь в вихре грез!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ посвятил ей все порывы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда же ты Елену вез?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтвечу на вопрос сейчас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ те дни похитили Елену.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДва Диоскура в тот же час\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасли свою сестру из плена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо похитители, озлясь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа дерзость нашего налета,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПустились за беглянкой вслед.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы взяли вбок у поворота,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРешивши уходить от бед\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧрез Элевзинские болота.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ братья перешли их вброд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ ж переплыл с живою ношей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, наземь спрыгнув на бегу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ручкой гриву мне ероша,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна была на берегу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак хороша, так молода,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ старику на загляденье!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй шел десятый год?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГода\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе — ученых измышленье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМифическая героиня —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛицо без возрастных примет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэт дает без точных линий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе расплывчатый портрет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще до совершеннолетья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ ней поклонников орда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда она уже седа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо и тогда еще в расцвете.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе оставляя в ней следа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсю жизнь, сквозь все метаморфозы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрозят ей свадьбы и увозы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэту время не указ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна и не пример для нас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь удалось Ахиллу в Ферах,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак, верно, ведомо тебе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ней жить вне наших рамок серых,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВне времени,\u003ca class=\"ref\" id=\"r169\" href=\"#n169\" data-tip=\"№169 \u0026#183; Тесей (Плутарх); Описание Эллады (Павсаний) и др.\"\u003e169\u003c/a\u003e назло судьбе!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеужто я ее одну,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБожественную, молодую,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак я ее себе рисую,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсей страстью к жизни не верну?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе ты видел в старину,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я лишь поутру сегодня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я тоскую безысходней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем ты. Я дня не протяну.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПришлец! Наверно, твой влюбленный пыл\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСреди людей считается законным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо духи держатся иных мерил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мне ты кажешься умалишенным.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы вовремя нас, к счастью, посетил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в эту ночь, долину обегая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДочь Эскулапа, Манто, посещаю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна отцу в тиши моленья шлет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб обуздал врачей он и безвинно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм больше не давал морить народ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУсердием во славу медицины.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХочу, чтоб ты немного погостил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ Манто, самой милой из сивилл.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛечись травой под бабки руководством\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ навсегда покончишь с сумасбродством.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛечиться, чтоб огонь во мне потух?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб стал я рассудителен и сух?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе отвергай спасительного зелья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлезай скорее наземь. Мы у цели.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда через ручьи и мимо скал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо мраке ночи ты меня примчал?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОлимп налево и Пеней направо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь Греция и Рим решали спор,\u003ca class=\"ref\" id=\"r171\" href=\"#n171\" data-tip=\"№171 \u0026#183; История от основания города (Тит Ливий); Эмилий Павел (Плутарх)\"\u003e171\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧьей будет необъятная держава,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеряющаяся в песках средь гор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ царь бежал, а победил народ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь взгляни. Безмолвием волнуя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред нами древний храм стоит вплотную,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛучам луны распахивая вход.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМанто  (внутри храма, в бреду)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧу! Не копыта ли коня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГремят на мраморном пороге?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе вы ли навестить меня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожаловали, полубоги?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, это мы перед тобой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлаза пошире лишь открой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМанто  (пробуждаясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобро пожаловать. Ты подоспел?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, это я. Твой храм, как прежде, цел?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМанто\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак видишь, цел. А ты, как прежде, рыщешь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы неподвижности для счастья ищешь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я для удовольствия кружу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМанто\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, время мчит, я ж в стороне сижу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА это кто?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХирон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНочное колдовство\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВолной прибило к берегу его.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесчастный помешался на Елене.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн ищет здесь ее, а как найти,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля этого не ведает пути.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБольной нуждается в твоем леченье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМанто\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто хочет невозможного, мне мил.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем временем Хирон быстро уносится.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходи, смельчак! Ты мне приязнь внушил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот спуск в Олимпа недра к Персефоне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна там в подземелье стережет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГостей, как ты, непрошеный приход.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднажды, совершая беззаконье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОрфея тайно я сюда ввела.\u003ca class=\"ref\" id=\"r170\" href=\"#n170\" data-tip=\"№170 \u0026#183; Фиваида (Стаций); Божественная комедия (Данте) и др.\"\u003e170\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКончай ловчей, чем он, свои дела.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпускаются в глубину.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ верховьев Пенея как прежде\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС камня бросимся в Пеней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоду плеском рук запеним.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрусть людей разгоним пеньем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб жилось им веселей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез воды была б напасть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК устью поплывем и вскоре\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИгрищам в Эгейском море\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШумно отдадимся всласть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемлетрясение.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо река надулась, стала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ обратно побежала,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазливается, бурля,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрохот, гул, трещит земля.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз расселин валит дым.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрашно нам! Бежим, бежим!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрай небезопасный бросьте,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСледуйте за нами, гости!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК морю, к дали голубой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде сверкающий прибой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНабегает, пеной брызжет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтбегает, камни лижет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ где блещут две луны —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС неба и из глубины.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам пловцов свободных взмахи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь — землетрясенья страхи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдравый смысл бежать велит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМестность ужасом грозит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейсмос  (возясь и ворча под землей)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу-ка, плечи понатужу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрякну, двину раз-другой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысунусь в дыру наружу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе подастся предо мной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинксы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак качает! Фу, как гадко!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи покоя, ни порядка!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо налево валит с ног,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо кладет на правый бок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ни велика досада,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудем мы терпеть и ждать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли б ад восстал, не надо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеста никогда менять.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто за выдавшийся свод\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧудом из-под почвы прет?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто он, седоволосый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗодчий острова Делоса,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриподнявший вверх из вод\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстровок со дна морского\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖенщине, рожать готовой,\u003ca class=\"ref\" id=\"r172\" href=\"#n172\" data-tip=\"№172 \u0026#183; Гимн к Аполлону Делосскому; Метаморфозы (Овидий) и др.\"\u003e172\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля приюта от невзгод.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлотен, кряжист, коренаст,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак Атлант, наддаст, надавит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСдвинет почвы целый пласт\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ его ребром поставит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДно речное, хрящ, песок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзвалит вдруг на горб заплечный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрещиной весь край приречный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазорвавши поперек.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт натуги став огромней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШеей подперев гранит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак со дна каменоломни\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн из-под земли глядит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДальше вылезть не дадим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПуть наружу преградим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейсмос\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ конце концов признать пора\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМои труды, толчки и встряски.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез них могла ль земли кора\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакой прекрасной быть, как в сказке?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде было б гор великолепье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б я в недра их не влез\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на своей спине их цепи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе поднял в синеву небес?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвидетелями были предки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХаос и Ночь, как я их тряс,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа и титаны-однолетки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУчастники моих проказ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам были нипочем утесы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ своем задоре, силачи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы горы Пелион и Оссу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодбрасывали, как мячи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА в довершение веселья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПовесы и озорники,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы сверху на Парнас надели\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДва пика\u003ca class=\"ref\" id=\"r173\" href=\"#n173\" data-tip=\"№173 \u0026#183; Теогония (Гесиод); Одиссея (Гомер) и др.\"\u003e173\u003c/a\u003e те, как колпаки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь там рощи Аполлона,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я и Зевсу порадел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодняв ему Олимп для трона\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ для его громов и стрел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, вырвавшись рывком тяжелым\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз бездн на шумный праздник ваш,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ подарок бодрым новоселам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ выворотил этот кряж.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСфинксы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДелом древности могли бы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоказаться эти глыбы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли б мы не убедились,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак их слой из почвы вылез.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВокруг нагроможденья свежих плит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗеленый лес разросся и шумит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вопреки сильнейшим потрясеньям\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы, сфинксы, старых мест не переменим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрифы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосмотрите. В дыры, в щели\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИскры золота засели.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМуравьи, не проморгайте:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтот клад отковыряйте!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор муравьев\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде кручу горную\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасперло сдвигом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТуда, проворные,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПуститесь мигом!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСемьею бойкою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТащи находки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПласты с прослойкою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ самородки!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС рассвета самого\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДо поздней ночи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРуду отламывай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорнорабочий!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ скале расколотой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолпою дружной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИщите золото!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемли не нужно!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрифы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМарш, марш! И золотистый крап\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСсыпайте здесь, у наших лап.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь нет запоров и ключей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВернее грифовых когтей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПигмеи\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот и мы тут разместились,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтали на ноги, стоим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА откуда мы явились,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеизвестно нам самим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля пристанища довольно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМалой трещины в земле.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДаст скала разлом продольный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДаст и карлика в скале.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ этом каменном уступе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн и разведет семью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС карлицей своею вкупе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не хуже, чем в раю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо случайности счастливой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут нашелся кров жилой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ восток и запад живы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько матерью-землей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДактили  (мальчики с пальчики)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо если за ночь эта мать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлодит пигмеев род мизерный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо не откажется рожать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас, самых маленьких, наверно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредводители пигмеев\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС резвою прытью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМесто займите.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНатиск мгновенный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСиле замена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуйте в дни мира\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойску секиры.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКузницы зданье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтройте заране.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРод муравьиный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВройся в глубины!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМало-помалу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлавьте металлы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДактили-крошки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТонкие ножки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаскивай в кучи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХворост и сучья!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖгите совместно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУголь древесный.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГенералиссимус\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛуки и стрелы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзявши, за дело!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБейте в заливах\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦапель спесивых\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШтурмом нежданным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсех до одной!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ шлеме с султаном\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад головой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМуравьи и дактили\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак быть? Спасенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет никакого.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы роем руды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз этой груды\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуются звенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам на оковы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДо той минуты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак, взяв преграды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе сбросим путы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМириться надо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИвиковы журавли\u003ca class=\"ref\" id=\"r174\" href=\"#n174\" data-tip=\"№174 \u0026#183; Илиада (Гомер); Метаморфозы (Овидий) и др.\"\u003e174\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрик убийц и жертв стенанье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрыльев шумное ширянье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКатится из тростника\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК нам сюда за облака!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦапли скопом перебиты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКровью берега покрыты.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПерья их и хохолки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУкрашают шишаки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзуверов и злодеев,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолстых и хромых пигмеев.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтзовитесь, журавли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа морями и вдали,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоберите ополченье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПреисполнясь духом мщенья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи пред чем не постоим!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмерть исчадьям воровским!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(С криком разлетаются.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (на равнине)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедьм севера смирять — одни безделки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА здесь я, право, не в своей тарелке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНасколько лучше Блоксбергская высь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам ты свой брат, куда ни повернись.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой Ильзенштейн там Ильза стережет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа высоте своей нас Генрих ждет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ Храпуны шлют Эленду-деревне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛет тысячу свой отзвук эха древний.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам прочно все, а тут того гляди,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПуть под тобой прогнется впереди.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШел, кажется, сейчас по ровной глади,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлядишь — гора образовалась сзади.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть не гора, бугор, но, став стеной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПреграда он меж сфинксами и мной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОгни костров горят. Пройдусь вдоль ряда,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриглянется компания, подсяду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще, заигрывая и дразня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШалуньи вертятся вокруг меня.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу что ж, пожалуйста. Я по привычке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе откажусь от свеженькой клубнички.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛамии  (увлекая Мефистофеля за собой)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивее, живо!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо приближаясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо удаляясь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолпой болтливой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, как потешно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто в виде кары\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбезник старый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа нами, грешный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрусит поспешно!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО волокита!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО сердцеед!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНогой разбитой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВлача копыто,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХромает вслед.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (останавливаясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМужчины-дурни, род упрямый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосмешища со дня Адама!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы, и состарившись весьма,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе прибавляете ума.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроверено на деле всеми,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто бабы — порченое племя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе сделано, все из прикрас,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтан сужен, растопырен таз.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоказывать, однако, надо ль,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто сами пуститесь вы в пляс,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва засвищет эта падаль?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛамии  (останавливаясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн стал, обдумывает, ждет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриблизимся, а то уйдет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (двинувшись вперед)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРешительней! Без остановок!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаздумывать в мои лета!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыть только чертом без чертовок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе стоило бы ни черта.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛамии  (приветливо)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК молодцу приблизим лица.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн к одной из нас, сестрицы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНежностью воспламенится.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри неполном освещенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе вы просто восхищенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоворю не в осужденье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭмпуза  \u0026#160;\u0026#160;(врываясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдравствуйте! Я той же масти\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в игре приму участье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛамии\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы — лишняя, да и урод,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ нам испортишь хоровод.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭмпуза  (Мефистофелю)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ тетушка твоя Эмпуза\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ослиною ногой кургузой.\u003ca class=\"ref\" id=\"r175\" href=\"#n175\" data-tip=\"№175 \u0026#183; Лягушки (Аристофан); Жизнь Аполлония Тианского (Филострат)\"\u003e175\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя ты с конскою ногой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПривет тебе, племянник мой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт всех в чужом краю скрываясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа родственников натыкаюсь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто Гарц, что Греция,\u0026#160;— меня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВезде преследует родня.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭмпуза\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ превращаться мастерица,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я сегодня в честь твою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб к родственнику подольститься,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ослиной головой стою.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя фамильное родство\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут ценят более всего,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ отрекаюсь самочинно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт тетки с головой ослиной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛамии\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУродину ты эту брось!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна — страшилище округи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, что есть милого, в испуге\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБежит, рассеиваясь врозь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако вы и сами, дивы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак подозрительно смазливы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто, ежели румянцем щек\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрикрыт какой-нибудь порок?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛамии\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмелее! Выбирай! Нас много.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтважься, подойди, потрогай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛови счастливый миг, храбрец!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе дорожись, к чему волынка?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы тоже, знаешь, не картинка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА держишься грозой сердец.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриблизься, и под платьем бальным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез масок, в виде натуральном\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРассмотришь всех нас наконец.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК красивейшей подъеду храбро.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Обнимая ее.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО ужас! Тощая, как швабра!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Хватая другую.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыть может, эта? Ай-ай-ай!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛамии\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе стоишь лучшей, так и знай.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне маленькая взгляд бросает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо — ящерицей ускользает\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо скользкой, как змея, косой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриволокнусь-ка за большой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, надо было быть воздержней!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вместо девушки рукой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХватаю булаву на стержне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт этой палки путь прямой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДо той упитанной особы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаких в гаремах чтут набобы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо только тронул пышку,\u0026#160;— вмиг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лопнула, как дождевик.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛамии\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзлетим в лазурь! Подымем бурю!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад ним завьемся стаей фурий!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗареем, как нетопыри!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, ведьмин сын, доволен нами?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ты отделался от ламий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак дешево, благодари!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (отряхиваясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдуматься б, а я все прытче,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмней не стал от этих штук.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоездишь, смотришь, нет различий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто дальний север наш, что юг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбман повсюду одинакий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗасилье призраков-кривляк,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВезде писатели ломаки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо всех краях народ дурак.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тут, как у других, хлопочут\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в масках чувственность щекочут,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо по спине прошел мороз,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть руку к грациям поднес.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь я не враг самообмана,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе обрывался б он так рано.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Заблудившись среди камней.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде я? Что это? Вот те на!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШел по тропинке, вдруг — стена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткуда это возвышенье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот так камней передвиженье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапрасно влез я на гряду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде сфинксов я своих найду?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНедурно, за ночь, наугад\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасставить цепь таких громад!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут ведьмы сами к месту сбора\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПривозят Блоксбергские горы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОреада  \u0026#160;\u0026#160;(с высоты естественного утеса)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСюда, на эту гору влезь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна с начала мира здесь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧти Пинда крайние отроги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни незыблемы с тех дней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда, бежал по той дороге,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСраженье проиграв, Помпей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА эти призраки — труха.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх сгонит пенье петуха,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кажущийся округ горный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИсчезнет в виде сказки вздорной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХвала тебе, скалы чело!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы густо дубом обросло.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя обходит месяц краем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМрак чащ твоих непроницаем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вот другой какой-то свет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМелькает за луною вслед.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак кстати! Этой вспышкой малой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул мне дает сигналы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткуда ты взялся, пузырь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ облететь успел всю эту ширь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне в полном смысле хочется родиться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазбив свою стеклянную темницу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо все, что я заметил до сих пор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня не увлекает на простор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвух мудрецов подслушал я беседу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШел о природе философский спор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ все верчусь по свежему их следу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб до конца дослушать разговор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверно, все известно им, всесильным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни укажут, может быть, пути,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак поступить мне в деле щепетильном\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ полностью на свет произойти.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, лучше верь себе лишь одному.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде призраки, свой человек философ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн покоряет глубиной вопросов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн все громит, но после всех разносов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаводит новых предрассудков тьму.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто не сбивался, не придет к уму,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ если ты не крохоборец жалкий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозникни сам, сложись своей смекалкой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагой совет порой неоценим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСчастливый путь! Потом поговорим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасходятся.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнаксагор  \u0026#160;\u0026#160;(Фалесу)\u003ca class=\"ref\" id=\"r176\" href=\"#n176\" data-tip=\"№176 \u0026#183; Метафизика (Аристотель); Метеорологика (Аристотель) и др.\"\u003e176\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакие доводы представить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб взгляд превратный твой исправить?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПослушна ветерку волна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо прочь бежит от валуна.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнаксагор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлед извержений — гор зигзаги.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся жизнь проистекла из влаги.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул  (между обоими)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростите, вторгнусь в вашу речь:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я хотел бы проистечь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнаксагор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес, ты б за ночь мог из тины\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакие взгромоздить вершины?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрироды превращенья шире,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем смена дня и ночи в мире.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо всем большом есть постепенность,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА не внезапность и мгновенность.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнаксагор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо здесь внезапный был толчок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлутон внутри огонь зажег,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРавнину газами Эол\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзорвал, и холм произошел.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДопустим. Он стоит. Ну что ж?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой ты вывод извлечешь?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы времени с тобой не ценим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗанявшись этим словопреньем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнаксагор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз недр горы явились мирмидоны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПигмеи, муравьи, народ смышленый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрудолюбивый, хоть и мелкота,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ заселили впадины хребта.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Гомункулу.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы не мечтал о власти над толпой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖил, оградясь своею скорлупой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, если изберешь судьбу иную,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя царем я здешним короную.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес, что скажешь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПропадешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь малых действуя, мельчаешь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА средь больших и сам растешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы тучу в небе замечаешь?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПигмеям, испуская клики,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПророчат гибель журавли.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак было бы и их владыке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б тебя им нарекли.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТревога в карликовом стане!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсю тяжесть клювов и когтей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРука слепого воздаянья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбрушит на коротышей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПигмеи сами виноваты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ если попадут в беду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо это должная расплата\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа мертвых цапель на пруду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа кровь, окрасившую воды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВступились птицы их породы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь ничто, ни шлем ни щит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВиновников не защитит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНарод убийц забился в норы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА войско, не сдержав напора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмешалось, дрогнуло, бежит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнаксагор  (после некоторого молчания, торжественно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолился я подземным божествам, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНебесным надо поклоняться нам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛуна, Диана и Геката!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ обращаюсь в высоту\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ твой предвечный образ чту\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ трех этих именах, тройчатый!\u003ca class=\"ref\" id=\"r177\" href=\"#n177\" data-tip=\"№177 \u0026#183; Метаморфозы (Овидий); Эподы (Гораций) и др.\"\u003e177\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа бедный мой народ поратуй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВрагу попавший под пяту.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, животворная и углубленная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы внешне кроткая, но непреклонная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо устрашенье вражьих душ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой гнев с небес на них обрушь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Останавливается.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогиня мне вняла до срока.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ сам не рад:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМольбой к владычице высокой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ пошатнул земли уклад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе ближе, ближе и огромней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛетящий сверху лунный шар.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт ужаса себя не помню.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ сам навлек ее удар.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНедаром носится молва,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто фессалийские колдуньи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСводили силой колдовства\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛуну на землю в полнолунье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШар близится и потемнел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГотово! Стрелы молний, пламя!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогини голос прогремел!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНиц! Наземь пред ее стопами!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вызвал эту тучу стрел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ виноват кругом пред вами.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Падает ниц.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧего-чего он только не видал!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПризнаться, ничего я не заметил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезумна ночь, и он безумным стал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА месяц в высоте, как прежде, светел\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в том же месте блещет, где сиял.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзгляни на холм, где скучились пигмеи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГора была кругла, теперь острее.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ треск неописуемый слыхал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС луны обломок каменный упал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ раздавил укрывшихся в канавах,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе разбирая правых и неправых.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я хвалю тот творческий почин,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый, сверху действуя и снизу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ теченье ночи, как бы по капризу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНастроил столько гор и котловин.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе думай! Эти горы — призрак мнимый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть гибнет гномов гадостная тварь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ радуйся, что ты у них не царь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа праздник моря поспешить должны мы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде от души нам каждый будет рад.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУходят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (взбираясь с другой стороны)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва вскарабкался на этот скат,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХватаясь за кривые корни дуба!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, оттого-то мне на Гарце любо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто с серой схож сосновый аромат,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА на дубовой этой лесосеке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе чувствуется запаха смолы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотел бы знать, чем нагревают греки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ своем аду для грешников котлы?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДриада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы смыслом доморощенным хорош,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА на чужбине этим не возьмешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем к нам соваться со своим уставом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы поклонился б здесь святым дубравам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокинутый вдали родимый край\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда в разлуке дорог, словно рай.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто жмется там за чудище тройное\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ пещере, освещаемой луною?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДриада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам форкиады скорчились внутри.\u003ca class=\"ref\" id=\"r178\" href=\"#n178\" data-tip=\"№178 \u0026#183; Теогония (Гесиод); Прикованный Прометей (Эсхил)\"\u003e178\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе трусь, ступай к ним и заговори.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОхотно. Я стою и столбенею.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак я ни горд, а опозорен в лоск.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе может этого вместить мой мозг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто эти дивы мандрагор страшнее!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ смертный грех, видать, не так дурен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаз с пугалами этими не сходен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы б выгнали из преисподней вон\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаких неописуемых уродин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ безобразья крайнего черты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРодятся здесь, в отчизне красоты!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще зовут античной эту жуть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверное считая славой мира.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо чудища зашевелились, чуть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня вблизи почуяли, вампиры.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодайте мне единственный наш глаз.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто, сестры, в храме потревожил нас?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриблизившись сюда, позвольте мне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагословенья попросить втройне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вам чужой, но, разобрав детальней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверное, я родственник вам дальний.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУже, как странник по святым местам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ поклонился старым всем богам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ Опс и Рее. Я в порыве жарком\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрем вашим сестрам поклонился, паркам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо равных вам хотя бы чем-нибудь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не нашел за весь свой долгий путь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ слов ищу приличных для канона\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, не найдя, смолкаю восхищенно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиады\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух этот, кажется, умен и смел.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак странно, что никто вас не воспел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ удивительно, что средь скитаний\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе находил я ваших изваяний,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА в отношенье формы и лица\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы не в пример достойнее резца,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем бюсты Гер, Паллад, Венер и прочих,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтоль частые у скульпторов и зодчих.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиады\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУединившись по своей охоте,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе думали мы о таком почете.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа где и было думать вам в тиши\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакого полного уединенья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде вас никто не видит, вне общенья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ дыре, где не бывает ни души?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереезжайте в бойкие места,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде царствует искусства красота\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ежедневно чередой богатой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозводит на высокий пьедестал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГероев края в виде стройных статуй.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиады\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе соблазняй! Ты б лучше замолчал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК чему нам свет, к чему совет твой пылкий?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас Ночь произвела, мы три бобылки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРодясь во тьме, останемся мы тут,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ безвестности забившись в свой закут.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда мы ваше дело так поправим:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ вас ведь зуб и глаз один на трех?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвершим мифологический подлог\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вас троих как бы двумя объявим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я бы взять тогда на время мог\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ свое распоряженье внешность третьей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб представлять вас с выгодою в свете.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдна из форкиад\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу как вы, сестры?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругие\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСговоримся с ним,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако глаза с зубом не дадим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВенец картины в зубе ведь и глазе!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак быть тогда при этаком отказе?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдна из форкиад\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗажмурь свой глаз один и выставь клык,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в профиль ты наш вылитый двойник,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто брат наш.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлишком много чести.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа будет так!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиады\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа будет так!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (уподобившись в профиль форкиаде)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез лести,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот я, Хаоса сын новооткрытый!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиады\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы дочери его. Ты средь сестер.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, до чего я дожил! Вот позор!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня все примут за гермафродита!\u003ca class=\"ref\" id=\"r179\" href=\"#n179\" data-tip=\"№179 \u0026#183; Метаморфозы (Овидий)\"\u003e179\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиады\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, как мы все похорошели сразу:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь у нас два зуба и два глаза.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне в этом виде лишь чертей пугать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА больше носу некуда казать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r183\" href=\"#n183\" data-tip=\"№183 \u0026#183; Одиссея (Гомер); Георгики (Вергилий)\"\u003e183\u003c/a\u003eСкалистые бухты Эгейского моря\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛуна, остающаяся все время в зените.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены  (расположившись кругом на утесах, играют на флейтах и поют)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак преступницы и лгуньи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФессалийские колдуньи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНизводили беззаконно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрон твой наземь с небосклона.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо спокойно, примиренно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосмотри на блеск затона\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на белые буруны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазволнованной лагуны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлужим мы тебе усердно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудь, луна, к нам милосердна.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНереиды  \u0026#160;и тритоны\u003ca class=\"ref\" id=\"r180\" href=\"#n180\" data-tip=\"№180 \u0026#183; Теогония (Гесиод); Картины (Филострат Старший) и др.\"\u003e180\u003c/a\u003e  (в виде морских чудовищ)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВызовем трубой протяжной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа простор равнины влажной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсех со дна, из глубины!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз пучины, бурей взрытой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы сюда, в залив укрытый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеснями привлечены.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы для праздника надели\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПерстни, цепи, ожерелья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗолотые пояса.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут утопленниц каменья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто — кораблекрушений\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗатонувшая краса.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто, демоны залива,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВаша страшная пожива.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоряки, ища причала,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазбивались здесь о скалы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлыша ваши голоса.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнаем мы, что в синей зыби\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНежится порода рыбья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтливая чешуей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо на нынешнем веселье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы б увериться хотели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто не рыбы вы душой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНереиды и тритоны\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрежде чем сюда приплыли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто мы сообразили.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтплывем от этих глыб,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ глубину нырнем проворно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ докажем, что, бесспорно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКровью мы теплее рыб.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Удаляются.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИсчезли вмиг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПопутным зефиром\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУносит их\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК высоким кабирам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО них в Самофракии\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредания всякие.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХодит молва:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСами себя производят, не зная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто они сами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТе божества.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМесяц над нами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстанься всю ночь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУтро лучами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПогонит нас прочь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес  (на берегу, Гомункулу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б мог свести тебя с охотой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС Нереем, мы у края грота.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо он ужасный мизантроп,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВорчлив, упрям и твердолоб.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдно уже людское имя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРождает злобу в нелюдиме.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо будущность ему ясна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот оправданье ворчуна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтарик своим сужденьем строгим\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНередко был полезен многим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаглянем все ж. Я не боюсь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто сгасну или разобьюсь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНерей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюдской какой-то голос? Что за гость?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО люди! В сердце будите вы злость!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС богами вы желаете сравняться\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ над собой не можете подняться.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой бы дивный я вкушал покой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе будь мне жалко слабости людской!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапрасно проявлял я жалость эту,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ пропадали зря мои советы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все же нас ответом удостой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМудрец пучины, старец водяной!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот в образе людском огонь пред нами.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖдет от тебя совета это пламя.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНерей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСовета? Кто оценит мой совет?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля увещаний в мире слуха нет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть люди платятся своей же шкурой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмней не делаются самодуры.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак я Париса предостерегал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб он чужой жены не похищал!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь, на границе греческой земли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда он предо мной стоял надменно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ предсказал ему проникновенно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, что прозрел я мысленно вдали:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойну, приплытье греков, дни осады,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТреск балок, дым, горящие громады,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗахват твердыни, преданной огню,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожар, убийство, бойню и резню.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДень судный Трои, гением поэта\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа страх тысячелетиям воспетый.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вызывающего смельчака\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе удержало слово старика.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ угоду чувству он попрал закон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ пал его виною Илион.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо-богатырски пал, во всем величье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОрлов на Пинде сделавшись добычей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУлисса остерег я наперед\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО том, что он к Циклопу попадет,\u003ca class=\"ref\" id=\"r181\" href=\"#n181\" data-tip=\"№181 \u0026#183; Оды (Гораций); Одиссея (Гомер)\"\u003e181\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ предсказал плененье у Цирцеи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо стал ли он от этого умнее?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто спасся он — счастливая случайность.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то б его не миновала крайность.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКонечно, грубость сердит мудреца,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо есть и благодарные сердца.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПризнательности капля перевесит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТьму оскорблений, как они ни бесят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожалуйста, дай мальчику совет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак до конца произойти на свет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНерей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе омрачайте моего чела.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ весел нынче. Побоку дела!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖду дочерей своих на праздник званый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДорид прелестных, граций океана.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи на Олимпе, ни у вас — нигде\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет равного их игрищам в воде.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПерелетая и садясь, верхом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо спин драконьих на коней Нептуна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни плывут в безудержности юной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНыряют вглубь и носятся кругом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни слились с водой так воедино,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто пена носит их, как паутину.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот, показавшись из-за их голов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ Галатея\u0026#160;по верхам валов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ Венериной жемчужной колеснице,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа цельной раковине стоя, мчится.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тех пор как нет Киприды с нами тут,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе в Пафосе как богиню чтут.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой выезд, остров, храм и все затеи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВенера завещала Галатее.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтупайте прочь. В приятный этот час\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе хочется мне гневаться на вас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей пусть разгадает вам загадку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак народиться и расти зачатку.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит к морю.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШаг этот не дал ничего. Найдется\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей, он тут же тотчас расплывется,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА если даст ответ, его язык\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗагадочен и ставит всех в тупик.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо так как выход все ж необходим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПопробуем, Протея посетим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУдаляются.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены  (с вершины скалы)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто, издали белея,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ волнах плывет к Нерею?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак паруса, вразвалку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРусалка за русалкой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВрезаются, нагие,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ родимую стихию.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСойдемте с косогора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрислушаемся к хору.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНереиды и тритоны\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвященные предметы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ нас в руках воздеты.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы на щите Хелоны\u003ca class=\"ref\" id=\"r182\" href=\"#n182\" data-tip=\"№182 \u0026#183; О божествах Самофракии (Шеллинг); Комментарий к Энеиде (Сервий)\"\u003e182\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам привезли, тритоны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостойные служенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогов изображенья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРостом — сморчки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСилой — быки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКабиры — спасенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТерпящим крушенье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНереиды и тритоны\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни — порука мира\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь празднества и пира.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ морях под их охраной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе страшно урагана.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМилее отца\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКабир для пловца\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС разбитой галеры\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлиз нашей пещеры.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНереиды и тритоны\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС собой захватили мы трех,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧетвертый остался, не мог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн главный, его к вам не тянет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн важными мыслями занят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть боги, сойдясь меж собой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПорочат любого любой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад ними трунить мы не смеем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо чтим их и благоговеем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНереиды и тритоны\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСчиталось ведь семеро их.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда ж подевали троих?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНереиды и тритоны\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНикто не мог дать справок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдет с Олимпа слух,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто есть восьмой, вдобавок\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК семи примкнувший вдруг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни нам дали слово\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыть тут, но не готовы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭти несравненные\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ жажде перемены,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак на волю пленные,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРвутся из вселенной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы и луну и солнце чтим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ всех богов на свете молим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы делу тем не повредим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда в усердье пересолим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНереиды и тритоны\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадо праздник с блеском справить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн нас может всех прославить.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерои древности — руна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИскали золотого.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо много больше вам цена\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вашему улову!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКабиры выше, чем руно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайти их было вам дано.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Припев хором.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКабиры выше, чем руно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайти их было вам дано.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНереиды и тритоны проплывают мимо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак вот что, не щадя башки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИсследует ученый?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБожки похожи на горшки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз глины обожженной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМонета — редкость, если медь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтара и стала зеленеть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей  \u0026#160;\u0026#160;(незамеченный)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюблю я шалости и козни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем что курьезней, тем серьезней.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде ты, Протей?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей  (голосом чревовещателя, то близко, то издали)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ там! Я тут!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе те же шутки, шелапут.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля друга брось свои повадки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ знаю, ты играешь в прятки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей  (как бы издали)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрощай!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес  (шепотом Гомункулу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн рядом, в двух шагах.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоярче засветился ты бы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн любопытнее, чем рыба.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо что бы этот вертопрах\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи воплотился, он пред нами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредстанет, чуть увидит пламя.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ добела накал довел бы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе лопнула бы только колба.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей  (в образе гигантской черепахи)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто я за странный свет манящий вижу?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес  (закрывая Гомункула)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ этот свет совсем к тебе приближу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо на себя возьми ничтожный труд:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯвись нам в положении стоячем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвуногим человеком без причуд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мы тебе покажем то, что прячем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей  (в благородном образе)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы сохраняешь мудреца уловки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты все тот же оборотень ловкий.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Открывает Гомункула.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей  (удивленно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛучистый гном! Не видел никогда!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай нам совет. Вот в чем его нужда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотел бы он родиться не на шутку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ рожденье он, как понял я малютку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстался, так сказать, на полпути\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лишь наполовину во плоти.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуховных качеств у него обилье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТелесными ж его не наградили.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн ничего б не весил без стекла.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак сделаться ему, как все тела?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн ранний плод, созревший до посева,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак преждевременное чадо девы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес  (вполголоса)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя вопрос пока еще открыт,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне кажется, что он — гермафродит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем лучше. Он в тот пол и попадет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК которому он больше подойдет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПослушай, малый! В море средь движенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНачни далекий путь свой становленья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольствуйся простым, как тварь морей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлотай других, слабейших, и жирей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУспешно отъедайся, благоденствуй\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ постепенно вид свой совершенствуй.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой здесь воздух вольный и живой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак пахнет морем и морской травой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, мальчик, прав. Когда ж сойдешь ты вниз,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа узкий, выдавшийся в море мыс,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде разбиваются седые гребни,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо запах моря там еще целебней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вот и шествие вдали.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри, мы вовремя пришли.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПойдем туда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ к вам пристану.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрех духов выход к океану.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРодосские тельхины \u0026#160;с трезубцем Нептуна подплывают на морских конях и драконах.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы этот трезубец сковали Нептуну,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн им усмиряет валы и буруны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда Громовержца удары гремят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНептун отвечает на грома раскат.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗубчатые молнии падают в воду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКосматые волны встают к небосводу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА все, что меж ними, то обречено\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ неравной борьбе погрузиться на дно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖезл этот нам передан временно в руки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб праздник прошел без заботы и скуки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам, молитвенникам лета,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСолнца и дневного света,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы, поклонницы луны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКланяемся с вышины.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТельхины\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогиня ночная, ты тем благодатней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто дышишь без зависти славою братней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы ждешь с нетерпеньем, чтоб остров Родос\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой гимн, славословящий солнце, принес.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНачав восхожденье из глуби бездонной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСияя, глядит Аполлон с небосклона\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа море, на остров, на горы, луга,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа улицы города и берега.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА если случайно их мгла затуманит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛуч лишний, другой, и тумана не станет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ бог узнает себя в сотне картин,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн кроток, он юноша, он исполин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы образ его изваяли впервые,\u003ca class=\"ref\" id=\"r184\" href=\"#n184\" data-tip=\"№184 \u0026#183; Историческая библиотека (Диодор); География (Страбон) и др.\"\u003e184\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридав божеству очертанья людские.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПускай гордятся, самохвалы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтихии солнечной нимало\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе нужны мертвые дела.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни кричат, как о победе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО выделке богов из меди,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто б польза в том была.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтоят недолго истуканы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лава первого вулкана\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРастапливает их литье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСуществование на суше\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедет к ничтожеству, к бездушью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ обрекает на нытье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтак, в извечную пучину\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорее на спине дельфина\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеребирайся на житье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Превращается в дельфина.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСбеги по отмелям песчаным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа обрученье с Океаном,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ котором — счастие твое.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПленись задачей небывалой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНачни творенья путь сначала.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС разбегу двигаться легко.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеняя формы и уклоны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПройди созданий ряд законный,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДо человека далеко.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул садится на Протея-дельфина.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоверься морю, дух без плоти!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКружась в его водовороте,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНосись по прихоти любой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе думай только, диво эко,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДогнать в развитье человека,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА то все кончено с тобой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотря как к делу подойдете:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПорой и человек в почете.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей  (Фалесу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, если он на твой покрой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо долго помнится такой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы у меня ведь на примете\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУже не первое столетье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены  (на скалах)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто за облака белеют\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВенчиком вокруг луны?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолуби влюбленно реют,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрастью к ней привлечены.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в святилище пафосском,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНежно воркованье стай.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх горячим отголоском\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПраздник полон через край.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНерей  (подходя к Фалесу)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМожно счесть за испаренья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто лунное кольцо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДухи, мы иного мненья:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь другое налицо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто голуби Венеры\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ свите дочери моей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрорезают атмосферу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВихря всякого резвей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧту и я, как все, богиню\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ считаю, что везде\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадо содержать святыню\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ теплом, обжитом гнезде.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПсиллы и марсы  \u0026#160;\u0026#160;(плывя на морских быках, тельцах и баранах)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа Кипре, в глухом углубленье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдали от морского волненья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазливов и землетрясений,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ пещере, закрытой чужим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ блаженном краю безмятежном,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОвеянном вечным, безбрежным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧарующим ветром морским,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы, в жизни видавшие виды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлужители дивной Киприды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе колесницу храним.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда же ночною порою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри ласковом плеске прибоя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы дочь твою, детище влаги,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУкрадкой вывозим на мыс\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ коралловой той колымаге,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНичто нам не сбавит отваги,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНичей не пугает девиз:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКреста ли, или полумесяца,\u003ca class=\"ref\" id=\"r185\" href=\"#n185\" data-tip=\"№185 \u0026#183; Естественная история (Плиний); Фарсалия (Лукан) и др.\"\u003e185\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОрла иль крылатого льва.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦари пусть враждуют и бесятся,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрирода, как прежде, жива.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ уничтожают ли пажити\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ гибнут в боях города,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы нам никогда не закажете\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПути с Галатеей сюда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыделяясь станом дюжим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНереиды во весь рост\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗамыкают полукружьем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШествия морского хвост.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, вся в мать свою, богиню,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеж дорид, своих сестер,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГалатея в середине\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыплывает на простор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесмотря на свой бесстрастный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОлимпийский, вечный род,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо-людски она прекрасна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, как смертная, влечет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДориды  (проплывая на дельфинах мимо Нерея, хором)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы своих супругов юных\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоказать хотим отцу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМесяц, в переливах лунных\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвет разлей по их лицу!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Нерею.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтих молодых матросов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыброшенных близ земли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы нашли среди утесов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбогрели и спасли.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ теперь от них в награду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы получим жар любви,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы ж, не отвращая взгляда,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаш союз благослови.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНерей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвойным добром должно считаться\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобра плодами наслаждаться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДориды\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли ты не осудил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас, что мы судьбою вертим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдари их всех бессмертьем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак и нас ты одарил.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНерей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПорадуйтесь прекрасным пленным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ можете их взять в мужья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо Зевс лишь делает нетленным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ чем властен он, не властен я.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас волны зыблют, как качели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ так же зыблема любовь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда пройдет ее похмелье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВерните на берег их вновь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДориды\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСчастливый путь вам, дорогим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасстанемся на полдороге.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы вечной верности хотим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторой не желают боги.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЮноши\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если бы нас, моряков,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда, как вы, ласкали,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы лучшего бы до веков\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкончанья не желали.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГалатея приближается на своей раковине, превращенной в колесницу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНерей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы здесь, моя прелесть?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГалатея\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтец! О судьбина!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне глаз не отвесть. Погодите, дельфины!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНерей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУже их нет, проплыли мимо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаницею неудержимой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУшли, меня не захватив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто им сердечный мой порыв?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо и единственному взгляду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ теченье года сердце радо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлава вам! Слава вам дважды!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ ожил, цвету, торжествую\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ большего в мире не жажду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ истину понял живую:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся жизнь из воды происходит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВода все хранит, производит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б не скоплялся туман,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ туч не рождал океан,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дождь не струился ручьями,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ реки, наполнившись, сами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпять не впадали в моря,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде были бы горы со льдами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолины и все мирозданье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВода, из себя все творя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе зиждет, вся жизнь — в океане!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭхо  (хор всех рядов)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИсточник всего в океане!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНерей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни свернули, но не вспять,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА в сторону, за эти скалы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа вольную морскую гладь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо колесница из коралла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ которой дочку увезли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще виднеется вдали\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСветящеюся точкой малой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе всегда я отличу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак звездочку, или свечу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли язык огня средь дыма,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли знакомый взгляд любимый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодобный яркому лучу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ чужой толпе неисчислимой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ воде еще всесильней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорит моя светильня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСреди чудес вокруг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ особенности странно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто твой колпак стеклянный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДает чудесный звук.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНерей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо что там за новый таинственный случай\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗамедлил движенье ватаги пловучей?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВкруг раковины и у ног Галатеи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПылает огонь то сильней, то слабее,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто приливом любви пламенея.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФалес\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо-видимому, по совету Протея\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГомункул охвачен томленья огнем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне слышатся стоны. Вот вскрик потрясенья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесчастный на трон налетает стеклом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтекло разбивается, а наполненье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСветясь, вытекает в волну целиком.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСирены\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак пышут и светятся волны прибоя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДруг друга гоня и сшибаясь гурьбою!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсем морем чудесный огонь овладел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ блещут в воде очертания тел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХвала тебе, Эрос, огонь первозданный,\u003ca class=\"ref\" id=\"r186\" href=\"#n186\" data-tip=\"№186 \u0026#183; Теогония (Гесиод); Пир (Платон) и др.\"\u003e186\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбъявший собою всю ширь океана!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлава чуду, и хваленье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМорю в пламени и пене!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлава влаге и огню!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлава редкостному дню!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе вместе\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлава воздуху! Хвала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТайнам суши без числа!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсем у этой переправы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧетырем стихиям слава!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2 class=\"part\"\u003eАкт третий\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r191\" href=\"#n191\" data-tip=\"№191 \u0026#183; Тесей (Плутарх); Палинодия (Стесихор) и др.\"\u003e191\u003c/a\u003e\u003ca class=\"ref blk\" id=\"r187\" href=\"#n187\" data-tip=\"№187 \u0026#183; Орест (Еврипид); Троянки (Еврипид) и др.\"\u003e187\u003c/a\u003e\u003ca class=\"ref blk\" id=\"r209\" href=\"#n209\" data-tip=\"№209 \u0026#183; Биография Байрона; Разговоры с Гёте (Эккерман)\"\u003e209\u003c/a\u003eПеред дворцом Менелая в Спарте\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит Елена в сопровождении хора пленных троянок с Панталидой, предводительницей хора, во главе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена, славой и стыдом покрытая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ с берега иду, с недавней высадки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще от корабельной качки пьяная.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас волны только что на гребнях пенистых\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоставили с полей унылой Фригии\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапором Эвра и Нептуна милостью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСюда, в родной залив.\u0026#160;Пока у берега\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСреди своих отважнейших сподвижников\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарь Менелай свое прибытье празднует,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрими меня радушно, дом возвышенный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый Тиндарей, отец мой, выстроил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь, на холме Паллады.\u0026#160;В годы детские,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда с сестрой я здесь играла, с братьями,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС Кастором и Поллуксом, с Клитемнестрою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДом этот в Спарте был отделан с роскошью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, здравствуйте, дверные створки медные!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ пролете вашем, широко распахнутом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне Менелай, жених-избранник, некогда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯвился гостем, празднично разряженным.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткройтесь снова мне, чтоб поручение\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦаря могла исполнить я с поспешностью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак истинной супруге полагается.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в дверь войду, и пусть за ней останется\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСобытий ужас, что меня преследовал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВплоть до сего мгновенья в дни истекшие.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тех самых пор, как я с порога этого\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ Цитеры храм отправилась с беспечностью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ там была фригийцем дерзко схвачена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлучилось в мире столько необычного!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧужим приятно это пересказывать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо слушать тяжело самим участникам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторых жизнь, как сказку, приукрасили.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе брезгуй, светлая госпожа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗавидно редким даром своим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдинственная из многих, ты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозвысилась своей красотой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерою предшествует имени шум,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн этим и горд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо склоняется самый упрямый гордец\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред могуществом красоты.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольно! Муж мой, высадившись на берег,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня вперед со взморья выслал к городу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС какою целью, остается тайною.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто я? Его жена, царица прежняя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИль к жертвоприношенью предназначена\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа мужнины страданья и за бедствия,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз-за меня изведанные греками?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвободна я или в плену,\u0026#160;— не ведаю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвусмысленность судьбы и славы двойственность\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне дали боги в роковые спутники,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ грозное присутствие неясности\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо мною даже у порога этого.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМуж слова мне на корабле не вымолвил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПочти со мною не встречаясь взглядами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто мне задумывал недоброе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда ж у рукавов Эврота к берегу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНосы передних кораблей приблизились,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн, словно по внушенью бога, вымолвил:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Здесь по положенному выйдут воины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я на взморье смотр рядам их сделаю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы ж подымайся по речному берегу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоней гоня лугами травянистыми\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвященного Эврота, до излучины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде прежде простиралась местность сельская\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ выстроен Лакедемон впоследствии,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо всех сторон горами грозно стиснутый.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ жилище царском с башнями высокими\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбследуй, что за это время сделали\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлужанки под надзором старой ключницы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаруха пусть тебе покажет множество\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСокровищ, нам твоим отцом завещанных,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторые и я безостановочно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКопил в года военные и мирные.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы все найдешь в порядке установленном,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь это властелина преимущество,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто он находит все по возвращении\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа месте том, где было им оставлено.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМенять уклад не вправе подчиненные\u0026#187;\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмущества великолепный вид\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе порадует сердце и взор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнушительные золотые венцы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛежат, замерев в вековой полутьме.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойди в хранилище, вызов им брось\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ видом своим покори.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПомеряйся силами с блеском убранств,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто краше, они или ты.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот что гласило дальше слово царское:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Когда же вдоволь ты удостоверишься,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто все в порядка, размести треножники,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак заблагорассудишь ты, и выложи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, что бывает под рукой старейшины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвершающего жертвоприношение.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоставь котлы, тазы и блюда плоские,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНалей воды из родника священного\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ кувшины, заготовь сухого топлива\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ острый нож, заботливо отточенный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа видном месте положи. Дальнейшее\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредоставляю твоему решению\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак он сказал, прощаясь, не прибавивши,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивотное иль человека хочет он\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаклать богам. Здесь есть о чем задуматься,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я не беспокоюсь. Боги ведают,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто надо и что нет, и так и сделают,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем люди ни считали б их веления,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобром иль злом. Что решено бессмертными,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо, смертные, должны суметь мы вынести.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖрец подымал порой топор над жертвою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА опустить не мог: тому помехою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБывало приближенье неприятеля\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИль бога подоспевшего вмешательство.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто предначертано, знать не ищи.\u003ca class=\"ref\" id=\"r188\" href=\"#n188\" data-tip=\"№188 \u0026#183; Андромаха (Еврипид); Елена (Еврипид)\"\u003e188\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмело, царица, входи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не робей!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗло и добро\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗастигают врасплох.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем, кто предскажет их наперед,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе верит никто.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТроя горела, мы видели смерть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмерть пред глазами, смерть и позор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, а теперь разве мы не в живых,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазве не солнце над нами, не твердь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазве пред нами не ты, госпожа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛучшее чудо земли?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, будь что будет. Что бы ни грозило мне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ во дворец войду безотлагательно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторого увидеть я не чаяла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ который я вернуться не надеялась,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый чудом снова тем не менее\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПередо мной. Через ступени лестницы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ девочкой привыкла перепрыгивать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ныне, видно, нет былого мужества,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ноги подо мною подгибаются.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит во дворец.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭй, не вешать голов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБедные пленницы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНечего унывать!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРадуйтесь: госпожа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена венчанная\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ этот счастливый час,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоздно, зато тем уверенней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК отчему очагу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозвращается.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлавьте богов — обновителей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВосстановителей прежнего,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВновь приводящих на родину.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсвобожденный взмывает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСловно на крыльях,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад испытаниями.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУзник же, руки простерши,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРвется напрасно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдаль за ограду зубчатую\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз темницы решетчатой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо ее, но изгнанницу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыхватил бог из грозы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ назад перенес\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз разрушенной Трои\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ этот древний, украшенный заново\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтчий дом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб после мук и блаженств\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеописанных\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь она освежила\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПамять детства и юности.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПанталида  (в качестве предводительницы хора)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе торжествуйте, сестры, преждевременно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмолкните, взглянув на дверь дворцовую.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы видите? Царица возвращается\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз внутренних покоев быстрой поступью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарица, в доме что тебя расстроило?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ты могла найти под отчей кровлею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПомимо верных слуг и их приветствия?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак что ж тогда тебя так озадачило\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вызвало твое неудовольствие?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена  (в замешательстве, оставив двери открытыми)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДочь Зевса знать не может малодушия.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрикосновенье страха ей неведомо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо древний ужас, в чреве Ночи зреющий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тьмой теней над нею нависающий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак пепел над горою огнедышащей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпособен потрясти героя мужество.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак ознаменовали мой сегодняшний\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриезд с чужбины божества стигийские,\u003ca class=\"ref\" id=\"r189\" href=\"#n189\" data-tip=\"№189 \u0026#183; Илиада (Гомер); Энеида (Вергилий)\"\u003e189\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто я, хозяйка, словно гость непрошеный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБежать готова без оглядки из дому.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо нет! На свет я вырвалась из сумрака\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дальше прочь не двинусь, силы темные!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДом надо освятить, чтобы, очищенный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн встретить мог хозяина с хозяйкою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ согласии у очага домашнего.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредводительница хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткрой своим служанкам, благородная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа что наткнулась ты в покоях внутренних?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто видела я, сами вы увидите,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоль скоро Ночь свое исчадье мерзкое\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе вобрала назад в утробу старую.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтак, когда, о порученье думая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВступила бодро я в покои царские,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыла поражена я, обнаруживши\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПустых палат и галерей безмолвие.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШагов, движенья слух мой не улавливал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСледов труда не видел взор мой в комнатах,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНавстречу мне не поспешила ключница,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлужанки в глубине меня не встретили.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда же к устью печи я приблизилась,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо перед кучкой пепла я заметила\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗакутанную, сгорбленную женщину,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторая спала или задумалась.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ по-хозяйски Женщину окрикнула,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриняв ее, бездельницу, за ключницу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторой царь доверил дом за выездом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ встать велю ей, делом озаботиться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна ж и ухом не ведет, не двинется.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотом, повторный окрик мой услышавши,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНегодница движеньем отстраняющим\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКо мне вытягивает руку правую:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Ступай, мол, вон\u0026#187;. Бросаюсь, возмущенная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК дверям опочивальни, к ложу брачному,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткуда доступ был к казнохранилищу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ что же? С полу чудище срывается\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ преграждает путь мне повелительно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОгромное, худое, безобразное,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС пустыми и кровавыми глазницами!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я ведь вам бросаю речи на ветер,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлова бессильны описать страшилище.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа вот она сама! Неужто пугало\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа свет посмело из потемок вылезти?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ отсутствии царя тут мы хозяева.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут мы под Аполлона покровительством.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн нас не даст в обиду, он заступится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн, солнечный смиритель чудищ сказочных.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдна из форкиад показывается на пороге между дверными косяками.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоловы наши хоть и кудрявы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМного мы горя видели в жизни:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУжасы боя, мрак беспросветный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ночь, когда пал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИлион.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ облаке пыли, поднятой боем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБоги взывали голосом страшным.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРознь громыхала медью, и с поля\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГул приближался\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК крепости валу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтены в то время\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦелы стояли.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПламя ж гудело\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ пожирало\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗданье за зданьем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБурей пожара\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл город охвачен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБегством спасаясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ зарева блеске\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВидели мы:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГневные боги\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШли нам навстречу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРостом до неба,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрашно шагали\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ облаке дыма.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыло ли это\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВправду, иль только\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам средь смятенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВообразилось, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам неизвестно. Но эта вот, эта\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТварь перед нами.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто не снится.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы бы могли ее\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПощупать руками,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли б не страх\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не отвращенье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркия дочь —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, но которая?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИбо их трое,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВместе владеющих\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлазом одним\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ единственным зубом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак же ты, пугало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмелость имеешь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРядом с прекрасною\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВещему взору\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФеба являться?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтой себе, впрочем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн к безобразью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНевосприимчив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак солнце не видит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтброшенной тени.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас же, несчастных,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСудьба заставляет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСносить терпеливо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлизость уродства.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак слушай, бесстыдница,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаше проклятье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа дерзость явленья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудь с бранью отвержена\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУстами счастливиц,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторых боги\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоздали краше.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтара и все же не стареет истина,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто красота несовместима с совестью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ что у них дороги в жизни разные.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС давнишних пор их разделяет ненависть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда случайно встретятся противницы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДруг другу спину повернуть торопятся\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ врозь идут: стыдливость опечаленно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА красота с победоносной дерзостью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока ее не скроет сумрак Оркуса\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИль зрелый возраст не научит разуму.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриплыв с чужбины, чужестранки грубые,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы подняли тут крик по-журавлиному,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда, крича нестройно и пронзительно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни летят над головою путника.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн вверх посмотрит на станицу шумную,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотом, забыв про них, опустит голову,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ журавли своим путем потянутся,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА он своим. Вот так и с вами станется.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто вы такие, что в жилище царское\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВорваться смели, как менады пьяные?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто вы такие, чтоб орать на ключницу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак воют псы на месяц ночью лунною?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы думаете, я не распознала вас,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоенных лет отродье, тварь походная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаразы плод, заразы передатчицы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ воинов и мирных граждан пагуба?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы ненасытной саранчой мне кажетесь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбрушившейся на поля и пажити,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧужих трудов губительницы жадные,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДешевая статья торговли лагерной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри госпоже прислуге делать выговор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсть покушенье на права хозяйские:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй надлежит одной хвалить похвальное\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ за грехи и промахи наказывать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоих прислужниц я довольна службою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ многократно верность их проверила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда крепился Илион обложенный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда он пал и лег, осадой сломленный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе менее того я в них уверилась\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ превратностях бродячей жизни, в плаванье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде каждый дорог сам себе, а к ближнему\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБывает равнодушен средь опасностей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ жду и здесь от них того же самого,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоэтому ты замолчи и более\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа них не огрызайся незаслуженно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХвалю тебя за то, что дом в исправности.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы сберегла его в мое отсутствие.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я вернулась, отойди же в сторону,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб похвала не обратилась в выговор.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКорить домашних — это право высшее\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСупруги повелителя счастливого,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторое достойно ею добыто\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДомохозяйства долголетним опытом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ так как ты пришла на место старое\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарицей и хозяйкой снова признанной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозьми бразды правленья и владычествуй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогатством завладей и всею челядью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо защити, как старшую надсмотрщицу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВперед меня от стада этих выскочек,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторые мне кажутся гусынями\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред твоей красою лебединою.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредводительница хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС красой уродство рядом как уродливо!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА глупость как глупа в соседстве с разумом!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоретиды выходят из хора и, начиная отсюда, отвечают поодиночке.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервая хоретида\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖив твой отец Эреб? Жива ль Ночь-матушка?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА как твоя сестрица Сцилла здравствует?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторая хоретида\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ вас в семье все сплошь такие чудища?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвою родню меж мертвыми разыскивай.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТретья хоретида\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ сравнении с тобой они так молоды.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС Тирезием седым в аду заигрывай.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧетвертая хоретида\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе ведь внучкой мамка Орионова?\u003ca class=\"ref\" id=\"r190\" href=\"#n190\" data-tip=\"№190 \u0026#183; Теогония (Гесиод); Одиссея (Гомер)\"\u003e190\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя отбросами вскормили гарпии.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПятая хоретида\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем ты поддерживаешь худобу свою?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе кровью, до которой ты так лакома.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШестая хоретида\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы стала падалью, питаясь трупами.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВампир зубастый, рот заткни немедленно!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредводительница хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ твой заткну, назвав тебя по имени.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажи, кто ты, и будет все разгадано.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ перестать велю вам, но не гневаюсь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА огорчаюсь вашей перебранкою.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлухой разлад меж преданными слугами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ домохозяйстве самое опасное.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда никто не слушает хозяина,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе тонет во взаимных пререканиях,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе ссорятся и ничего не делают.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо суть не в том. Взаимными упреками,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапоминаньями и обвиненьями\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы вызвали такие вещи в памяти,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакие образы, такие ужасы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто, хоть, по счастью, снова я на родине,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСамой мне захотелось в сумрак Оркуса.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа полно, было ль это все действительно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИль только ночью мне во сне привиделось?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзаправду ль я была той страшной женщиной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМечтой и мукой безрассудных воинов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз-за которой города разрушены?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрепещут девушки, все это вспомнивши.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажи мне что-нибудь хоть ты, спокойная.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто счастьем пользовался годы долгие,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТому былое сновиденьем кажется.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогов дарами ты была осыпана\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез меры и числа. Всю жизнь ты видела\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдних самозабвенных обожателей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГотовых на безумства и на подвиги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТобой пленился первым в годы ранние\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТезей,\u0026#160;красою с Геркулесом споривший.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн взял меня, как лань, десятилетнею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа ним — Афидн, меня скрывавший в Аттике.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКастор с Поллуксом от него спасли тебя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто за тобой в те годы не ухаживал?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо из героев больше всех мне нравился\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПатрокл, Пелида повторенье верное.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо ты отцом за Менелая выдана,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн — семьянин и храбрый мореплаватель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМуж царский сан за мною взял в приданое.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы Гермиону родили в супружестве.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда же Крит супруг твой завоевывал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасавец гость твою разлуку скрашивал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы мне полувдовство тех дней напомнила\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ зло, которое отсюда выросло.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго поход принес мне, вольной критянке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлен и порабощенья годы долгие.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо царь тебя назначил управляющей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дом тебе доверил с укрепленьями.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторому ты предпочла, однако же,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДни радости в другой, троянской, крепости.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе говори о радостях! Страданьями\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеисчислимыми они оплачены.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПередают, что ты жила в двух обликах,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в Трое и в Египте одновременно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ без того в минувшем все запутано,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак с толку не сбивай меня нелепостью.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА правда, что из царства мертвых будто бы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК тебе Ахилл являлся на свидание,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя давно любивший и пожизненно?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак призрак с призраком с ним сочеталась я,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак с духом дух, как с видимостью видимость.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я сама упасть готова в обморок.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Поникает без чувств на руки хоретид)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗамолчи, клеветница,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтродье зловещее!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто хорошего\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМожет высказать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭта пасть однозубая\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ язык ядовитый?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапускное сочувствие\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВолка в шкуре овечьей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрашней и опаснее\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПса трехголового.\u003ca class=\"ref\" id=\"r192\" href=\"#n192\" data-tip=\"№192 \u0026#183; Евангелие от Матфея; Теогония (Гесиод) и др.\"\u003e192\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБоязливо мы ждем:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде, когда, каким образом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСквозь личину участья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоварство проявится?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВместо слов утешительных,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДарящих забвение,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы ей в жизни напомнила\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСамое худшее.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОмрачив настоящее,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы порочишь грядущее,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтнимая надежду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа судьбы улучшение.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗамолчи, клеветница,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб душа государыни,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас покинуть хотевшая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУдержалась, помедлила\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ этом лучшем из образов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда-либо виданных.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена приходит в себя и снова становится в середине хора.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыглянь, солнышко ты наше, улыбнись нам, госпожа!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ни хороша ты в горе, в счастье много ты милей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМир перед тобой открылся, и расцвел твой чудный взор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть слыву я безобразной, знаю толк я в красоте.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз беспамятства, шатаясь, я в сознанье прихожу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ усталостью разбита и забыться вновь не прочь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо царице подобает, как и прочим смертным всем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред опасностью грозящей силы духа не терять.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы стоишь во всем величье и во всей своей красе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПовелителен твой облик. Что же ты прикажешь мне?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗря потраченное время с запозданьем наверстай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе для жертвоприношенья приготовь, как царь велел.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ сборе всё: треножник, чаши и отточенный топор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кадило, и кропило, только жертву назови.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарь не указал предмета.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, несчастье! О, беда!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто тебя так огорчает?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн тебя имел в виду.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак? Меня?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ этих.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоре!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы умрешь под топором.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ предчувствовала это!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтого не избежать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх! А мы? Что с нами будет?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС честью госпожа умрет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы же — смертию позорной: я под кровельным венцом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа стропиле вас повешу, словно пойманных дроздов.\u003ca class=\"ref\" id=\"r193\" href=\"#n193\" data-tip=\"№193 \u0026#183; Одиссея (Гомер)\"\u003e193\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена и хор, расступившись, стоят, пораженные ужасом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы, словно статуи, застыли, призраки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДрожа за жизнь, вам не принадлежащую.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак люди, тоже призраки не меньшие,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасстаться не хотят со светом солнечным.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо нет от рока никому спасения.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе это знают, редко кто смиряется.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо к делу! Вы пропали. Эй, подручные!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Хлопает в ладоши.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ дверях показываются карлики в масках, быстро исполняющие приказания.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСюда скорее, сил недобрых скопища!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДелами злыми вволю вы натешитесь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАлтарь поставьте с золотыми крыльями,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС подставкою для топора серебряной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаполните кувшины, чтобы было чем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмыть брызги черной крови на треножнике.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКовер роскошный постелите под ноги\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоленопреклоненной жертвы царственной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ который тело после обезглавленья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы с честью завернем для погребения.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредводительница хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарица в стороне стоит задумавшись,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоникли девушки, как злак подкошенный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне, пожилой, священным долгом кажется\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПообсудить дела с тобой, старейшею.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы опытна, умна, доброжелательна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть дуры эти на тебя накинулись.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтак, скажи, спасти нас нет ли способа?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛегко сказать! Спасти себя со свитою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗависит от царицы. Это требует\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРешимости и быстроты немедленной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостославнейшая парка, чтимейшая из сивилл!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖизни нить не обрывай нам и спасенье объяви.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМысленно, в воображенье, мы уже непоправимо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧувствуем, как холод смерти сковывает наше тело,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСозданное для любви.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх страх простителен, а я расстроена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо не страшусь. Я выходом воспользуюсь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто мудр, для тех возможно невозможное.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтак, скажи, что ты нам посоветуешь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе скрывай, скажи скорее, как избавиться нам, бедным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт петли, от удушенья, мысленно уже сдавивших\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаши шеи холодящим, тесным ожерельем смерти,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли только милость Реи, матери богов великой,\u003ca class=\"ref\" id=\"r194\" href=\"#n194\" data-tip=\"№194 \u0026#183; Теогония (Гесиод); О природе вещей (Лукреций)\"\u003e194\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас в беде не защитит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТерпенья хватит ли у вас, чтоб выслушать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМое повествование пространное?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПродли нам жизнь растянутою повестью.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто бережет добро и домоседствует,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто в доме подновляет стены старые,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто крышу от ненастья чинит вовремя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротянет долго под родимой кровлею.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо кто через порог свой легкомысленно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ чужую землю прочь уходит из дому,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот, возвратясь, находит место старое\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеременившимся или разрушенным.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУместны ль замечанья в миг решающий?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРассказывай без вставок неприязненных.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо не в укор тебе, а только к сведенью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо островам чужим и побережиям\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШатался Менелай морским разбойником.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС набегов возвращался он с добычею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторая внутри дворца наставлена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн десять с лишним лет провел под Троею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА сколько лет он плыл домой — не ведаю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеж тем, что сталось с домом Тиндареевым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто сталось с целым царством этим временем?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПридирчивость срослась с твоей природою.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе можешь слова ты сказать без горечи.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыла долина столько лет покинута\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеж Спартой с юга и Тайгетом с севера,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткуда ручейком Эврот спускается\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, в камышах разлившись, лебедей ютит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто там обосновалось племя смелое,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорсть северян, страны полночной выходцы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПостроив замок, в нем они запрятались\u003ca class=\"ref\" id=\"r195\" href=\"#n195\" data-tip=\"№195 \u0026#183; Морейская хроника; Завоевание Константинополя (Виллардуэн)\"\u003e195\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ правят краем всем из этой крепости.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм это удалось? Почти не верится.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа двадцать лет осели и обстроились.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ них начальник есть? Они разбойники?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНисколько. Но один из них начальствует.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть он не обошел меня поборами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не браню его. Он из имущества\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзял малое, назвавши дань дарением.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКаков собою он?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн мне понравился.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивой, бесстрашный, вежливый, понятливый.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакой понятливости нет меж греками.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя их племя варварским считается,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни до людоедства не опустятся,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак греческие воины под Троею.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ верю в благородство их начальника.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА замок их на круче! Поглядела бы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн не чета твердыням ваших прадедов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторые и впрямь циклопы строили,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак глыбы друг на друга наворочены.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА этот замок весь по нитке выверен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзглянула бы! Весь к небу устремляется,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрямой, лощеный весь, как сталь, как зеркало.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзлезть на него? Уже само намеренье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо стен соскальзывая, обрывается.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнутри — дворы, пристройки, службы разные,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБалконы, галереи, ходы крытые,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГербы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто это?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ Аякса, помните,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл на щите представлен змей свернувшийся,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ семеро у Фив таким же образом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЩиты снабдили знаками особыми.\u003ca class=\"ref\" id=\"r196\" href=\"#n196\" data-tip=\"№196 \u0026#183; Семеро против Фив (Эсхил); Античная ваза из Веймарского дворца и др.\"\u003e196\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам можно было видеть звезды с месяцем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли мечи и факелы и лестницы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУгрозу городов во время приступа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ резьбе или в изображенье выпуклом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакие же значки в роду наследуют\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт прадедов мои вояки храбрые.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧего-чего у них в гербы не вставлено:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОрлы и львы, рога козлов и буйволов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦветы, хвосты павлиньи, крылья, полосы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСеребряные, золотые, черные\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ синие. Щиты с гербами этими\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВисят вдоль зал, просторных, как вселенная, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот где для танцев место подходящее.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам есть танцоры?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсть! Золотокудрые!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасавцы, так и пышущие юностью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак юностью дышал Парис единственно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ те дни, когда с царицей близко встретился.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДержись границ, не уклоняйся в сторону\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ слово мне свое скажи последнее.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, ты его скажи мне, и немедленно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОчутишься в том замке по желанию.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажи то слово, дай свое согласие\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ нас спаси.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС такой жестокой низостью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО Менелае мысль моя не вяжется.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня он не погубит так безжалостно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА как он Деифоба изуродовал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУбитого Париса брата младшего,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый был с тобой, вдовой, в сожительстве?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтрезал уши, нос перекалечивши.\u003ca class=\"ref\" id=\"r197\" href=\"#n197\" data-tip=\"№197 \u0026#183; Энеида (Вергилий)\"\u003e197\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотреть ужасно было на несчастного!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз-за меня он с бедным так разделался.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз-за него с тобой он так расправится.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасы не делят. Кто владел ей полностью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсю истребит сполна, а не поделится.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрубы вдали. Хор содрогается.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак раздирает уши резкость трубная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВселяется в мужчину ревность грубая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолбя о том, чем обладал он некогда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ что невозвратимо им утрачено.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы не слышишь труб раската? Видишь, это блеск мечей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдравствуй, царь и повелитель. Дам тебе сейчас отчет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак же мы?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам все известно. Ей придет сейчас конец,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА потом и вам за нею. Я помочь вам не могу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПауза.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой шаг ближайший я уже обдумала.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя ты демон зла,\u0026#160;— я это чувствую, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ обратишь во зло мое доверие,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо в замок твой решила я последовать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИная вещь самой царицы помыслы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ никому на свете не открою их.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВперед, старуха. Будь нам провожатою.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, с какою готовностью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы туда устремляемся!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСзади — смерти угроза,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНасилу избегнутой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРядом — новой твердыни\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтена неприступная.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗамок, будь для царицы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакой же оградою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак троянская крепость,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько хитростью взятая.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаспространяется туман, заволакивая заднюю часть переднего плана.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСестры, что это? Видите?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНебо было безоблачно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг туман неожиданный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкрыл Эврота течение\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ извилины берега,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКамышами поросшие.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ уже горделивые\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкрылись из виду лебеди,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезмятежно скользившие\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо зеркальной поверхности.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько крики их хриплые\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС замирающей силою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрики их с перерывами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ отдалении слышатся.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоворят, голос лебедя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлужит смерти предвестием.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько в нашем бы случае\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе пришло подтверждение.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы и сами лебедушки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС грудью белой, высокою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА царица тем более, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗевса-лебедя детище.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСерой мглы пеленою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКругом все затянуто.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам друг дружку не видно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтоим мы иль движемся?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто-то странное в воздухе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам, скажите, не чудится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто Гермеса виднеется\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВпереди очертание?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлещет жезл золотой его.\u003ca class=\"ref\" id=\"r198\" href=\"#n198\" data-tip=\"№198 \u0026#183; Одиссея (Гомер)\"\u003e198\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн ведет нас к безрадостным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАда призрачным пустошам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолным мглой бестелесною.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеожиданно темнеет, мгла редеет и уходит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо светлей ничуть не стало. Стены, стены перед нами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас ограда обступает. Это двор или могила?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе равно ужасно это! Сестры, сестры, мы в ловушке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы в плену, как никогда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнутренний двор замка, окруженный богатыми причудливыми строениями средневековья\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредводительница хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВертушки, дуры, истинные женщины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИгрушки мига, жертвы настроения!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи в счастье, ни в несчастье не умеете\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы показать характер свой с достоинством.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи в чем у вас нет лада и согласия,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ только в крайней боли или радости\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе как одна визжите вы и воете.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольно, не трещите! Молча выждите,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто порешит высокая владычица.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде ты, пророчица? Зовись, как вздумаешь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть Пифониссой,\u003ca class=\"ref\" id=\"r199\" href=\"#n199\" data-tip=\"№199 \u0026#183; Ион (Еврипид); Вульгата (1 Цар. 28:7)\"\u003e199\u003c/a\u003e но навстречу выгляни\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз внутренности замка. Впрочем, если ты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтправилась уведомить хозяина,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб мне прием устроил подобающий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда спасибо, и безотлагательно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредставь меня герою достославному.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокоя жажду я, конца блужданию.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредводительница хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарица, не ищи старухи взорами.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тумане, может быть, осталась, гадкая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз недр которого, путем неведомым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеренеслись сюда мы, ног не двигая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА может быть, она ушла действительно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнутрь переходов предварить владетеля,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы тебя по-царски, с честью приняли\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ волшебном этом замке, как бы выросшем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз многих крепостей соединившихся.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо посмотри: вверху, по окнам портика\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзад и вперед снуют толпой служители.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе прием заслуженный готовится.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт души отлегло. Посмотрите туда,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак учтивой толпой милых юношей ряд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтройным шествием в лад сходят, вниз не спеша.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо чьему повеленью пред нами предстал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозмужалых подростков пленительный рой?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ чем их прелесть? В равненье, в осанке, в ходьбе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ их, венчающих лоб, белокурых кудрях\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли в ямочках щек, что, как персик, в пуху,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак и манят, как персики, их укусить?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУкусила б, но — страшно сказать: укушу, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРот наполнится прахом могильным.\u003ca class=\"ref\" id=\"r200\" href=\"#n200\" data-tip=\"№200 \u0026#183; Иудейская война (Иосиф Флавий); Фольклор о выходцах с того света\"\u003e200\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭти красавцы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодходят сюда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто они вносят?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрон и ковер,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК трону подножье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ балдахин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолог шатровый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак нимб облаков,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНашей царицы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВенчает главу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот она всходит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа трона ступень.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы полукругом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦепи сомкнем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлавен, славен, славен трикратно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтот благословенный прием.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, что объявляет хор, постепенно исполняется. После того как длинным шествием по лестнице спускаются пажи и оруженосцы, на верху ее показывается Фауст в одежде средневекового рыцаря и медленно, с достоинством сходит вниз.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредводительница хора  (внимательно его рассматривая)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, если боги человеку этому\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысокий рост, осанку, обходительность\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе в ссуду дали, а на веки вечные,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн будет все увенчивать победою:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБои ль кровопролитные с мужчинами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли с красавицами стычки мелкие.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦенила в прошлом многих я и видела,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА этот лучше всех. Вот он почтительно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриблизился. Царица, обратись к нему.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (подводит с собой человека в оковах)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарица, вместо надлежащей встречи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ слов привета, выдаю тебе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗакованного в цепи человека.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой  долг нарушив, мой  нарушил он.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтань перед госпожою на колени\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ повинись пред нею, низкий раб.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарица, это сторож наш на башне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа редкость зоркий, он поставлен мной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОсматривать с дозорной этой вышки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВесь кругозор полей до той черты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде сходятся вдали земля и небо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ доносить про все, что разглядит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудь это стадо или вражье войско.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтада храним мы, а врагов мы бьем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредставь себе, что сделал он сегодня:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы здесь,\u0026#160;— он не доносит ничего,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ по его вине мы упускаем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставшееся время, чтоб предстать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ готовности перед высокой гостьей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостоин смерти он, и он давно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛежал бы на земле в крови, казненный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вот он тут, и ты сама реши,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто делать с ним, казни его иль милуй.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя бы ты царицей и судьей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь для того меня над ним поставил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб испытать меня, начну с того,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто составляет первый долг судейский,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ обвиняемого допрошу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБашенный сторож Линкей\u003ca class=\"ref\" id=\"r201\" href=\"#n201\" data-tip=\"№201 \u0026#183; Аргонавтика (Аполлоний Родосский); Аргонавтика (Валерий Флакк)\"\u003e201\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтать вели мне на колени,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖить и с жизнью распроститься,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ тебе без разделенья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВесь принадлежу, царица.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак всегда, я ждал с востока\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУтром солнце со стены,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо оно сегодня к сроку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВстало с южной стороны.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не видел башни шпиля,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не видел гор и нив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа единственном светиле\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖадно взор остановив.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗренье рыси мне досталось,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРыси, хищницы лесной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо теперь перемешалось\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, как сон, передо мной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМост подъемный пред твердыней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБашня, крепостной курган\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред лицом такой богини\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазом канули в туман.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ослепленье, став у края,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе сводил с нее я глаз.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот она стоит, живая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак же ослепляя вас.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРогом не дал я сигнала,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолг дозорного, презрев.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖалуй плахой, иль опалой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИль смени на милость гнев.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе вправе взыскивать я за провинность,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторой я виной. О горе мне!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня преследует печальный жребий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак обольщать весь век сердца мужчин,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто больше ничего они не помнят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбманом, силою, захватом в плен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня герои, боги, полубоги\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ демоны таскали за собой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ своих походах, битвах, отступленьях.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСперва я голову кружила всем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ одном своем лице, потом в двояком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тройном и четверном. Освободи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗакованного. Бедный не повинен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто ослеплен богами — чист душой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарица-лучница, с тобою рядом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вижу пораженного стрелой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОхотница, стреляешь ты так метко.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто, чуть ты натянула тетиву,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ во мгновенье ока тоже ранен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоображаю, сколько будет жертв,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда ты воцаришься в нашем замке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в нем засвищут тучи этих стрел!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем стану я? Ты мне мой двор взбунтуешь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНебезопасным станет камень стен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я боюсь, тебе, победоносной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе войско восхищенно присягнет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто остается мне, как не отдать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе во власть себя и все владенья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторые своими я считал.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ ног твоих позволь мне всенародно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПризнать тебя своею госпожой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторой только стоило явиться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб покорить нас и занять престол.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛинкей  (с ящиком, во главе нескольких человек с такою же поклажею)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарица, я пришел назад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы бросишь человеку взгляд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сразу же, ошеломясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн нищ, как голь, богат, как князь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем был я? Чем успел я стать?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто делать мне, что предпринять?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть взгляд мой молнией бы жег,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн сломится о твой порог.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС востока накатил наш вал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ запад содрогнулся, пал.\u003ca class=\"ref\" id=\"r202\" href=\"#n202\" data-tip=\"№202 \u0026#183; Деяния (Аммиан Марцеллин); О происхождении и деяниях гетов (Иордан)\"\u003e202\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНароду двигалась тьма тем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ степи, не мерянной никем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвалился первый, стал второй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ следующий занял строй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдиному заменой сто,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ убыль тысячи — ничто.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа место с места, вплавь и вброд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеслось нашествие вперед,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ где вчера я был главой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСегодня буйствовал другой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХватали все, кто чем прельщен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИные уводили жен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИные угоняли скот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоней же — все наперечет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я рукою знатока\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрал вещь, которая редка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ доли в общем грабеже\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе требовал при дележе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ нападал на кладов след\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ их вытаскивал на свет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ отпер не один баул,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо все карманы заглянул.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ золота не мог я счесть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ отдавал каменьям честь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть у тебя на сердце тут\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИграет этот изумруд.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА этот жемчуг дорогой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПовесь в ушко себе серьгой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот и рубин, но он поблек\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред твоим румянцем щек.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе это раздобыл я сам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ приношу к твоим ногам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут битв кровавых урожай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ты его не отвергай.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот ящики и сундуки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо манию твоей руки,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ это ведь не похвальба,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНабью я ими погреба.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва на трон ты поднялась,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогатство, сила, ум, пленясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагоговейно пали ниц\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред царицей из цариц.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсей этой кучею добра\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще я дорожил вчера,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь, я вижу,\u0026#160;— это прах,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ отдал все, я нищ и наг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ отдал все, я нищ, убог,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ всем, что было, пренебрег,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо улыбнись, и за урон\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСполна я буду награжден.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей добычу эту унеси\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез знаков похвалы и порицанья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарице в замке все принадлежит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ часть дарить ей поздно и бесцельно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНагромозди дары до потолков.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУкрась в невиданных размерах залы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть роскоши недышащая жизнь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ покоях разместится без движенья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ предупреждение ее шагов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтели везде ковры перед царицей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб было в залах мягко ей ступать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ чтобы блеск глаза ее встречали,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе ослепляющий одних богов.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛинкей\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподин, такой пустяк\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСделает слуга и так.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧелядь в замке вся сполна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтой гостьей пленена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ военный гарнизон\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез оружья покорен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред силой этих чар\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХолодеет солнца жар,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак красой ее давно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе в ничто обращено!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена  (Фаусту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХочу поговорить с тобой. Взойди\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа возвышенье. Сядь со мною рядом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНезанятое место ждет того,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоседство с кем и мне защитой будет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПозволь тебе присягу принести\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ руку дай поцеловать, которой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня ты подымаешь до себя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня в своем бескрайнем царстве сделай\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРегентом, соправителем, слугой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоклонником, защитником — чем хочешь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНемало насмотрелась я чудес,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаслушалась того, пожалуй, больше.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО многом бы хотела я спросить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ первым делом: отчего так странно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПленяла речь служителя того?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн подгонял так стройно слово к слову,\u003ca class=\"ref\" id=\"r203\" href=\"#n203\" data-tip=\"№203 \u0026#183; История персидского красноречия (Хаммер-Пургшталь); Бахрамгур (Гёте)\"\u003e203\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в хоре сочетают голоса,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛаская слух их сменой и согласьем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда тебе наш говор по душе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолюбятся тебе напевы наши.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы сразу эту музыку поймешь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа первой нашей дружеской беседой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мне усвоить ваш прием красивый?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн кроется в невольности порыва.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы ждем, в потребности обнять весь свет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТого, кто тем же полон…\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам в ответ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда наш дух беспечностью велик.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрекрасен только…\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНастоящий миг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖизнь только им ценна и глубока.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТому порукою?..\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоя рука.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто плохого в том, девушки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли наша владычица\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбладателю замка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОкажет доверие?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы — невольницы, пленницы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС того самого времени,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак разрушили Трою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мы стали бездомными.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтнят выбор у женщин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх не принято спрашивать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ былые поклонники\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько копят им опытность.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПастухам златокудрым ли\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли фавнам щетинистым\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтдаваться приходится\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСообразно случайности.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе тесней прижимаются,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрислонившись друг к другу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сближают колени,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ хватаются за руки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШироко перевесившись\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад подушками трона.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля царей посторонние\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСловно место пустое,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ при нас они нежатся,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак на тайном свидании.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ — далеко и близко вместе с тем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мне легко остаться тут совсем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДышу едва, забывшись как во сне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все слова претят и чужды мне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа склоне дней я как бы родилась,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ любви твоей всецело растворясь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе умствуй о любви. Какой в том толк?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖиви. Хоть миг живи. Жить — это долг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада  (быстро входя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто за ветреное племя!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВздором забивая темя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНежничать теперь не время\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ твердить любви букварь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтих грозных труб раскаты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГибелью для вас чреваты,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК замку подступает царь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойску нет конца и края,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо и ты на Менелая\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСилой дружною ударь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа участье к человеку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудешь превращен в калеку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, как раньше Деифоб.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтих вздернут по ранжиру,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА царице под секирой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУготован свежий гроб.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпять помеха! Не люблю вмешательства,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОправданного даже и опасностью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГонца-красавца портит весть недобрая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты уже и без того уродина.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа этот раз не беспокой нас попусту,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДействительной угрозы и в помине нет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА если есть, мы тоже подготовлены\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ даром не дадим себя запугивать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСигналы, залпы с башен, трубы и рожки, боевая музыка, прохождение больших военных сил.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот кто от бед тебя укроет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь что ни воин, то герой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь тот вниманья женщин стоит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто рад стоять за них горой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(К военачальникам, которые отделяются от колонн и подходят к нему.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДружиной грозной и жестокой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбимцы славы и войны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмелей вперед, сыны востока,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вы, о севера сыны!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВатага, царства низвергая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдет, закованная в сталь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод ней дрожит земля сырая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ гулом отвечает даль.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы высадились у Пилоса,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет больше Нестора в живых,\u003ca class=\"ref\" id=\"r204\" href=\"#n204\" data-tip=\"№204 \u0026#183; Илиада (Гомер); Одиссея (Гомер)\"\u003e204\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тут же у речного плеса\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарьков разбили островных.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтбросьте Менелая живо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК морскому берегу назад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть грабит бухты и проливы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИспытанный морской пират.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда он в бегство обратится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтброшенный от этих стен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаздаст спартанская царица\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам герцогства за это в лен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПускай Коринфский перешеек\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерманец валом обведет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАхею с тысячей лазеек\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозьмет в свое владенье гот.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ Элиде станут франки станом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМессену саксам отдадим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ Арголиды край — норманнам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС надзором за путем морским.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбъедините оборону,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА в старой Спарте вековой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарица будет вам исконной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ общепризнанной главой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоверивши ее заботе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрану, которой лучше нет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ ног ее всегда найдете\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУчастье, помощь и совет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст сходит с трона, князья окружают его, чтобы подробнее выслушать приказы и распоряжения.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто красивейшую пожелал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОб оружии пусть позаботится.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛестью он приобрел\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаивысшее благо земное,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо спокойно ему не дано\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСохранить обладанье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПожелает обманщик сманить\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли силой похитит разбойник,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадо в оба смотреть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостохвальный наш князь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДальновидней других.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн сумел опереться\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа союзников храбрых\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ послушных ему.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКаждый княжий приказ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИсполняют на месте\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС общей пользой для всех\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ему в прославленье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто ее отобьет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ могучего друга?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн ее заслужил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто мы признаем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ благодарность за то, что и нас\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗащитит он стеною и войском.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть разойдутся воеводы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы земли дали им кругом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА сами после их ухода\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредину области займем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы их оберегать обяжем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвой полуостров с трех сторон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС четвертой сам он горным кряжем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК горам Европы прикреплен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго луга, его дубравы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХребты, которыми он сжат,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоей владычице по праву\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРождения принадлежат.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь здесь она, своим зачатьем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся в бога Зевса и отца,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯвилась матери и братьям\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз лебединого яйца.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРодную землю, неизменно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе устающую цвести,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсей преданной тебе вселенной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВластительница, предпочти.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть сверху леденят морозы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВершины гор и перевал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНемного ниже щиплют козы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТраву по углубленьям скал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРучьи, потоки, водопады,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе сочной зелени полно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на лугу овечье стадо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКолышет белое руно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШажком расходится по кручам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРогатый осторожный скот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ норовит на солнце жгучем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабресть в пещеру или грот.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам с ними Пан в прохладном хлеве,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТуда и нимфы забрались,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОттуда тянутся деревья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз глубины ущелья ввысь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам непокорную макушку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВздымает узловатый дуб,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ клены следом друг за дружкой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолпой восходят на уступ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам молоко дает природа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля ребятишек и ягнят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ без участья пчеловода\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ колодах пчелы мед таят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь все бессмертны, словно боги,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУлыбка у людей чиста,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольство, чуждое тревоги,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаследственная их черта.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛазурью ясною согрето,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМужает здешнее дитя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНевольно спросишь: люди это\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИль олимпийцы, не шутя?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде бога с сумкою пастушьей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзобразили овчары,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоприкоснулись в простодушье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе виды жизни, все миры.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Садясь рядом с Еленой.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мы в таком же положенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто с нами было — позади.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДочь бога, Зевса порожденье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСебя в той мысли убеди!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы не останемся в твердыне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ соседстве с ней, у рубежа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАркадия еще доныне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеиссякаемо свежа.\u003ca class=\"ref\" id=\"r205\" href=\"#n205\" data-tip=\"№205 \u0026#183; Буколики (Вергилий); Аркадия (Саннадзаро) и др.\"\u003e205\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ краю безоблачности редкой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тобой укроемся вдвоем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриютом изберем беседку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ полным счастьем заживем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСцена совершенно меняется. Вдоль скалистого отвеса, изрытого пещерами, лепятся закрытые беседки. Перед ними в середине тенистая роща. Фауста и Елены не видно. Хор спит, разлегшись отдельными группами.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе ведаю, когда заснули девушки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм снилось ли, что я на деле видела?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ разбужу их. Вот они заахают!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы тоже удивитесь, бородатые,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРассевшиеся в зале, в ожидании\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазвязки этой были чудодейственной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВставайте, девушки! Оправьте волосы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлаза протрите и живее слушайте.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, рассказывай скорее, что за диво приключилось?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнаешь ведь, всего охотней слушаем мы небылицы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак нам скучно, до того нам надоело здесь средь скал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть глаза протерли, дети, и уж надоело вам?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу так знайте: здесь в пещерах, гротах этих и беседках,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл приют и кров дарован, как в идиллии любовной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподину с госпожой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам внутри?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ отъединенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОто всех. Одну меня лишь в услуженье допустили.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПользуясь их уваженьем, как обычай меж наперсниц,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не все при них сидела, а по сторонам вертелась,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСобирала мох, коренья и за сбором трав целебных\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставляла их одних.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо твоим словам, в пещере все, что хочешь, как на воле:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛес, луга, ручьи, озера. Что выдумываешь ты?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазумеется, простушки! Это девственные дебри:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗал за залом, ход за ходом открывала я, бродя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо внезапно я в пещере отзвук смеха слышу сзади,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОглянулась,\u0026#160;— мальчик скачет по родительским коленям,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС материнских рук к отцовским,\u0026#160;— шутки, ласки, прибаутки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзрывы смеха, вскрики счастья в радостном чередованье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак что могут оглушить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоленький бескрылый гений, фавн без грубости звериной,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик спрыгивает на пол, но его упругость почвы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВмиг подбрасывает кверху, с двух и трех прыжков малютка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостает до потолка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМать кричит в испуге: \u0026#171;Прыгай, как душе твоей угодно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБерегись летать, однако, запрещен тебе полет!\u0026#187;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА отец увещевает: \u0026#171;Верен будь земле, в ней сила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОттого ты вверх взлетаешь, что земли коснулся пяткой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрикоснись к ней, и окрепнешь, словно сын земли Антей\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМальчик прыгает, как мячик, кверху на утес с утеса,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ внезапно исчезает за обрывом крутизны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак что кажется погибшим. Мать рыдает, знать не хочет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПро отцовы утешенья, я плечами пожимаю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг, какое превращенье! Не сокровища ль там скрыты?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде достал он эту роскошь? В платье из цветов и тканей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг стоит пред нами он!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС плеч спускаются гирлянды, на груди повязки вьются,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗолотую лиру держит, и, как некий Феб-младенец,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсходит он на край стремнины. Застываю в изумленье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА родители в восторге обнимаются, смеясь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто над ним венцом сияет? Золотое украшенье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнутреннего ль превосходства проявившийся огонь?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо в движениях ребенка виден будущий художник,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолный с детства форм извечных и преемственных мотивов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот в точности таким-то, как в моем изображенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы увидите в восторге и услышите его.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто ли, критянка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧудо, по-твоему?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСходных сказаний\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы разве не слышала?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПесен Ионии,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГреции мифов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВстарь о богах\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСочиненных поэтами?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе, что на памяти\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНашей случается,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтзвук слабеющий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДней незапамятных.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПравда, хотя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвой рассказ очевидицы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСказка о Майе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПравдоподобнее.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудто сынок ее\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл, чуть родившись,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНянек толпой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗапеленут в свивальники.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо шалунишка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасивый и крепенький,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкинул пеленки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРучками-ножками.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак оболочку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысохшей куколки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг покидает\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРезвая бабочка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, расправляя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛегкие крылышки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ синь улетает\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС игривою смелостью.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак же и этот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлут непоседливый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС детства был другом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВорам и проказникам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ Посейдона\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрезубец взял хитростью,\u003ca class=\"ref\" id=\"r206\" href=\"#n206\" data-tip=\"№206 \u0026#183; Гимн к Гермесу; Разговоры богов (Лукиан)\"\u003e206\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеч утащить\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ Ареса осмелился,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛук снял у Феба,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЩипцы сгреб Гефестовы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолнии Зевса\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтащил бы наверное,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли б обжечься\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе побоялся\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ единоборстве\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодножку дал Эросу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛастясь к Венере,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтянул ее пояс.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз пещеры доносится мелодичная струнная музыка, к которой все прислушиваются, продолжающаяся с данной минуты вплоть до паузы, отмеченной ниже.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВаших россказней прекрасней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭта струнная игра.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО богах забудьте басни,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМиновала их пора.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас не понимает время,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНовых требуя красот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаше сердце только с теми,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто от сердца речь ведет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Отходит к скале.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли и в таком отродье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМузыка еще властна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак же нас ее мелодий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокоряет глубина?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯрче солнца и денницы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСветоноснее зари\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМиг, когда рассвет родится\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ сердце нашем изнутри.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена, Фауст и Эвфорион \u0026#160;в вышеописанном наряде.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас мои прыжки и пенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо-родительски бодрят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаставляя в восхищенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВаше сердце прыгать в лад.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвух сливая воедино,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДлит любовь блаженства миг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо конечная вершина\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдинение троих.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тогда-то мы у цели:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВесь я твой и ты моя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК этому и тяготели\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПобужденья бытия.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнаки правды долголетней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавней радости черты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ наследника заметней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем в лице самой четы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХочу подпрыгнуть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб ненароком\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНебес достигнуть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдним наскоком!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот что желанье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМое и страсть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо ввысь не надо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез меры влечься!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри не падай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе изувечься!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы все погибнем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлучись напасть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТомлюсь от скуки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ вас в объятье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставьте руки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКудрей не гладьте,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставьте платье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе тешьтесь мной!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодумай, милый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧье ты спасенье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам смертью б было\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазъединение.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкреплен насилу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаш мир тройной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвы, порвется\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСогласный строй.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена и Фауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСдерживай, сглаживай\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБуйную силу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли нас заживо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВгонишь в могилу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧерпай свободу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь на лугу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам лишь в угоду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе убегу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Пробираясь среда хора и увлекая всех к танцу.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот в хороводе я,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас подхватив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВьюсь под мелодии\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБойкий мотив.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак интереснее.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвигайтесь с песнею\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМерно кругом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, благодарствую!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВряд ли, фиглярствуя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКончат добром.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион и хор, распевая и танцуя, движутся переплетающимися рядами.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда, кудрявою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТряхнув головкой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРукою правою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас крутишь ловко,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда с улыбкою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеотразимой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФигуркой гибкою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкользишь ты мимо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГордись удачею:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнай, дорогой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСердца горячие\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолны тобой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПауза.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак диким ланям,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам нет тут счета.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавайте станем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИграть в охоту.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы будьте дичью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ — зверолов.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНетрудной станет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоя работа.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ так нас тянет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ твои тенета.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоя добыча\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы все без слов.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧрез лес и камни!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе цель сладка мне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА лишь преграды\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВлекут к себе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПобеду надо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКупить в борьбе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена и Фауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМечется как бесноватый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ голове лишь беззаконья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ как бы рогов раскаты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлышатся в лесной погоне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто за ярость! Что за пыл!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор  (быстро входя поодиночке)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПробежал по кругу мимо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСделав бешеный прыжок,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБросился неудержимо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК самой дикой и увлек.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион  (внося на руках молодую девушку)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе уловкою умильной,\u0026#160;—\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ ее влеку насильно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы радости хлебнуть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрепко стискиваю грудь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ целую в упоенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПобедив сопротивленье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДевушка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтой, не тронь! Не так мы хилы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ женском существе своем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротив неугодной силы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСилу мы в себе найдем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДумаешь, что так слаба я?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДумай, думай — на бегу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ схвачу тебя, играя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тебя, смеясь, сожгу!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Воспламеняется и, взвившись ввысь, сгорает в воздухе.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ склепе под землей преследуй\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУскользнувшую победу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ небе опиши дугу!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион  (отряхивая остатки пламени)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, все овражистей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлушь чернолесья!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСбросить бы тяжести,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзмыть к поднебесью!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВетер, неистово\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуй и насвистывай!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБейся, морской\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДальний прибой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Прыгая со скалы на скалу, подымается все выше.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена, Фауст и хор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрыгая подобно сернам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе сорвись в прыжке неверном!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыше всё душою жадной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде пространства неоглядны!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот я вижу, где стою:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в Пелопсовом краю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолуостров этот мой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоздан морем и землей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет разве радости\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ рощах прохладных,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрызжущих сладостью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛоз виноградных?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗелень долинная\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯблок полна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯгоды винные,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМир, тишина!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМир вам мерещится?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБой до конца\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнаменем плещется\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ жизни борца!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот, кто воинственным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПылом отравлен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМиром, единственным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСчастьем, оставлен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде за отечество\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз рода в род\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦвет человечества\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКровь отдает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМожно заранее\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлаву предречь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ смелом дерзании\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВынувшим меч.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосмотрите вверх, подруги!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн стоит на крутизне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРослым воином в кольчуге,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПобедителем в броне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет нужды в форта\u0026amp;#769;х мужчине,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТын его — его рука.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрепче каменной твердыни\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрудь стальная смельчака.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНезависимость берется\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС бою, в поле, налегке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАмазонкою дерется\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМать с героем на руке.\u003ca class=\"ref\" id=\"r207\" href=\"#n207\" data-tip=\"№207 \u0026#183; Илиада (Гомер); Мифологическая библиотека (Аполлодор)\"\u003e207\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзвейся, поэзия,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВверх за созвездия!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзмыв к наивысшему,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВспыхнув во мгле,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы еще слышима\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь на земле!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в мир пришел не малым чадом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ зрелым юношей примкну\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК другим передовым отрядам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУшедшим раньше на войну.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы во всем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПризнаем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБоевую честь одну.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена и Фауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНародившись к жизни еле,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвет увидевши едва,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРвешься ты к смертельной цели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде слетает голова.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазве к нам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы и сам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе питаешь чувств родства?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрислушайтесь к раскатам грома!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГудит земли любая пядь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБорцы, не усидевши дома,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдут страдать и умирать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмерть — завет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтих лет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛучших нет, пора понять.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена, Фауст и хор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмерть от ран, тоска агоний,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто нашел ты, милый, в них?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ не зритель посторонний,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА участник битв земных.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрежние\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУчасть смертельная\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтот задор!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭвфорион\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ширь беспредельную\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрылья простер!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмелый бросается\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ битвы разгар!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБросается в воздух. Одежды временно поддерживают его. Голова его сияет. За ним тянется светящийся след в воздухе.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто кончается\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНовый Икар.\u003ca class=\"ref\" id=\"r208\" href=\"#n208\" data-tip=\"№208 \u0026#183; Метаморфозы (Овидий)\"\u003e208\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрекрасный юноша падает к ногам родителей. Лицо умершего напоминает другой знакомый образ. Все телесное вскоре исчезает. Ореол в виде кометы возносится к небу, на земле остаются лира, туника и плащ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена и Фауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКончилось вмиг торжество!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТягостна страшная явь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГолос Эвфориона  (из-под земли)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМать, меня одного\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ царстве теней не оставь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПауза.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор  (похоронное пение)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы не сгинешь одиноким,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудучи в лице другом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо чертам своим высоким\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвету целому знаком.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖребий твой от всех отличен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоревать причины нет:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы был горд и необычен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ дни падений и побед.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСчастья отпрыск настоящий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнаменитых дедов внук,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВспышкой в миг неподходящий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы из жизни вырван вдруг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл ты зорок, ненасытен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖенщин покорял сердца,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ безмерно самобытен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл твой редкий дар певца.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы стремился неуклонно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрочь от света улететь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, поправ его законы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСам себе расставил сеть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлавной целью ты осмыслил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод конец слепой свой пыл,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСил, однако, не расчислил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодвига не завершил.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто тот подвиг увенчает?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРок ответа не дает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько кровью истекает\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПут не сбросивший народ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНовой песнью кончим тризну,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб не удлинять тоски.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеснями жива отчизна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИспытаньям вопреки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолная пауза. Музыка прекращается.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕлена  (Фаусту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа мне сбывается реченье старое,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто счастье с красотой не уживается.\u003ca class=\"ref\" id=\"r210\" href=\"#n210\" data-tip=\"№210 \u0026#183; Героиды (Овидий); Сатиры (Ювенал)\"\u003e210\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвы, любви и жизни связь разорвана.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОплакивая их, с тобой прощаюсь я,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ последний раз к тебе в объятья падая.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрими меня, о Персефона, с мальчиком!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Обнимает Фауста. Телесное исчезает, платье и покрывало остаются у Фауста в руках.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада  (Фаусту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДержи покрепче, что тебе оставлено.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе выронь платья. Демоны подземные\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж за него со всех сторон хватаются,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб унести к себе. Держи, не вырони.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть платье не богиня, та — потеряна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако ткань в твоих руках — божественна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоспользуйся неоценимой милостью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ улети. Она над миром низменным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеренесет тебя, пока удержишься.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрощай. Вдали, в великой отдаленности\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт этих мест, с тобою мы увидимся.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдежды Елены превращаются в облака, окутывают Фауста, подымают его ввысь и уплывают с ним.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада  (подбирает с земли платье, лиру и плащ Эвфориона, подходит к просцениуму, подымает вещи, оставшиеся после умершего, кверху и говорит)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПущу находку эту в дело.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть пламя, правда, догорело,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМир и останкам будет рад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ буду гения наряд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавать поэтам напрокат,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкрывающим одеждой старой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтсутствие живого дара.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Садится на просцениуме у колонны.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПанталида\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, девушки, скорее! От заклятия\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКолдуньи фессалийской мы избавились.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтряхнули иго ведьмы ненавистное\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ гнет бренчанья, звуков наваждение,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧужое нам и разуму противное.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ Аид толпою следом за царицею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИдущей впереди, под землю спустимся.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак подобает нам, служанкам преданным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ трона Непостижной мы найдем ее.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ цариц свое общество,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРады все их присутствию,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС Персефоной, как равные,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод землей они встретятся.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто же делать нам, челяди,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь лугов асфоделевых,\u003ca class=\"ref\" id=\"r211\" href=\"#n211\" data-tip=\"№211 \u0026#183; Одиссея (Гомер)\"\u003e211\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа задворках, обсаженных\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТополями и ветлами?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИль мышами летучими\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрепетать и попискивать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРади нетопыриного\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПровождения времени?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПанталида\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПринадлежит к стихиям тот, кто имени\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе приобрел и не стремился к высшему.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмешайтесь с ними. Я хочу с царицей быть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ верность наша, а не только подвиги\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриобретает нам значенье личности.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвету солнца мы отданы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе отдельными лицами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА все вместе, всем множеством,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в Аид не вернемся мы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мы знаем и чувствуем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо природа бессмертная\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбо всем позаботится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы, сонм духов ее,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа нее полагаемся.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧасть хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрячась и перебегая в шелестенье тысяч веток,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз корней манить мы будем вверх к побегам соки жизни,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо цветов пучки, то листья в волосы себе вплетая.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУпадут плоды, созревши, и толпою будут люди\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШарить по земле, сбирать их и откусывать на пробу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа колени перед нами, как перед богами, став.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДругая часть хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы к поверхности отвесной этих гладких скал прижмемся,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб подслушивать все звуки, будь то шорох камыша,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПтичий свист иль голос Пана. Тотчас мы ответим тем же,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа жужжание — жужжаньем, громыханием — на гром,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУдвояя отголоски и катя в ответ раскаты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОглушительнее трижды, следом десять раз подряд.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТретья часть хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСестры! Мы других подвижней, пустимся ручьям вдогонку.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас к себе потянут далей низбегающие склоны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо отлогостям, все глубже, потечем мы, орошая\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоле, пастбище, усадьбу и вкруг дома тихий сад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКипарисы обозначат линию речного русла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодымаясь в отдаленье стройно к небу в два ряда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧетвертая часть хора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы живите, где хотите. Мы шумливо холм обступим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде в шпалерах зеленеет виноградная лоза.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦелый день там виноградарь, неуверенный в успехе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоказательство усердья беспримерного дает.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн окапывает лозы то лопатой, то мотыгой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодрезает их и вяжет по тычинам и жердям.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн к богам и богу солнца обращается с молитвой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо о нем, слуге радивом, мало помышляет Вакх.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтот бог в беседке дремлет иль болтает с фавном в гроте,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаделенный всем в избытке, нужном для сонливых грез.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ бурдюках вино, в кувшинах, из даров и приношений,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо углам пещер хранится с незапамятных времен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо когда помогут боги, первый Гелиос средь прочих,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ наполнят рог гроздями, солнцем их позолотив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОживает сад, который обработал виноградарь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ кустов, где тишь царила, целодневный шум стоит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкрип корзин, бряцанье ведер, переноска винограда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ чан давильщикам, веселым босоногим плясунам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСеменя ногами, люди топчут, давят кучи гроздьев;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрызжет, пенится под ними дивный виноградный сок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тогда гремят тимпаны, ибо, сняв покровы таинств,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткрывается народу в шуме празднеств Дионис.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСледом толпы козлоногих и Силена зверь ушастый,\u003ca class=\"ref\" id=\"r212\" href=\"#n212\" data-tip=\"№212 \u0026#183; Вакханки (Еврипид); Метаморфозы (Овидий) и др.\"\u003e212\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПопирается стыдливость, попирается закон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ этом головокруженье глохнут уши, ум мутится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПьяный тянется за чашей, переполнены кишки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНекоторые крепятся, но пред наполненьем снова\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадо от остатков старых выпорожнить бурдюки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗанавес падает.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФоркиада на просцениуме исполински выпрямляется, сходит с котурнов, снимает маску и покрывало и оказывается Мефистофелем, готовым, в случае надобности, объяснить пьесу в эпилоге.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2 class=\"part\"\u003eАкт четвертый\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r216\" href=\"#n216\" data-tip=\"№216 \u0026#183; Послание к Ефесянам\"\u003e216\u003c/a\u003eГорная местность\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысокий скалистый гребень. Подплывает облако, оседает на плоском выступе горы, из облака выходит Фауст.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ ног моих лежат холмы и пропасти.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа край горы схожу с предосторожностью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз облака, которое в дни ясные\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесло меня над морем и над сушею.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОно, не расплываясь, отрывается\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на восток уходит белой глыбою.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа ним я наблюдаю с удивлением.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОно клубится, делится, меняется,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе больше упрощая очертания.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне глаз не лжет. На пышном изголовии\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОблитых солнцем снежных гор покоится\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФигура женщины красы божественной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЮнона ль это, Леда ли, Елена ли?\u003ca class=\"ref\" id=\"r213\" href=\"#n213\" data-tip=\"№213 \u0026#183; Илиада (Гомер); Мифологическая библиотека (Аполлодор) и др.\"\u003e213\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак царственно рисуется видение!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вот и нет его. Теснясь, вздымается\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОно нагроможденьем туч, подобное\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДалеким ледникам, в которых светится\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВеликий отблеск дней давно исчезнувших.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо грудь и лоб своим прикосновением\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне освежает полоса туманная.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна спешит принять черты какие-то.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе обманулся я. О, благо высшее\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбви начальных дней, утрата давняя!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ узнаю тебя, души сокровище,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзор, встреченный зарею жизни утренней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПорывисто отвеченный, непонятый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзор девушки, которая затмила бы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсех, если бы я удержал ее.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе разрушаясь, как краса душевная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУходит очертанье, унося с собой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсю чистоту мою, всю сущность лучшую.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа гору становится семимильный сапог, за ним — другой.\u003ca class=\"ref\" id=\"r214\" href=\"#n214\" data-tip=\"№214 \u0026#183; Мальчик-с-пальчик (Перро); Детские и семейные сказки (братья Гримм) и др.\"\u003e214\u003c/a\u003e С них сходит Мефистофель, и сапоги спешно отправляются дальше.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСовсем измучен маршировкой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажи, зачем у этих скал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРешил ты сделать остановку?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь эту местность я узнал:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрутая эта высь сначала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДно преисподней представляла.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе можешь ты без вечных штук.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВздор, небылицы, что ни звук.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (серьезно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо слушай же. Когда за грех один\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподь низверг нас в глубину глубин,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы центр земли в паденье пересекли\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ очутились в вековечном пекле,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде полыхал огонь среди теснин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПризнаться, несмотря на освещенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы оказались в трудном положенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаскашлялись тут черти целым адом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТяжелый дух пуская ртом и задом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт вони ад раздулся. Серный газ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавил на стенки каменистых масс.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРосло давленье. От его прироста\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотрескалась кругом земли короста.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзрыв тотчас вызвал общий перелом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ стало верхом то, что было дном.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГеологи, наш опыт разработав,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВвели теорию переворотов.\u003ca class=\"ref\" id=\"r215\" href=\"#n215\" data-tip=\"№215 \u0026#183; Книга пророка Исаии; Откровение Иоанна Богослова и др.\"\u003e215\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ правда, свергнув бездны жаркий гнет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь мы дышим воздухом высот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь откровенье с трудностию крайней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюдей подготовляет к этой тайне.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Ефес. 6, 12)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГора крута, а как и почему,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПретит копаться духу моему.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда природа всю себя сложила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо шар земной круженьем обточила.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВершины гор — естественный нарост\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВокруг ложбин, ущелий и борозд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПонятно, что крутых хребтов отроги\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК долинам рек становятся отлоги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСуществованье гор, лугов, лесов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбходится без глупых катастроф.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы полагаешь? Но иного мненья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто был свидетелем их появленья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ был при том, когда еще на дне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПылал огонь и гул катился громкий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолох ковал утесы на огне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сыпал стопудовые обломки.\u003ca class=\"ref\" id=\"r217\" href=\"#n217\" data-tip=\"№217 \u0026#183; Мессиада (Клопшток); Книга Левит и др.\"\u003e217\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайдя в полях гигантскую плиту,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмолкает ум философа неловкий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГигантский камень брошен на лету\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо времена горячей этой ковки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн говорит при виде этих стен:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Ничем необъяснимый феномен\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростонародье более пытливо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОно не остается в стороне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, наблюдая странные массивы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриписывает чудо сатане.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа \u0026#171;чертов мост\u0026#187;\u003ca class=\"ref\" id=\"r218\" href=\"#n218\" data-tip=\"№218 \u0026#183; Легенда о Чёртовом мосте; Немецкие саги (братья Гримм)\"\u003e218\u003c/a\u003e глядит в пути скиталец\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли в песке находит \u0026#171;чертов палец\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакие любопытные подходы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ вас, чертей, во взглядах на природу!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто мне природа? Чем она ни будь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо черт ее соавтор, вот в чем суть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы с жилкой творческой, мы род могучий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезумцы, бунтари. Взгляни на кручи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся ширь земная — дело наших рук.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь ты облетел ее вокруг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ какой-нибудь из точек перелета\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпуститься ты не ощутил охоты?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы видел как-никак с высот своих\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Все царства мира и всю славу их\u0026#187;.\u003ca class=\"ref\" id=\"r219\" href=\"#n219\" data-tip=\"№219 \u0026#183; Евангелие от Матфея\"\u003e219\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Матф. 4, 8)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо ты брюзглив, и кругозор привольный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе властен над душою недовольной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все ж я полон мыслей о большом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСам угадай, о чем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавай дерзнем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб прогреметь, на месте бы твоем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ старый город выбрал бы столицей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде в тесном центре бы лежал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаринный деловой квартал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ рынок, крытый черепицей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо скопищем жужжащих мух\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад тухлым мясом на прилавке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кучей овощей вокруг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь вони, духоты и давки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам в спертом воздухе, средь дел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНарод весь день кишмя б кишел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля знати дальше б шли районы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШироких улиц, площадей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА дальше бы, среди полей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаскинулся б еще вольней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростор предместий отдаленный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам в сотнях мчащихся карет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрогуливался б высший свет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ радостно бы наблюдал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак, весь уйдя в свой муравейник,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХлопочет человек-затейник.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б гулять я выезжал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь сотен тысяч, днем и ночью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ составлял бы средоточье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ всех вниманье привлекал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу это был бы труд напрасный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПравитель добрый недоспит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб был народ одет и сыт,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лишь бунтовщиков плодит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа голову свою, несчастный.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак замок я б себе воздвиг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ веселом живописном месте\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ превратил бы в парк, в цветник\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвое обширное поместье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДеревья в прихотливой стрижке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛужайки, просеки аллей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПитали бы воды излишки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРучьев, каскадов и ключей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВезде бы разрослись газоны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА в чаще, замыкая круг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ выстроил бы павильоны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля обольстительных подруг.\u003ca class=\"ref\" id=\"r220\" href=\"#n220\" data-tip=\"№220 \u0026#183; Версаль и Марли; Мемуары Сен-Симона\"\u003e220\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б с ними проводил в именье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвои часы уединенья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Подруг\u0026#187; я с умыслом сказал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА не для округленья слога:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасавицы — мой идеал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ том случае, когда их много.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДань времени! Сарданапал!\u003ca class=\"ref\" id=\"r221\" href=\"#n221\" data-tip=\"№221 \u0026#183; Историческая библиотека (Диодор); Эпитома (Юстин) и др.\"\u003e221\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе разгадав твоих мечтаний,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ все ж предположить дерзну,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто захотел ты на луну\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ своем заоблачном скитанье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО нет! Широкий мир земной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще достаточен для дела.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще ты поразишься мной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ выдумкой моею смелой!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы сделался славолюбив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ древних героинь побыв?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе в славе суть. Мои желанья —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВласть, собственность, преобладанье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМое стремленье — дело, труд.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы можешь не нуждаться в шуме,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебя поэты вознесут,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб пламенем твоих причуд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоспламенять других безумье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, человека ты никак\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИстолковать не в состоянье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто для тебя его желанья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДешевый, плоский, злой остряк?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть так. Я не обижен бранью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ж привлекло твое вниманье?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой взор был сверху привлечен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткрытым морем в час прилива,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда весь берег до обрыва\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗатоплен им со всех сторон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня все это укололо.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦарю природы, мне была\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбидна дерзость произвола:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвободный дух не терпит зла.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще и то меня кольнуло,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто после краткого разгула\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВода, уставши прибывать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо слепотой такой же ярой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОчистила за пядью пядь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы в свой час прийти опять\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля повторенья шутки старой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (к зрителям)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу и открытье откопал!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСто тысяч лет я это знал.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (страстно продолжая)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМорское это полноводье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодкрадываясь на часы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриносит на века бесплодье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемле прибрежной полосы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНедолговечно волн злорадство,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПуста достигнутая цель,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ море очищает мель,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпустошив земли богатства.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазбушевавшуюся бездну\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б властно обуздать хотел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ трате силы бесполезной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСумел бы положить предел.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тут вопрос простейший самый:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак ни свиреп воды напор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна, смиривши нрав упрямый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолжна затечь в любую яму\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ обогнуть любой бугор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я решил: построив гать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалы насыпав и плотины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбой ценою у пучины\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКусок земли отвоевать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот чем я занят. Помоги\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне сделать первые шаги.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа спиной зрителей с правой стороны раздаются отдаленные звуки барабанов и военной музыки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзволь. Ты слышишь, в барабаны бьют?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпять война? Мудрец не любит смут.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойною не тебе трудить плечо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВопросов посторонних с ней не путай.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ если случай есть, лови минуту,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖелезо куй, покуда горячо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе понял ничего. Какой тут случай?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажи ясней, загадками не мучай.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ пути сюда мне сообщали,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто император наш в печали.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго ты помнишь? Это тот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторого мы развлекали\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДождем обманчивых щедрот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри помощи своих банкнот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн молодым взошел на трон\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тут был нами ослеплен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКупить надеясь полвселенной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосредством нашего подмена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоверил постепенно он,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто до скончания времен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕму и море по колено,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто царствованья образцом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакое будет почитаться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда две цели совместятся\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ будет он в лице одном\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ царствовать и наслаждаться.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОшибка многих! Властелин\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольствоваться должен властью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПускай владеет он один\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсей тайною людского счастья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕму приказ лишь стоит дать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в удивленье мир приходит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА наслаждаться, прозябать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа низшую ступень низводит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА этот, правда, пожил всласть!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ при начавшемся развале\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесостоятельную власть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ стране сменило безначалье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсех стала разделять вражда.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа братьев ополчились братья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ города на города.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРемесленники бились с знатью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с мужиками господа.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШли на мирян войной попы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ каждый встречный-поперечный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГубил другого из толпы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС жестокостью бесчеловечной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо делу уезжал купец —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ находил в пути конец.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостигло крайнего размаха\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУкоренившееся зло.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе потеряли чувство страха.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖил тот, кто дрался. Так и шло.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eШло, падало, плелось, тащилось,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока совсем не развалилось.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНикто в том не был виноват.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсем значить что-нибудь хотелось.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыгадывал второй разряд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА первым это лишь терпелось.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако этот ералаш\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе по душе стал лучшим людям.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни задумали: \u0026#171;Добудем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПорядок. Император наш\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам не оплот в борьбе суровой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавайте выберем другого,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторый властною рукой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам будет обновленья знаком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб сочетать счастливым браком\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ справедливость и покой\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯзык поповский.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуховенство,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБунт освятив исподтишка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзяло над мятежом главенство\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля пользы своего брюшка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь в войне междоусобной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойскам повстанцев за горой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДаст император наш беззлобный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаверно, свой последний бой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне жаль его. Он был так прям.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПойдем, примкнем к его войскам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто жив, не говори: \u0026#171;Пропало!\u0026#187;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасенный раз — навек спасен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДостаточно победы малой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак вновь под сень его знамен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеребегут его вассалы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни спускаются до середины горы и осматривают расположение войска в долине. Снизу слышится барабанный бой и военная музыка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПозиция его крепка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы победим наверняка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо как, каким путем? Поведай!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосредством лжи, обмана, бреда?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосредством тонких стратагем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты, в расчете на победу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГни линию свою меж тем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда мы, выиграв сраженье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕму упрочим положенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖди милостей и перемен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред троном преклони колена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ государь в вознагражденье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе даст берег моря в лен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы вызвал эти мятежи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы и победу одержи.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, ты, восставших одолев,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь будешь генерал-аншеф.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрекрасный — льщу себя надеждой —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ делах, где я кругом невежда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИных фельдмаршалов-растяп\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасает генеральный штаб.\u003ca class=\"ref\" id=\"r222\" href=\"#n222\" data-tip=\"№222 \u0026#183; Кампания во Франции 1792 года (Гёте)\"\u003e222\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХод дел предвидя современный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСоставил я совет военный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз горцев, боевых ребят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни любого победят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам под оружьем чуть не племя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУжель ты заручился всеми?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет. Я, как Петер Сквенц, в отряд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз массы выбрал концентрат.\u003ca class=\"ref\" id=\"r223\" href=\"#n223\" data-tip=\"№223 \u0026#183; Сон в летнюю ночь (Шекспир); Господин Петер Сквенц (Грифиус)\"\u003e223\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходят трое сильных.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Кн. царств, II, 23, 8)\u003ca class=\"ref\" id=\"r224\" href=\"#n224\" data-tip=\"№224 \u0026#183; Вторая книга Царств\"\u003e224\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу вот мои бойцы-задиры,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрех разных возрастов народ,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа них различные мундиры,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто с ними, тот не пропадет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(К зрителям.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМечтает малое дитя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь о рыцарском уборе.\u003ca class=\"ref\" id=\"r225\" href=\"#n225\" data-tip=\"№225 \u0026#183; Волшебное кольцо (де ла Мотт-Фуке); Рыцарские романы Вальтера Скотта и Людвига Тика\"\u003e225\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе лучше ль этот сброд, хотя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредставлен в форме аллегорий?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРауфебольд  (молодой, легко вооруженный, в пестром наряде)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКого ни встречу — в ухо дам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ съезжу кулаком по рылу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА беглеца обратно сам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоставлю за волосы силой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГабебальд  (средних лет, хорошо вооруженный, богато одетый)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДрачливость — это вздор ребячий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе стоящий моей руки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ граблю, чтобы стать богаче.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе остальное — пустяки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГальтефест  (пожилой, тяжело вооруженный, без лишней одежды)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаграбить денежки не штука,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТруднее их скопить для внука\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не потратить пятака.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто молод, тратит без расчета,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА уберечь добро от мота,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот в чем задача старика.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпускаются втроем глубже в долину.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eНа переднем горном отроге\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСнизу слышатся барабаны и военная музыка. Раскидывают императорский шатер.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор, главнокомандующий, телохранители.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлавнокомандующий\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне кажется по-прежнему разумным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто мы укрыли армию свою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ овраге незаметном и бесшумном.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаш выбор оправдается в бою.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосмотрим. Мне, признаться, неприятно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодобье бегства, наш отход попятный.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлавнокомандующий\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа правый фланг наш, государь, взгляни,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ убедишься ты, что все в порядке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтратег мечтает о такой площадке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКлюч местности мы заняли одни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХолмы волнисты, нас прикрыли склоны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВраг не пойдет на нас атакой конной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе спорю. Место славное для сеч,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде разгуляются рука и меч.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлавнокомандующий\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь, в середине луга, на плато\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойска не хуже, чем на правом фланге.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа солнце пики блещут, и ничто\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе остановит натиска фаланги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак зыблется могучее каре!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе терпится схватиться молодчинам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротивник укрепился на горе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ их пошлю туда врубиться клином.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоволен видом воинов твоих.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь будет каждый биться за двоих.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлавнокомандующий\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа левом фланге батальон рубак\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесет охрану с тою же отвагой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ прикрывает подступы к оврагу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне почему-то кажется, что враг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРванется в это именно преддверье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ понесет кровавые потери.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот, вот она, двуличная родня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторая презренных выгод ради\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПритворно-ласково звала меня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто братом, кто племянником, кто дядей!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни мне рознью расшатали трон\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ довели страну до безначалья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрай ненасытностью их разорен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на меня они еще восстали!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолпа слепа, и ловок демагог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНарод пошел, куда понес поток.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлавнокомандующий\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вижу, вниз с обрывистого ската\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпешит с разведки верный соглядатай.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервый разведчик\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы успешно, храбро, метко\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСделали свои дела,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, однако, нам разведка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМало радости дала.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть широким населеньем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы по-прежнему любим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрах пред нынешним правленьем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе дает сплотиться им.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе врозь, всяк о себе самом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолг, честь и верность отрицая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вспыхнет у соседа дом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе скажешь: \u0026#171;Наша хата с краю\u0026#187;.\u003ca class=\"ref\" id=\"r226\" href=\"#n226\" data-tip=\"№226 \u0026#183; Послания (Гораций)\"\u003e226\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлавнокомандующий\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторой лазутчик огибает склон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн телом всем дрожит и утомлен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторой разведчик\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас утешил несказанно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезголовый их разброд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо властитель самозванный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдруг скомандовал — вперед.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ народ потек всем станом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтадной спайкою горя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСловно овцы за бараном,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод знамена лжецаря.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх император помогает мне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтать вашим императором впервые.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростым солдатом вышел я в броне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вспомнил цели высшие, иные.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда весь свет съезжался к нам на бал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпасности недоставало в мире.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРапирою я обруч протыкал,\u003ca class=\"ref\" id=\"r227\" href=\"#n227\" data-tip=\"№227 \u0026#183; Турнирная книга (Рюкснер)\"\u003e227\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА чувствовал себя, как на турнире.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда б от войн меня не отвращали,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, б славой был теперь уже покрыт.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда вскричали вы: \u0026#171;Горит, горит!\u0026#187; —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы помните, на маскараде, в зале, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак вдруг заликовало все во мне!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрозило пламя мне, я был в огне!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, вы-то знали, что огонь — потешный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО подвиге тогда я стал мечтать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто в эти годы упустил я, грешный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь я постараюсь наверстать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Отправляет герольдов с вызовом на единоборство императору недовольных.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит Фауст, в латах, с полуопущенным забралом. За ним следуют трое сильных в вышеописанном наряде и вооружении.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы прибыли, надеюсь, в добрый час.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда спасала осторожность нас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы знаешь, горцам тайна гор открыта.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК природе близки эти племена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни прочли давно в кусках гранита\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе рунические письмена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тех пор как духи с низменных лугов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереселились в горные пещеры,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни в них трудятся средь атмосферы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНасыщенных металлами паров,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГотовят смеси, превращают в газ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСорта руды, с единственною целью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайти состав, невиданный доселе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа новое наткнуться в первый раз.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри помощи подвластных им начал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСовершены великие открытья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни провидят, глядя сквозь кристалл,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемли неотвратимые событья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлыхал и верю, впрочем усомнясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмеет ли все это с нами связь?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНурсийский некромант, Сабинский маг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе шлет преданности изъявленья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт смерти отделял его лишь шаг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрещал костер, огонь лизал поленья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн задыхался, в дыму исчез.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто б мог спасти его на этой грани?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНикто: ни человек, ни бог, ни бес,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн был спасен твоей монаршей дланью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл в Риме ужас этот им изведан.\u003ca class=\"ref\" id=\"r228\" href=\"#n228\" data-tip=\"№228 \u0026#183; Жизнь Бенвенуто Челлини; Легенда о Тангейзере\"\u003e228\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тех пор тебе он беззаветно предан.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн все забыл, узнав про твой поход,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, полный только о тебе забот,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоспешно нас послал тебе в подмогу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриродных сил в горах безмерно много,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лишь попов тупое существо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ исследованье видит колдовство.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда во дни удач к нам люди вхожи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак рады мы толпящимся гостям!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНасколько же нам должен быть дороже,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто в бедствии спешит на помощь к нам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто собственною волею, без зова,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСжимая крепко шпаги рукоять,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ невыясненный час судьбы суровой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа нас берется грудью постоять!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВложите меч назад в ножны, однако,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВеличье дела общего ценя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь тысячами бросятся в атаку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБорясь против меня и за меня.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо тут бессилен первый вставший воин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпор лично мною должен быть решен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто у меня оспаривает трон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПускай докажет, что его достоин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо лжецарем, приснившимся в бреду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКнязьям моим, сойдусь я в поединке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС успехом в царство мертвых низведу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ совершу по призраку поминки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХвала твоим намереньям. Меж тем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам целость головы твоей потребней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри, для безопасности твой шлем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСнабжен султаном и дугою гребня.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕдва лишь сон коснется головы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтяжелеют и другие члены.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот так и мы. Мы живы и мертвы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоей особой неприкосновенной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаз голова цела, то и рука\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЩитом подъятым череп защищает\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли удар враждебного клинка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСама клинком удачно отражает.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУчаствует в победе и нога,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтав на затылок павшего врага.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы тоже силы к этому приложим:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб стал его затылок нам подножьем.\u003ca class=\"ref\" id=\"r229\" href=\"#n229\" data-tip=\"№229 \u0026#183; Псалтирь; Книга Иисуса Навина\"\u003e229\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГерольды  (вернувшись)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМало чести, невниманье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы нашли во вражьем стане.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагородный вызов твой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысмеяли всей толпой:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Император ваш забыт\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ погублен без возврата.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак и сказка говорит:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Жил-был царь один когда-то\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДела сложились так и обстоят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак все твои приверженцы хотят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВраг близится, нас охватило рвенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУдобен миг, скомандуй наступленье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКомандованье князю я сдаю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Главнокомандующему.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзволь вступить в обязанность свою.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлавнокомандующий\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть выстроится правое крыло.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротивник из долины вышел левым.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзбираться на гору им тяжело,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы сбросим их с пригорка, овладев им.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда позволь, чтоб этот вот герой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСражался у тебя на фланге правом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе зная удержу, он рвется в бой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ увлечет других примером бравым.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Указывает на стоящего справа.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРауфебольд  (выступая вперед)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто мне лицо подставит, шутнику\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДам по скулам и в зубы что есть силы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто тыл покажет, тем сверну башку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб морду всю назад перекосило.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПопробуй-ка меня останови\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС моею палицею беспощадной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротивника утопим мы в крови,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб к нам соваться не было повадно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлавнокомандующий\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФаланга центра пусть готовит схватку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриблизившись к противнику украдкой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотрите, наше правое крыло\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмятенье в их рядах произвело.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (указывая на стоящего в середине)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПошлемте в центр, где битва горяча,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот этого проныру-ловкача.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГабебальд  (выступая вперед)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ блеск победы увеличу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа захвачу притом добычу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все верну, что этот вор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтащил, награбив, в свой шатер.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНедолго царствовать поганцу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз центра выбьем самозванца.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАйлебойта, маркитантка  (прижимаясь к Габебальду)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть он мне не законный муж,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо друг и компаньон к тому ж.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ походе только не зевай —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ снимешь знатный урожай.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА баба хваткою берет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи в чем запрета нет. Вперед!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОба уходят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлавнокомандующий\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто враг нажим свой весь сосредоточит\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа левом фланге, знал, я наперед.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн не жалеет жертв и, видно, хочет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗанять ущелья узкого проход.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (кивая налево)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот помощь им. На этого взгляни лишь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ силу новой силою усилишь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГальтефест\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть левый фланг вас больше не заботит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде я, туда не сунуться врагу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ молния с дороги той своротит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторую один я стерегу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (спускаясь сверху)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь смотрите, как в тылу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз всех теснин, по узким тропам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа помощь левому крылу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСолдаты в шлемах рвутся скопом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь гор устроивши затор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз лат, мечей, щитов и шпор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе ждут команды властелина,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб хлынуть на врагов лавиной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Вполголоса, понимающим, в чем суть.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоискиваться б не просил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОткуда подкрепленье взято:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ оружейные палаты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля этого опустошил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВооружения модели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ былом — князья и короли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтояли и верхом сидели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак встарь, владыками земли.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоспехов целый арсенал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в залах с постаментов снял.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорлупки высохших улиток\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапяливши на чертенят,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредневековья пережиток\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь я вывел на парад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКольчуги, копья, самопалы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроизведут эффект немалый.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Громко.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак гулко оглашают даль\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвон лат, бряцающая сталь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнамена веют с видом бранным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа свежем ветре долгожданном.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНарод охватывает жар\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВмешаться в бой под гром фанфар.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрашный трубный раскат сверху. Неприятельское войско дрогнуло.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВесь горизонт покрылся мраком.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь там и сям предвестья знаком\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа небе рдеет полоса.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОружие от крови ало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ бой втянуты леса и скалы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в битву рвутся небеса.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа правом фланге бьется стойко,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазвертываясь во всю ширь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГанс Рауфебольд, верзила бойкий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОрудуя, как богатырь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ разгаре боя мог я счесть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак он, мелькая пред глазами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМахал двенадцатью руками.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеладное тут что-то есть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда узнаешь ты, как странны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ Сицилии фата-морганы,\u003ca class=\"ref\" id=\"r230\" href=\"#n230\" data-tip=\"№230 \u0026#183; Смерть Артура (Мэлори); Ars magna lucis et umbrae (Кирхер)\"\u003e230\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВопросов этих не задашь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам часто в воздухе стеною\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь бела дня, на зыбком зное\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВстает обманчивый мираж.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо это всем сплетеньем веток\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВисящий над землею сад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо город, волн качанью в лад\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКачающийся так и этак.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо странно! Копий острия\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокрылись беглыми огнями.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад каждым кончиком копья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзметнулось маленькое пламя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе чисто это и чудно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО государь! Давным-давно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда бывало море хмуро,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНиспосылали Диоскуры\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакой же свет на корабли\u003ca class=\"ref\" id=\"r231\" href=\"#n231\" data-tip=\"№231 \u0026#183; Гимн к Диоскурам; Естественная история (Плиний) и др.\"\u003e231\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ залог доплытья до земли.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм поклонялись шкипера.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни желают нам добра\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ шлют нам это ободренье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОднако кто тот чародей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКому я так обязан всей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСчастливою судьбой сраженья?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе он, Нурсийский звездочет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто мыслью о тебе живет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасчет врагов приведши в ясность,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСказал он, осознав опасность,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто за поступок славный твой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасет тебя любой ценой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ торжественной процессии по Риму\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВезли меня, я помню. Полный сил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТворить добро стремясь неудержимо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНемедля я помиловать решил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСедого старца средь огня и дыма.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦерковникам я радость отравил,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа что у них с тех пор и не в фаворе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак неужели через столько лет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа помощь ту давнишнюю в ответ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне блещет луч добра в беде и горе?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобро плоды приносит сам-десят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо наверх посмотри. Явленье это\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбозначает некую примету.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДве эти птицы неспроста летят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОрел парит на небосклоне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГриф бросился за ним в погоню.\u003ca class=\"ref\" id=\"r232\" href=\"#n232\" data-tip=\"№232 \u0026#183; Геральдика Священной Римской империи; Гербовник (Зибмахер)\"\u003e232\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСледи. Тут, верно, добрый знак.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто гриф? Гриф — сказка, гриф — пустяк.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мог он до того забыться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб мериться с орлом, царь-птицей?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак носятся они по кругу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вдруг, сближаться перестав,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВдвоем слетаются стремглав\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ грудь и шею рвут друг другу!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри ж, как рваный, драный гриф,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобившись в драке только сраму\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ хвост свой львиный опустив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ вершины леса рухнул прямо.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если б все случилось так!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагоговейно верю в знак.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (повернувшись вправо)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОттесненный нами в схватке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВраг отходит в беспорядке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтбиваясь кое-как.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн отходит к части средней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПошатнув свой центр соседний\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеудачей контратак.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ этот пункт, пример бесстрашья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРинулась фаланга наша,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСловно молния разя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ равенстве слепого пыла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдинаковые силы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБьются, яростней нельзя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлизко, близко к разрешенью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыигранное сраженье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор  (повернувшись влево, Фаусту)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосмотри, не так-то просто\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоложенье аванпоста.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеприятельские группы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобрались до крутизны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВерхние ее уступы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНашими обнажены.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаша участь все тяжело.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе их силы подоспели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы штурмом взять проход.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПод угрозою ущелье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот нечестья должный, плод,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКозни не достигли цели.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПауза.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМои два ворона, глядите,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейчас расскажут ход событий.\u003ca class=\"ref\" id=\"r233\" href=\"#n233\" data-tip=\"№233 \u0026#183; Младшая Эдда (Снорри Стурлусон); Старшая Эдда и др.\"\u003e233\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБоюсь, нерадостны дела.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам только их недоставало!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни к нам с левого крыла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа черных парусах устало\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлывут предвестниками зла.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (обращаясь к воронам)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК ушам моим на плечи сядьте.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне ваша помощь очень кстати,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак до сих пор всегда была.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (императору)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо памяти о старом месте\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПочтовый голубь с мирной вестью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛетит издалека домой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ противность почте голубиной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоронья почта властелину\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоносит, как проходит бой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтчаянные донесенья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНепобедимы затрудненья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа левом фланге роковом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротивник захватил высоты.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗайми он горные ворота,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам может угрожать разгром.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтак, в итоге я обманут!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ знал, что в сеть меня затянут\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе ваши происки и ложь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМужайся, и не пропадешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе безнадежна обстановка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайти военную уловку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПомогут эти вещуны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВверь мне ведение войны.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлавнокомандующий  (подоспевший между тем)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы с темными людьми связался,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе время этим я терзался,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы из-за них пойдем ко дну.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМой план расстроили их штуки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзялись, так им и книги в руки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖезл полководца я верну.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставь его до лучших дней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ перелома в обороне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОпасен этот чародей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС подмогою своей вороньей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Мефистофелю.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет, я не дам тебе жезла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы не годишься в полководцы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРискуй, была иль не была,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ выручай нас, как придется.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит в палатку вместе с главнокомандующим.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХрани тебя тупой твой прут.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы не нуждаемся в игрушке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС крестом, вдобавок, на верхушке.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто делать?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыход тут как тут!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛетите, черные, с поклоном\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК ундинам в озере студеном.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть нам изобразят потоп\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКаким-нибудь приемом лживым\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ледниковых вод разливом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазмоют склоны горных троп.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРусалок женское кокетство\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНайдет необходимый путь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ женщин есть в запасе средства\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз видимости сделать суть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПауза.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРусалок вороны твои\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПронзили, видно, словом льстивым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзгляни по сторонам: ручьи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСочатся всюду по обрывам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВрага победу у высот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСнесет разлитье этих вод.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, хоть какого ползуна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСумеет охладить волна.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРучьи, стекая отовсюду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкопляются в большой поток.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВода встречает камней груду.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут образуется порог.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо тут же за запрудой, рядом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрутой обрывистый карниз,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с шумом все слетает вниз,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбрушиваясь водопадом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК чему врага сопротивленье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто храбрость против наводненья?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ сам в испуге от всего.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я не вижу ничего\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз этих водяных феерий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь человека легковерье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодатливо на плутовство.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня смешит их перепуг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто, не умея плавать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни толпой попали в заводь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак глупы эти взмахи рук,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ фырканье, и малодушье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА дураки меж тем на суше\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ почва твердая вокруг.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВороны возвращаются.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа эту меткость глазомера\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, похвалю вас Люциферу.\u003ca class=\"ref\" id=\"r234\" href=\"#n234\" data-tip=\"№234 \u0026#183; Книга пророка Исаии; Иероним Стридонский\"\u003e234\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь вам доказать пора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто и в другом вы мастера.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛетите к кузнице подгорной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде гномы день и ночь упорно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖелезо на огне куют.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрудолюбивый этот люд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУговорите дать нам пламя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе выразимое словами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКаленья белого предел,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб каждый, увидав, чумел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбычны в облаках зарницы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПривычен звезд падучих вид,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо гром из ветки — небылица,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа и звезда во сне не снится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторая в траве шипит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВороны улетают. Все совершается согласно сказанному.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВраги погружены в потемки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеверен шаг по горной кромке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА тут, слепя их, ко всему\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСверканья прорезают тьму,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, будто этих вспышек мало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлушит их грохот небывалый.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз оружейных зал доспехи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа воле предались потехе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрещат, стучат, шумят, звенят, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазноголосица, разлад.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперешний их шум нестройный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДань добрым старым временам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда их рыцарские войны\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакой же подымали гам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх дребезжащих лат пластины\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозобновили нелады,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстаток вековой вражды,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДелившей с гвельфом гибеллина.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ через столько сотен лет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДерет нам уши их фальцет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозьми строптивый самый норов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо нет свирепей ничего\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеждоусобных старых споров:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь безрассудства торжество.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри, как этот адский гул,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлепой, панический, бесчинный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмешал противника дружины\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, в бегство обратив, столкнул\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстатки войска их в долину.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГромкая нескладица в оркестре, под конец переходящая в веселые военные мотивы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eШатер враждебного императора\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрон, богатая обстановка.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГабебальд и Айлебойта.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАйлебойта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь первая с тобою я.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГабебальд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы быстролетней воронья.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАйлебойта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогатства сколько! Как во сне!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС чего начать? Что стибрить мне?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГабебальд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВещей, вещей! Не перечесть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе знаю, раньше что загресть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАйлебойта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозьму ковер, а то жестка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоя кровать без тюфяка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГабебальд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я мечтал давно в душе\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак раз об этом бердыше.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАйлебойта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА я мечтаю взять домой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлащ красный с золотой каймой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГабебальд  (забрав оружие)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот этим встречного хвати —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ нет преграды на пути.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты без пользы пол-узла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПустого хлама набрала.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ б дряни этой не берег,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА взял бы лучше сундучок.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ нем целой армии казна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн полон золотом до дна.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАйлебойта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда мне! Словно врос он в пол.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе подыму, так он тяжел.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГабебальд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНагнись, не уплыло б из рук.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ на тебя взвалю сундук.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАйлебойта\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОй-ой! Приходит мой конец!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛарец сломает мне крестец.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯщик падает и раскрывается.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГабебальд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы видишь, куча золотых.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивей хватай горстями их.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАйлебойта  (на корточках)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкорей в передник их сейчас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДо самой смерти хватит с нас.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГабебальд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ живо уходи. Пора.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна встает.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАй-ай, в переднике дыра!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКарман-то оказался худ,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ на пол денежки текут.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТелохранители истинного императора\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в императорском шатре\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы рыться смеете в добре?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГабебальд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа так, что мы за этот приз\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлужить в солдатах нанялись.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА скарба вражьего дележ —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗахват по праву, не грабеж.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТелохранители\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ нас в войсках иной разбор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСолдат не вор, не мародер,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ к нам на службу лишь идет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысокой честности народ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГабебальд\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ этой честности прием\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы контрибуцией зовем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДевиз наш: \u0026#171;Отдавай мошну!\u0026#187; —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот с чем идем мы на войну.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(К Айлебойте.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПойдем, тащи свою суму,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы не милы тут никому.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУходят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервый телохранитель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем грубьяну-наглецу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы не дал тотчас по лицу?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторой телохранитель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРука не поднялась, представь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКазалось, это сон, не явь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТретий телохранитель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мне глаза застлала муть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак что не мог на них взглянуть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧетвертый телохранитель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ сам не знаю, но с утра\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыла ужасная жара,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все смешалось в духоте:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВалились эти, бились те.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПротивник падал, что ни шаг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт взмаха чьих-то рук впотьмах.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлаз был туманом замутнен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ушах стоял какой-то звон.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вот мы здесь, а доищись,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мы сюда перенеслись.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит император в сопровождении четырех князей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТелохранители удаляются.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто там ни говори, мы выиграли бой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазбитые враги рассеялись толпой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот трон изменника, а вот сундук тяжелый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС казной, которой он поддерживал крамолу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы ж, свитой окружив себя со всех сторон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖдем представителей от подданных племен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзвестья добрые: везде успокоенье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ стране подавлен бунт, нам радо населенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам скажут, в наш успех вмешалось колдовство,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлоды достались нам — довольно и того.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА мало ли еще случайности какие\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа памяти хранят анналы боевые?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа голову врагов то дождь кровавый льет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо град камней летит, то ураган невзгод.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИли вселяет гул таинственный в пещере\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУверенность в одних, а в остальных неверье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо побежденный пал, преследуем стыдом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА тот, кто победил, не помнит ни о чем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо славит господа, сливая в хор хвалебный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМильоны голосов собравшихся к молебну.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ счастливый этот час дарений и наград\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ на себя смотрю и перемене рад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПравитель молодой пусть времени не ценит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГода пройдут, года его и переменят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ долю уделить хочу вам четырем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ распоряженье царством, домом и двором.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Первому.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУстройство войска, князь, налажено тобою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ опасный миг оно не пошатнуло строя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВо время мира будь таким же молодцом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ жалую тебя фельдмаршальским мечом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФельдмаршал\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам до сих пор внутри страны случалось биться.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда ж давать отпор начнем мы у границы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда на торжество весь двор мы созовем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в императорском чертоге родовом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеч этот обнажив, с тобой я рядом стану,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем знаменуя, как крепка твоя охрана.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор  (второму)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы — храбр и слыл всегда учтивости примером.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот трудный пост тебе, будь первым камергером.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот государь без слуг, при ком семью и двор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодтачивают рознь, интриги и раздор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты покажешь, как характером покорным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНетрудно угодить монарху и придворным.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервый камергер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдушевляемый стремлением одним —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХорошим помогать и не вредить дурным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ буду прям без лжи, без плутовства спокоен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ близости с тобой, мой государь, достоин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА на твоем пиру перед столом твоим\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредстану пред тобой я с тазом золотым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ кольца подержу, и радоваться буду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто руки моешь ты водою из сосуда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу что ж, задумывай пиры и торжества,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА у меня полна не этим голова.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Третьему.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОхотою моей и птичником заведуй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудь стольником моим и обеспечь к обеду\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПродуманный подбор моих любимых блюд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в сроки разные к столу их подают.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтольник\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоститься буду я, подавленный и грустный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока не будешь ты доволен кухней вкусной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе помешают нам ни дальность, ни пора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДворецкий сыщет все, все сварят повара.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа сам ты враг причуд, не свойственных сезону,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ любишь стол простой, здоровый, немудреный.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор  (четвертому)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо речь опять к пирам свелась сама собой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудь виночерпием, герой мой молодой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотри, чтобы вино у нас не убывало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСортами лучшими наполни нам подвалы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, веселя гостей во время шумных встреч,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСам страсти пагубной не дай себя увлечь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВиночерпий\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗнай, государь: когда нам старший доверяет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо юноша, гордясь доверием, мужает.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ так как на пиры опять слова свелись,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРоскошный подберу я к пиршеству сервиз.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКовши из золота, серебряные чаши,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе же выберу бокал ценней и краше —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВенецианского прозрачного стекла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде винная струя чиста, крепка, светла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ пьется медленней, сознанья не туманя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ менее пьянит, и учит воздержанью.\u003ca class=\"ref\" id=\"r236\" href=\"#n236\" data-tip=\"№236 \u0026#183; Трактаты о ядах Пьетро д\u0026#39;Абано; Handw\u0026#246;rterbuch des deutschen Aberglaubens\"\u003e236\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто я облюбовал для каждого из вас,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ устно объявил в высокий этот час.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ том вы заверены высоким словом честным.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо в дополнение к решениям словесным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа подпись подадут мне письменный указ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА вот и канцлер,\u003ca class=\"ref\" id=\"r235\" href=\"#n235\" data-tip=\"№235 \u0026#183; Золотая булла (1356)\"\u003e235\u003c/a\u003e он и нужен нам как раз.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВходит архиепископ-канцлер.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы камнем угловым смыкаем дуги свода,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторому тогда не угрожают годы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС князьями четырьмя, как видишь ты, с утра\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРассматриваю я потребности двора.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо если эта часть под стать такому штату,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб царством управлять,\u0026#160;— понадобится пятый.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы выделяем вас из всех, и пятерым\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмущество князей-изменников дарим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы во много раз расширенным наделом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоднять вас высоко над нашим краем целым.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСверх этого еще рескрипт мой подтвердит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб не чинили вам и в остальном обид.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы вправе округлять владенья по желанью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокупкой, меною или по завещанью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ преимущества вам пятерым раздам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрисущие другим владетельным князьям:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВершите у себя свой суд, свою расправу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез апелляции в суды моей державы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзимайте пошлины и подати свои.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрибавьте к этому доходные статьи:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧекан монет, руду, акциз, налоги с соли,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДорожный сбор, весь лист коронных монополий.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ до себя почти вас поднял, уступив\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакое множество моих прерогатив.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАрхиепископ\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагодарю тебя за всех, но не жалей:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУсилив нас, ты сам становишься сильней.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще я отдаю на ваше попеченье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМысль о наследнике и трона замещенье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще я жив и жить хочу, но всякий миг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМогу отозван быть в круг праотцев моих.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда умру я, вам пяти я поручаю\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПреемника избрать покинутому краю.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ день коронации избранник молодой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть миром кончит то, что началось войной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКанцлер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы этим польщены и пред тобой смиренно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСклоняемся, князья, властители вселенной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокамест кровь течет по жилам верных слуг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы — плоть твоя, а ты — нас двигающий дух.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб не дробить земли, пожалованной в дар,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСопровожу одним условьем циркуляр.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть вам земля дана на все века и свято,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо вам принадлежит по праву майората.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть вотчину свою умножит господин,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаследует ее один лишь старший сын.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКанцлер\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ на себя сейчас возьму завидный труд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПергаменту предать монарший твой статут.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереписать указ — задача канцелярий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе завершат печать и подпись государя.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ отпускаю вас, и вы об этом дне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодумайте, домой вернувшись, в тишине.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСветские князья уходят. Архиепископ, как лицо духовное, остается и говорит с пафосом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАрхиепископ\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть канцлер вышел. Я, епископ,\u0026#160;— пред тобой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТревога за тебя, мой сын, владеет мной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС отеческой к тебе я укоризной строгой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакая у тебя в столь ясный день тревога?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАрхиепископ\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ счастливый этот час владеет горько мною\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСознание, что ты в союзе с Сатаною.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотя, на первый взгляд, упрочен твой престол,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи к богу ближе ты, ни к папе не пришел.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУзнай он, как достиг ты снова воцаренья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн поразит твой край громами отлученья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь не забыты им еще те времена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКогда, взойдя на трон, простил ты колдуна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ милости лучом, склонясь челом венчанным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоснулся головы, противной христианам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокайся между тем и в грудь себя ударь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лепту скромную дай церкви, государь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеста, в которых след оставил осквернитель\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПобедой колдовства, отдай ты под обитель\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС окрестной полосой, с лесами и горой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоросшей по краям травою луговой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ключами, бьющими сквозь каменные глыбы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо множеством озер, богатых всякой рыбой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем шире будет мера щедрости твоей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТем и прощенье будет ближе и верней.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезмерно потрясен свершенным прегрешеньем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде хочешь, проведи границу тем владеньям.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАрхиепископ\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб след кощунства смыть, во-первых нужно нам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсевышнему на той горе воздвигнуть храм.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот храм провижу я, и мысленному взору\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРисуется: в лучах восхода блещут хоры,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрестом посереди два корабля сошлись,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолящихся как бы приподымая ввысь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни по паперти проходят богомольно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх благовест из сел сзывает колокольный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ долинах далеко гудит церковный звон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ грешник кается, молитвой обновлен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ присутствии твоем уже в предвосхищенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ храма этого свершаю освященье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрославь зиждителя и этот храм построй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОчисти от греха дух отягченный мой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадеждою одной, и то я окрыляюсь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАрхиепископ\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак канцлер, в записи я дарственной нуждаюсь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФормальный акт составь, пожалуйста, ты сам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будет он готов, я подпись тотчас дам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАрхиепископ  (откланивается, но перед выходом снова возвращается)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ храму в собственность отдай доход старинный:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПовинности крестьян, налоги, десятину.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой дар увековечь и храму сделай клад.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоддерживать его потребует затрат.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА чтоб начать скорей святилища закладку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧасть вражьих денег дай нам в качестве задатка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ даром отпусти для стройки матерьял.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы убедим народ с амвонов, чтоб не брал,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасая душу тем, никто за перевозку\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ доски нам возил, и камень, и известку.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа близость с магами плачусь я тяжело;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасходов из-за них все множится число.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАрхиепископ  (снова возвращаясь, с глубоким поклоном)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрости, о государь! Ты отдал чародею\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМорские берега. Но, чтоб спасти злодея,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаставь отступника на все века отсель\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго святейшеству платить налог с земель.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор  (с досадою)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемель ведь нет еще. Они в пучине моря.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАрхиепископ\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто правом облечен, ждать для того не горе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольно слова с нас, дай обещанье нам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходит.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператор  (один)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПослушаться, так им все царство я раздам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2 class=\"part\"\u003eАкт пятый\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eОткрытая местность\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтранник\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа ведь это липы те же!\u003ca class=\"ref\" id=\"r237\" href=\"#n237\" data-tip=\"№237 \u0026#183; Метаморфозы (Овидий); Разговоры с Гёте (Эккерман)\"\u003e237\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак я счастлив их найти\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ вековой их мощи свежей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосле стольких лет пути!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа и хижина сохранна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКров гостеприимный мой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ дни, когда на холм песчаный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл я выброшен волной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо хозяева лачуги\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНыне живы ль, добряки?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь уже тогда супруги\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыли оба старики.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКротким людям без гордыни\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ скажу ли: \u0026#171;Мир чете,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаходящей и поныне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУтешенье в доброте\u0026#187;?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБавкида  (старая-престарая бабушка)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТише, милый гость! Беседой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы разбудишь старика.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолог сон теперь у деда,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА работа коротка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтранник\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлов найти не в состоянье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто могу тебя опять\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа твои благодеянья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС благодарностью обнять!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто ты, Бавкида, та же,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКем я к жизни возвращен?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыходит ее муж.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы ли, часть моей поклажи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ море спасший, Филемон?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько ваш огонь сигнальный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКолокола звон с земли\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт погибели печальной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне спасенье принесли.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ пойду с вершины склона\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа морскую даль взглянуть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, коленопреклоненный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОблегчу молитвой грудь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Идет вперед по дюне.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФилемон  (Бавкиде)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам на стол накрой мгновенно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВынеси его в цветник.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред общей переменой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтанет, верно, гость в тупик.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Подойдя к страннику.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде бушующей пучиной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыл ты к берегу прибит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВместо отмели пустынной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГустолистый сад шумит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтар я стал сидеть в дозоре\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо ночам на маяке,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА тем временем и море\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОчутилось вдалеке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмные распоряженья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ прилежный смелый труд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОттеснили в отдаленье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоре за черту запруд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСела, нивы вслед за морем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаступили место вод.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧервячка пойдем заморим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкоро солнце ведь зайдет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПарусников вереницы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПредваряя темноту,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТянутся, как к гнездам птицы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереночевать в порту.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа прорытою канавой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМоря синяя черта,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА налево и направо —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаселенные места.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВтроем за столом в саду\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБавкида\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзглядом приковавшись к дюне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы не скушал ни куска.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФилемон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ наши чудеса, болтунья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПосвятила б новичка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБавкида\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДа, поистине загадка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭти наши пустыри.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут нечистая подкладка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ты там ни говори.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФилемон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот пришлец законно, свято\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолучил морской пустырь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИмператорский глашатай\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбъявил об этом вширь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТут вначале был по плану\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛагерь для людей разбит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА теперь на месте стана\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ зелени дворец стоит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБавкида\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь для виду днем копрами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБили тьмы мастеровых:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПламя странное ночами\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоздвигало мол за них.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБедной братии батрацкой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСколько погубил канал!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗлой он, твой строитель адский,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ какую силу взял!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтали нужны до зарезу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДом ему и наша высь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн без сердца, из железа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажет — и хоть в гроб ложись\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФилемон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн дает нам вместо дома\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНовый, на земле низин.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБавкида\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе глава ты дну морскому,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА холму ты господин.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФилемон\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо пойдем в часовню. Взглянем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа огни зари втроем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВместе на колени станем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ молитвы вознесем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eДворец\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбширный загородный сад на берегу широкого и прямого канала.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст, сильно состарившийся, прогуливается по саду.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛинкей, караульный на башне  (говорит в рупор)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСадится солнце, у причала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБросают с палубы канат;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт моря в гавань по каналу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоследние суда спешат.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе гнутся мачты их. Красиво\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодрагивают вымпела.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе, хозяину залива,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрибывших путников хвала.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКолокольный звон на песчаном взморье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (раздраженно)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроклятый звон! Как в сердце нож!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет впереди границ успеху,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА позади, как разберешь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе та же глупая помеха!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне говорят колокола,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто план моих работ случаен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто церковь с липами цела,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто старикам я не хозяин.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни — бельмо в глазу моем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока от них я не избавлен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ час прогулки мой отравлен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПри встрече с этим старичьем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛинкей  (как выше)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМорского берега держась,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодходит к пристани баркас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнутри его не счесть добра:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМешков и ящиков гора.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПричаливает великолепный парусник, доверху нагруженный произведениями чужих стран.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель и трое сильных.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот и земля,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПричалил бот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВладельцу корабля\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПочет!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоднимаются на пристань, груз выносят на берег.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолжна прославить нас молва,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо что нам скажет наш глава?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНачав с двух кораблей в пути,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВернулись мы на двадцати.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО сделанном дает понять\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДоставленная нами кладь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ открытом море дерзок взгляд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМолчит закон, царит захват.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо китобойщик, то пират,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗахватываешь ты фрегат.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНапав на два, ты жизнь отдашь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб третий взять на абордаж.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗатем берешь четыре, пять,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ уж не можешь перестать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФлот этот твой! Таков устав:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ ком больше силы, тот и прав.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНикто не спросит: \u0026#171;Чье богатство?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде взято и какой ценой?\u0026#187;\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВойна, торговля и пиратство —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТри вида сущности одной.\u003ca class=\"ref\" id=\"r238\" href=\"#n238\" data-tip=\"№238 \u0026#183; История обеих Индий (Рейналь); История Ост-Индских компаний\"\u003e238\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрое сильных\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХозяин дал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ награду шиш,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто мал\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕму барыш.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтоит угрюм\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред слугой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа полный трюм\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлядит брюзгой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБесцельный шум:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж был дележ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа всех вас сумм\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе напасешь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрое сильных\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТе наградные —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКурам смех.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаздайте поровну\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа всех.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе до последнего\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛарца\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасставьте\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ комнатах дворца.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХозяйский глаз\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОценит склад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сам на вас\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзменит взгляд.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ за работу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ разбой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗадаст он флоту\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПир горой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖду завтра пестрых птиц и тотчас\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОб их приеме позабочусь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыгруженную кладь уносят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Фаусту.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем ты складками на лбу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМрачишь счастливую судьбу?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗакончен труд, готов затон,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМир суши с морем заключен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда велишь, твои суда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУносит на себе вода.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз стен дворца своей рукой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы правишь мировой судьбой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь был задуман первый шаг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа этом месте был барак.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрорытый здесь когда-то ров\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПокрылся веслами гребцов.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоим умом к концу работ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт моря возведен оплот.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь…\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтвратительное \u0026#171;здесь\u0026#187;!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот в нем одном и ужас весь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, ты такой ведь воротила\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с хитростями так знаком!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мне разделаться с постылой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтарухою и стариком?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТомлюсь, безумствую, мытарюсь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа шее ж — это старичье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто мне владычество мое?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ сам на тот участок зарюсь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ там устроил бы помост\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ созерцал бы с этой вышки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростор прирезанных борозд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗемли отхваченной излишки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТам наблюдал бы я разбег\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРастущих в ширину владений,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторыми венчал свой гений\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ даль заглянувший человек.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак неприятен недочет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь общего великолепья!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗапахнут липы, звон пойдет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо словно погребен я в склепе.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНеужто в жертву я отдам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой план препятствиям невольным?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак быть со звоном колокольным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с липовою рощей нам?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗвон колокольный — не пустяк.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн отравляет каждый шаг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНедопустимо равнодушье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК тому, что вечно режет уши.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаладят это \u0026#171;динь-динь-динь\u0026#187;, —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрощай, безоблачная синь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто похороны, что крестины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля колокола все едино,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся жизнь как будто — призрак, хмарь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА главное — один звонарь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСопротивляясь, эти люди\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМрачат постройки торжество.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни упрямы до того,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто плюну я на правосудье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх выселить давно пора\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ назначенные хутора.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы знаешь место у бугра,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде их усадьбой наделили?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереселяй их со двора!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни и глазом не моргнут,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будут уж от нас за милю,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде об испытанном насилье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабудут в несколько минут.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПронзительно свищет. Возвращаются трое сильных.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот вам начальника приказ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн завтра просит в гости вас.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрое сильных\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн с нами груб. Пусть угостит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы не вспоминать обид.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходят.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (к зрителям)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак отдал в дни, еще древней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвой виноградник Навуфей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Кн. царств, III, 21)\u003ca class=\"ref\" id=\"r239\" href=\"#n239\" data-tip=\"№239 \u0026#183; Третья книга Царств\"\u003e239\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлубокая ночь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКараульный Линкей  (поет на сторожевой башне)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе видеть рожденный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ зорко, в упор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотрю с бастиона\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа вольный простор.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вижу без края\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСозвездий красу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лес различаю,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ланей в лесу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, полная славы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда на виду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся жизнь мне по нраву\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ я с ней в ладу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлаза мои! Всюду,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасширив зрачки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы видели чудо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсему вопреки.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПауза.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе всегда меня встречает\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРадостью высокий пост.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтсвет ужаса бросает\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНынче ночь на мой помост.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИскры носятся роями\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ стариковском липняке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе сильней бушует пламя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеж стволов на сквозняке.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ полна лачуга дыма,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтсыревшая от лет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПомощи необходимой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНиоткуда нет как нет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗакрывали осторожно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобряки заслон печной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто за случай невозможный!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДом горит не их виной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧерной крыши обгорелой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПламенеют угольки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько бы остались целы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе сгорели старики!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСловно молнии зигзаги,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо листве бегут огни\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, треща на сильной тяге,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРассыпают головни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА часовня, что ласкала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз-под лип веками взор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВся под тяжестью обвала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС ними рушится в костер.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛип обуглившийся остов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаскаленный до корней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБезутешнее погостов\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотрит в даль ушедших дней.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот отполыхало пламя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗапустенье, пепел, чад.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДолгая пауза, потом снова пение.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ уходит вдаль с веками\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо, что радовало взгляд.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (на балконе напротив дюн)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВверху на башне — пенье, стоны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо сделанного не вернуть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛинкея песня с бастиона\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне жалостью пронзает грудь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо ведь утрату пепелища\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ старцам возместить хочу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ их пожарище расчищу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ там построю каланчу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтав на высоком бельведере,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзгляну на новый их приют,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде оба, позабыв потерю,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпокойно век свой доживут.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель и трое сильных внизу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы кинулись сюда бегом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДела не кончились добром.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы в дверь стучались к ним раз сто,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо нам не отворил никто.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы налегли, не тратя слов,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дверь слетела с косяков.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы сообщили твой приказ,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни не стали слушать нас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы не жалели просьб, угроз,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо не был разрешен вопрос.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКонец желая положить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы стали вещи выносить.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда их охватил испуг,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ оба испустили дух.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА гость, который был там скрыт,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСопротивлялся и убит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеж тем как все пошло вверх дном,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт искры загорелся дом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ эти, трупы к той поре,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВтроем сгорели на костре.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ мену предлагал со мной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА не насилье, не разбой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа глухоту к моим словам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроклятье вам, проклятье вам!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред силою бессильна речь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмирись пред нею, не перечь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА если хочешь взять борьбой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРискуй и домом и собой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУходят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (на балконе)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе видно звезд, их скрыла мгла.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСгорела хижина дотла.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПахнуло свежим ветерком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ дымом понесло кругом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОшиблись, меру перешли!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо что маячит там вдали?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eПолночь\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоявляются четыре седые женщины.\u003ca class=\"ref\" id=\"r240\" href=\"#n240\" data-tip=\"№240 \u0026#183; Энеида (Вергилий); Оды (Гораций)\"\u003e240\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервая\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗовусь я Нехваткой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВторая\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗовусь я Виной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТретья\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗовусь я Заботой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧетвертая\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗовусь я Нуждой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПервые три\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас в дверь не пускают, она под замком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогач в этом доме, мы в дом не войдем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНехватка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ в тень превращусь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВина\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ уйду без следа.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНужда\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБогатого не испугает Нужда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабота\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрочь, сестры! Возможность Заботе лишь есть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ замочную скважину эту пролезть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабота исчезает.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНехватка\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы, сестры седые, назад повернем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВина\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС тобой неразлучны всегда мы вдвоем.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНужда\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа вами ступает Нужда по пятам.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе трое\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗатянуты тучами звезды и твердь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА там, на большом расстоянье, а там\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыходит навстречу сестра наша, Смерть.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Уходят.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (во дворце)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧетыре были и остались три.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ речь их смутно слышал изнутри.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНужду упоминали, звезды, твердь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в заключенье, как бы в рифму,\u0026#160;— смерть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕще за мною призраки снуют,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ все еще не вырвался из пут!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если бы мне магию забыть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаклятий больше не произносить,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, если бы, с природой наравне,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБыть человеком, человеком мне!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТаким я был, но преступил устав,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнафеме себя и жизнь предав.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь все привиденьями полно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ поделом, оно не мудрено.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь даже если мы разумны днем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас ночь пугает нехорошим сном.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУслышу на прогулке поутру —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрокаркает ворона — не к добру!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоверьями кругом опутан свет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе неспроста, и все полно примет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мы дрожим, и всюду колдовство.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДверь скрипнула. Не вижу никого.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Настороженно.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь кто-то есть?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабота\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсть кто-то, спору нет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо кто же это?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабота\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНекто, вот ответ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУйди!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабота\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ там, где надо, нахожусь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (сперва негодуя, потом успокоившись, про себя)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК заклятьям не прибегну и сдержусь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабота\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕсли внять мне не желаешь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСердцем ты меня узнаешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ разных видах, я везде\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсех держу в своей узде.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ на море и на суше\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПовергаю в малодушье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНезнакома, незвана,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсем судьбой предрешена.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто, ты Заботы не знавал в былом?\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ шел всю жизнь беспечно напролом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ удовлетворял свои желанья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто злило — оставлял я без вниманья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто умиляло — не тужил о том.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ следовал желаньям, молодой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ исполнял их сгоряча, в порыве.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда я жил с размахом, с широтой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу а теперь — скромней и бережливей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ этот свет достаточно постиг.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГлупец, кто сочинит потусторонний,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУверует, что там его двойник,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ пустится за призраком в погоню.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтой на своих ногах, будь даровит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБрось вечность утверждать за облаками!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам здешний мир так много говорит!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто надо знать, то можно взять руками.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак и живи, так к цели и шагай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе глядя вспять, спиною к привиденьям,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ движенье находя свой ад и рай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе утоленный ни одним мгновеньем!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабота\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто в мои попался сети,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНичему не рад на свете.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСолнце встанет, солнце сядет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо морщин он не разгладит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе пред ним покрыто мраком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе недобрым служит знаком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ плывет богатство мимо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ такого нелюдима.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолон дом — он голодает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКопит впрок, недоедает,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТихо усидеть не может,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧерный день его тревожит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудущее роковое\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе дает ему покоя.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтстань! Меня ты этим не проймешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне надоели эти прибаутки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, слушая унылый твой долбеж,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмнейший может тронуться в рассудке.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабота\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ колеблется тупица,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДумая, на что решиться.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ него на полдороге\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМогут подкоситься ноги.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоложенье все серьезней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн повсюду видит козни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗлой, пришибленный, кургузый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн себе и всем в обузу\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ живет наполовину,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолутруп, полуруина.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа ничтожность, за блужданья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа безволье, за шатанье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа сомненья, за смешенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолусна и полубденья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн достоин без пощады\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУготованного ада.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНавязчивые страхи! Ваша власть —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроклятье человеческого рода.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы превратили в пытку и напасть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПривычный круг людского обихода.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай силу демонам, и их не сбыть.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе выношу их нравственного гнета.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо больше всех бессмыслиц, может быть,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ презираю власть твою, Забота!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабота\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак ощути ту власть краями век!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлачу тебе проклятьем за презренье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивет слепорожденным человек,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ты пред смертью потеряешь зренье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Дует ему в глаза и исчезает.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (ослепленный)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВокруг меня сгустились ночи тени,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо свет внутри меня ведь не погас.\u003ca class=\"ref\" id=\"r241\" href=\"#n241\" data-tip=\"№241 \u0026#183; Handw\u0026#246;rterbuch des deutschen Aberglaubens; Потерянный рай (Мильтон) и др.\"\u003e241\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБессонна мысль и жаждет исполненья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ жив распорядителя приказ.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВставайте на работу дружным скопом!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРассыпьтесь цепью, где я укажу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКирки, лопаты, тачки землекопам!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыравнивайте вал по чертежу!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаграда всем, несметною артелью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаботавшим над стройкою плотин!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТруд тысяч рук достигнет высшей цели,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторую наметил ум один!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eБольшой двор перед дворцом\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФакелы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВпереди Мефистофель в качестве смотрителя работ.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭй, эй, сюда, сюда скорей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСюда, народ понурый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз жил, и связок, и костей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкроенные лемуры!\u003ca class=\"ref\" id=\"r242\" href=\"#n242\" data-tip=\"№242 \u0026#183; Фасты (Овидий); Послания (Гораций) и др.\"\u003e242\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛемуры  \u0026#160;\u0026#160;(хором)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда нас хочешь посылай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, в некотором роде,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлыхали мы, что целый край\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНам отдан под угодья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы взяли колышки для вех\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ цепи для промера,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо для чего ты звал нас всех,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗабыли землемеры.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ вам работу дам одну:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеж вами рослый самый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПускай растянется в длину,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо нем и ройте яму.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак рыл отец ваш для отца\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКладбищенскую глину,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПереселенцу из дворца\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКопайте домовину.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдин из лемуров  (копая землю, с ужимками)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ дни молодости и проказ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа все хватало силы.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде можно, я пускался в пляс,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ все мне с рук сходило.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДала мне старость по горбу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в яму я свалился.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вылетело все в трубу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ гробу я очутился.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст  (выходит ощупью из дворца, хватаясь за дверные косяки)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мне приятен этот стук лопат!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРабочие, их разобрав, толпою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКладут границу бешенству прибоя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, как бы землю примирив с собою,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозводят, вал и насыпи крепят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (в сторону)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа мельницу мою ты воду льешь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПлотиной думая сковать буруны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМорскому черту, старику Нептуну,\u003ca class=\"ref\" id=\"r244\" href=\"#n244\" data-tip=\"№244 \u0026#183; Энеида (Вергилий)\"\u003e244\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаранее готовишь ты кутеж.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ союзе с нами против вас стихии,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ты узнаешь силы роковые,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в разрушенье сам, как все, придешь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНадсмотрщик!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУсилий не жалей!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗадатками и всевозможной льготой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВербуй сюда работников без счету\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ доноси мне каждый день с работы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак подвигается рытье траншей.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (вполголоса)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа этот раз, насколько разумею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе могилу роют — не траншею.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБолото тянется вдоль гор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГубя работы наши вчуже.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо чтоб очистить весь простор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ воду отведу из лужи.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМильоны я стяну сюда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа девственную землю нашу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ жизнь их не обезопашу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо благодатностью труда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вольной волею украшу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтада и люди, нивы, села\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаскинутся на целине,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК которой дедов труд тяжелый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодвел высокий вал извне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВнутри по-райски заживется.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть точит вал морской прилив,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНарод, умеющий бороться,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда заделает прорыв.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот мысль, которой весь я предан,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИтог всего, что ум скопил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишь тот, кем бой за жизнь изведан,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖизнь и свободу заслужил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак именно, вседневно, ежегодно,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТрудясь, борясь, опасностью шутя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПускай живут муж, старец и дитя.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНарод свободный на земле свободной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУвидеть я б хотел в такие дни.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТогда бы мог воскликнуть я: \u0026#171;Мгновенье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО как прекрасно ты, повремени!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоплощены следы моих борений,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ не сотрутся никогда они\u0026#187;.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ это торжество предвосхищая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ высший миг сейчас переживаю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eФауст падает навзничь. Лемуры подхватывают его и кладут на землю.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ борьбе со всем, ничем ненасытим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПреследуя изменчивые тени,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоследний миг, пустейшее мгновенье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотел он удержать, пленившись им.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто так сопротивлялся мне, бывало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПростерт в песке, с ним время совладало,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧасы стоят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтоят. Молчат, как ночь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУпала стрелка. Делу не помочь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУпала стрелка. Сделано. Свершилось.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКонец.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКонец? Нелепое словцо!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧему конец? Что, собственно, случилось?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаз нечто и ничто отожествилось,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТо было ль вправду что-то налицо?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем же созидать? Один ответ:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб созданное все сводить, на нет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e\u0026#171;Все кончено\u0026#187;. А было ли начало?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМогло ли быть? Лишь видимость мелькала,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗато в понятье вечной пустоты\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвусмысленности нет и темноты.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003eПоложение во гроб\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдин из лемуров\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто строил заступом в песке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакой барак дырявый?\u003ca class=\"ref\" id=\"r243\" href=\"#n243\" data-tip=\"№243 \u0026#183; Гамлет (Шекспир)\"\u003e243\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛемуры  (хором)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖильцу в пеньковом сюртуке\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольно и канавы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдин из лемуров\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ж не обставлено жилье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет даже стульев в зале.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛемуры  (хором)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь все чужое, не свое.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗаимодавцы взяли.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть дух покинет тело, договор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕму представлю, кровью подкрепленный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо столько средств есть с некоторых пор\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтбить у черта душу беззаконно!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоверья предков, словно старый хлам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛишились силы, всякий смысл утратив.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБывало, я со всем справлялся сам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТеперь нуждаюсь в помощи собратьев.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТяжелые для черта времена!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ загоне честь, обычай, старина.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсегда готовым надо быть к подвохам,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА в старину душа была честна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ вылетала вон с последним вздохом.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ схватывал ее, как кошка мышь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез промаха, и вмиг, без проволочки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСжимал в когтях. Теперь не то, шалишь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуша нейдет из грязной оболочки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕй дорога вонючая дыра,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПока ее не сгонят со двора\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВраждующие меж собой стихии.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСиди, гадай, когда она и как\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРешит уйти и хитрости какие\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГотовить ей, чтоб не попасть впросак.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмерть на руку уже не так скора,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСражает не ударом топора.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗастынет труп, его б уж класть в гробницу,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАн смотришь, ожил он и шевелится.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Производит странные, заклинательные движения, словно отдает приказания.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтарейших корпораций господа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКнязья прямого и кривого рога!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБез промедленья, всей толпой в дорогу!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПасть адову несите мне сюда!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПасть адова, положим, не одна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ по разрядам грешников их много.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо нам пред заключеньем эпилога\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТакая щепетильность не нужна.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрашная пасть ада разверзается слева.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПо сторонам клыки торчат. От злобы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоток огня слюной стекает с нёба,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ город мук, дымящийся в огне,\u003ca class=\"ref\" id=\"r245\" href=\"#n245\" data-tip=\"№245 \u0026#183; Кукольный театр о Фаусте; Божественная комедия (Данте) и др.\"\u003e245\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВиднеется в далекой глубине.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОб зубы бьется бешеная пена,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ грешники, подплыв, хотят спастись,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо, скрежеща, смыкается геенна,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ их смывает огненная слизь.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрастей таит еще немало бездна\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля грешных вольномыслящих мирян.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХорошая острастка им полезна.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм кажется, что это все обман.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Толстым чертям с коротким прямым рогом.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбжоры, краснощекие кубышки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНалившиеся сальные угри!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотрите в оба: фосфористой вспышки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы в теле не заметите ль внутри?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТу душу, ту крылатую Психею\u003ca class=\"ref\" id=\"r246\" href=\"#n246\" data-tip=\"№246 \u0026#183; Золотой осёл (Апулей); Античная иконография Психеи\"\u003e246\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХватайте, остальное — червь дрянной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПечать поставлю я на ней, и с нею\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ круговорот бросайтесь огневой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбследуйте внимательно брюшину.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто о душе мы знаем, толстяки?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОна могла иметь свою причину\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗапрятаться куда-нибудь в кишки\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, выйдя сквозь отверстие пупа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОкажется, совсем не так глупа.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Тощим чертям с длинным кривым рогом.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы ж вытянитесь, жерди, в высоту\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ лапами по воздуху машите.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуть выскользнет душа из-под прикрытья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕе хватайте разом на лету.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь гений жизни рвется унестись\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИз ветхого былого, дома ввысь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛучезарный свет, исходящий с правой стороны сверху.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНебесное воинство\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнгельской ратью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДвинемся, братья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ тихий полет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрешных прощая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрах оживляя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКроткой, радушной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛегкой, воздушной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаей слетая\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС горних высот.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе выношу я шайки голосистой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ резкий свет такой, что пропадешь!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоют женоподобные хористы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбимцы богомолок и святош.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб род людской сразить бичом тяжелым,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотели мы, чтоб пол был отменен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаш адский план о существе бесполом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ мечатаньях набожности воплощен.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаивничают, тайно строя глазки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтобы обставить нас не в первый раз!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь это — черти, как и мы, но в маске,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОружьем нашим побивают нас.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе посрамимся! Станем пред могилой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ силе противопоставим силу!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор ангелов  (рассыпая розы)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРозы румяные,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагоуханные,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПадая, радуя\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНежной прохладою\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖивотворящею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВейте над спящею\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТихо душой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРайских селений\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВечный покой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСейте весенней\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАлой копной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (бесам)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДрожать и жаться? И не стыдно вам?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть сыплют розы. Что вы оробели?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ дам вам пятиться! Все по местам!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни хотят цветочной канителью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВас занести, как снежною метелью.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОгнем дохните, и конец цветам.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНу, дуйте, дуйте! Кончено! Не надо!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоблекло все от одного лишь смрада.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе так неистово! Закройте рты!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы слишком надышали, кавалеры.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНи в чем не соблюдаете вы меры,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе только сохнут, а горят цветы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ жгут нас ядовитыми огнями.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСплотитесь вместе! Отражайте пламя!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак быстро, черти, ваша прыть прошла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПред лаской чужеродного тепла.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнгелы  (хор)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПолные пламени\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРозы, вы — знаменья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлагости любящей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСилы, голубящей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКроткий завет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе перевесьте\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРадостной вестью!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнгелов шествие\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСеет ваш свет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроклятье! Стыд! Несчастные балбесы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеревернулись вверх ногами бесы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ чехардою друг за дружкой в ад,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак в баню, вверх тормашками летят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСчастливо искупаться! С легким паром!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ остаюсь один на месте старом.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Отбиваясь от летающих роз.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрочь, светляки! Как вы там ни свети,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПоймаешь вас, нет ничего паскудней:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасплывчатое что-то вроде студня,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА обжигает, как смола почти.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнгелы  (хор)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем ни прикрашивай\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуха чужого,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРода не нашего\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭта основа.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТолько с любовью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛадит краса.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИм наготове\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВход в небеса.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорит печенка, сердце, голова,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот дьявольское, право, наважденье!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуда похлеще эти существа,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧем самый яростный огонь в геенне.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот отчего всегда так жалко вас,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесчастные влюбленные! Отказ\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВам не урок. Вы рады без ответа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотреть, свернувши шею, вслед предмету.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе то ль со мной? Уставившись в упор,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛюбуюсь тем, что было ненавистно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТого гляди на шее я повисну\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ тех, с кем враждовал я до сих пор!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой-то чуждый ток в меня проник.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПремилые какие мальчуганы!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХочу проклясть, не движется язык.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто в самом деле за исход нежданный?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь если я, дурак, еще разнежусь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто будет после зваться дураком?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАх, сорванцы! Чем я к вам так влеком,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто, кажется, в вас, ненавистных, врежусь.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкажите, дети милые, к примеру,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы тоже не родня ли Люциферу?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКрасавчики, я не могу сдержать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖеланья нежно вас расцеловать.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы встретились, я рад такой удаче,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРасчувствовавшись просто по-кошачьи,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак будто я на вас сто тысяч раз\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСмотрел, не отводя влюбленных глаз.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗачем нас разделяет расстоянье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриблизьтесь, если облик ваш так мил!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнгелы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы подошли, но сам ты отступил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе удаляйся, если в состоянье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнгелы, раздвигаясь вширь, постепенно занимают все пространство.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (оттесненный на просцениум)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы духами нас падшими зовете,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеж тем гораздо больше есть причин,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак колдунов, винить вас в привороте,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрельщающем и женщин и мужчин!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ, кажется, влюбился, что за притча!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПылает не спинной хребет один,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе тело у меня — огня добыча!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭй вы, народец вы такой-сякой!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДовольно реять вереницей гибкой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа землю станьте твердою ногой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХоть вам к лицу серьезность и покой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХотел бы видеть я у вас улыбку,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак, беглую, слегка, краями рта,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак улыбаться свойственно влюбленным.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМеня и эта скудная черта\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОставила б навеки восхищенным.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысокий мальчик, ты прелестней всех,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТебе лишь не подходит вид монаха.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА ну, на шее расстегни рубаху,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб промелькнул во взгляде томный грех.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОтвертываются! Я не в накладе!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСложенье их еще приятней сзади.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор ангелов\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПламенем ясным,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСветом прозренья\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПадшим несчастным\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай исцеленье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПусть одолеют\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗло и прозреют,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтоб благодать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС нами познать.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (спохватываясь)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО, что со мной! Как Иов, весь в нарывах,\u003ca class=\"ref\" id=\"r247\" href=\"#n247\" data-tip=\"№247 \u0026#183; Книга Иова\"\u003e247\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ страшен сам себе и все же горд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ радуюсь, уверившись, что черт —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ наследственных своих основах тверд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ спасся от соблазнов нечестивых.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗараза дальше кожи не пошла.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОгни отполыхали все дотла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ отрезвлен и всем вам без изъятья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак подобает, шлю свое проклятье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор ангелов\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПламя священное!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто им охвачен,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК жизни блаженной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДобра предназначен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоздух очищен.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБратья, в полет!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух сей похищенный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВольно вздохнет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Подымаются к небу, унося бессмертную сущность Фауста.)\u003ca class=\"ref\" id=\"r248\" href=\"#n248\" data-tip=\"№248 \u0026#183; О душе (Аристотель); Сумма теологии (Фома Аквинский) и др.\"\u003e248\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМефистофель  (оглядываясь кругом)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа крыльях унеслись, озорники!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА где душа? Украли воровски!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТак вот зачем, почуяв дух приманки,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОни у ямы вытянулись в ряд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ стерегли бесценные останки?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКакой удар! Но сам я виноват.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСо мной побившаяся об заклад\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦеною участи своей небесной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысокая душа, залог наград,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУкрадена из рук моих бесчестно.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКому теперь я жаловаться стану?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто за ущерб меня вознаградит?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа старости стать жертвою обмана!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо я позором поделом покрыт.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПогибло сразу все, единым махом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТруд стольких лет, надежды, тьма затрат!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазвесить уши пред толпой ребят\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВлюбленным, поглупевшим вертопрахом!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрожженный старый черт с такой закалкой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСыграл к концу такого дурака!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВедь эта глупость до того жалка,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто даже потерпевшего не жалко!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003ch2\u003e\u003ca class=\"ref blk\" id=\"r249\" href=\"#n249\" data-tip=\"№249 \u0026#183; Письмо В. Гумбольдта к Гёте; Жития отшельников Фиваиды (фреска Кампо-Санто) и др.\"\u003e249\u003c/a\u003eГорные ущелья, лес, скалы, пустыня\u003c/h2\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвятые отшельники, ютящиеся по ступенчатым уступам горы, по сторонам которой пропасти.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор и эхо\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКруча над кручею,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧаща дремучая\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС пнями, корягами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМхами, оврагами.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоды — живители\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПустынножителей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛьвы к ним у пропасти\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛастятся с кротостью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧтя сокровенное\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМесто священное.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003ePater ecstaticus. Отец восторженный  (поднимаясь и опускаясь в воздухе)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЖар сверхъестественный\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМуки божественной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСердце пронзи мое,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрастью палимое,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКопьями, стрелами,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТучами целыми.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКорка под палицей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТреснет, развалится,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМусор отвеется,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСущность зардеется,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЛьющая свет всегда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВечной любви звезда.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003ePater profundus. Отец углубленный  (в нижней области)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ высящиеся обрывы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНад бездной страшной глубины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ тысячи ручьев, шумливо\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНесущиеся с крутизны,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ стройность дерева в дуброве,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ мощь древесного ствола\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдушевляются любовью,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКоторая их создала.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ то же чудо, дива дивней,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОбрушивается с небес,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПотоками косого ливня\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКлоня шатающийся лес.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНет-нет и молния ударит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе слепнет на ее свету,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо более уже не парит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГром разгоняет духоту.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе эти громы, и лавины,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ ливни — вестники любви.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуши остывшей сердцевину\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрозой такой же оживи!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде дух мой пленный, как в темнице,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТомится в немощной плоти,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДай, боже, мыслям проясниться\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ сумрак сердца освети!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003ePater seraphicus.\u003ca class=\"ref\" id=\"r250\" href=\"#n250\" data-tip=\"№250 \u0026#183; Почётные титулы схоластов (Doctor Seraphicus и др.); Разговоры с Гёте (Эккерман)\"\u003e250\u003c/a\u003e Отец ангелоподобный  (в средней области)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто за облачко белеет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ глубине за сосняком?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДогадался, что там реет:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто юных духов сонм.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор блаженных младенцев\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде мы тут, отец, ответствуй,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКто мы, милый, вразуми,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМы, оставшиеся с детства\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНепорочными детьми.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003ePater seraphicus\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы, родившись в полночь, вскоре\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзяты маленькими в рай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля родителей на горе,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК радости крылатых стай.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСердце любящее чуя,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтаньте с этой стороны.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВы, по счастью, в жизнь земную\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе были посвящены.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо в глаза мои войдите,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ их вам даю взаймы.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Принимает их в себя.)\u003ca class=\"ref\" id=\"r251\" href=\"#n251\" data-tip=\"№251 \u0026#183; О небесах, о мире духов и об аде (Сведенборг)\"\u003e251\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИзнутри вовне смотрите:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот деревья, вот холмы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВот текущая средь леса\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ с крутого бугорка\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВодопадом вниз с отвеса\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРушащаяся река.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлаженные младенцы  (изнутри)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВид поистине могучий,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо пугает этот мрак.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыпусти нас вон, не мучай,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтрашно нам, святой добряк!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003ePater seraphicus\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодымайтесь кверху стаей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ растите без конца,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак мужает, вырастая,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух в присутствии творца.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭто духов пропитанье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВысшее их торжество:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРаствориться в созерцанье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯвленной любви его.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор блаженных младенцев  (кружащих вокруг высочайших вершин)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРуки протянем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСтанем кольцом,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГосподу грянем\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГромкий псалом!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт колыбели\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзятые им,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБога у цели\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУлицезрим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнгелы  (парят в высшей атмосфере, неся бессмертную сущность Фауста)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпасен высокий дух от зла\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПроизволеньем божьим:\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧья жизнь в стремлениях прошла,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТого спасти мы можем.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА за кого любви самой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХодатайство не стынет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТот будет ангелов семьей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРадушно в небе принят.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМладшие ангелы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРозами из рук смиренниц,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриносящих покаянье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВыиграно состязанье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПобежден был отщепенец.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаша сторона отбила\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДушу у нечистой силы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ бегство обратив лукавых\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ цветами закидав их.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВместо адских мук, с печалью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБоль любви они познали.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеред ней сдалась природа\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСатаны, их коновода.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн не снес ее укола.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМилосердье побороло.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБолее совершенные ангелы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОстанки несть в руках\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДля нас мученье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудь из асбеста прах,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн — жертва тленья.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух с веществом входил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ союз условный.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУ ангелов нет сил\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРвать связи кровной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНо двойственность пройдет,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ боль отляжет.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдна любовь с высот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРешит и вяжет.\u003ca class=\"ref\" id=\"r252\" href=\"#n252\" data-tip=\"№252 \u0026#183; Евангелие от Матфея; Первое послание к Коринфянам\"\u003e252\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМладшие ангелы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВон над вершиною\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЭтой скалистой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНечто невинное,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлед чей-то чистый.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМгла тонкостенная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в промежутке —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуши блаженные,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДети, малютки.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧуждые бремени\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорестей лишних,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДышат вне времени\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлавою в вышних.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОщупью шарящий\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух для начала\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПустим в товарищи\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК братии малой.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлаженные младенцы\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПримемте, братья,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ виде коко\u0026amp;#769;на\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eАнгела в платье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКуколки сонной.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТкани придаточной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСкинемте нити.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДух уж достаточно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВырос в развитье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eDoctor Marianus.\u0026#160;Возвеститель почитания богоматери  (в высочайшей чистейшей келье)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь вид открыт с высот\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ к высям дух уводит.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВон женщины в полет\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗа облака уходят.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСредь них, блестя каймой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвоею многозвездной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорит венец самой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВладычицы небесной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Восторженно.)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМиродержица, склонись\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ лицезримой тайне\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсей твоей, взнесенной ввысь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСиневой бескрайней!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлавословий не отринь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ от чувств наплыва\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоссылаю в эту синь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИх благочестиво.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБеззаветно верен дух\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоему приказу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы души любой недуг\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУмеряешь сразу.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПриснодеву, деву-мать,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГоспожу вселенной,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРадостно мне величать\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПеснью вдохновенной.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПрильнув с моленьем,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eК ее коленям,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорсть грешниц, каясь\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ здесь спасаясь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВзывает к тверди\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eО милосердье.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДева безневестная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы для жертв обмана\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПристанью небесною\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБудешь постоянно.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСлабых женщин скользок путь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде найти спасенье?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак самим им разомкнуть\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦепи искушенья?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКак не поскользнуться им\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНа дороге вязкой?\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНежный взгляд неотразим,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМанят лесть и ласка.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПарящая Mater gloriosa (Божья Матерь в славе небесной) движется навстречу.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eХор кающихся грешниц\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуши пристанище!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСвятою силой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОт боли ранящей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСпаси, помилуй!\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, беззакатная,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, благодатная!\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eMagna peccatrix. Великая грешница\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Ев. от Луки, 7, 36)\u003ca class=\"ref\" id=\"r254\" href=\"#n254\" data-tip=\"№254 \u0026#183; Евангелие от Луки\"\u003e254\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРади слез, что на пороге\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ роняла внутрь кувшина,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОмывая миром ноги\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТвоего святого сына,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДорогой амфоры ради\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ волос, которых шалой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГорько выбившейся прядью\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ потом их утирала, —\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eMulier Samaritana.\u003ca class=\"ref\" id=\"r255\" href=\"#n255\" data-tip=\"№255 \u0026#183; Евангелие от Иоанна\"\u003e255\u003c/a\u003e Жена Самарянская  ]\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРади пастбищ Авраама\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС бьющей родниковой жилой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГде водою тою самой\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЯ Спасителя поила,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРади чистого потока,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВылившегося оттуда\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ по всей земле широко\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРазбежавшегося всюду, —\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eMaria Aegyptiaca (Acta sanctorum).\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМария Египетская\u003ca class=\"ref\" id=\"r256\" href=\"#n256\" data-tip=\"№256 \u0026#183; Acta Sanctorum\"\u003e256\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003e(Ев. от Иоанна, 4)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРади той святой гробницы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВход куда был прегражден\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eМне незримою десницей,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eРади памятных времен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТех, когда я в покаянье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСорок лет жила в тоске\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ в пустыне завещанье\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаписала на песке, —\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе три\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы, что к осужденной грешной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС помощью всегда приходишь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eКающихся безутешно\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДо высот своих возводишь,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы и этой неповинной\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eГрешнице прости деянье,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ жизни только раз единый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСогрешившей по незнанью.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eUna pоеnitentium. Одна из кающихся, прежде называвшаяся Гретхен  (прижавшись к ним)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОплот мой правый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ сиянье славы,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСклони свой лик над счастием моим.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДавно любимый,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНевозвратимый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВернулся, горем больше не томим.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eБлаженные младенцы  (приближаясь круговым движением)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУж он шагнул вперед,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ, думать надо,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн нам за наш уход\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВоздаст наградой.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eС младенческих пелен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНас жизнь не давит,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eА этот вразумлен\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ нас наставит.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОдна из кающихся, прежде называвшаяся Гретхен\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСобраньем духов окруженный,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНе знает новичок того,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЧто ангельские легионы\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ нем видят брата своего.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eУже он чужд земным оковам\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ прежний свой покров сложил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВ воздушном одеянье новом\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eОн полон юношеских сил.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПозволь мне быть его вожатой,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЕго слепит безмерный свет.\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eMater gloriosa. Богоматерь\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eНаправься в высший круг. Объятый\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДогадкой, двинется он вслед.\u003ca class=\"ref\" id=\"r257\" href=\"#n257\" data-tip=\"№257 \u0026#183; Божественная комедия (Данте)\"\u003e257\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eDoctor Marianus. Ее провозвеститель  (молится, пав на лицо)\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eПодымите к небу взгляд,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДуши грешниц младших,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозведенные в разряд\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозрожденных падших.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТы ж их покаянья дань\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВозрасти сторицей\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИ заступницей им стань,\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eДева, мать, царица!\u003ca class=\"ref\" id=\"r253\" href=\"#n253\" data-tip=\"№253 \u0026#183; Лоретанская литания; Акафист Пресвятой Богородице\"\u003e253\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eChorus mysticus. Мистический хор\u003c/div\u003e\n\u003cdiv class=\"gap\"\u003e\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВсе быстротечное —\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eСимвол, сравненье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЦель бесконечная\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь — в достиженье.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eЗдесь — заповеданность\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eИстины всей.\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eВечная женственность\u003c/div\u003e\n\u003cdiv class=\"l\"\u003eТянет нас к ней.\u003ca class=\"ref\" id=\"r258\" href=\"#n258\" data-tip=\"№258 \u0026#183; Пир (Платон); Новая жизнь (Данте) и др.\"\u003e258\u003c/a\u003e\u003c/div\u003e\n\u003csection id=\"notes\"\u003e\u003ch2\u003eОтсылки\u003c/h2\u003e\u003cp class=\"sub\"\u003eВсего: 258. Нажмите номер в тексте, чтобы перейти сюда; «↑ К тексту» вернёт к той же кнопке.\u003c/p\u003e\n\u003ch3\u003e1. Посвящение, Театральное вступление и Пролог на небе (с. 1–9)\u003c/h3\u003e\n\u003cdiv class=\"note\" id=\"n1\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e1\u003c/span\u003e\u003cspan\u003eПосвящение, с. 1\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Им, не услышать следующих песен, / Кому я предыдущие читал\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Биографические материалы И. В. Гёте: \u0026#171;Поэзия и правда\u0026#187; (кн. XIII–XV), переписка Гёте и примечания к изданию (с. 364).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В 1770-е гг. Гёте читал ранние сцены (\u0026#171;Прафауста\u0026#187;) кругу близких; к 1797 г., когда писалось \u0026#171;Посвящение\u0026#187;, сестра Корнелия Шлоссер, критик И. Г. Мерк и поэт Я. М. Р. Ленц уже умерли, а Ф. Г. Клопшток, Ф. М. Клингер, братья Штольберги и И. Г. Гердер жили вдали или отдалились от него.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eПоэзия и правда (Гёте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r1\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n2\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e2\u003c/span\u003e\u003cspan\u003eПосвящение, с. 1\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Эоловою арфой прорыдало\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Одиссея\u0026#187; (песнь X, ст. 1–76 — Эол, хранитель ветров); ода С. Т. Кольриджа \u0026#171;Эолова арфа\u0026#187; (1795) и ода Ф. Г. Клопштока \u0026#171;Летняя ночь\u0026#187; / романтическая символика XVIII в.\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В \u0026#171;Одиссее\u0026#187; Эол завязывает ветры в мех для Одиссея; от его имени получил название струнный инструмент (эолова арфа), звучащий сам от порыва ветра и ставший в поэзии конца XVIII в. символом непроизвольного вдохновения.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОдиссея (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭолова арфа (Кольридж)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЛетняя ночь (Клопшток)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r2\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n3\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e3\u003c/span\u003e\u003cspan\u003eТеатральное вступление, с. 4\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Кто защита / Богам под сенью олимпийских рощ?\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Илиада\u0026#187; (песнь I, ст. 493–611; песнь VIII, ст. 1–52); Гесиод, \u0026#171;Теогония\u0026#187; (ст. 617–735).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В древнегреческом эпосе гора Олимп описана как резиденция верховных богов во главе с Зевсом, чьи деяния и величие сохраняются в памяти людей именно благодаря поэтам (о чём здесь говорит Поэт).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r3\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n4\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e4\u003c/span\u003e\u003cspan\u003eТеатральное вступление, с. 5\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ловите на ходу, в работе / Удобный случай за хохол\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Посидипп, эпиграмма в \u0026#171;Палатинской антологии\u0026#187; (кн. XVI, № 275 — о статуе Кайроса работы Лисиппа); Федр, \u0026#171;Басни\u0026#187; (кн. V, 8 — \u0026#171;Случай\u0026#187; / \u003cem\u003eOccasio\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Античный бог удачного мига Кайрос (в Риме \u003cem\u003eOccasio\u003c/em\u003e) изображался с густым чубом на лбу и абсолютно лысым затылком: схватить его за волосы можно только в момент приближения, а пропустив — уже не удержать.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eПалатинская антология (Посидипп)\u003c/span\u003e\u003cspan class=\"chip\"\u003eБасни (Федр)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r4\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n5\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e5\u003c/span\u003e\u003cspan\u003eТеатральное вступление, с. 6\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;В дощатом этом — балагане / Вы можете, как в мирозданье, / Пройдя все ярусы подряд, / Сойти с небес сквозь землю в ад\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Средневековый театр мистерий (напр., \u0026#171;Франкфуртская мистерия Страстей\u0026#187;, XV–XVI вв.) и пьеса П. Кальдерона \u0026#171;Великий театр мира\u0026#187; (\u003cem\u003eEl gran teatro del mundo\u003c/em\u003e, ок. 1635).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В средневековых мистериях сцена строилась по вертикали из трёх ярусов — Рай (небеса), Земля и Ад, что позволяло наглядно разыгрывать вселенскую драму спасения и гибели души.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eФранкфуртская мистерия Страстей\u003c/span\u003e\u003cspan class=\"chip\"\u003eВеликий театр мира (Кальдерон)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r5\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n6\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e6\u003c/span\u003e\u003cspan\u003eПролог на небе, с. 6–9\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eСцена \u0026#171;Пролог на небе\u0026#187; (встреча Бога и Мефистофеля, спор о Фаусте) и реплика \u0026#171;Он мой раб\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Книга Иова (Иов 1:6–12; 2:1–7); подтверждено в \u0026#171;Разговорах с Гёте\u0026#187; И. П. Эккермана (запись от 18 января 1825 г., с. 364).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В Книге Иова в день собрания сынов Божиих перед Господом является сатана, ставит под сомнение искренность веры праведного Иова (которого Бог называет \u0026#171;рабом Моим\u0026#187;, Иов 1:8) и получает разрешение испытать его.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Иова\u003c/span\u003e\u003cspan class=\"chip end\"\u003eРазговоры с Гёте (Эккерман)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r6\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n7\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e7\u003c/span\u003e\u003cspan\u003eПролог на небе, с. 6\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Три архангела: Рафаил, Гавриил, Михаил\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия: Книга Товита (Тов. 12:15 — Рафаил), Книга Даниила (Дан. 8:16; 10:13, 21 — Гавриил и Михаил), Евангелие от Луки (Лк. 1:19, 26 — Гавриил), Откровение (Откр. 12:7 — Михаил).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Трое библейских архангелов выступают перед престолом Всевышнего как хранители небесного порядка и вестники Его славы.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Товита\u003c/span\u003e\u003cspan class=\"chip end\"\u003eКнига пророка Даниила\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Луки\u003c/span\u003e\u003cspan class=\"chip end\"\u003eОткровение Иоанна Богослова\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r7\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n8\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e8\u003c/span\u003e\u003cspan\u003eПролог на небе, с. 6\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;В пространстве, хором сфер объятом, / Свой голос солнце подает\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Аристотель, трактат \u0026#171;О небе\u0026#187; (кн. II, гл. 9, 290b — изложение учения пифагорейцев); Платон, \u0026#171;Государство\u0026#187; (кн. X, 617b — миф об Эре); Цицерон, \u0026#171;Сон Сципиона\u0026#187; (\u0026#171;О государстве\u0026#187;, кн. VI, 18).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Согласно учению Пифагора (VI в. до н. э., с. 364–365), вращение небесных светил в космосе порождает совершенную, не слышимую смертными музыкальную гармонию.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eО небе (Аристотель)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГосударство (Платон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eСон Сципиона (Цицерон)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r8\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n9\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e9\u003c/span\u003e\u003cspan\u003eПролог на небе, с. 6\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Как в первый день, так и сегодня / Безмерна слава божьих дел\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Книга Бытия (Быт. 1:1–5).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Отсылка к первому дню сотворения мира, когда Бог создал свет и увидел, что он хорош.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Бытия\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r9\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n10\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e10\u003c/span\u003e\u003cspan\u003eПролог на небе, с. 7\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Он свиристит, как саранча\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u003cem\u003eПредположительная отсылка\u003c/em\u003e к Библии: Книга Чисел (Чис. 13:34) и Псалтирь (Пс. 108:23).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В Чис. 13:34 разведчики-израильтяне говорят, что перед великанами они казались \u0026#171;как саранча\u0026#187;, а в Пс. 108:23 страждущий человек сравнивается с изгоняемой саранчой. Мефистофель использует это сравнение, чтобы принизить разумного человека до насекомого.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Чисел\u003c/span\u003e\u003cspan class=\"chip end\"\u003eПсалтирь\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r10\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n11\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e11\u003c/span\u003e\u003cspan\u003eПролог на небе, с. 7\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;странно этот эскулап\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Пиндар, Пифийская ода III (ст. 1–58); Аполлодор, \u0026#171;Мифологическая библиотека\u0026#187; (кн. III, гл. 10, 3–4).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Асклепий (лат. Эскулап) — сын Аполлона, величайший целитель античности, овладевший даже воскрешением мёртвых. Его именем Мефистофель иронически называет врача Фауста.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eПифийская ода III (Пиндар)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМифологическая библиотека (Аполлодор)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r11\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n12\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e12\u003c/span\u003e\u003cspan\u003eПролог на небе, с. 8\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Жрать будет прах от башмака, / Как пресмыкается века / Змея, моя родная тетя\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Книга Бытия (Быт. 3:14).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e После грехопадения Адама и Евы Бог проклинает Змея-искусителя словами: \u0026#171;будешь ходить на чреве твоём, и будешь есть прах во все дни жизни твоей\u0026#187; (с. 365).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Бытия\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r12\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003ch3\u003e2. Первая часть. Сцены в кабинете и за городом (\u0026#171;Ночь\u0026#187; — \u0026#171;Рабочая комната Фауста\u0026#187;, с. 9–53)\u003c/h3\u003e\n\u003cdiv class=\"note\" id=\"n13\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e13\u003c/span\u003e\u003cspan\u003eНочь, с. 9\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я богословьем овладел, / Над философией корпел, / Юриспруденцию долбил / И медицину изучил\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Анонимная \u0026#171;История о докторе Иоганне Фаусте, знаменитом волшебнике и чернокнижнике\u0026#187; (изд. И. Шписа, 1587, гл. 1–2); Кристофер Марло, \u0026#171;Трагическая история доктора Фауста\u0026#187; (акт I, сц. 1, ок. 1592).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Традиционный зачин легенды о Фаусте: учёный проходит все четыре классических факультета средневекового университета (теология, философия/свободные искусства, право, медицина) и, разочаровавшись в них, обращается к магии.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИстория о докторе Иоганне Фаусте (Шпис)\u003c/span\u003e\u003cspan class=\"chip\"\u003eТрагическая история доктора Фауста (Марло)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r13\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n14\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e14\u003c/span\u003e\u003cspan\u003eНочь, с. 10\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Где феи с эльфами в тумане\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Вальтер Мап, \u0026#171;О забавах придворных\u0026#187; (\u003cem\u003eDe nugis curialium\u003c/em\u003e, XII в.); Якоб Гримм, \u0026#171;Немецкая мифология\u0026#187; (\u003cem\u003eDeutsche Mythologie\u003c/em\u003e, 1835, гл. XVII \u0026#171;Wichte und Elbe\u0026#187;); У. Шекспир, \u0026#171;Сон в летнюю ночь\u0026#187; (акт II–III).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Эльфы и феи в германо-кельтской традиции — природные духи полян и лесов, олицетворяющие живую стихию природы в противовес затхлой учёности.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eО забавах придворных (Вальтер Мап)\u003c/span\u003e\u003cspan class=\"chip\"\u003eНемецкая мифология (Гримм)\u003c/span\u003e\u003cspan class=\"chip\"\u003eСон в летнюю ночь (Шекспир)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r14\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n15\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e15\u003c/span\u003e\u003cspan\u003eНочь, с. 10\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Творенье Нострадама взять\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Мишель де Нострдам (Нострадамус), книга пророчеств \u0026#171;Центурии\u0026#187; (\u003cem\u003eLes Proph\u0026#233;ties / Centuries\u003c/em\u003e, Лион, 1555).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Реальный французский врач и астролог XVI в. (с. 365); Фауст использует книгу с его именем как магический гримуар, открывающий тайные связи космоса.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЦентурии (Нострадамус)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r15\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n16\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e16\u003c/span\u003e\u003cspan\u003eНочь, с. 11\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;(Открывает книгу и видит знак макрокосма.)\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Генрих Корнелий Агриппа Неттесгеймский, \u0026#171;Оккультная философия\u0026#187; (\u003cem\u003eDe occulta philosophia\u003c/em\u003e, 1533, кн. II–III); Парацельс, \u0026#171;Философия оккультная\u0026#187; / \u0026#171;Великая астрономия\u0026#187; (\u003cem\u003eAstronomia magna\u003c/em\u003e, 1537); Э. Сведенборг, \u0026#171;Небесные тайны\u0026#187; (\u003cem\u003eArcana Coelestia\u003c/em\u003e, 1749–1756).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В ренессансном герметизме и у Сведенборга (с. 365) макрокосм — Вселенная как единый живой организм, гармонически связанный с человеком (микрокосмом); графически передавался гексаграммой (\u0026#171;печатью Соломона\u0026#187;).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОккультная философия (Агриппа)\u003c/span\u003e\u003cspan class=\"chip\"\u003eВеликая астрономия (Парацельс)\u003c/span\u003e\u003cspan class=\"chip\"\u003eНебесные тайны (Сведенборг)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r16\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n17\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e17\u003c/span\u003e\u003cspan\u003eНочь, с. 11\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;\u0026quot;Мир духов рядом, дверь не на запоре, / Но сам ты слеп, и все в тебе мертво. / Умойся в утренней заре, как в море, / Очнись, вот этот мир, войди в него\u0026quot;\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Эммануил Сведенборг, \u0026#171;Небесные тайны\u0026#187; (\u003cem\u003eArcana Coelestia\u003c/em\u003e, 1749–1756) и \u0026#171;О небесах, о мире духов и об аде\u0026#187; (\u003cem\u003eDe caelo et eius mirabilibus\u003c/em\u003e, 1758).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Поэтический пересказ тезисов Сведенборга (см. с. 365): мир духов не отделён от нас пространством и открыт тем, кто пробудил внутреннее духовное зрение; заря символизирует вечное духовное обновление.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eНебесные тайны (Сведенборг)\u003c/span\u003e\u003cspan class=\"chip\"\u003eО небесах, о мире духов и об аде (Сведенборг)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r17\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n18\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e18\u003c/span\u003e\u003cspan\u003eНочь, с. 11\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;тысяча существ крылатых / Поочередно подает / Друг другу в золотых ушатах / И вверх снует и вниз снует\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Книга Бытия (Быт. 28:12 — сон Иакова о лестнице до неба и сходящих/восходящих ангелах); Антон Йозеф Кирхвегер, алхимический трактат \u0026#171;Золотая цепь Гомера\u0026#187; (\u003cem\u003eAurea Catena Homeri\u003c/em\u003e, 1723, ч. I — об \u0026#171;оживляющей цепи\u0026#187; стихий).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Соединение библейского видения лестницы Иакова с популярной в XVIII в. алхимической концепцией (книгу Кирхвегера Гёте подробно изучал в молодости, о чём писал в \u0026#171;Поэзии и правде\u0026#187;, кн. VIII) о непрерывном круговороте сил между небом и землёй.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Бытия\u003c/span\u003e\u003cspan class=\"chip\"\u003eЗолотая цепь Гомера (Кирхвегер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r18\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n19\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e19\u003c/span\u003e\u003cspan\u003eНочь, с. 13\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;И ткацкий стан / С волшебной нитью, / Где, времени кинув сквозную канву, / Живую одежду я тку божеству\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Бенедикт Спиноза, \u0026#171;Этика\u0026#187; (ч. I, теор. 15, 29 — \u003cem\u003eDeus sive Natura\u003c/em\u003e, \u0026#171;Бог, то есть Природа\u0026#187;, и \u003cem\u003eNatura naturans\u003c/em\u003e); Библия, Псалтирь (Пс. 103:2 — \u0026#171;Ты одеваешься светом, как ризою\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Дух Земли выступает как имманентная творческая сила природы (в духе пантеизма Спинозы), созидающая изменчивый мир явлений как \u0026#171;живую одежду\u0026#187; единого Божества.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЭтика (Спиноза)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eПсалтирь\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r19\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n20\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e20\u003c/span\u003e\u003cspan\u003eНочь, с. 13\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я, образ и подобье божье\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Книга Бытия (Быт. 1:26–27).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Дословное воспроизведение библейской формулы сотворения человека по образу и подобию Божию.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Бытия\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r20\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n21\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e21\u003c/span\u003e\u003cspan\u003eНочь, с. 13\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;не из греческих трагедий / Вы только что читали монолог?\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Классическая аттическая трагедия (Эсхил, Софокл, Еврипид — V в. до н. э.) и практика университетской риторики XVIII в.\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Педант Вагнер воспринимает экстатическую беседу Фауста с Духом Земли как заученную декламацию античной драмы ради совершенствования ораторского искусства.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eАттическая трагедия (Эсхил, Софокл, Еврипид)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r21\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n22\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e22\u003c/span\u003e\u003cspan\u003eНочь, с. 15\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Нам не сломить ее семи печатей\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Новый Завет — Откровение Иоанна Богослова (Откр. 5:1–5).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В Апокалипсисе за семью печатями заперта книга тайн Божиих и человеческой судьбы, которую никто не может открыть, кроме Агнца.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eОткровение Иоанна Богослова\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r22\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n23\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e23\u003c/span\u003e\u003cspan\u003eНочь, с. 15\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Немногих, проникавших в суть вещей... Сжигали на кострах и распинали\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Евангелия (Мф. 27:35 — распятие Иисуса Христа); исторические процессы и казни мыслителей (приговор Констанцского собора Яну Гусу 1415 г., инквизиционный приговор Джордано Бруно 1600 г., казнь Мигеля Сервета 1553 г.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Фауст обобщает исторические расправы церкви и власти над теми, кто бросал вызов догмам и открывал людям истину.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Матфея\u003c/span\u003e\u003cspan class=\"chip end\"\u003eПриговор Яну Гусу (1415)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eПриговор Джордано Бруно (1600)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eКазнь Мигеля Сервета (1553)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r23\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n24\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e24\u003c/span\u003e\u003cspan\u003eНочь, с. 17\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я червь слепой, я пасынок природы\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет: Книга Иова (Иов 25:6 — \u0026#171;тем менее человек, который есть червь\u0026#187;) и Псалтирь (Пс. 21:7 — \u0026#171;Я же червь, а не человек\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Традиционная библейская метафора смертного ничтожества человека, контрастирующая с недавней гордыней Фауста (\u0026#171;я, образ и подобье божье\u0026#187;).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Иова\u003c/span\u003e\u003cspan class=\"chip end\"\u003eПсалтирь\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r24\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n25\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e25\u003c/span\u003e\u003cspan\u003eНочь, с. 17\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ты, голый череп посреди жилья!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u003cem\u003eПредположительная отсылка\u003c/em\u003e к трагедии У. Шекспира \u0026#171;Гамлет\u0026#187; (акт V, сц. 1 — монолог над черепом Йорика) и к иконографии \u003cem\u003eVanitas\u003c/em\u003e / \u003cem\u003eMemento mori\u003c/em\u003e (напр., гравюра А. Дюрера \u0026#171;Святой Иероним в келье\u0026#187;, 1514).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Череп на столе учёного служит традиционным символом тщеты земных знаний перед лицом смерти.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eГамлет (Шекспир)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eСвятой Иероним в келье (Дюрер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r25\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n26\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e26\u003c/span\u003e\u003cspan\u003eНочь, с. 18\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Слетает огненная колесница\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Четвёртая книга Царств (4 Цар. 2:11 — вознесение пророка Илии в огненной колеснице с огненными конями).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Фауст видит в самоубийстве не гибель, а триумфальное восхождение в иные миры, подобное вознесению пророка Илии.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЧетвёртая книга Царств\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r26\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n27\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e27\u003c/span\u003e\u003cspan\u003eНочь, с. 18–20\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Хор ангелов: Христос воскрес!\u0026#187; / \u0026#171;Хор мироносиц\u0026#187; / \u0026#171;Хор учеников\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Евангелия (Мф. 28:1–10; Мк. 16:1–8; Лк. 24:1–12; Ин. 20:1–18 — погребение Христа в благовониях, приход жён-мироносиц к пустому гробу, вознесение к Отцу) и католическая пасхальная секвенция \u003cem\u003eVictimae paschali laudes\u003c/em\u003e (XI в., приписывается Випону Бургундскому).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Пасхальный крестный ход и песнопения воссоздают литургический диалог ангелов, мироносиц и учеников в пасхальную ночь (с. 365).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Матфея\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Марка\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Луки\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Иоанна\u003c/span\u003e\u003cspan class=\"chip end\"\u003eVictimae paschali laudes\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r27\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n28\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e28\u003c/span\u003e\u003cspan\u003eУ ворот, с. 22\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Как в Турции далекой, где война, / Сражаются друг с другом ополченья\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Хроники и публицистика Австро-турецких войн XVI–XVIII вв. (от походов Сулеймана Великолепного и сочинения М. Лютера \u0026#171;О войне против турка\u0026#187;, 1529, до австро-турецкой войны 1787–1791 гг.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Реплика горожанина отражает многовековой бытовой интерес немецких бюргеров к далёким войнам с Османской империей.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eХроники австро-турецких войн\u003c/span\u003e\u003cspan class=\"chip\"\u003eО войне против турка (Лютер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r28\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n29\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e29\u003c/span\u003e\u003cspan\u003eУ ворот, с. 26\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Там звали \u0026#171;лилиею\u0026#187; серебро, / \u0026#171;Львом\u0026#187; — золото, а смесь их — связью в браке. / Полученное на огне добро, / \u0026#171;Царицу\u0026#187;, мыли в холодильном баке\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Алхимические трактаты XVI–XVII вв.: \u0026#171;Триумфальная колесница антимония\u0026#187; и \u0026#171;Двенадцать ключей\u0026#187; Василия Валентина, а также \u0026#171;Opus Mago-Cabbalisticum et Theosophicum\u0026#187; Георга фон Веллинга (1735 — книгу изучал молодой Гёте).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В алхимии \u0026#171;Белая лилия\u0026#187; означала очищенное серебро/ртуть, \u0026#171;Красный лев\u0026#187; — золото/серу, их соединение — \u0026#171;химический брак\u0026#187;, а получаемый препарат (\u0026#171;царица\u0026#187; — красная тинктура) должен был стать панацеей, но на деле часто отравлял больных ртутью и сурьмой.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТриумфальная колесница антимония (Василий Валентин)\u003c/span\u003e\u003cspan class=\"chip\"\u003eДвенадцать ключей (Василий Валентин)\u003c/span\u003e\u003cspan class=\"chip\"\u003eOpus Mago-Cabbalisticum (Веллинг)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r29\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n30\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e30\u003c/span\u003e\u003cspan\u003eУ ворот, с. 28\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Но две души живут во мне, / И обе не в ладах друг с другом\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Платон, диалог \u0026#171;Федр\u0026#187; (246a–254e — миф о душе-колеснице с белым возвышенным и чёрным земным конём); Новый Завет, Послание к Римлянам (Рим. 7:15–23 — борьба закона ума и закона плоти).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Классическая концепция раздвоенности человеческой природы между земной страстью и небесным порывом.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eФедр (Платон)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eПослание к Римлянам\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r30\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n31\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e31\u003c/span\u003e\u003cspan\u003eУ ворот, с. 28\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Не призывайте лучше никогда / Существ, живущих в воздухе и ветре... То демон севера...\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Агриппа Неттесгеймский, \u0026#171;Оккультная философия\u0026#187; (кн. I, гл. 20; кн. III, гл. 16–20 — о стихийных духах воздуха и ветрах четырёх сторон света); Михаил Пселл, трактат \u0026#171;О действии демонов\u0026#187; (XI в.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Вагнер пересказывает средневековую демонологию, связывавшую болезни (простуды, чахотку, солнечный удар) с кознями воздушных духов, приносимых ветрами.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОккультная философия (Агриппа)\u003c/span\u003e\u003cspan class=\"chip\"\u003eО действии демонов (Пселл)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r31\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n32\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e32\u003c/span\u003e\u003cspan\u003eУ ворот, с. 28\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Заметил, черный пес бежит по пашне?\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u0026#171;История о докторе Иоганне Фаусте\u0026#187; (изд. И. Шписа, 1587) и \u0026#171;Правдивые и ужасные истории о докторе Фаусте\u0026#187; И. Я. Фиценцера (1674); собрание поверий \u0026#171;Handw\u0026#246;rterbuch des deutschen Aberglaubens\u0026#187; (ст. \u003cem\u003eHund\u003c/em\u003e, \u003cem\u003ePudel\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В народной книге Фауста сопровождал чёрт в виде чёрного пса по кличке Престигиар (в книге с опечаткой \u0026#171;Прехтигиар\u0026#187;, с. 366), а в немецких суевериях чёрный пудель считался частым обличьем дьявола.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИстория о докторе Иоганне Фаусте (Шпис)\u003c/span\u003e\u003cspan class=\"chip\"\u003eПравдивые истории о докторе Фаусте (Фиценцер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eHandw\u0026#246;rterbuch des deutschen Aberglaubens\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r32\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n33\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e33\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 31\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;В начале было Слово\u0026#187;... \u0026#171;В начале мысль была\u0026#187;... \u0026#171;Была в начале сила\u0026#187;... \u0026#171;В начале было дело\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Новый Завет — Евангелие от Иоанна (Ин. 1:1); И. Г. Гердер, \u0026#171;Комментарии к Новому завету\u0026#187; / \u0026#171;О даре языков\u0026#187; (\u003cem\u003eVon der Gabe der Sprachen\u003c/em\u003e, 1794).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Фауст переводит греческое \u003cem\u003eΛόγος\u003c/em\u003e, следуя филологическому комментарию Гердера (с. 366), который указывал, что немецкое \u003cem\u003eWort\u003c/em\u003e (\u0026#171;слово\u0026#187;) слишком узко для \u003cem\u003eLogos\u003c/em\u003e, включающего в себя и \u0026#171;смысл\u0026#187;, \u0026#171;волю\u0026#187;, \u0026#171;дело\u0026#187;.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Иоанна\u003c/span\u003e\u003cspan class=\"chip\"\u003eО даре языков (Гердер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r33\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n34\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e34\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 31\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Раскрыла пасть, как бегемот\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Книга Иова (Иов 40:10–19); трактат Иоганна Вейера \u0026#171;О кознях бесов\u0026#187; (\u003cem\u003eDe praestigiis daemonum\u003c/em\u003e, 1563 — классификация демонов, \u0026#171;Псевдомонархия\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В Книге Иова Бегемот описан как могучее первобытное чудовище, а в ренессансной демонологии стал именем одного из сильнейших демонов.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Иова\u003c/span\u003e\u003cspan class=\"chip\"\u003eО кознях бесов (Вейер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r34\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n35\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e35\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 31\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Совет, как пакость обуздать, / \u0026#171;Ключ Соломона\u0026#187; может дать\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Магический гримуар \u0026#171;Ключ Соломона\u0026#187; (\u003cem\u003eClavicula Salomonis\u003c/em\u003e, списки XIV–XVII вв., широко распространённые в Европе XVIII в.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Подлинный средневековый сборник заклинаний, приписываемый царю Соломону и содержащий ритуалы подчинения и изгнания духов (с. 366).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКлюч Соломона\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r35\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n36\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e36\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 32\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Саламандра, жгись, / Ундина, вейся, / Сильф, рассейся, / Кобольд, трудись!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Теофраст Парацельс, трактат \u0026#171;Книга о нимфах, сильфах, пигмеях и саламандрах и о прочих духах\u0026#187; (\u003cem\u003eLiber de nymphis, sylphis, pygmaeis et salamandris et de caeteris spiritibus\u003c/em\u003e, опубл. 1566).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Парацельс систематизировал учение о четырёх элементальных духах стихий: саламандры (огонь), ундины/нимфы (вода), сильфы (воздух), кобольды/пигмеи (земля) (с. 366).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eКнига о нимфах, сильфах, пигмеях и саламандрах (Парацельс)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r36\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n37\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e37\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 32–33\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Прочтешь ли ты имя, / Осилишь ли знак / Несотворенного, / Неизреченного, / С неба сошедшего, в лето Пилатово / Нашего ради спасенья распятого?\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Никео-Цареградский Символ веры (381 г.) и Библия, Книга Исход (Исх. 3:14; 20:7 — непроизносимое имя Бога YHWH); католический \u0026#171;Римский ритуал\u0026#187; (\u003cem\u003eRituale Romanum\u003c/em\u003e, 1614, чин экзорцизма).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Фауст пускает в ход высший обряд изгнания беса — пересказывает формулу Символа веры о воплощении и распятии Христа при Понтии Пилате и показывает распятие (или монограмму IHS).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eНикео-Цареградский Символ веры\u003c/span\u003e\u003cspan class=\"chip end\"\u003eКнига Исход\u003c/span\u003e\u003cspan class=\"chip end\"\u003eРимский ритуал\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r37\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n38\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e38\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 33\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я троицей сожгу / Тебя триипостасной!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Афанасиев Символ веры (\u003cem\u003eQuicumque vult\u003c/em\u003e) и постановления Первого Никейского собора (325 г.) о Святой Троице; \u0026#171;Римский ритуал\u0026#187; (чин экзорцизма).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Призыв имени триединого Бога — кульминация средневекового заклинания против нечистой силы.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eАфанасиев Символ веры\u003c/span\u003e\u003cspan class=\"chip end\"\u003eПервый Никейский собор\u003c/span\u003e\u003cspan class=\"chip end\"\u003eРимский ритуал\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r38\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n39\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e39\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 33\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Мушиный царь, обманщик, враг, обидчик\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия: Четвёртая книга Царств (4 Цар. 1:2 — Баал-Зебуб, \u0026#171;бог мух\u0026#187;), Евангелие от Матфея (Мф. 12:24 — Вельзевул), Откровение (Откр. 12:9–10 — дьявол \u0026#171;клеветник\u0026#187; и сатана \u0026#171;противник/враг\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Перечень буквальных значений ветхозаветных и новозаветных имён дьявола.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЧетвёртая книга Царств\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Матфея\u003c/span\u003e\u003cspan class=\"chip end\"\u003eОткровение Иоанна Богослова\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r39\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n40\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e40\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 35\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ты испугался пентаграммы?\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Агриппа Неттесгеймский, \u0026#171;Оккультная философия\u0026#187; (кн. II, гл. 23; кн. III); Парацельс, \u0026#171;Архидоксы магии\u0026#187; (\u003cem\u003eArchidoxis magica\u003c/em\u003e); Якоб Гримм, \u0026#171;Немецкая мифология\u0026#187; (гл. XXXV — \u003cem\u003eDrudenfuss\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Пятиконечная звезда без разрывов (\u003cem\u003eDrudenfuss\u003c/em\u003e — \u0026#171;ведьмина стопа\u0026#187;) в народной магии чертилась на порогах как преграда против ведьм и бесов.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОккультная философия (Агриппа)\u003c/span\u003e\u003cspan class=\"chip\"\u003eАрхидоксы магии (Парацельс)\u003c/span\u003e\u003cspan class=\"chip\"\u003eНемецкая мифология (Гримм)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r40\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n41\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e41\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 38\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Царь крыс, лягушек и мышей, / Клопов, и мух, и жаб, и вшей\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия (Исх. 8:1–24 — казни египетские: жабы, мошки, пёсьи мухи; Мф. 12:24 — Вельзевул, \u0026#171;повелитель мух\u0026#187;) и немецкие народные предания о Крысолове и \u0026#171;Крысином короле\u0026#187; (\u003cem\u003eRattenk\u0026#246;nig\u003c/em\u003e, ср. у братьев Гримм).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Мефистофель пародийно величает себя царём мелких гадов и вредителей, отсылая к титулу \u0026#171;мушиного царя\u0026#187; Вельзевула.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Исход\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Матфея\u003c/span\u003e\u003cspan class=\"chip end\"\u003eНемецкие саги (братья Гримм)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r41\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n42\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e42\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 39\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;На шляпе петушиное перо\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Немецкие народные поверья о внешности дьявола, зафиксированные в \u0026#171;Немецкой мифологии\u0026#187; Якоба Гримма (гл. XXXIII \u0026#171;Teufel\u0026#187;) и в \u0026#171;Handw\u0026#246;rterbuch des deutschen Aberglaubens\u0026#187; (ст. \u003cem\u003eTeufel\u003c/em\u003e, \u003cem\u003eHahnenfeder\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В позднесредневековом немецком фольклоре дьявол часто являлся в образе франтоватого охотника (\u003cem\u003eJ\u0026#228;ger\u003c/em\u003e) или дворянина в красном плаще со шпагой и петушиным пером на шляпе.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eНемецкая мифология (Гримм)\u003c/span\u003e\u003cspan class=\"chip\"\u003eHandw\u0026#246;rterbuch des deutschen Aberglaubens\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r42\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n43\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e43\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 41\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Кляну Маммона, власть наживы\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Новый Завет — Евангелие от Матфея (Мф. 6:24) и от Луки (Лк. 16:13).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В Нагорной проповеди Христос говорит: \u0026#171;Не можете служить Богу и маммоне\u0026#187; (арамейскому идолу богатства).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Матфея\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Луки\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r43\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n44\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e44\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 41\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Оставь заигрывать с тоской своей, / Точащею тебя, как коршун злобный\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u003cem\u003eПредположительная отсылка\u003c/em\u003e к Эсхилу (\u0026#171;Прикованный Прометей\u0026#187;, ст. 1021–1025) и Гесиоду (\u0026#171;Теогония\u0026#187;, ст. 523–525).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В мифе о Прометее прилетевший орёл/коршун ежедневно клюёт печень прикованного титана; этот образ стал метафорой самоистязающей тоски.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eПрикованный Прометей (Эсхил)\u003c/span\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r44\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n45\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e45\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 44\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Изволь тут расписаться каплей крови\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u0026#171;История о докторе Иоганне Фаусте\u0026#187; (изд. И. Шписа, 1587, гл. 6 — \u0026#171;Доктор Фауст подписывает обязательство собственной кровью\u0026#187;); средневековая легенда о Феофиле Аданском (VI в., стихотворная драма Хросвиты Гандерсгеймской X в. и \u0026#171;Золотая легенда\u0026#187; Иакова Ворагинского).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Договор с дьяволом, скреплённый собственной кровью вместо чернил, — центральный канонический мотив всех обработок легенды о Фаусте.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИстория о докторе Иоганне Фаусте (Шпис)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЗолотая легенда (Иаков Ворагинский)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЛегенда о Феофиле (Хросвита Гандерсгеймская)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r45\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n46\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e46\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 44\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Кровь, надо знать, совсем особый сок\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Книга Левит (Лев. 17:11, 14) и Второзаконие (Втор. 12:23).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Древняя библейская формула (\u0026#171;душа всякого тела есть кровь его\u0026#187;) объясняет магическую силу кровной подписи.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Левит\u003c/span\u003e\u003cspan class=\"chip end\"\u003eВторозаконие\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r46\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n47\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e47\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 48\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Таких, как я, здесь легион\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Новый Завет — Евангелие от Марка (Мк. 5:9) и от Луки (Лк. 8:30).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Ответ беса из гадаринского бесноватого на вопрос Христа об имени: \u0026#171;Легион имя мне, потому что нас много\u0026#187;.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Марка\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Луки\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r47\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n48\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e48\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 49\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Encheiresis naturae\u0026#187; — вот / Как это химия зовет\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Лекции и учебники по химии XVIII в. — в частности, курс страсбургского профессора Якоба Рейнгольда Шпильмана \u0026#171;Institutiones chemiae\u0026#187; (1763, которые слушал Гёте в 1770–1771 гг.) и книга Г. Бургаве \u0026#171;Elementa chemiae\u0026#187; (1732).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Термин \u003cem\u003eencheiresis naturae\u003c/em\u003e (букв. \u0026#171;хват / приём природы\u0026#187;, с. 366) обозначал таинственный способ, которым природа соединяет элементы в живое вещество, недоступный механическому расчленению.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eInstitutiones chemiae (Шпильман)\u003c/span\u003e\u003cspan class=\"chip\"\u003eElementa chemiae (Бургаве)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r48\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n49\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e49\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 52\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Теория, мой друг, суха, / Но зеленеет жизни древо\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия: Книга Бытия (Быт. 2:9 — \u0026#171;дерево жизни посреди рая\u0026#187;) и Книга Притчей Соломоновых (Притч. 3:18 — \u0026#171;она — древо жизни для тех, которые приобретают её\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Мефистофель противопоставляет сухую схоластику живому жизненному опыту, используя библейский образ \u0026#171;древа жизни\u0026#187;.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Бытия\u003c/span\u003e\u003cspan class=\"chip end\"\u003eКнига Притчей Соломоновых\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r49\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n50\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e50\u003c/span\u003e\u003cspan\u003eРабочая комната Фауста, с. 53\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Eritis sicut Deus, scientes bonum et malum\u0026#187; / \u0026#171;Змеи, моей прабабки, следуй изреченью\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Книга Бытия (Быт. 3:5, точная цитата из латинского перевода — Вульгаты).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Обещание Змея Еве в Эдеме: \u0026#171;будете, как боги, знающие добро и зло\u0026#187; (с. 366), которым Мефистофель с издёвкой благословляет наивного студента.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Бытия\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r50\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003ch3\u003e3. Первая часть. От \u0026#171;Погреба Ауэрбаха\u0026#187; до \u0026#171;Тюрьмы\u0026#187; (с. 54–146)\u003c/h3\u003e\n\u003cdiv class=\"note\" id=\"n51\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e51\u003c/span\u003e\u003cspan\u003eс. с. 54–66\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eСцена \u0026#171;Погреб Ауэрбаха в Лейпциге\u0026#187; (добывание вина из стола, иллюзия виноградника, бегство \u0026#171;верхом на бочке\u0026#187; на с. 66)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Настенные картины XVII в. в реальном \u0026#171;Погребе Ауэрбаха\u0026#187; в Лейпциге (изображавшие пирушку Фауста и его вылет на винной бочке) и \u0026#171;История о докторе Иоганне Фаусте\u0026#187; (изд. И. Шписа, 1587, или расширенная редакция Г. Р. Видмана 1599 г. / Н. Пфицера 1674 г.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В народной книге и в лейпцигском предании оба фокуса (сверление стола ради вина и морок с виноградными гроздьями, когда гуляки хватают друг друга за носы вместо ягод) совершал сам Фауст; Гёте передал их Мефистофелю (с. 366).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eФрески Погреба Ауэрбаха\u003c/span\u003e\u003cspan class=\"chip\"\u003eИстория о докторе Иоганне Фаусте (Шпис)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r51\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n52\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e52\u003c/span\u003e\u003cspan\u003eПогреб Ауэрбаха, с. 55\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Всей Римскою империей священной / Мы долго устоим ли во вселенной?\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Политико-правовые трактаты о кризисе Священной Римской империи германской нации — напр., Самуэль Пуфендорф, \u0026#171;О состоянии Германской империи\u0026#187; (1667, назвавший империю \u0026#171;неправильным телом, подобным чудовищу\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Пародия на студенческие политические куплеты о дряхлении раздробленной Германской империи, существовавшей формально до 1806 г.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eО состоянии Германской империи (Пуфендорф)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r52\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n53\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e53\u003c/span\u003e\u003cspan\u003eПогреб Ауэрбаха, с. 55\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я предлагаю выбрать папу / Порядком, утвержденным встарь\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Легенда о папессе Иоанне (хроника Мартина Опавского / Полонуса \u0026#171;Chronicon pontificum et imperatorum\u0026#187;, XIII в.) и студенческие застольные обычаи (описаны в \u0026#171;Поэзии и правде\u0026#187; Гёте и студенческих уставах XVII–XVIII вв.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Согласно средневековой легенде о женщине, обманом занявшей папский престол под именем Иоанна VIII в IX в., при избрании нового папы якобы проверяли его пол на прорезном стуле (\u003cem\u003esella stercoraria\u003c/em\u003e); студенты перенесли этот сюжет в шутовское избрание \u0026#171;короля/папы попойки\u0026#187; (с. 366–367).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eХроника Мартина Опавского\u003c/span\u003e\u003cspan class=\"chip\"\u003eПоэзия и правда (Гёте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r53\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n54\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e54\u003c/span\u003e\u003cspan\u003eПогреб Ауэрбаха, с. 55\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Соловей ты мой, звеня, / Взвейся к небосклону\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Немецкая народная любовная песня XVI в. \u003cem\u003e\u0026#171;Schwing dich auf, Frau Nachtigall\u0026#187;\u003c/em\u003e (публиковалась в песеннике \u003cem\u003eAmbraser Liederbuch\u003c/em\u003e, 1582; позднее в собрании Л. Уланда).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Фрош поёт начальные строки популярной песни, где соловей выступает вестником любви к возлюбленной (с. 367).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eSchwing dich auf, Frau Nachtigall (народная песня)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eAmbraser Liederbuch\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r54\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n55\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e55\u003c/span\u003e\u003cspan\u003eПогреб Ауэрбаха, с. 55\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ей с Блоксберга проблеет сатана\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Иоганн Преториус, \u0026#171;Blockes-Berges Verrichtung\u0026#187; (1668); Якоб Гримм, \u0026#171;Немецкая мифология\u0026#187; (гл. XXXIV \u0026#171;Hexen\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e По немецким преданиям, на вершине горы Брокен (Блоксберг) в Гарце собираются ведьмы на шабаш, где поклоняются сатане в облике чёрного козла.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eBlockes-Berges Verrichtung (Преториус)\u003c/span\u003e\u003cspan class=\"chip\"\u003eНемецкая мифология (Гримм)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r55\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n56\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e56\u003c/span\u003e\u003cspan\u003eПогреб Ауэрбаха, с. 56\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Как Лютер, с салом на брюшке\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Биографические свидетельства и портреты Мартина Лютера позднего периода (напр., портреты Лукаса Кранаха Старшего 1530–1540-х гг. и \u0026#171;Застольные речи\u0026#187; Лютера).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Католическая и светская сатира XVI–XVIII вв. часто высмеивала тучность Лютера и его любовь к хорошей еде и пиву.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eПортреты Лютера (Кранах)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЗастольные речи (Лютер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r56\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n57\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e57\u003c/span\u003e\u003cspan\u003eПогреб Ауэрбаха, с. 57\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;А Лейпциг — маленький Париж\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Мемуары И. В. Гёте \u0026#171;Поэзия и правда\u0026#187; (ч. II, кн. VI — описание студенческих лет в Лейпциге 1765–1768 гг.) и путеводители XVIII в. по Саксонии.\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Лейпциг в XVIII в. славился ярмарками, университетом и галантными манерами по французскому образцу, из-за чего имел устойчивое прозвище \u0026#171;маленький Париж\u0026#187;.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eПоэзия и правда (Гёте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r57\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n58\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e58\u003c/span\u003e\u003cspan\u003eПогреб Ауэрбаха, с. 58\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Он на ногу одну как будто хром\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Раннехристианские апокрифы и фольклорные предания (Я. Гримм, \u0026#171;Немецкая мифология\u0026#187;, гл. XXXIII; отголосок мифа о хромом Гефесте, сброшенном с неба — Гомер, \u0026#171;Илиада\u0026#187;, I, 590–594).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В народных сказаниях дьявол хромает, потому что сломал ногу при низвержении с небес в преисподнюю (с. 367).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eНемецкая мифология (Гримм)\u003c/span\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r58\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n59\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e59\u003c/span\u003e\u003cspan\u003eПогреб Ауэрбаха, с. 58\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;С Иванушкою-дурачком видались?\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Саксонская студенческая поговорка о вымышленном \u0026#171;Гансе из Риппаха\u0026#187; (в оригинале \u003cem\u003eHans Arsch von Rippach\u003c/em\u003e, от названия реальной деревни Риппах под Лейпцигом — зафиксировано в студенческих словарях XVIII в.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Традиционная шутка-поддёвка лейпцигских студентов над приезжими провинциалами (передана Пастернаком через русский фольклорный эквивалент).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eСаксонские студенческие словари XVIII в.\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r59\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n60\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e60\u003c/span\u003e\u003cspan\u003eПогреб Ауэрбаха, с. 63\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Как в луже свиньям пятистам!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u003cem\u003eПредположительная отсылка\u003c/em\u003e к Библии (Евангелие от Марка, Мк. 5:11–13 — легион бесов вселяется в стадо свиней) в соединении со студенческим бурсацким выражением XVIII в.\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Упоение пьяных гуляк бесовским вином уподоблено скотскому свинскому разгулу.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Марка\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r60\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n61\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e61\u003c/span\u003e\u003cspan\u003eремарка, с. 66\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eДекорация и персонажи сцены \u0026#171;Кухня ведьмы\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гравюра нюрнбергского художника XVII в. Михаэля Герра (Michael Herr) \u0026#171;Zauberey / Кухня ведьмы\u0026#187; (или её гравированная копия, широко известная в Германии).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Котёл на очаге, обезьяны-прислужники (мартышки) и развешанные атрибуты колдовства восходят к этой конкретной изобразительной композиции (с. 367).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eZauberey (гравюра Михаэля Герра)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r61\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n62\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e62\u003c/span\u003e\u003cspan\u003eКухня ведьмы, с. 67\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я навожу мосты над хлябью\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Братья Гримм, \u0026#171;Немецкие саги\u0026#187; (\u003cem\u003eDeutsche Sagen\u003c/em\u003e, 1816, напр., саги о постройке мостов чёртом — в т. ч. Саксенхаузенского моста во Франкфурте и Чёртова моста в Швейцарии).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Распространённое в Европе предание о том, что недоступные каменные мосты над пропастями возводил дьявол за плату первой прошедшей по ним душой (с. 367).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eНемецкие саги (братья Гримм)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r62\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n63\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e63\u003c/span\u003e\u003cspan\u003eКухня ведьмы, с. 69\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Зачем тут несколько решет?\u0026#187; / \u0026#171;Сквозь лубяной их переплет / Себя преступник выдает\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Феокрит, \u0026#171;Идиллии\u0026#187; (Идиллия III, ст. 31); Эразм Роттердамский, \u0026#171;Пословицы\u0026#187; (\u003cem\u003eAdagia\u003c/em\u003e — \u003cem\u003eCribro divinare\u003c/em\u003e); \u0026#171;Handw\u0026#246;rterbuch des deutschen Aberglaubens\u0026#187; (ст. \u003cem\u003eSieblaufen / Koskinomantie\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Античное и средневековое гадание с помощью решета (коскиномантия): подвешенное на ножницах решето якобы начинало вертеться при произнесении имени вора (с. 367).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИдиллии (Феокрит)\u003c/span\u003e\u003cspan class=\"chip\"\u003eАдагии (Эразм Роттердамский)\u003c/span\u003e\u003cspan class=\"chip\"\u003eHandw\u0026#246;rterbuch des deutschen Aberglaubens\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r63\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n64\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e64\u003c/span\u003e\u003cspan\u003e76, Кухня ведьмы, с. 69\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Кто этот облик неземной / Волшебным зеркалом наводит?\u0026#187; / \u0026#171;он Елену / Во всех усмотрит непременно\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Поздние переработки народной книги о Фаусте (Н. Пфицер, 1674, и \u0026#171;Христовомыслящий\u0026#187; / \u003cem\u003eChristlich Meynender\u003c/em\u003e, 1725) и античный миф о Елене Спартанской (Гомер, \u0026#171;Илиада\u0026#187;, III).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Мотив волшебного зеркала, в котором Фаусту показывают прекраснейшую женщину мира — Елену (или символ идеальной красоты, с. 367).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eХристовомыслящий (Пфицер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r64\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n65\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e65\u003c/span\u003e\u003cspan\u003eКухня ведьмы, с. 70\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Бог, трудясь шесть дней / И на седьмой воскликнув \u0026#171;браво\u0026#187;\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Книга Бытия (Быт. 1:26–31; 2:1–3).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Сотворение женщины на шестой день и благословение Богом всего созданного на седьмой день (с. 367).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Бытия\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r65\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n66\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e66\u003c/span\u003e\u003cspan\u003eКухня ведьмы, с. 70\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Корону сдави, / В поту, на крови / Скрепи, словно клеем\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u003cem\u003eПредположительная отсылка\u003c/em\u003e к политическим кризисам Европы 1780-х гг. (напр., \u0026#171;делу об ожерелье\u0026#187; и предреволюционному кризису во Франции при Людовике XVI, описанному впоследствии Гёте в комедии \u0026#171;Великий Кофта\u0026#187;, 1791).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Комментаторы нередко видят здесь намёк на крах монархий во Французской революции, однако сцена написана в 1788 г. (с. 367), то есть до 1789 г., и может отражать лишь общее ощущение шаткости европейских тронов.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eДело об ожерелье (1785)\u003c/span\u003e\u003cspan class=\"chip\"\u003eВеликий Кофта (Гёте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r66\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n67\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e67\u003c/span\u003e\u003cspan\u003eКухня ведьмы, с. 71\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;У, василиск!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Плиний Старший, \u0026#171;Естественная история\u0026#187; (кн. VIII, гл. 33, \u0026#167; 78); \u0026#171;Физиолог\u0026#187; (\u003cem\u003ePhysiologus\u003c/em\u003e, II–III вв. н. э.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Василиск — мифический \u0026#171;царь змей\u0026#187;, убивающий взглядом и дыханием; его именем Мефистофель ругает злобную ведьму.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЕстественная история (Плиний)\u003c/span\u003e\u003cspan class=\"chip\"\u003eФизиолог\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r67\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n68\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e68\u003c/span\u003e\u003cspan\u003eКухня ведьмы, с. 74\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Вот ведьмина таблица умноженья\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u003cem\u003eПредположительная отсылка\u003c/em\u003e к \u0026#171;Оккультной философии\u0026#187; Агриппы Неттесгеймского (кн. II, гл. 22 — магический квадрат Сатурна $3 \\times 3$ с суммой 15 по строкам и столбцам), а также к средневековой схоластической полемике вокруг тринитарного догмата (ср. слова Мефистофеля далее на с. 74: \u003cem\u003e\u0026#171;Из тройственности и единства...\u0026#187;\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Абракадабра чисел, дающая магический квадрат или пародию на \u0026#171;три в одном и одно в трёх\u0026#187;, высмеивает богословские и оккультные спекуляции.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОккультная философия (Агриппа)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r68\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n69\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e69\u003c/span\u003e\u003cspan\u003eКухня ведьмы, с. 75\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Довольно, мудрая сивилла!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Вергилий, \u0026#171;Энеида\u0026#187; (кн. VI, 9–155 — Кумская сивилла); \u0026#171;Сивиллины книги\u0026#187; (античные прорицания).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Имя древних пророчиц сивилл Мефистофель с иронией переносит на старую ведьму.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЭнеида (Вергилий)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eСивиллины книги\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r69\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n70\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e70\u003c/span\u003e\u003cspan\u003eКухня ведьмы, с. 76\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Приятной ленью Купидон\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. I, 452–473); Апулей, \u0026#171;Метаморфозы\u0026#187; (\u0026#171;Золотой осёл\u0026#187;, кн. IV–VI).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Римский бог любовной страсти Купидон (Амур), разжигающий плотское желание.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЗолотой осёл (Апулей)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r70\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n71\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e71\u003c/span\u003e\u003cspan\u003eУлица, с. 77\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ты судишь, как какой-то селадон\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Оноре д’Юрфе, пасторальный роман \u0026#171;Астрея\u0026#187; (\u003cem\u003eL\u0026#39;Astr\u0026#233;e\u003c/em\u003e, 1607–1627).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Имя главного героя романа, томного влюблённого пастуха Селадона, стало в Европе XVIII в. нарицательным обозначением сентиментального или слащавого воздыхателя.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eАстрея (д\u0026#39;Юрфе)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r71\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n72\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e72\u003c/span\u003e\u003cspan\u003eУлица, с. 78\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Здесь много старых кладов близ церквей\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u0026#171;История о докторе Иоганне Фаусте\u0026#187; (изд. И. Шписа, 1587, а также дополнения Видмана 1599 г. / Пфицера 1674 г.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В народных книгах Фауст и Мефистофель неоднократно добывают сокровища, зарытые в земле и у старых церквей и монастырей (с. 367).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИстория о докторе Иоганне Фаусте (Шпис)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r72\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n73\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e73\u003c/span\u003e\u003cspan\u003eВечер, с. 81\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Король жил в Фуле дальней\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Страбон, \u0026#171;География\u0026#187; (кн. I–II — изложение плавания Пифея к острову Туле/Фуле); Вергилий, \u0026#171;Георгики\u0026#187; (кн. I, 30 — \u003cem\u003eUltima Thule\u003c/em\u003e); Сенека, трагедия \u0026#171;Медея\u0026#187; (ст. 379).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e У древних греков и римлян \u003cem\u003eUltima Thule\u003c/em\u003e (\u0026#171;Крайняя Фула\u0026#187;) — полулегендарный северный остров на самом краю обитаемого мира (предположительно Исландия или Шетландские острова, с. 367).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eГеография (Страбон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГеоргики (Вергилий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМедея (Сенека)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r73\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n74\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e74\u003c/span\u003e\u003cspan\u003eНа прогулке, с. 83\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;А церковь при своем пищеваренье / Глотает государства, города...\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Немецкая реформационная сатира XVI в. — в частности, памфлеты Ульриха фон Гуттена и Ганса Сакса, а также пословица \u003cem\u003e\u0026#171;Die Kirche hat einen guten Magen\u0026#187;\u003c/em\u003e (\u0026#171;У церкви хороший желудок\u0026#187;), записанная в сборниках пословиц И. Агриколы (1529) и С. Франка (1541).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Полемическое обвинение католического духовенства в ненасытном присвоении мирских богатств под видом благочестия (с. 368).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eПамфлеты Ульриха фон Гуттена\u003c/span\u003e\u003cspan class=\"chip\"\u003eМасленичные игры (Ганс Сакс)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eСборники пословиц Агриколы и Франка\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r74\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n75\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e75\u003c/span\u003e\u003cspan\u003eДом соседки, с. 84\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eМонолог Марты о сбежавшем муже\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Ганс Сакс, нюрнбергские масленичные игры (\u003cem\u003eFastnachtsspiele\u003c/em\u003e, XVI в.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Техника комического вступительного монолога, где персонаж напрямую рассказывает зрителям о своих семейных бедах (с. 368).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМасленичные игры (Ганс Сакс)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r75\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n76\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e76\u003c/span\u003e\u003cspan\u003eДом соседки, с. 87\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Его хранит Антоний Падуанский\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Житие святого Антония Падуанского (1195–1231) в сборнике \u0026#171;Золотая легенда\u0026#187; (дополнения XIV в.) и история базилики Сант-Антонио в Падуе.\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Гробница одного из самых почитаемых католических святых в итальянской Падуе; Мефистофель сочиняет набожную небылицу ради доверия Марты.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЗолотая легенда (Иаков Ворагинский)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eБазилика Сант-Антонио в Падуе\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r76\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n77\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e77\u003c/span\u003e\u003cspan\u003eУлица, с. 91\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Sancta simplicitas!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Поздние биографии Яна Гуса (в частности, Иоганн Агрикола, \u0026#171;Tragedia Johannis Huss\u0026#187;, 1537, и хроники XVI в. о Констанцском соборе 1415 г.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e По преданию, чешский реформатор Ян Гус воскликнул на костре \u0026#171;Святая простота!\u0026#187;, увидев крестьянку, из благочестивого усердия подбросившую охапку хвороста в его огонь (с. 368).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eTragedia Johannis Huss (Агрикола)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eХроники Констанцского собора\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r77\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n78\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e78\u003c/span\u003e\u003cspan\u003eУлица, с. 92\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ты, как всегда, софист и лжец\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Платон, диалоги \u0026#171;Софист\u0026#187;, \u0026#171;Горгий\u0026#187;, \u0026#171;Протагор\u0026#187;; Аристотель, \u0026#171;О софистических опровержениях\u0026#187;.\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Софисты V в. до н. э., подвергнутые критике Сократом, Платоном и Аристотелем, дали имя искусству подменять истину ловкой игрой слов.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eСофист (Платон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГоргий (Платон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eПротагор (Платон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eО софистических опровержениях (Аристотель)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r78\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n79\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e79\u003c/span\u003e\u003cspan\u003eЛесная пещера, с. 100\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ты предо мной проводишь череду / Живых существ и учишь видеть братьев / Во всем: в зверях, в кустарнике, в траве\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e И. Г. Гердер, \u0026#171;Идеи к философии истории человечества\u0026#187; (\u003cem\u003eIdeen zur Philosophie der Geschichte der Menschheit\u003c/em\u003e, ч. I, кн. 2–3, 1784); Бенедикт Спиноза, \u0026#171;Этика\u0026#187; (ч. I).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Натурфилософия Гердера рассматривала всю природу как единую восходящую цепь родственных организмов, называя животных \u0026#171;старшими братьями человека\u0026#187; (с. 368).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИдеи к философии истории человечества (Гердер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭтика (Спиноза)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r79\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n80\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e80\u003c/span\u003e\u003cspan\u003eЛесная пещера, с. 102\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Она в окошко наблюдает... И дни и ночи распевает; / \u0026#171;Когда б я ласточкой была!\u0026#187;\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Немецкая народная песня \u003cem\u003e\u0026#171;Wenn ich ein V\u0026#246;glein w\u0026#228;r, / Und auch zwei Fl\u0026#252;glein h\u0026#228;tt\u0026#187;\u003c/em\u003e, опубликованная И. Г. Гердером в сборнике \u0026#171;Народные песни\u0026#187; (\u003cem\u003eVolkslieder\u003c/em\u003e, 1778, ч. I, кн. 1).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Популярная песня о тоске влюблённой девушки, желающей обрести крылья, чтобы прилететь к милому (в переводе Пастернака \u0026#171;птичка\u0026#187; заменена на \u0026#171;ласточку\u0026#187;).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eWenn ich ein V\u0026#246;glein w\u0026#228;r (народная песня)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eНародные песни (Гердер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r80\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n81\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e81\u003c/span\u003e\u003cspan\u003eЛесная пещера, с. 102–103\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я завидую Христову телу; / Его касаются ее уста\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Постановления IV Латеранского собора (1215) и Тридентского собора (сессия XIII, 1551) о таинстве Евхаристии и пресуществлении; Библия (Мф. 26:26).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Отсылка к католическому причастию: прикасаясь губами к освящённой гостии (обла́тке), верующая принимает Тело Христово.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eПостановления IV Латеранского собора\u003c/span\u003e\u003cspan class=\"chip end\"\u003eПостановления Тридентского собора\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Матфея\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r81\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n82\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e82\u003c/span\u003e\u003cspan\u003eЛесная пещера, с. 103\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я вспомнил пастбище средь роз / И ланей, символы желанья\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Песнь Песней Соломона (Песн. 4:5; 7:4; в немецком переводе Библии Мартина Лютера — \u003cem\u003e\u0026#171;die unter Rosen weiden\u0026#187;\u003c/em\u003e, \u0026#171;пасущиеся среди роз\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Мефистофель цинично обыгрывает чувственную поэтику Песни Песней: \u0026#171;два сосца твои — как двойни молодой серны, пасущиеся между лилиями [у Лютера — розами]\u0026#187;.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eПеснь Песней\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r82\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n83\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e83\u003c/span\u003e\u003cspan\u003eСад Марты, с. 106\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eМонолог Фауста о вере (\u0026#171;Создателя всего... Все дело в чувстве, а названье / Лишь дым...\u0026#187;)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Бенедикт Спиноза, \u0026#171;Этика\u0026#187; (ч. I и V); записки И. Х. Кестнера о Гёте (1772, цит. на с. 368–369) и эстетика движения \u0026#171;Буря и натиск\u0026#187; (\u003cem\u003eSturm und Drang\u003c/em\u003e, ср. с \u0026#171;Письмами\u0026#187; в \u0026#171;Страданиях юного Вертера\u0026#187; Гёте, 1774).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Выражение нецерковного пантеизма и культа искреннего сердечного чувства, характерного для молодого Гёте и кружка штюрмеров.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЭтика (Спиноза)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЗаписки Кестнера о Гёте\u003c/span\u003e\u003cspan class=\"chip\"\u003eСтрадания юного Вертера (Гёте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r83\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n84\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e84\u003c/span\u003e\u003cspan\u003eСад Марты, с. 109\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Что хват я или Вельзевул\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Новый Завет — Евангелие от Матфея (Мф. 10:25; 12:24).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Евангельское именование \u0026#171;князя бесовского\u0026#187; (см. также № 39).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Матфея\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r84\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n85\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e85\u003c/span\u003e\u003cspan\u003eУ колодца, с. 110–111\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Наденет девка власяницу / За эти подвиги свои\u0026#187; / \u0026#171;На свадьбе парни ей цветы / Сорвут со свадебной фаты, / А девки перед дверью дома / Насыплют отрубей с соломой\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Свод веймарского уголовного права и докладная записка И. В. Гёте герцогу Карлу-Августу (1786 г. об отмене церковного покаяния \u0026#171;блудных матерей\u0026#187;, с. 369); немецкие свадебные обычаи порицания опозоренной невесты (описаны в этнографических трудах, ср. срывание девичьего венца \u003cem\u003eKranzabreissen\u003c/em\u003e и посыпание порога мякиной/соломой — \u003cem\u003eH\u0026#228;ckerling streuen\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Девушек, родивших вне брака, заставляли каяться у входа в церковь во власянице, а даже при выходе замуж с них срывали знак невинности — миртовый венок.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eВеймарский уголовный свод\u003c/span\u003e\u003cspan class=\"chip end\"\u003eДокладная записка Гёте об отмене церковного покаяния\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭтнографические труды о свадебных обычаях\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r85\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n86\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e86\u003c/span\u003e\u003cspan\u003eНа городском валу, с. 111\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;К молящей / Свой лик скорбящий / Склони в неизреченной доброте, / С кручиной / Смотря на сына, / Простертого в мученьях на кресте\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Католическая секвенция \u003cem\u003eStabat Mater Dolorosa\u003c/em\u003e (XIII в., приписывается Якопоне да Тоди) и Библия, Евангелие от Луки (Лк. 2:35 — пророчество Симеона Богоприимца Богоматери: \u0026#171;и Тебе Самой оружие пройдёт душу\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Молитва Гретхен перед скульптурой Скорбящей Богоматери воспроизводит ритм, интонацию и ключевые образы знаменитого средневекового гимна.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eStabat Mater Dolorosa\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Луки\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r86\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n87\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e87\u003c/span\u003e\u003cspan\u003eНочь. Улица перед домом Гретхен, с. 114\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eПесня Мефистофеля: \u0026#171;Смиряя дрожь, / Зачем под нож, / Катринхен, к милому идешь...\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e У. Шекспир, трагедия \u0026#171;Гамлет\u0026#187; (акт IV, сц. 5 — песня Офелии \u0026#171;Tomorrow is Saint Valentine\u0026#39;s day...\u0026#187; в немецком переводе А. В. Шлегеля или И. И. Эшенбурга); \u0026#171;Разговоры с Гёте\u0026#187; И. П. Эккермана (запись от 18 января 1825 г., с. 369).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Первый куплет песни Мефистофеля воспроизводит балладу Офелии о девушке, утратившей честь, придя на рассвете к возлюбленному.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eГамлет (Шекспир)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eРазговоры с Гёте (Эккерман)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r87\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n88\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e88\u003c/span\u003e\u003cspan\u003eНочь. Улица перед домом Гретхен, с. 114\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Кого ты пеньем манишь, крысолов?\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Братья Гримм, \u0026#171;Немецкие саги\u0026#187; (\u003cem\u003eDeutsche Sagen\u003c/em\u003e, 1816, № 245 \u0026#171;Дети из Гамельна\u0026#187;); хроники города Гамельна (XIV–XVI вв.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Легенда о дудочнике, который очистил Гамельн от крыс, а когда бургомистр отказал ему в плате, увёл за своей музыкой всех городских детей (с. 369).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eНемецкие саги (братья Гримм)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eХроники города Гамельна\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r88\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n89\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e89\u003c/span\u003e\u003cspan\u003eНочь. Улица перед домом Гретхен, с. 117\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Тебе не даст проступок твой / Блистать в цепочке золотой\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Полицейские и цеховые регламенты города Франкфурта-на-Майне XVI в. (запреты на роскошь для низших сословий и \u0026#171;падших женщин\u0026#187;, \u003cem\u003eKleiderordnungen\u003c/em\u003e, с. 369).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Историческое постановление прямо запрещало блудницам и простым девушкам носить золотые цепи, бархат и атлас в церкви и на праздниках.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eПолицейские регламенты Франкфурта (Kleiderordnungen)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r89\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n90\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e90\u003c/span\u003e\u003cspan\u003eСобор, с. 118–119\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Dies irae, dies illa...\u0026#187;, \u0026#171;Judex ergo cum sedebit...\u0026#187;, \u0026#171;Quid sum miser tunc dicturus...\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Католический заупокойный гимн-секвенция \u0026#171;Dies irae\u0026#187; (XIII в., традиционно приписывается Фоме Челанскому; входит в чин Реквиема).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Точные латинские строфы (1-я, 6-я и 7-я) о Дне Гнева, явлении Судии, раскрытии тайных грехов и страхе праведника перед Страшным судом (с. 369).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eDies irae\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r90\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n91\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e91\u003c/span\u003e\u003cspan\u003e122–123, 236, Вальпургиева ночь / Классическая Вальпургиева ночь, с. 119\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Горы Гарца близ деревень Ширке и Эленд\u0026#187;, \u0026#171;На Брокен ведьмы тянут в ряд\u0026#187;, \u0026#171;От Ильзенштейна...\u0026#187;, \u0026#171;На высоте своей нас Генрих ждет\u0026#187;, \u0026#171;Храпуны\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Путевые дневники и письма И. В. Гёте о путешествиях на Гарц (1777, 1783, 1784 гг.), письмо К. Ф. Цельтеру от 2 декабря 1812 г. (с. 370); сборник \u0026#171;Немецкие саги\u0026#187; братьев Гримм (предание о принцессе Ильзе из скалы Ильзенштейн и возлюбленном её, императоре Генрихе II; гранитные скалы \u0026#171;Храпуны\u0026#187; — \u003cem\u003eSchnarcherklippen\u003c/em\u003e близ деревни Эленд).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Гёте опирался на реальную географию Гарца и местные народные предания, связывавшие вершину Брокен с шабашем ведьм в ночь с 30 апреля на 1 мая (день памяти св. Вальпургии, с. 370, 377).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eПутевые дневники Гёте о Гарце\u003c/span\u003e\u003cspan class=\"chip end\"\u003eПисьмо Цельтеру (1812)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eНемецкие саги (братья Гримм)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r91\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n92\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e92\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 121\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Видишь, в недрах гор взошел / Царь Маммон на свой престол\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Джон Мильтон, поэма \u0026#171;Потерянный рай\u0026#187; (кн. I, ст. 678–730 — 1667); Библия (Мф. 6:24).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В \u0026#171;Потерянном рае\u0026#187; падший ангел Маммон находит золотую руду в недрах земли и строит в преисподней сияющий золотой дворец Пандемониум (с. 370).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eПотерянный рай (Мильтон)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Матфея\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r92\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n93\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e93\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 122\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Там Уриан, князь мракобесья\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Нижненемецкие сказки и суеверия, зафиксированные в словаре И. Х. Аделунга и в \u0026#171;Немецкой мифологии\u0026#187; Якоба Гримма (гл. XXXIII \u0026#171;Teufel\u0026#187; — \u003cem\u003eHerr Urian\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Народное нижненемецкое прозвище сатаны или незваного/нечестивого гостя (с. 370).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eСловарь Аделунга\u003c/span\u003e\u003cspan class=\"chip\"\u003eНемецкая мифология (Гримм)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r93\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n94\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e94\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 122\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Старуха Баубо мчит к верхушке / Верхом на супоросой хрюшке\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Климент Александрийский, \u0026#171;Увещевание к язычникам\u0026#187; (\u003cem\u003eПротрептик\u003c/em\u003e, гл. II, 20–21 — орфический миф о Баубо); Павсаний, \u0026#171;Описание Эллады\u0026#187; (о свиньях в Элевсинском культе Деметры).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Согласно орфической версии элевсинского мифа, в Элевсине старуха Баубо развеселила скорбящую по похищенной Персефоне Деметру бесстыдными речами и жестом, задрав подол (с. 370).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eПротрептик (Климент Александрийский)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОписание Эллады (Павсаний)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r94\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n95\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e95\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 124\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Втиранье ускоряет прыть\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Апулей, \u0026#171;Метаморфозы\u0026#187; (\u0026#171;Золотой осёл\u0026#187;, кн. III, гл. 21 — превращение Памфилы в птицу при помощи мази); Генрих Крамер и Якоб Шпренгер, трактат \u0026#171;Молот ведьм\u0026#187; (\u003cem\u003eMalleus Maleficarum\u003c/em\u003e, 1486, ч. II, вопрос 1, гл. 3).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Древнее и средневековое поверье о летательной мази, которой натираются колдуньи, чтобы летать на шабаш (с. 370).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЗолотой осёл (Апулей)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМолот ведьм (Крамер и Шпренгер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r95\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n96\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e96\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 125\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Поистине живой пример / Мегер и фурий без манер\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Эсхил, трагедия \u0026#171;Эвмениды\u0026#187; (ст. 46–59); Вергилий, \u0026#171;Энеида\u0026#187; (кн. XII, 845–848 — три фурии: Тисифона, Алекто, Мегера).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Крылатые богини мести со змеями вместо волос, чьи крики и безобразие уподоблены сборищу ведьм.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЭвмениды (Эсхил)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭнеида (Вергилий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r96\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n97\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e97\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 126\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;У нас не носят ордена Подвязки\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Устав Благороднейшего ордена Подвязки (\u003cem\u003eOrder of the Garter\u003c/em\u003e, учреждён королём Эдуардом III в 1348 г.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Высший рыцарский орден Великобритании (носимый в виде ленты под левым коленом) противопоставляется \u0026#171;знаку отличия\u0026#187; Мефистофеля — лошадиному копыту (с. 370).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eУстав ордена Подвязки (1348)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r97\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n98\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e98\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 128\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Лилит... Первая жена Адама\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Иудейский памятник \u0026#171;Алфавит Бен-Сиры\u0026#187; (VIII–X вв.) и каббалистический трактат \u0026#171;Зогар\u0026#187; (XIII в.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В отличие от Книги Бытия, эти источники повествуют о Лилит — первой жене Адама до Евы, которая отказалась покориться ему, бежала и превратилась в ночного демона, губящего младенцев и соблазняющего мужчин (с. 370).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eАлфавит Бен-Сиры\u003c/span\u003e\u003cspan class=\"chip\"\u003eЗогар\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r98\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n99\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e99\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 128\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Вам Ева-мать внушила страсть / Рвать яблоки в садах и красть\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Книга Бытия (Быт. 3:6) и европейская иконография запретного плода как яблока (под влиянием игры латинских слов \u003cem\u003emalum\u003c/em\u003e — \u0026#171;зло\u0026#187; и \u0026#171;яблоко\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Фривольная шутка о первородном грехе Евы в контексте эротических намёков Фауста.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Бытия\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r99\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n100\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e100\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 129–130\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Проктофантасмист (Задопровидец)\u0026#187; / \u0026#171;Поставленные к копчику пиявки\u0026#187; / \u0026#171;в Тегеле на чердаках моих\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Статья Христиана Фридриха Николаи \u0026#171;Пример появления нескольких фантазмов\u0026#187; (\u003cem\u003eBeispiel einer Erscheinung mehrerer Phantasmen\u003c/em\u003e, прочитана в Берлинской академии наук 28 февраля 1799 г. и напечатана в \u003cem\u003eNeue Berlinische Monatsschrift\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Просветитель Николаи, критиковавший Гёте и Шиллера, описал в этой статье свои галлюцинации (упомянув и слухи о призраках в замке Тегель, принадлежавшем роду Гумбольдтов) и объяснил своё излечение тем, что поставил пиявки к заднему проходу, согнав прилив крови (с. 371).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eСтатья Николаи о фантазмах (1799)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r100\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n101\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e101\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 130\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;изо рта у ней во время пенья / Вдруг выпрыгнула розовая мышь\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Иоганн Преториус, \u0026#171;Blockes-Berges Verrichtung\u0026#187; (1668); братья Гримм, \u0026#171;Немецкие саги\u0026#187; (предание о душе/демоне, выбегающем изо рта в виде красной или белой мыши).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В средневековых суевериях мышь, выскочившая изо рта женщины, считалась зримым признаком её одержимости дьяволом (с. 371).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eBlockes-Berges Verrichtung (Преториус)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eНемецкие саги (братья Гримм)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r101\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n102\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e102\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 130–131\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Небось ты слышал о Медузе?\u0026#187; / \u0026#171;Ей голову срубил Персей\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гесиод, \u0026#171;Теогония\u0026#187; (ст. 274–281); Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. IV, 772–803); Аполлодор, \u0026#171;Мифологическая библиотека\u0026#187; (кн. II, гл. 4, 2–3).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Персей отрубил голову смертной горгоне Медузе, чей взгляд превращал всё живое в камень; Мефистофель пытается отвлечь Фауста от страшного видения казнённой Гретхен, сравнивая его с мороком Медузы (с. 371).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМифологическая библиотека (Аполлодор)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r102\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n103\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e103\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 131\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Как в Пратере во дни гулянья\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Топография Вены (императорский парк Пратер, открытый для народных гуляний Иосифом II в 1766 г.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Сравнение суеты на Брокене с шумным ярмарочным парком столицы Австрии (с. 371).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eТопография Вены (Пратер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r103\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n104\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e104\u003c/span\u003e\u003cspan\u003eВальпургиева ночь, с. 131\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Servibilis (Подлиза)\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Веймарская театральная критика 1790-х гг. — деятельность археолога и литератора Карла Августа Бёттигера (1760–1835; в примечании на с. 371 опечатка \u0026#171;Беттингер\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Латинское прозвище \u0026#171;угодливый/готовый к услугам\u0026#187; высмеивает Бёттигера за угодничество перед посредственностями и потакание невзыскательному вкусу публики.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eВеймарская театральная критика о Бёттигере\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r104\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n105\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e105\u003c/span\u003e\u003cspan\u003eс. с. 131–137\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eИнтермедия \u0026#171;Сон в Вальпургиеву ночь, или Золотая свадьба Оберона и Титании\u0026#187; (Оберон, Титания, Пук, Ариэль)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e У. Шекспир, \u0026#171;Сон в летнюю ночь\u0026#187; (1595, Оберон, Титания, Пук) и \u0026#171;Буря\u0026#187; (1611, дух Ариэль); К. М. Виланд, поэма \u0026#171;Оберон\u0026#187; (1780); зингшпиль/оперетта П. Враницкого \u0026#171;Оберон, царь эльфов\u0026#187; (пост. в Веймаре в 1796 г.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В комедии Шекспира и поэме Виланда поссорившиеся король и королева эльфов примиряются; Гёте переносит их \u0026#171;золотую свадьбу\u0026#187; (50-летний юбилей) в интермедию сатирических эпиграмм (с. 371).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eСон в летнюю ночь (Шекспир)\u003c/span\u003e\u003cspan class=\"chip\"\u003eБуря (Шекспир)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОберон (Виланд)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОберон, царь эльфов (Враницкий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r105\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n106\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e106\u003c/span\u003e\u003cspan\u003eСон в Вальпургиеву ночь, с. 132\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Мидинга потомки!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Поэма И. В. Гёте \u0026#171;На смерть Мидинга\u0026#187; (\u003cem\u003eAuf Miedings Tod\u003c/em\u003e, 1782).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Иоганн Мартин Мидинг († 1782) был знаменитым бутафором и мастером сценических эффектов Веймарского театра (с. 371).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eНа смерть Мидинга (Гёте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r106\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n107\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e107\u003c/span\u003e\u003cspan\u003eСон в Вальпургиеву ночь, с. 133\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Заиграл волынщик\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Немецкие средневековые сатирические гравюры эпохи Реформации (напр., гравюра Э. Шёна 1535 г. \u0026#171;Дьявол, играющий на волынке\u0026#187;) и демонологические поверья, отмеченные в \u0026#171;Handw\u0026#246;rterbuch des deutschen Aberglaubens\u0026#187; (ст. \u003cem\u003eDudelsack\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В средневековой иконографии волынка считалась инструментом дьявола (черта надували ею как мехом, с. 371).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eДьявол, играющий на волынке (гравюра Шёна)\u003c/span\u003e\u003cspan class=\"chip\"\u003eHandw\u0026#246;rterbuch des deutschen Aberglaubens\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r107\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n108\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e108\u003c/span\u003e\u003cspan\u003eСон в Вальпургиеву ночь, с. 133–136\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eСатирические маски: \u0026#171;Любопытный путешественник\u0026#187;, \u0026#171;Ортодокс\u0026#187;, \u0026#171;Северный художник\u0026#187;, \u0026#171;Пурист\u0026#187;, \u0026#171;Флюгер\u0026#187;, \u0026#171;Ксении\u0026#187;, \u0026#171;Геннингс / Музагет / Бывший гений своего времени\u0026#187;, \u0026#171;Журавль\u0026#187;, \u0026#171;Светский человек\u0026#187;, \u0026#171;Догматик / Идеалист / Реалист / Супернатуралист / Скептик\u0026#187;, \u0026#171;Блуждающие огни\u0026#187;, \u0026#171;Падающая звезда\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Немецкая литературно-философская полемика 1790-х гг. (см. с. 371–372): \u003cem\u003e \u003c/em\u003eЛюбопытный путешественник\u003cem\u003e — читатель 12-томного \u0026#171;Описания путешествия по Германии и Швейцарии\u0026#187; (1783–1796) Ф. Николаи; \u003c/em\u003e \u003cem\u003eОртодокс\u003c/em\u003e — статья графа Ф. Л. Штольберга (в журнале \u003cem\u003eDeutsches Museum\u003c/em\u003e, 1788) против стихотворения Ф. Шиллера \u0026#171;Боги Греции\u0026#187;; \u003cem\u003e \u003c/em\u003eСеверный художник\u003cem\u003e — сам Гёте (или художник Ф. Мюллер); \u003c/em\u003e \u003cem\u003eФлюгер\u003c/em\u003e — композитор и публицист И. Ф. Рейхардт (журналы \u003cem\u003eFrankreich\u003c/em\u003e, \u003cem\u003eDeutschland\u003c/em\u003e); \u003cem\u003e \u003c/em\u003eКсении\u003cem\u003e — совместный цикл эпиграмм Гёте и Шиллера в \u0026#171;Альманахе муз на 1797 год\u0026#187; (название восходит к кн. XIII \u0026#171;Эпиграмм\u0026#187; Марциала); \u003c/em\u003e \u003cem\u003eГеннингс / Музагет / Бывший гений\u003c/em\u003e — издатель Август фон Геннингс и его журналы \u0026#171;Der Genius der Zeit\u0026#187; (1794–1800) и \u0026#171;Der Musaget\u0026#187; (1798–1799); \u003cem\u003e \u003c/em\u003eЖуравль\u003cem\u003e — швейцарский пастор и писатель И. К. Лафатер (\u0026#171;Физиогномические фрагменты\u0026#187;, 1775–1778; за походку Гёте называл его журавлём); \u003c/em\u003e \u003cem\u003eФилософы\u003c/em\u003e — спор учений Г. В. Лейбница и Х. Вольфа (\u003cem\u003eДогматик\u003c/em\u003e), И. Г. Фихте (\u0026#171;Основа общего наукоучения\u0026#187;, 1794 — \u003cem\u003eИдеалист\u003c/em\u003e), эмпиризма (\u003cem\u003eРеалист\u003c/em\u003e), Ф. Г. Якоби (\u0026#171;Письма об учении Спинозы\u0026#187;, 1785 — \u003cem\u003eСупернатуралист\u003c/em\u003e) и Д. Юма (\u0026#171;Исследование о человеческом разумении\u0026#187;, 1748 — \u003cem\u003eСкептик\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Гёте продолжил серию язвительных \u0026#171;Ксений\u0026#187;, превратив шабаш на Брокене в пародийный смотр своих литературных, религиозных и философских оппонентов.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОписание путешествия по Германии и Швейцарии (Николаи)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eСтатья Штольберга против Богов Греции\u003c/span\u003e\u003cspan class=\"chip\"\u003eБоги Греции (Шиллер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eКсении (Гёте и Шиллер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭпиграммы (Марциал)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eDer Genius der Zeit\u003c/span\u003e\u003cspan class=\"chip end\"\u003eDer Musaget\u003c/span\u003e\u003cspan class=\"chip\"\u003eФизиогномические фрагменты (Лафатер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОснова общего наукоучения (Фихте)\u003c/span\u003e\u003cspan class=\"chip\"\u003eПисьма об учении Спинозы (Якоби)\u003c/span\u003e\u003cspan class=\"chip\"\u003eИсследование о человеческом разумении (Юм)\u003c/span\u003e\u003cspan class=\"chip\"\u003eФилософия Лейбница и Вольфа\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r108\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n109\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e109\u003c/span\u003e\u003cspan\u003eПасмурный день. Поле, с. 138\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ты тянешься за молниями, громовержец?\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Илиада\u0026#187; (песнь I, 580; VIII, 133 — Зевс-Кронион, метатель перунов); Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. III, 305–307).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Мефистофель язвительно сравнивает беспомощную ярость Фауста с гневом верховного бога-громовержца Зевса.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r109\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n110\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e110\u003c/span\u003e\u003cspan\u003eТюрьма, с. 139\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Чтоб вольнее гулять, / Извела меня мать, / И отец-людоед / Обглодал мой скелет, / И меня у бугра / Закопала сестра...\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Нижненемецкая народная сказка \u0026#171;О можжевеловом дереве\u0026#187; (\u003cem\u003eVon dem Machandelboom\u003c/em\u003e, опубликована Ф. О. Рунге в 1808 г. и вошла в \u0026#171;Детские и семейные сказки\u0026#187; братьев Гримм, 1812, KHM 47).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В сказке злая мачеха убивает пасынка и подаёт его в похлёбке отцу; сестра Марленхен собирает косточки под можжевельник, из которого вылетает птичка и поёт эту песню, разоблачая убийство (с. 372). Безумная Гретхен узнаёт в ней историю собственной семьи.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eО можжевеловом дереве (сказка)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eДетские и семейные сказки (братья Гримм)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r110\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n111\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e111\u003c/span\u003e\u003cspan\u003eТюрьма, с. 145\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Вот стали в колокол звонить, / И вот уж жезл судейский сломан\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Уголовный кодекс Священной Римской империи \u0026#171;Каролина\u0026#187; (\u003cem\u003eConstitutio Criminalis Carolina\u003c/em\u003e, 1532, ст. 96) и материалы франкфуртского суда над детоубийцей Сусанной Маргаретой Брандт (1771–1772).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Историческая процедура смертной казни в Германии: под звон \u0026#171;колокола грешников\u0026#187; (\u003cem\u003eArmens\u0026#252;nderglocke\u003c/em\u003e) судья публично переламывал над осуждённой белый жезл (\u003cem\u003eStabbrechen\u003c/em\u003e) со словами \u0026#171;Бог да помилует душу твою!\u0026#187; (с. 373).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКаролина (1532)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eМатериалы суда над Сусанной Брандт\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r111\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003ch3\u003e4. Вторая часть. Акт Первый (с. 147–202)\u003c/h3\u003e\n\u003cdiv class=\"note\" id=\"n112\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e112\u003c/span\u003e\u003cspan\u003eКрасивая местность, с. 147\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ариэль (пение под аккомпанемент эоловых арф)\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e У. Шекспир, пьеса \u0026#171;Буря\u0026#187; (1611, акт I, сц. 2; акт V, сц. 1 — дух воздуха Ариэль).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e У Шекспира Ариэль — светлый дух, управляющий музыкой и ветрами; Гёте делает его целителем измученной души Фауста.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eБуря (Шекспир)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r112\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n113\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e113\u003c/span\u003e\u003cspan\u003eКрасивая местность, с. 147\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ночь на четыре четверти разбита\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Полибий, \u0026#171;Всеобщая история\u0026#187; (кн. VI, гл. 35–36); Вегеций, \u0026#171;Краткое изложение военного дела\u0026#187; (кн. III, гл. 8).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В Древнем Риме ночь делилась на четыре равные стражи (\u003cem\u003evigiliae\u003c/em\u003e) от заката до восхода (с. 373).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eВсеобщая история (Полибий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eКраткое изложение военного дела (Вегеций)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r113\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n114\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e114\u003c/span\u003e\u003cspan\u003eКрасивая местность, с. 147\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Росой забвенья сбрызните чело\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Платон, диалог \u0026#171;Государство\u0026#187; (кн. X, 621a–c — миф об Эре); Вергилий, \u0026#171;Энеида\u0026#187; (кн. VI, 705–715).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Воды подземной реки Леты, испив из которой души забывают прошлую земную жизнь и страдания.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eГосударство (Платон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭнеида (Вергилий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r114\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n115\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e115\u003c/span\u003e\u003cspan\u003eКрасивая местность, с. 148\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Слышите, грохочут Оры!... Феба четверня рванула\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Илиада\u0026#187; (песнь V, ст. 749–751; песнь VIII, ст. 393 — Оры отворяют облачные врата неба); Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. II, 107–155 — четвёрка солнечных коней Феба/Гелиоса).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Богини времён года Оры охраняют небесные врата, с грохотом отворяя их на рассвете перед выездом солнечной квадриги (с. 373).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r115\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n116\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e116\u003c/span\u003e\u003cspan\u003eКрасивая местность, с. 148–149\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eМонолог Фауста на рассвете (терцины: \u0026#171;Опять встречаю свежих сил приливом... Та радуга и жизнь — одно и то же\u0026#187;)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Данте Алигьери, \u0026#171;Божественная комедия\u0026#187; (написана терцинами); Платон, \u0026#171;Государство\u0026#187; (кн. VI–VII, 508a–517c — сравнение Солнца с идеей Блага, на которую невозможно смотреть прямо); И. В. Гёте, \u0026#171;Учение о цвете\u0026#187; (\u003cem\u003eZur Farbenlehre\u003c/em\u003e, 1810).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Фауст говорит размером поэмы Данте, приходя к платоновско-гётевскому выводу: абсолютная Истина (солнце) слепит, и человек познаёт её лишь в земных \u0026#171;цветных отражениях\u0026#187; (в радуге брызг водопада) (с. 373).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eБожественная комедия (Данте)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГосударство (Платон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eУчение о цвете (Гёте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r116\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n117\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e117\u003c/span\u003e\u003cspan\u003eс. с. 149–157\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Императорский дворец\u0026#187; (архиепископ-канцлер, \u0026#171;гвельфы и гибеллины\u0026#187;, сокровища глубже плуга, семь планет Астролога)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Имперские законы Священной Римской империи (\u0026#171;Золотая булла\u0026#187; 1356 г. — архиепископ Майнцский как имперский эрцканцлер); Дж. Виллани, \u0026#171;Новая хроника\u0026#187; (XIV в. — борьба гвельфов и гибеллинов в Италии XI–XV вв.); германский правовой свод XIII в. \u0026#171;Саксонское зерцало\u0026#187; (\u003cem\u003eSachsenspiegel\u003c/em\u003e, кн. I, ст. 35, \u0026#167; 1 — о правах короля на клады); арабско-средневековые астрологические трактаты (Абу Машар, Агриппа Неттесгеймский \u0026#171;Оккультная философия\u0026#187;, кн. I, гл. 23–29 — соответствие 7 планет 7 металлам).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Сцена объединяет реальные институты распадающейся средневековой империи с традиционной системой алхимико-астрологических соответствий (Солнце — золото, Меркурий — ртуть, Венера — медь, Луна — серебро, Марс — железо, Юпитер — олово, Сатурн — свинец, с. 373).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЗолотая булла (1356)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eНовая хроника (Виллани)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eСаксонское зерцало\u003c/span\u003e\u003cspan class=\"chip\"\u003eОккультная философия (Агриппа)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r117\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n118\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e118\u003c/span\u003e\u003cspan\u003eИмператорский дворец, с. 156\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;О мандрагорах вздор твердите / И глупости о черном псе\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Иосиф Флавий, \u0026#171;Иудейская война\u0026#187; (кн. VII, гл. 6, 3 — выкапывание корня собакой); Плиний Старший, \u0026#171;Естественная история\u0026#187; (кн. XXV, гл. 94); Якоб Гримм, \u0026#171;Немецкие саги\u0026#187; (№ 84 \u0026#171;Альраун\u0026#187;) и \u0026#171;Handw\u0026#246;rterbuch des deutschen Aberglaubens\u0026#187; (ст. \u003cem\u003eAlraun\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Поверье, что корень мандрагоры растёт под виселицами, указывает клады и смертельно кричит при вырывании, поэтому к нему привязывали чёрного пса, который погибал вместо человека (с. 373).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИудейская война (Иосиф Флавий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЕстественная история (Плиний)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eНемецкие саги (братья Гримм)\u003c/span\u003e\u003cspan class=\"chip\"\u003eHandw\u0026#246;rterbuch des deutschen Aberglaubens\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r118\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n119\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e119\u003c/span\u003e\u003cspan\u003eИмператорский дворец, с. 157\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Стада златых тельцов сверкнут\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Книга Исход (Исх. 32:1–8).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Во время пребывания Моисея на горе Синай израильтяне отлили идола — золотого тельца; символ идолопоклонства перед золотом (с. 373).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Исход\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r119\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n120\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e120\u003c/span\u003e\u003cspan\u003eИмператорский дворец, с. 158\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я б философский камень дал им\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Средневековые и ренессансные алхимические трактаты (Арнольд из Виллановы, Раймунд Луллий, Василий Валентин).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Легендарная субстанция (\u003cem\u003eLapis philosophorum\u003c/em\u003e), способная превращать неблагородные металлы в золото и даровать эликсир жизни.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eАлхимические трактаты Арнольда из Виллановы, Луллия и Василия Валентина\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r120\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n121\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e121\u003c/span\u003e\u003cspan\u003eСад для гулянья, с. 183–185\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eВыпуск бумажных денег, обеспеченных невыкопанными подземными кладами\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Исторические документы о финансовой системе Джона Ло во Франции (1716–1720 гг., банкноты, \u0026#171;обеспеченные\u0026#187; ресурсами Миссисипи, описаны у Вольтера в \u0026#171;Веке Людовика XV\u0026#187;, гл. II) и декреты Учредительного собрания Франции 1789–1790 гг. о выпуске бумажных ассигнатов под конфискованные земли.\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Сатира на инфляцию и государственные финансовые пузыри, основанные на ничем не подкреплённых бумажных обязательствах.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eДокументы о системе Джона Ло\u003c/span\u003e\u003cspan class=\"chip\"\u003eВек Людовика XV (Вольтер)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eДекреты об ассигнатах (1789–1790)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r121\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n122\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e122\u003c/span\u003e\u003cspan\u003eМаскарад, с. 158\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Здесь не тевтонской пляской смерти / Вас встретят ряженые черти\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Серия гравюр Ганса Гольбейна Младшего \u0026#171;Образы смерти\u0026#187; (\u003cem\u003eLes Simulachres et histori\u0026#233;es faces de la mort\u003c/em\u003e, 1538) и средневековые немецкие настенные росписи \u0026#171;Пляски смерти\u0026#187; (\u003cem\u003eTotentanz\u003c/em\u003e в Любеке, Базеле, Берлине).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Герольд противопоставляет жизнерадостный итальянский карнавал мрачным североевропейским аллегориям смерти, уводящей в пляс людей всех сословий.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eОбразы смерти (Гольбейн)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eРосписи Пляски смерти\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r122\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n123\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e123\u003c/span\u003e\u003cspan\u003eМаскарад, с. 158\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;У папы туфлю лобызая, / Он с императорским венцом\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Ритуал императорской коронации в Риме (\u003cem\u003eOrdo Romanus XIV\u003c/em\u003e, хроника коронаций Оттона I и последующих германских императоров, вплоть до Карла V в 1530 г.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Целование папской туфли при коронации символизировало духовное главенство папы римского над светской властью императора (с. 373–374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eOrdo Romanus XIV\u003c/span\u003e\u003cspan class=\"chip end\"\u003eХроники императорских коронаций\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r123\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n124\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e124\u003c/span\u003e\u003cspan\u003eМаскарад, с. 159\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Дар Цереры дамам статным\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Овидий, \u0026#171;Фасты\u0026#187; (кн. IV, 393–620) и \u0026#171;Метаморфозы\u0026#187; (кн. V, 341–661 — Церера/Деметра, даровавшая людям земледелие и колосья пшеницы).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Золотой венок из колосьев — традиционный атрибут римской богини урожая и плодородия Цереры (с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eФасты (Овидий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r124\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n125\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e125\u003c/span\u003e\u003cspan\u003eМаскарад, с. 160\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Имени мне Теофраст / Дать не мог бы и не даст\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Теофраст Эресский (ок. 371–287 до н. э.), трактаты \u0026#171;Исследование о растениях\u0026#187; (\u003cem\u003eHistoria plantarum\u003c/em\u003e) и \u0026#171;О причинах растений\u0026#187; (\u003cem\u003eDe causis plantarum\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Греческий философ-перипатетик, ученик Аристотеля и основоположник научной ботаники, классифицировавший сотни видов растений (с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИсследование о растениях (Теофраст)\u003c/span\u003e\u003cspan class=\"chip\"\u003eО причинах растений (Теофраст)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r125\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n126\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e126\u003c/span\u003e\u003cspan\u003eМаскарад, с. 162\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Полишинели\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Итальянская комедия дель арте (\u003cem\u003eCommedia dell\u0026#39;arte\u003c/em\u003e, XVI–XVIII вв.; неаполитанский персонаж Пульчинелла / фр. Полишинель; ср. \u0026#171;Итальянское путешествие\u0026#187; И. В. Гёте, Неаполь, 1787).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Традиционная маска ленивого, хитрого и горбатого шута с двойным горбом (на груди и спине) (с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКомедия дель арте\u003c/span\u003e\u003cspan class=\"chip end\"\u003eИтальянское путешествие (Гёте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r126\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n127\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e127\u003c/span\u003e\u003cspan\u003eМаскарад, с. 164\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Певцы кладбищ и полуночи... отвлечены интереснейшей беседой с одним новопоявившимся вампиром\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u0026#171;Кладбищенская школа\u0026#187; английской поэзии XVIII в. (Эдвард Юнг \u0026#171;Ночные думы\u0026#187;, 1742; Томас Грей \u0026#171;Элегия, написанная на сельском кладбище\u0026#187;, 1751) и повесть Джона Полидори \u0026#171;Вампир\u0026#187; (1819, долго приписывавшаяся Байрону).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Иронический выпад Гёте против мрачных мотивов предромантизма и \u0026#171;вампирской\u0026#187; моды европейского романтизма 1810–1820-х гг.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eНочные думы (Юнг)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭлегия на сельском кладбище (Грей)\u003c/span\u003e\u003cspan class=\"chip\"\u003eВампир (Полидори)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r127\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n128\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e128\u003c/span\u003e\u003cspan\u003eМаскарад, с. 164\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Грации: Аглая, Гегемона, Ефросина\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гесиод, \u0026#171;Теогония\u0026#187; (ст. 907–909 — Аглая, Евфросина и Талия); Павсаний, \u0026#171;Описание Эллады\u0026#187; (кн. IX, гл. 35, 2 — две древние афинские хариты Авксо и Гегемона).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Гёте заменил третью гесиодовскую хариту Талию на Гегемону (\u0026#171;предводительницу\u0026#187;), чтобы связать триаду Граций с темой благородного даяния, восприятия и благодарности.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОписание Эллады (Павсаний)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r128\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n129\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e129\u003c/span\u003e\u003cspan\u003eМаскарад, с. 164–165\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Парки: Атропос, Клото, Лахезис\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гесиод, \u0026#171;Теогония\u0026#187; (ст. 217–222, 904–906); Платон, \u0026#171;Государство\u0026#187; (кн. X, 617c).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В мифе Клото прядёт нить жизни, Лахезис отмеряет её, а Атропос (\u0026#171;неотвратимая\u0026#187;) перерезает ножницами; в маскараде Гёте поменял роли Клото и Атропос местами (с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГосударство (Платон)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r129\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n130\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e130\u003c/span\u003e\u003cspan\u003eМаскарад, с. 165–166\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Фурии: Алекто, Мегера, Тизифона\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Вергилий, \u0026#171;Энеида\u0026#187; (кн. VI, 555–572; кн. VII, 324–340; кн. XII, 845); Аполлодор, \u0026#171;Мифологическая библиотека\u0026#187; (кн. I, гл. 1, 4).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Три сестры-фурии (эринии) — \u0026#171;Непрощающая\u0026#187; (Алекто), \u0026#171;Завистливая\u0026#187; (Мегера) и \u0026#171;Мстящая за убийство\u0026#187; (Тизифона) — олицетворяют в сцене клевету, супружескую рознь и кровавое возмездие (с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЭнеида (Вергилий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМифологическая библиотека (Аполлодор)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r130\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n131\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e131\u003c/span\u003e\u003cspan\u003eМаскарад, с. 166\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ночами злого духа Асмодея\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет (неканоническая Книга Товита, Тов. 3:8, 17); Вавилонский Талмуд (трактат \u0026#171;Гиттин\u0026#187;, 68а–б).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В Книге Товита демон Асмодей из ревности поочерёдно убил семерых мужей Сарры в первую брачную ночь; отсюда его роль разрушителя браков (с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Товита\u003c/span\u003e\u003cspan class=\"chip\"\u003eВавилонский Талмуд\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r131\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n132\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e132\u003c/span\u003e\u003cspan\u003eМаскарад, с. 166\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Камни вопиют о мести\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия: Книга пророка Аввакума (Авв. 2:11 — \u0026#171;камни из стен возопиют\u0026#187;) и Евангелие от Луки (Лк. 19:40 — \u0026#171;если они умолкнут, то камни возопиют\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Библейская формула неотвратимости возмездия даже при молчании людей.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига пророка Аввакума\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Луки\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r132\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n133\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e133\u003c/span\u003e\u003cspan\u003eМаскарад, с. 166–168\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eАллегорическая группа на слоне (Боязнь, Надежда, Разумность, Победа)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Франческо Петрарка, поэма \u0026#171;Триумфы\u0026#187; (\u003cem\u003eI Trionfi\u003c/em\u003e, XIV в.); серия триумфальных гравюр \u0026#171;Триумфальное шествие императора Максимилиана I\u0026#187; работы Ханса Бургкмайра и Альбрехта Дюрера (1516–1518); ренессансные книги эмблем (Андреа Альчато, \u0026#171;Emblematum liber\u0026#187;, 1531).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Ренессансный жанр политического триумфа, где слон, ведомый Разумностью (Благоразумием), несёт крылатую богиню Победы и ведёт на цепи главные страсти человека — Страх и Надежду.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТриумфы (Петрарка)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eТриумфальное шествие Максимилиана I\u003c/span\u003e\u003cspan class=\"chip\"\u003eКнига эмблем (Альчато)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r133\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n134\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e134\u003c/span\u003e\u003cspan\u003eМаскарад, с. 168\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Зоило-Терсит\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Илиада\u0026#187; (песнь II, ст. 212–277 — Терсит); Витрувий, \u0026#171;Десять книг об архитектуре\u0026#187; (кн. VII, предисл., \u0026#167; 8–9 — Зоил).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Объединение двух знаменитых античных злопыхателей: уродливого и трусливого горлопана Терсита из \u0026#171;Илиады\u0026#187; и ритора IV–III вв. до н. э. Зоила, прославившегося мелочной хулой на Гомера (с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eДесять книг об архитектуре (Витрувий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r134\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n135\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e135\u003c/span\u003e\u003cspan\u003eМаскарад, с. 171\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Плутус, он — богатства бог\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Аристофан, комедия \u0026#171;Плутос\u0026#187; (388 г. до н. э.); Гесиод, \u0026#171;Теогония\u0026#187; (ст. 969–974 — бог изобилия Плутос, смешавшийся в античности с Плутоном, владыкой подземных сокровищ, ср. Лукиан \u0026#171;Тимон\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В свите Плутуса-Плутона объединены символы земных недр (гномы) и природной щедрости (фавны, сатиры, нимфы, Пан) (с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eПлутос (Аристофан)\u003c/span\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r135\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n136\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e136\u003c/span\u003e\u003cspan\u003eМаскарад, с. 178\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;В долинах Гарца поделом / Мы дикими людьми слывем... в ручищу взял сосновый ствол\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Герб герцогства Брауншвейг-Люнебург (с XVI в.) и серебряные монеты Гарца (\u0026#171;Вильдеманнсталер\u0026#187; / \u003cem\u003eWildemannstaler\u003c/em\u003e) с изображением \u0026#171;дикого человека\u0026#187;, опирающегося на вырванную с корнем ель; Якоб Гримм, \u0026#171;Немецкая мифология\u0026#187; (гл. XVII — \u003cem\u003eWilde Leute\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Фольклорно-геральдические лесные великаны Гарца, изображавшиеся голыми, опоясанными листьями и с древесным стволом в руках.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eГерб Брауншвейг-Люнебурга\u003c/span\u003e\u003cspan class=\"chip end\"\u003eВильдеманнсталеры\u003c/span\u003e\u003cspan class=\"chip\"\u003eНемецкая мифология (Гримм)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r136\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n137\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e137\u003c/span\u003e\u003cspan\u003eМаскарад, с. 178\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Телохранители, каких / Нет и у римских пап самих\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e История папской Швейцарской гвардии (основана папой Юлием II в 1506 г.; хроника битвы при Риме в 1527 г.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Намёк на знаменитую отборную личную стражу римских пап.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eИстория Швейцарской гвардии\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r137\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n138\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e138\u003c/span\u003e\u003cspan\u003eМаскарад, с. 179\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Все в робости замрет кругом, / Едва забудется он сном... Панический безумный страх\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Феокрит, \u0026#171;Идиллии\u0026#187; (Идиллия I, ст. 15–18 — о полуденном гневе Пана); Полиэн, \u0026#171;Стратегемы\u0026#187; (кн. I, 2 — о происхождении \u0026#171;панического страха\u0026#187;); Павсаний, \u0026#171;Описание Эллады\u0026#187; (кн. X, гл. 23, 7).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В древней Греции верили, что в полдень бог лесов Пан спит и будить его опасно, а на войне внезапный безотчётный ужас приписывался крику Пана (\u0026#171;паника\u0026#187;, с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИдиллии (Феокрит)\u003c/span\u003e\u003cspan class=\"chip\"\u003eСтратегемы (Полиэн)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОписание Эллады (Павсаний)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r138\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n139\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e139\u003c/span\u003e\u003cspan\u003eСад для гулянья, с. 182\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Где на море всего сильней волненье, / Нырни на дно...\u0026#187; (описание красок подводного мира)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e И. В. Гёте, \u0026#171;Учение о цвете\u0026#187; (\u003cem\u003eZur Farbenlehre\u003c/em\u003e, 1810, дидактическая часть, \u0026#167; 78).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Повествование Мефистофеля о пурпурных и лазурных переливах под водой воспроизводит физико-оптические наблюдения самого поэта (с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eУчение о цвете (Гёте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r139\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n140\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e140\u003c/span\u003e\u003cspan\u003eСад для гулянья, с. 182\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Взметет Фетида раковинок пласт / И новому Пелею руку даст\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Илиада\u0026#187; (песнь XVIII, ст. 432–435; XXIV, 62–63); Катулл, поэма LXIV (\u0026#171;Свадьба Пелея и Фетиды\u0026#187;); Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. XI, 221–265).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Морская богиня Фетида вышла замуж за смертного царя Пелея (на их свадьбе собрались все олимпийцы), родив от него Ахилла; Мефистофель льстит императору, пророча ему столь же блестящий союз (с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eСвадьба Пелея и Фетиды (Катулл)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r140\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n141\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e141\u003c/span\u003e\u003cspan\u003eСад для гулянья, с. 182\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Своею тысячей одною ночью... Будь, как Шехеразада, плодовит\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Сборник арабских и персидских сказок \u0026#171;Тысяча и одна ночь\u0026#187; (впервые переведён на европейский язык А. Галланом, 1704–1717; нем. переводы XVIII–XIX вв.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Шехеразада спасала свою жизнь тем, что каждую ночь рассказывала царю Шахрияру новую увлекательную историю, обрывая её на самом интересном месте.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eТысяча и одна ночь\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r141\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n142\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e142\u003c/span\u003e\u003cspan\u003eСад для гулянья, с. 183\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я словно на седьмое небо взят!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Второе послание к Коринфянам (2 Кор. 12:2 — вознесение до третьего неба); Вавилонский Талмуд (трактат \u0026#171;Хагига\u0026#187;, 12б — учение о семи небесных сферах, высшая из которых, Аработ, — престол Бога).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Идиома, восходящая к представлению о седьмом, высшем небе блаженства.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eВторое послание к Коринфянам\u003c/span\u003e\u003cspan class=\"chip\"\u003eВавилонский Талмуд\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r142\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n143\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e143\u003c/span\u003e\u003cspan\u003eТемная галерея, с. 189–192\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;То — Матери\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Плутарх, \u0026#171;Сравнительные жизнеописания\u0026#187; (\u0026#171;Марцелл\u0026#187;, гл. 20); \u0026#171;Разговоры с Гёте\u0026#187; И. П. Эккермана (запись от 10 января 1830 г., с. 374); Платон, диалог \u0026#171;Тимей\u0026#187; (48e–52c) и \u0026#171;Государство\u0026#187; (кн. X — учение о вечных прообразах-эйдосах).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e У Плутарха в сицилийском городе Энгийон стоял древний храм богинь, называемых \u0026#171;Матерями\u0026#187;. Гёте соединил это редкое упоминание с платоновским учением о вневременном мире идей-прототипов (\u0026#171;сущностей чертёж\u0026#187;, с. 191).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eСравнительные жизнеописания (Плутарх)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eРазговоры с Гёте (Эккерман)\u003c/span\u003e\u003cspan class=\"chip\"\u003eТимей (Платон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГосударство (Платон)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r143\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n144\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e144\u003c/span\u003e\u003cspan\u003e195–202, Темная галерея / Рыцарский зал, с. 188\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eВызов духов Париса и Елены перед императором\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u0026#171;История о докторе Иоганне Фаусте\u0026#187; (изд. И. Шписа, 1587, гл. 33 — вызов Александра Македонского и его жены перед императором Карлом V, и гл. 49 — вызов Елены Троянской перед студентами).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Сюжет слияния двух знаменитых эпизодов народной книги: Фауст демонстрирует античные тени не в скромной пивной, а при императорском дворе (с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИстория о докторе Иоганне Фаусте (Шпис)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r144\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n145\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e145\u003c/span\u003e\u003cspan\u003eЯрко освещённые балы [залы], с. 193\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Но мы подобное подобным лечим, / Стопу — стопой, спинным хребтом — хребет\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Самуэль Ганеман, \u0026#171;Органон врачебного искусства\u0026#187; (\u003cem\u003eOrganon der rationellen Heilkunde\u003c/em\u003e, 1810) — главный принцип гомеопатии \u003cem\u003eSimilia similibus curentur\u003c/em\u003e (\u0026#171;Подобное излечивается подобным\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Буквальная ироническая пародия на популярный в начале XIX в. гомеопатический метод лечения (с. 374).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОрганон врачебного искусства (Ганеман)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r145\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n146\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e146\u003c/span\u003e\u003cspan\u003eРыцарский зал, с. 195\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;И как Атлант, подперший небо шеей\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гесиод, \u0026#171;Теогония\u0026#187; (ст. 517–520, 746–748); Гомер, \u0026#171;Одиссея\u0026#187; (песнь I, 52–54).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Титан Атлант, наказанный Зевсом держать на голове и плечах небесный свод, стал прообразом архитектурных атлантов и колонн.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОдиссея (Гомер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r146\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n147\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e147\u003c/span\u003e\u003cspan\u003eРыцарский зал, с. 197\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Не царский сын, а пастушок топорный\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Аполлодор, \u0026#171;Мифологическая библиотека\u0026#187; (кн. III, гл. 12, 5; Эпитома III, 2); Овидий, \u0026#171;Героиды\u0026#187; (послания V и XVI).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Из-за пророчества о гибели Трои троянский царевич Парис был в младенчестве брошен на горе Иде, где вырос пастухом; там перед ним предстали три богини (Гера, Афина, Афродита) ради Суда Париса (с. 375).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМифологическая библиотека (Аполлодор)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГероиды (Овидий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r147\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n148\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e148\u003c/span\u003e\u003cspan\u003eРыцарский зал, с. 199\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Стройна, крупна. А голова — мала\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Плиний Старший, \u0026#171;Естественная история\u0026#187; (кн. XXXIV, гл. 19, \u0026#167; 65 — о пропорциях статуй скульптора Лисиппа).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Плиний сообщает, что Лисипп (IV в. до н. э.) ввёл новый канон красоты, делая головы статуй меньше, а тела стройнее и выше, чем у Поликлета (с. 375).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЕстественная история (Плиний)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r148\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n149\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e149\u003c/span\u003e\u003cspan\u003eРыцарский зал, с. 199\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Она — луна, а он — Эндимион\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Аполлодор, \u0026#171;Мифологическая библиотека\u0026#187; (кн. I, гл. 7, 5); Лукиан, \u0026#171;Разговоры богов\u0026#187; (XI — диалог Афродиты и Селены); Овидий, \u0026#171;Героиды\u0026#187; (XVIII, 61–64).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Прекрасный юноша-охотник Эндимион был погружён в вечный сон, а богиня луны Селена (Диана) спускалась с неба целовать его спящего (с. 375).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМифологическая библиотека (Аполлодор)\u003c/span\u003e\u003cspan class=\"chip\"\u003eРазговоры богов (Лукиан)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГероиды (Овидий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r149\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n150\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e150\u003c/span\u003e\u003cspan\u003eРыцарский зал, с. 201\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Но в древней Трое, говорит рассказ, / Она старейшим по душе пришлась\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Илиада\u0026#187; (песнь III, ст. 154–160).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Увидев Елену на Скейских воротах, троянские старейшины шепчутся, что ради такой красоты не жаль терпеть беды многолетней войны.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r150\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n151\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e151\u003c/span\u003e\u003cspan\u003eРыцарский зал, с. 201\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Названье сцены, / Как видно, \u0026#171;Похищение Елены\u0026#187;\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Колуф Ликополитанский, поэма \u0026#171;Похищение Елены\u0026#187; (\u003cem\u003eἉρπαγὴ Ἑλένης\u003c/em\u003e, конец V — начало VI в. н. э.; в примечании на с. 375 имя искажено как \u0026#171;Калифос\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Учёный-педант при дворе ссылается на позднеантичную эпическую поэму о похищении Елены Парисом (с. 375).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eПохищение Елены (Колуф)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r151\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003ch3\u003e5. Вторая часть. Акт Второй (с. 202–261)\u003c/h3\u003e\n\u003cdiv class=\"note\" id=\"n152\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e152\u003c/span\u003e\u003cspan\u003eТесная готическая комната, с. 204\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;И сам ключами, как апостол Петр, / Земли и неба тайны отмыкает\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Новый Завет — Евангелие от Матфея (Мф. 16:19).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Слова Иисуса Христа Петру: \u0026#171;и дам тебе ключи Царства Небесного: и что свяжешь на земле, то будет связано на небесах...\u0026#187;.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Матфея\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r152\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n153\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e153\u003c/span\u003e\u003cspan\u003eТесная готическая комната, с. 206\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Если Леты муть в разлитье / Вам памяти песком не затянула\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Вергилий, \u0026#171;Энеида\u0026#187; (кн. VI, 705–715); Платон, \u0026#171;Государство\u0026#187; (кн. X, 621a).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Подземная река забвения Лета (см. также № 114).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЭнеида (Вергилий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГосударство (Платон)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r153\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n154\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e154\u003c/span\u003e\u003cspan\u003eТесная готическая комната, с. 206\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Но стрижка без косы, по-шведски\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e История европейской мужской моды 1790–1800-х гг. (переход от пудреных париков с косичкой эпохи рококо к короткой стрижке в духе \u0026#171;шведской\u0026#187; причёски и стрижки \u0026#171;\u0026#224; la Titus\u0026#187;, введённой в моду в революционной Франции и Германии).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Деталь облика Бакалавра маркирует смену поколений: от старого академизма XVIII в. к дерзкой молодёжи начала XIX в.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eИстория мужской моды 1790-х\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r154\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n155\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e155\u003c/span\u003e\u003cspan\u003eТесная готическая комната, с. 207–208\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Все опыт, опыт! Опыт это вздор... Мир не был до меня и создан мной. / Я вывел солнце из морского лона...\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Иоганн Готлиб Фихте, \u0026#171;Основа общего наукоучения\u0026#187; (\u003cem\u003eGrundlage der gesamten Wissenschaftslehre\u003c/em\u003e, 1794–1795); Ф. В. Й. Шеллинг, \u0026#171;Система трансцендентального идеализма\u0026#187; (1800).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Гротескная пародия на радикальный субъективный идеализм Фихте, согласно которому абсолютное \u0026#171;Я\u0026#187; полагает само себя и творит весь внешний мир (\u0026#171;не-Я\u0026#187;) как объект своей деятельности (с. 375).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОснова общего наукоучения (Фихте)\u003c/span\u003e\u003cspan class=\"chip\"\u003eСистема трансцендентального идеализма (Шеллинг)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r155\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n156\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e156\u003c/span\u003e\u003cspan\u003eТесная готическая комната, с. 208\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Чуть человеку стукнет тридцать лет, / Он, как мертвец, уже созрел для гроба\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Клод Адриан Гельвеций, трактат \u0026#171;О человеке\u0026#187; (\u003cem\u003eDe l\u0026#39;homme\u003c/em\u003e, 1773, разд. II, гл. 10) / \u0026#171;Об уме\u0026#187; (1758).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Парафраза утверждения Гельвеция о том, что к 30–35 годам в человеке уже пробуждены все мысли, на которые он способен, а дальше ум лишь повторяет старое (с. 375).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eО человеке (Гельвеций)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОб уме (Гельвеций)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r156\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n157\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e157\u003c/span\u003e\u003cspan\u003eЛаборатория в средневековом духе, с. 211\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Гомункул\u0026#187; (искусственное создание человечка в реторте)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Теофраст Парацельс, трактат \u0026#171;О природе вещей\u0026#187; (\u003cem\u003eDe natura rerum\u003c/em\u003e, кн. I — \u0026#171;О рождении естественных вещей\u0026#187;, 1537); труды профессора натурфилософии И. Я. Вагнера (упоминаемого в примеч. на с. 376 как \u0026#171;П. Вагнер\u0026#187;); философия Канта, Фихте и Шеллинга (с. 375–376).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Парацельс описал алхимический способ вырастить \u003cem\u003ehomunculus\u003c/em\u003e (\u0026#171;человечка\u0026#187;) в закрытом сосуде без материнского лона; Гёте объединил этот мотив с сатирой на искусственную \u0026#171;книжную\u0026#187; жизнь и абстрактный идеализм.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eО природе вещей (Парацельс)\u003c/span\u003e\u003cspan class=\"chip\"\u003eТруды И. Я. Вагнера\u003c/span\u003e\u003cspan class=\"chip\"\u003eФилософия Канта, Фихте и Шеллинга\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r157\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n158\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e158\u003c/span\u003e\u003cspan\u003eЛаборатория; с. 225, У Нижнего Пенея, с. 212\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eСон Фауста о раздевающихся женщинах и лебеде у пруда\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Еврипид, \u0026#171;Елена\u0026#187; (ст. 17–21); Аполлодор, \u0026#171;Мифологическая библиотека\u0026#187; (кн. III, гл. 10, 7); Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. VI, 109) и \u0026#171;Героиды\u0026#187; (XVI, 55–58); картины \u0026#171;Леда и лебедь\u0026#187; Корреджо (ок. 1531) и Микеланджело.\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Миф о том, как Зевс в облике прекрасного лебедя соблазнил спартанскую царицу Леду у берега реки Эврот; от этого союза родилась Елена.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЕлена (Еврипид)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМифологическая библиотека (Аполлодор)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГероиды (Овидий)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЛеда и лебедь (Корреджо)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЛеда (Микеланджело)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r158\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n159\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e159\u003c/span\u003e\u003cspan\u003eЛаборатория, с. 214\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Течет средь рощ извилистый Пеней, / А выше — горы и следы камней / Старинного и нового Фарсала\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Юлий Цезарь, \u0026#171;Записки о гражданской войне\u0026#187; (кн. III, гл. 82–99 — битва при Фарсале 9 августа 48 г. до н. э.); Страбон, \u0026#171;География\u0026#187; (кн. IX, гл. 5 — Фессалия и река Пеней).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Историческое место решающего поражения Помпея Великого от Юлия Цезаря в Фессалии на севере Греции (с. 377).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЗаписки о гражданской войне (Цезарь)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГеография (Страбон)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r159\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n160\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e160\u003c/span\u003e\u003cspan\u003eКлассическая Вальпургиева ночь, с. 215–216\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Эрихто мрачная... Помпеи Великий... а Цезарь взвешивал...\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Марк Анней Лукан, поэма \u0026#171;Фарсалия, или О гражданской войне\u0026#187; (кн. VI, ст. 507–830).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В кн. VI \u0026#171;Фарсалии\u0026#187; Секст Помпей перед битвой приходит к жуткой фессалийской ведьме Эрихто, которая воскрешает труп павшего солдата, чтобы предсказать гибель Помпея и крушение Римской республики (с. 376).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eФарсалия (Лукан)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r160\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n161\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e161\u003c/span\u003e\u003cspan\u003eКлассическая Вальпургиева ночь; см. также с. 291: \u0026#171;словно сын земли Антей\u0026#187;, с. 217\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;И, встав с земли, я, как Антей, стою\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Аполлодор, \u0026#171;Мифологическая библиотека\u0026#187; (кн. II, гл. 5, 11); Лукан, \u0026#171;Фарсалия\u0026#187; (кн. IV, ст. 593–655).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Великан Антей, сын богини земли Геи, получал новые силы каждый раз, когда прикасался к земле; Геракл победил его, лишь подняв в воздух.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМифологическая библиотека (Аполлодор)\u003c/span\u003e\u003cspan class=\"chip\"\u003eФарсалия (Лукан)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r161\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n162\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e162\u003c/span\u003e\u003cspan\u003e233–234, У Верхнего Пенея, с. 218–219\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Грифы\u0026#187;, \u0026#171;Муравьи (огромного роста)\u0026#187;, \u0026#171;Аримаспы\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Геродот, \u0026#171;История\u0026#187; (кн. III, гл. 102–105 — гигантские муравьи в Индии; гл. 116 и кн. IV, гл. 13, 27 — аримаспы и грифы); Аристей Проконнесский, поэма \u0026#171;Аримаспея\u0026#187; (в пересказе Геродота и Павсания).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Геродот рассказывает о муравьях величиной почти с собаку, вырывающих золотой песок, и об одноглазом северном народе аримаспов, похищающих золото из-под когтей стерегущих его грифов (с. 376).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИстория (Геродот)\u003c/span\u003e\u003cspan class=\"chip\"\u003eАримаспея (Аристей Проконнесский)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r162\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n163\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e163\u003c/span\u003e\u003cspan\u003e222, У Верхнего Пенея, с. 219\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Сфинкс\u0026#187; / \u0026#171;Пред ними некогда стоял Эдип\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Софокл, трагедия \u0026#171;Царь Эдип\u0026#187; (ст. 35–39, 391–398, 1524–1525); Аполлодор, \u0026#171;Мифологическая библиотека\u0026#187; (кн. III, гл. 5, 8).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Фиванский Сфинкс (существо с головой женщины и телом львицы) задавал путникам загадку о существе, ходящем утром на четырёх ногах, днём на двух, вечером на трёх, пока её не разгадал Эдип (с. 376).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЦарь Эдип (Софокл)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМифологическая библиотека (Аполлодор)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r163\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n164\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e164\u003c/span\u003e\u003cspan\u003eУ Верхнего Пенея, с. 219\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Они меня назвали в старой пьесе / \u0026#171;The old Iniquity\u0026#187; с обычной спесью\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Бен Джонсон, комедия \u0026#171;Чёрт — осёл\u0026#187; (\u003cem\u003eThe Devil Is an Ass\u003c/em\u003e, 1616, акт I, сц. 1); У. Шекспир, хроника \u0026#171;Ричард III\u0026#187; (акт III, сц. 1 — \u003cem\u003e\u0026#171;the formal Vice, Iniquity\u0026#187;\u003c/em\u003e) и \u0026#171;Генрих IV, ч. 1\u0026#187; (акт II, сц. 4).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В английских моралите XVI в. \u003cem\u003eIniquity\u003c/em\u003e (\u0026#171;Неправда\u0026#187; / \u0026#171;Порок\u0026#187;) — традиционный комический чёрт-шут (с. 376).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЧёрт — осёл (Бен Джонсон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eРичард III (Шекспир)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГенрих IV (Шекспир)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r164\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n165\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e165\u003c/span\u003e\u003cspan\u003eУ Верхнего Пенея, с. 221–222\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Сирены\u0026#187; / \u0026#171;От этих Одиссей чуть не погиб, / В пеньковых путах корчась\u0026#187; / \u0026#171;Некогда Улисс любезный...\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Одиссея\u0026#187; (песнь XII, ст. 39–54, 165–200).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Чтобы услышать чарующее, но смертельное пение полуженщин-полуптиц сирен и не броситься в море, Одиссей (Улисс) велел залепить уши гребцам воском, а себя крепко привязать верёвками к мачте (с. 376).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОдиссея (Гомер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r165\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n166\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e166\u003c/span\u003e\u003cspan\u003eУ Верхнего Пенея, с. 222–223\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Убил последних бабок Геркулес\u0026#187; / \u0026#171;Стремительнее стрел Алкида... Над нами мчатся стимфалиды\u0026#187; / \u0026#171;То головы змеи Лернейской\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Аполлодор, \u0026#171;Мифологическая библиотека\u0026#187; (кн. II, гл. 5, 2 — Лернейская гидра; гл. 5, 6 — Стимфалийские птицы); Беньямин Гедерих, \u0026#171;Основательный мифологический словарь\u0026#187; (\u003cem\u003eGr\u0026#252;ndliches mythologisches Lexikon\u003c/em\u003e, 1770).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Упоминание подвигов Геракла (Алкида): уничтожение девятиглавой Лернейской гидры и хищных Стимфалийских птиц, бросавших острые железные перья как стрелы (с. 377).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМифологическая библиотека (Аполлодор)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМифологический словарь (Гедерих)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r166\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n167\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e167\u003c/span\u003e\u003cspan\u003eУ Верхнего Пенея, с. 224\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Чтоб направлять луны и солнца бег. / Мы сидим у пирамид...\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Плиний Старший, \u0026#171;Естественная история\u0026#187; (кн. XXXVI, гл. 17 — Великий сфинкс); Геродот, \u0026#171;История\u0026#187; (кн. II — о разливах Нила); мифологический словарь Б. Гедерихса и астрологическая традиция (знаки Льва и Девы).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e По античным и просветительским толкованиям, египетский сфинкс (тело льва и голова девы) символизировал зодиакальные месяцы июль (Лев) и август (Дева) — время летнего разлива Нила, служившего основой египетского календаря (с. 377).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЕстественная история (Плиний)\u003c/span\u003e\u003cspan class=\"chip\"\u003eИстория (Геродот)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМифологический словарь (Гедерих)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r167\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n168\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e168\u003c/span\u003e\u003cspan\u003eУ Нижнего Пенея, с. 226–228\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Хирон... Филиры знаменитый сын\u0026#187;, \u0026#171;Была Паллада скверной няней\u0026#187;, \u0026#171;Круг аргонавтов: Диоскуры, Бореады, Язон, Орфей, Линкей, Геркулес\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гесиод, \u0026#171;Теогония\u0026#187; (ст. 1001–1002 — Филира и Кронос, родители Хирона); Аполлоний Родосский, поэма \u0026#171;Аргонавтика\u0026#187; (кн. I, ст. 23–233 — перечень аргонавтов; кн. I, 151–155 — о зорком рулевом Линкее); Аполлодор, \u0026#171;Мифологическая библиотека\u0026#187; (кн. I, гл. 9, 16; кн. III, гл. 13, 6).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Мудрый кентавр Хирон, врач и воспитатель героев (Ахилла, Ясона, Асклепия), перечисляет участников похода на корабле \u0026#171;Арго\u0026#187; за золотым руном и называет величайшим из них Геракла (с. 377).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003cspan class=\"chip\"\u003eАргонавтика (Аполлоний Родосский)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМифологическая библиотека (Аполлодор)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r168\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n169\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e169\u003c/span\u003e\u003cspan\u003eУ Нижнего Пенея, с. 228–229\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;В те дни похитили Елену... Чрез Элевзинские болота\u0026#187; / \u0026#171;удалось Ахиллу в Ферах... С ней жить... вне времени\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Плутарх, \u0026#171;Сравнительные жизнеописания\u0026#187; (\u0026#171;Тесей\u0026#187;, гл. 31–34 — похищение 10-летней Елены Тезеем и освобождение её братьями Диоскурами; Афидн — друг Тезея в Аттике); Павсаний, \u0026#171;Описание Эллады\u0026#187; (кн. III, гл. 19, 11–13 — посмертный брак Елены и Ахилла на о. Левке); Б. Гедерих, \u0026#171;Мифологический словарь\u0026#187;.\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Объяснение мифологической \u0026#171;вневременности\u0026#187; Елены: она переживала приключения и браки от глубокой древности (похищение Тезеем) до загробного союза с Ахиллом (с. 379–380).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТесей (Плутарх)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОписание Эллады (Павсаний)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМифологический словарь (Гедерих)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r169\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n170\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e170\u003c/span\u003e\u003cspan\u003eУ Нижнего Пенея, с. 230–231\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Дочь Эскулапа, Манто... Орфея тайно я сюда ввела\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Стаций, \u0026#171;Фиваида\u0026#187; (кн. IV, 463 — вещунья Манто); Данте Алигьери, \u0026#171;Божественная комедия\u0026#187; (\u0026#171;Ад\u0026#187;, песнь XX, 52–93 — о прорицательнице Манто); Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. X, 1–63 — нисхождение Орфея в Аид к Персефоне за Эвридикой).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Манто (у Гёте — дочь бога медицины Эскулапа) открывает Фаусту тайный вход в подземный мир к Персефоне, напоминая о судьбе Орфея, которому удалось спуститься в Аид, но не удержать Эвридику.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eФиваида (Стаций)\u003c/span\u003e\u003cspan class=\"chip\"\u003eБожественная комедия (Данте)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r170\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n171\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e171\u003c/span\u003e\u003cspan\u003eУ Нижнего Пенея, с. 230\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Здесь Греция и Рим решали спор... при Пинде\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Тит Ливий, \u0026#171;История от основания города\u0026#187; (кн. XLIV, гл. 37–43); Плутарх, \u0026#171;Эмилий Павел\u0026#187; (гл. 16–23) — битва при Пидне (22 июня 168 г. до н. э.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Победа римского полководца Эмилия Павла над последним македонским царём Персеем, положившая конец независимости Греции (в тексте \u0026#171;Пидна\u0026#187; контаминирована с горами Пинда, с. 377).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИстория от основания города (Тит Ливий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭмилий Павел (Плутарх)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r171\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n172\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e172\u003c/span\u003e\u003cspan\u003eУ верховьев Пенея, с. 232\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Зодчий острова Делоса... Женщине, рожать готовой\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомеровский гимн III \u0026#171;К Аполлону Делосскому\u0026#187; (ст. 1–139); Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. VI, 184–203); Каллимах, \u0026#171;Гимн к Делосу\u0026#187; (ст. 28–54).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Преследуемая ревнивой Герой и змеем Пифоном беременная Латона (Лето) не могла нигде ступить на твёрдую землю, пока Посейдон не остановил и не поднял со дна моря остров Делос, где родились Аполлон и Артемида (у Гёте этот подвиг передан духу землетрясений Сейсмосу, с. 377).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eГимн к Аполлону Делосскому\u003c/span\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГимн к Делосу (Каллимах)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r172\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n173\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e173\u003c/span\u003e\u003cspan\u003eУ верховьев Пенея, с. 233\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Хаос и Ночь\u0026#187; / \u0026#171;Мы горы Пелион и Оссу / Подбрасывали, как мячи. / ...сверху на Парнас надели / Два пика\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гесиод, \u0026#171;Теогония\u0026#187; (ст. 116–125 — первородные Хаос и Ночь/Нюкта); Гомер, \u0026#171;Одиссея\u0026#187; (песнь XI, ст. 305–320 — Алоады, поставившие Оссу на Олимп и Пелион на Оссу); Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. I, 151–155).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Сейсмос приписывает себе титаническое громождение гор, отражая в речи вулканическую теорию катастроф (с. 377).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОдиссея (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r173\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n174\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e174\u003c/span\u003e\u003cspan\u003eУ верховьев Пенея, с. 234–236\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Пигмеи\u0026#187;, \u0026#171;Дактили\u0026#187;, \u0026#171;мирмидоны\u0026#187;, \u0026#171;Ивиковы журавли\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Илиада\u0026#187; (песнь III, ст. 3–6 — вражда пигмеев и журавлей); Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. VII, 614–657 — превращение муравьёв в народ мирмидонян); Диодор Сицилийский, \u0026#171;Историческая библиотека\u0026#187; (кн. V, гл. 64 — идейские дактили-кузнецы); баллада Ф. Шиллера \u0026#171;Ивиковы журавли\u0026#187; (1797, на сюжет Плутарха \u0026#171;О болтливости\u0026#187;, гл. 14).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Столкновение карликов-металлургов (пигмеев) с болотными птицами и мстительными журавлями поэта Ивика Гёте превращает в аллегорию спора вулканизма и нептунизма (с. 377).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eИсторическая библиотека (Диодор)\u003c/span\u003e\u003cspan class=\"chip\"\u003eИвиковы журавли (Шиллер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r174\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n175\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e175\u003c/span\u003e\u003cspan\u003eУ верховьев Пенея, с. 236–238\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ламии\u0026#187;, \u0026#171;Я тетушка твоя Эмпуза / С ослиною ногой кургузой\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Аристофан, комедия \u0026#171;Лягушки\u0026#187; (ст. 288–295 — оборотень Эмпуза с медной/ослиной ногой); Флавий Филострат, \u0026#171;Жизнь Аполлония Тианского\u0026#187; (кн. II, гл. 4 — Эмпуза; кн. IV, гл. 25 — ламия-соблазнительница в Коринфе).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Античные вампиры и оборотни: при приближении Мефистофеля прекрасные девы-ламии оборачиваются уродливыми призраками и прахом (с. 377).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЛягушки (Аристофан)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЖизнь Аполлония Тианского (Филострат)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r175\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n176\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e176\u003c/span\u003e\u003cspan\u003eУ верховьев Пенея, с. 241–244\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Анаксагор (Фалесу)\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Аристотель, \u0026#171;Метафизика\u0026#187; (кн. I, гл. 3, 983b — учение Фалеса Милетского о воде как начале всего сущего) и \u0026#171;Метеорологика\u0026#187; / Плутарх \u0026#171;Лисандр\u0026#187; (гл. 12 — учение Анаксагора о раскалённых камнях небесных тел в связи с падением метеорита в 467 г. до н. э.); научный спор XVIII–XIX вв. между А. Г. Вернером (\u003cem\u003eнептунизм\u003c/em\u003e) и Дж. Хаттоном / Л. фон Бухом / А. Гумбольдтом (\u003cem\u003eвулканизм\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В лице двух греческих досократиков сталкиваются теории постепенного осаждения из воды (нептунизм, к которому склонялся Гёте) и внезапных огненных извержений (вулканизм) (с. 377–378).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМетафизика (Аристотель)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМетеорологика (Аристотель)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЛисандр (Плутарх)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eСпор нептунистов и вулканистов\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r176\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n177\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e177\u003c/span\u003e\u003cspan\u003eУ верховьев Пенея, с. 243\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Луна, Диана и Геката / Я обращаюсь в высоту / И твой предвечный образ чту / В трех этих именах, тройчатый!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. VII, 194, 207–209 — заклинание Медеи и сведение луны); Гораций, \u0026#171;Эподы\u0026#187; (V, 45–46; XVII, 77); Аристофан, \u0026#171;Облака\u0026#187; (ст. 749–750 — фессалийские ведьмы, сводящие луну); Сервий, \u0026#171;Комментарий к „Энеиде“\u0026#187; (кн. IV, 511 — тройная Геката: Луна, Диана, Прозерпина).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Призыв к трёхликой богине (\u003cem\u003eHecate Triformis\u003c/em\u003e) сопровождается фессалийским колдовским чудом — падением камня с луны (с. 378).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭподы (Гораций)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОблака (Аристофан)\u003c/span\u003e\u003cspan class=\"chip\"\u003eКомментарий к Энеиде (Сервий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r177\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n178\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e178\u003c/span\u003e\u003cspan\u003eУ верховьев Пенея, с. 244–247\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;И Орс, и Рее... Там форкиады скорчились внутри\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гесиод, \u0026#171;Теогония\u0026#187; (ст. 270–273 — три старухи-грайи, дочери Форкиса и Кето); Эсхил, \u0026#171;Прикованный Прометей\u0026#187; (ст. 794–797 — Форкиды с одним общим глазом и одним зубом).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Три сестры-грайи (Форкиады) жили во мраке, передавая друг другу единственный глаз и зуб; Мефистофель заимствует их уродливый облик для III акта (с. 379).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003cspan class=\"chip\"\u003eПрикованный Прометей (Эсхил)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r178\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n179\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e179\u003c/span\u003e\u003cspan\u003eУ верховьев Пенея, с. 247\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Меня все примут за гермафродита!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. IV, 285–388 — слияние юноши Гермафродита и нимфы Салмакиды в двуполое существо).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Ироническая реакция Мефистофеля на своё превращение в женщину-Форкиаду.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r179\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n180\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e180\u003c/span\u003e\u003cspan\u003eСкалистые бухты Эгейского моря, с. 247–260\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Нереиды и тритоны\u0026#187;, \u0026#171;Нерей\u0026#187;, \u0026#171;Дориды\u0026#187;, \u0026#171;Галатея\u0026#187;, \u0026#171;Киприда в Пафосе\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гесиод, \u0026#171;Теогония\u0026#187; (ст. 233–264 — вещий старец Нерей и 50 дочерей-нереид от Дориды, в т. ч. Галатея; ст. 192–200 — выход Афродиты Киприды на Кипр); Филострат Старший, \u0026#171;Картины\u0026#187; (кн. II, 18 — Галатея на раковине-колеснице); фреска Рафаэля \u0026#171;Триумф Галатеи\u0026#187; (1511–1512, вилла Фарнезина в Риме).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Морской праздник с Галатеей, заступающей место богини красоты Афродиты, воссоздаёт античную мифологию и ренессансную живопись, знакомую Гёте по поездке в Рим (с. 378).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003cspan class=\"chip\"\u003eКартины (Филострат Старший)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eТриумф Галатеи (Рафаэль)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r180\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n181\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e181\u003c/span\u003e\u003cspan\u003eСкалистые бухты Эгейского моря, с. 249\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Как я Париса предостерегал... / Улисса остерег я наперед / О том, что он к Циклопу попадет, / И предсказал плененье у Цирцеи\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гораций, \u0026#171;Оды\u0026#187; (кн. I, ода 15 — \u0026#171;Пророчество Нерея\u0026#187; Парису, везущему Елену, о гибели Трои); Гомер, \u0026#171;Одиссея\u0026#187; (песнь IX, 105–542 — Полифем; песнь X, 135–400 — волшебница Кирка/Цирцея).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Нерей выступает как прорицатель-мизантроп, чьи предостережения о войнах и бедах люди упрямо пропускали мимо ушей (с. 378).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОды (Гораций)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОдиссея (Гомер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r181\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n182\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e182\u003c/span\u003e\u003cspan\u003e251–252, Скалистые бухты Эгейского моря, с. 248\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;К высоким кабирам. / О них в Самофракии / Предания всякие\u0026#187; / \u0026#171;На щите Хелоны\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Ф. В. Й. Шеллинг, трактат \u0026#171;О божествах Самофракии\u0026#187; (\u003cem\u003e\u0026#220;ber die Gottheiten von Samothrake\u003c/em\u003e, 1815); Сервий, \u0026#171;Комментарий к „Энеиде“\u0026#187; (кн. I, 505 — нимфа Хелона, превращённая Гермесом в черепаху за отказ прийти на свадьбу Зевса и Геры).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Загадочные самофракийские божки-кабиры, похожие на глиняные горшки, и спор о том, сколько их (три, семь или восемь), — прямая сатира Гёте на шеллингианскую мистическую филологию (с. 378).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eО божествах Самофракии (Шеллинг)\u003c/span\u003e\u003cspan class=\"chip\"\u003eКомментарий к Энеиде (Сервий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r182\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n183\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e183\u003c/span\u003e\u003cspan\u003eСкалистые бухты Эгейского моря, с. 252–256\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Протей\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Одиссея\u0026#187; (песнь IV, ст. 384–570); Вергилий, \u0026#171;Георгики\u0026#187; (кн. IV, 387–529).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Протей — вещий морской старец, способный мгновенно превращаться в любое животное, огонь или воду; у Гёте он воплощает принцип эволюционной метаморфозы форм (с. 378).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОдиссея (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГеоргики (Вергилий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r183\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n184\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e184\u003c/span\u003e\u003cspan\u003eСкалистые бухты Эгейского моря, с. 255\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Родосские тельхины... Мы образ его изваяли впервые\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Диодор Сицилийский, \u0026#171;Историческая библиотека\u0026#187; (кн. V, гл. 55); Страбон, \u0026#171;География\u0026#187; (кн. XIV, гл. 2, 7); Плиний Старший, \u0026#171;Естественная история\u0026#187; (кн. XXXIV, гл. 18, \u0026#167; 41 — падение Колосса Родосского от землетрясения).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Тельхины — древние обитатели Родоса, первыми начавшие отливать статуи богов из меди (упоминается также их гигантский Колосс Гелиоса, разрушенный стихией, с. 378).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИсторическая библиотека (Диодор)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГеография (Страбон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЕстественная история (Плиний)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eКолосс Родосский\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r184\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n185\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e185\u003c/span\u003e\u003cspan\u003eСкалистые бухты Эгейского моря, с. 257\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Псиллы и марсы... Ничей не пугает девиз: / Креста ли, или полумесяца, / Орла иль крылатого льва\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Плиний Старший, \u0026#171;Естественная история\u0026#187; (кн. VII, гл. 2, \u0026#167; 14–15 — племена заклинателей змей псиллов и марсов); Лукан, \u0026#171;Фарсалия\u0026#187; (кн. IX, 890–937); хроники владычества в Восточном Средиземноморье (Римской империи, Венецианской республики, рыцарей-крестоносцев на Кипре и Османской империи).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Перечисление сменявшихся геральдических эмблем завоевателей Эгейского моря (римский орёл, крылатый лев св. Марка в Венеции, крест крестоносцев, османский полумесяц, с. 378).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЕстественная история (Плиний)\u003c/span\u003e\u003cspan class=\"chip\"\u003eФарсалия (Лукан)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eХроники Восточного Средиземноморья\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r185\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n186\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e186\u003c/span\u003e\u003cspan\u003eСкалистые бухты Эгейского моря, с. 260\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Хвала тебе, Эрос, огонь первозданный\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гесиод, \u0026#171;Теогония\u0026#187; (ст. 116–122); Платон, \u0026#171;Пир\u0026#187; (178b); Орфические гимны (гимна LVIII \u0026#171;К Эроту\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В древнейших космогониях Эрос (Любовь) — одна из первых мировых сил, соединяющая стихии в живое целое (с. 378).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003cspan class=\"chip\"\u003eПир (Платон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОрфические гимны\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r186\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003ch3\u003e6. Вторая часть. Акт Третий (с. 261–303)\u003c/h3\u003e\n\u003cdiv class=\"note\" id=\"n187\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e187\u003c/span\u003e\u003cspan\u003eс. с. 261–263\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eЗавязка сцены \u0026#171;Перед дворцом Менелая в Спарте\u0026#187; (высадка Елены, похищение на Цитере, подозрительность Менелая)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Еврипид, трагедии \u0026#171;Орест\u0026#187; (ст. 57–70 — Менелай привозит Елену из Трои и тайно отправляет вперёд в Спарту), \u0026#171;Троянки\u0026#187; и \u0026#171;Елена\u0026#187;; Беньямин Гедерих, \u0026#171;Основательный мифологический словарь\u0026#187; (ст. \u003cem\u003eHelena\u003c/em\u003e — похищение на о. Кифера/Цитера в храме Дианы).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Построение и стихотворный размер сцены (античный триметр, хоровые строфы, антистрофы и эпод) точно имитируют древнегреческую трагедию (с. 379).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОрест (Еврипид)\u003c/span\u003e\u003cspan class=\"chip\"\u003eТроянки (Еврипид)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЕлена (Еврипид)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМифологический словарь (Гедерих)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r187\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n188\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e188\u003c/span\u003e\u003cspan\u003eПеред дворцом Менелая, с. 263\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Что предначертано, знать не ищи\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Еврипид, трагедии \u0026#171;Андромаха\u0026#187; и \u0026#171;Елена\u0026#187; (финальные хоровые строки в ряде драм Еврипида о неисповедимости судьбы; ср. примечание на с. 379).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Гномическая хоровая сентенция в духе концовок еврипидовских трагедий.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eАндромаха (Еврипид)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЕлена (Еврипид)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r188\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n189\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e189\u003c/span\u003e\u003cspan\u003eПеред дворцом Менелая, с. 265\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;божества стигийские\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Илиада\u0026#187; (песнь XV, ст. 37); Вергилий, \u0026#171;Энеида\u0026#187; (кн. VI, 252, 323 — подземная река Стикс и божества Аида).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Обозначение инфернальных сил преисподней и богинь мести эриний (с. 379).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭнеида (Вергилий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r189\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n190\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e190\u003c/span\u003e\u003cspan\u003eПеред дворцом Менелая, с. 269\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Жив твой отец Эреб? Жива ль Ночь-матушка?\u0026#187; / \u0026#171;сестрица Сцилла\u0026#187; / \u0026#171;С Тирезием седым в аду заигрывай\u0026#187; / \u0026#171;мамка Орионова\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гесиод, \u0026#171;Теогония\u0026#187; (ст. 123–125 — Эреб и Нюкта/Ночь, дети Хаоса); Гомер, \u0026#171;Одиссея\u0026#187; (песнь X, 492–495 — слепой прорицатель Тирезий в Аиде; песнь XI, 309–310, 572–575 — великан Орион; песнь XII, 85–100 — шестиглавая Сцилла).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Ритуальная словесная дуэль (стихомифия) хора с Форкиадой использует мифологические родословные и античную гиперболу баснословной старости (быть старше Тирезия или кормилицей великана Ориона) (с. 379).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОдиссея (Гомер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r190\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n191\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e191\u003c/span\u003e\u003cspan\u003eПеред дворцом Менелая, с. 270–271\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eМифологические эпизоды биографии Елены (похищение Тезеем и Афидном, любовь к Патроклу, брак с Менелаем и рождение Гермионы, отлучка на Крит, двойник Елены в Трое и пребывание в Египте, посмертный брак с Ахиллом)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Плутарх, \u0026#171;Тесей\u0026#187; (гл. 31–34 — Тезей и Афидн); Стесихор, \u0026#171;Палинодия\u0026#187; (у Платона в \u0026#171;Федре\u0026#187;, 243a) и Еврипид, \u0026#171;Елена\u0026#187; (ст. 31–67 — в Трое был эфирный призрак, а истинную Елену Гермес унёс в Египет); Птолемей Гефестион / Ликофрон \u0026#171;Александра\u0026#187; (симпатия к Патроклу); Гомер, \u0026#171;Одиссея\u0026#187; (IV, 12–14 — дочь Гермиона); Павсаний, \u0026#171;Описание Эллады\u0026#187; (кн. III, гл. 19, 11–13 — посмертный союз Ахилла и Елены на острове Левка).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Форкиада сбивает Елену с толку, сталкивая все противоречивые античные версии её мифа, чтобы заставить её усомниться в собственной реальности (с. 379–380).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТесей (Плутарх)\u003c/span\u003e\u003cspan class=\"chip\"\u003eПалинодия (Стесихор)\u003c/span\u003e\u003cspan class=\"chip\"\u003eФедр (Платон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЕлена (Еврипид)\u003c/span\u003e\u003cspan class=\"chip\"\u003eАлександра (Ликофрон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОдиссея (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОписание Эллады (Павсаний)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r191\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n192\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e192\u003c/span\u003e\u003cspan\u003eПеред дворцом Менелая, с. 272\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Напускное сочувствие / Волка в шкуре овечьей / Страшней и опаснее / Пса трехголового\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Новый Завет — Евангелие от Матфея (Мф. 7:15 — лжепророки в овечьей шкуре, внутри волки хищные); Гесиод, \u0026#171;Теогония\u0026#187; (ст. 311–312 — пёс Кербер/Цербер); Вергилий, \u0026#171;Энеида\u0026#187; (кн. VI, 417–423).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Хор соединяет евангельскую метафору лицемерия с образом трёхглавого пса Кербера, стража врат Аида.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Матфея\u003c/span\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭнеида (Вергилий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r192\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n193\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e193\u003c/span\u003e\u003cspan\u003eПеред дворцом Менелая, с. 273\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;я под кровельным венцом / На стропиле вас повешу, словно пойманных дроздов\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Одиссея\u0026#187; (песнь XXII, ст. 465–473).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Дословное воспроизведение гомеровского сравнения: Телемах вешает неверных служанок на канате под кровлей двора, где они бьются, \u0026#171;как дрозды в силке\u0026#187; (с. 380).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОдиссея (Гомер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r193\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n194\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e194\u003c/span\u003e\u003cspan\u003eПеред дворцом Менелая, с. 274\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Если только милость Реи, матери богов великой\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гесиод, \u0026#171;Теогония\u0026#187; (ст. 453–491); Лукреций, \u0026#171;О природе вещей\u0026#187; (кн. II, 600–643 — Великая мать богов Рея/Кибела).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Мольба троянок к матери Зевса и верховных олимпийских богов.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТеогония (Гесиод)\u003c/span\u003e\u003cspan class=\"chip\"\u003eО природе вещей (Лукреций)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r194\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n195\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e195\u003c/span\u003e\u003cspan\u003e288, Перед дворцом Менелая / Внутренний двор замка, с. 275\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Горсть северян, страны полночной выходцы. / Построив замок, в нем они запрятались\u0026#187; / \u0026#171;Пускай Коринфский перешеек / Германец валом обведет. / Ахею... Возьмет в свое владенье гот... франки... саксам... норманнам\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Анонимная \u0026#171;Морейская хроника\u0026#187; (XIV в.); Жоффруа де Виллардуэн, \u0026#171;Завоевание Константинополя\u0026#187; (XIII в.) — история Четвёртого крестового похода (1204) и основания франкского Ахейского княжества в Пелопоннесе Гийомом де Шамплиттом и Жоффруа де Виллардуэном (договор 1207/1209 гг. с Венецией).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Историческая основа \u0026#171;вторжения северян\u0026#187; в античную Спарту: крестоносцы в XIII в. действительно поделили Пелопоннес (Морею) на феодальные лены и возвели там готические рыцарские замки (Мистра и др.) (с. 380).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eМорейская хроника\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЗавоевание Константинополя (Виллардуэн)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r195\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n196\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e196\u003c/span\u003e\u003cspan\u003eПеред дворцом Менелая, с. 276\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;У Аякса, помните, / Был на щите представлен змей свернувшийся, / И семеро у Фив таким же образом / Щиты снабдили знаками особыми\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Эсхил, трагедия \u0026#171;Семеро против Фив\u0026#187; (ст. 375–652 — подробное описание гербовых эмблем на щитах семи вождей); расписная античная ваза из собрания Веймарского дворца (щит Аякса); И. Г. Гердер, \u0026#171;Критические рощицы\u0026#187; (\u003cem\u003eKritische W\u0026#228;lder\u003c/em\u003e, \u0026#171;Третья рощица\u0026#187;, 1769).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Пояснение происхождения средневековых рыцарских гербов через сравнение со знаками на щитах античных героев (с. 380).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eСемеро против Фив (Эсхил)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eАнтичная ваза из Веймарского дворца\u003c/span\u003e\u003cspan class=\"chip\"\u003eКритические рощицы (Гердер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r196\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n197\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e197\u003c/span\u003e\u003cspan\u003eПеред дворцом Менелая, с. 277\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;А как он Деифоба изуродовал... Отрезал уши, нос перекалечивши\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Вергилий, \u0026#171;Энеида\u0026#187; (песнь VI, ст. 494–534).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В \u0026#171;Энеиде\u0026#187; Эней встречает в Аиде тень Деифоба (брата Париса, взявшего Елену после гибели Париса) с отрубленными руками, ушами и изувеченным лицом — плод мести Менелая и Одиссея при взятии Трои (с. 380).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЭнеида (Вергилий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r197\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n198\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e198\u003c/span\u003e\u003cspan\u003eПеред дворцом Менелая, с. 279\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Что Гермеса виднеется / Впереди очертание? / Блещет жезл золотой его\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Одиссея\u0026#187; (песнь XXIV, ст. 1–10).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Гермес Психопомп (Водитель душ) золотым жезлом-кадуцеем собирает тени умерших и ведёт их в царство Аида.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОдиссея (Гомер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r198\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n199\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e199\u003c/span\u003e\u003cspan\u003eПеред дворцом Менелая, с. 279\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Хоть Пифониссой\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Еврипид, \u0026#171;Ион\u0026#187; (ст. 91–93, 1322 — Пифия Дельфийского оракула); Библия, Вульгата (1 Цар. 28:7 — \u003cem\u003emulierem habentem pythonem\u003c/em\u003e, Аэндорская волшебница).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Обращение к Форкиаде как к вещей прорицательнице.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИон (Еврипид)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eВульгата (1 Цар. 28:7)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r199\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n200\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e200\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 280\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Рот наполнится прахом могильным\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Средневековые описания \u0026#171;плодов Содома\u0026#187; (Иосиф Флавий, \u0026#171;Иудейская война\u0026#187;, кн. IV, гл. 8, 4 — плоды, рассыпающиеся пеплом при прикосновении) и европейский фольклор о призраках/выходцах с того света.\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Хор догадывается, что прекрасные юноши в замке Фауста — не живые люди, а призраки из Аида (с. 380).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИудейская война (Иосиф Флавий)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eФольклор о выходцах с того света\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r200\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n201\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e201\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 281–284\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Башенный сторож Линкей\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Аполлоний Родосский, \u0026#171;Аргонавтика\u0026#187; (кн. I, ст. 151–155); Валерий Флакк, \u0026#171;Аргонавтика\u0026#187; (кн. I, 462–469).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Линкей — аргонавт, обладавший столь сверхъестественной зоркостью, что видел даже сквозь землю; Гёте делает его зорким стражем башни, ослеплённым красотой Елены (с. 380).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eАргонавтика (Аполлоний Родосский)\u003c/span\u003e\u003cspan class=\"chip\"\u003eАргонавтика (Валерий Флакк)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r201\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n202\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e202\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 283\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;С востока накатил наш вал, / И запад содрогнулся, пал...\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u003cem\u003eПредположительная отсылка\u003c/em\u003e к историческим хроникам Великого переселения народов IV–VI вв. (Аммиан Марцеллин, \u0026#171;Деяния\u0026#187;, кн. XXXI; Иордан, \u0026#171;О происхождении и деяниях гетов\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Описание стремительного нашествия племён с востока на земли Запада в духе исторических войн средневековья.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eДеяния (Аммиан Марцеллин)\u003c/span\u003e\u003cspan class=\"chip\"\u003eО происхождении и деяниях гетов (Иордан)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r202\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n203\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e203\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 285\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;отчего так странно / Пленяла речь служителя того? / Он подгонял так стройно слово к слову...\u0026#187; (урок рифмы Елене)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Йозеф фон Хаммер-Пургшталь, \u0026#171;История персидского красноречия\u0026#187; (\u003cem\u003eGeschichte der sch\u0026#246;nen Redek\u0026#252;nste Persiens\u003c/em\u003e, 1818, с. 35); стихотворение И. В. Гёте \u0026#171;Бахрамгур, рассказывают, первым рифмовал...\u0026#187; (\u003cem\u003eBehramgur, sagt man, hat den Reim erfunden\u003c/em\u003e, цикл \u0026#171;Западно-восточный диван\u0026#187;, 1819).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Согласно персидской легенде, сасанидский царь Бахрам Гур и его возлюбленная Диларам первыми изобрели рифму в любовном перекличном диалоге; здесь Фауст точно так же передаёт Елене рифмованную гармонию романтической поэзии.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИстория персидского красноречия (Хаммер-Пургшталь)\u003c/span\u003e\u003cspan class=\"chip\"\u003eБахрамгур (Гёте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r203\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n204\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e204\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 287\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Мы высадились у Пилоса, / Нет больше Нестора в живых\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Илиада\u0026#187; (песнь I, ст. 247–284) и \u0026#171;Одиссея\u0026#187; (песнь III, ст. 1–485).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Царь Пилоса Нестор пережил три поколения людей и был самым старым из вождей под Троей; сообщение о его смерти означает, что античный мир ушёл в прошлое.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОдиссея (Гомер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r204\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n205\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e205\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 290\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Аркадия еще доныне / Неиссякаемо свежа\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Вергилий, \u0026#171;Буколики\u0026#187; (эклоги IV, VII, X — Аркадия как край счастливых пастухов-поэтов); Якопо Саннадзаро, роман \u0026#171;Аркадия\u0026#187; (1504); картина Н. Пуссена \u0026#171;Аркадские пастухи\u0026#187; (\u003cem\u003eEt in Arcadia ego\u003c/em\u003e, 1637–1638).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Горная область в центре Пелопоннеса, ставшая в мировой литературе каноническим символом золотого века и безмятежной идиллии.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eБуколики (Вергилий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eАркадия (Саннадзаро)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eАркадские пастухи (Пуссен)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r205\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n206\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e206\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 292\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Сказка о Майе... Будто сынок ее... У Посейдона / Трезубец взял хитростью...\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомеровский гимн IV \u0026#171;К Гермесу\u0026#187; (ст. 1–180 — младенец Гермес, сын Майи, вылезает из пелёнок и похищает коров Аполлона); Лукиан, \u0026#171;Разговоры богов\u0026#187; (VII — диалог Гефеста и Аполлона о воришке-Гермесе, укравшем трезубец Посейдона, меч Ареса, лук Аполлона, щипцы Гефеста и пояс Афродиты).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Хор сравнивает чудесно выросшего Эвфориона с античным мифом о проказнике-младенце Гермесе, соединив Гомеровский гимн и сатиру Лукиана.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eГимн к Гермесу\u003c/span\u003e\u003cspan class=\"chip\"\u003eРазговоры богов (Лукиан)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r206\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n207\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e207\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 298\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Амазонкою дерется / Мать с героем на руке\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Илиада\u0026#187; (песнь III, 189; VI, 186); Аполлодор, \u0026#171;Мифологическая библиотека\u0026#187; (кн. II, гл. 5, 9; Эпитома V, 1 — воинственное племя женщин-амазонок).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Сравнение отваги матерей, сражающихся за свободу отчизны, с легендарными женщинами-воительницами.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМифологическая библиотека (Аполлодор)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r207\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n208\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e208\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 299\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Это кончается / Новый Икар\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. VIII, 183–235 — миф о Дедале и Икаре).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Икар поднялся на скреплённых воском крыльях слишком близко к солнцу, воск растаял, и юноша упал в море (с. 381).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r208\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n209\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e209\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 299–300\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eОбраз Эвфориона (\u0026#171;Лицо умершего напоминает другой знакомый образ\u0026#187;, \u0026#171;Знаменитых дедов внук... Подвига не завершил... Пут не сбросивший народ\u0026#187;)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Биография Джорджа Гордона Байрона (1788–1824) — его участие в Греческой войне за независимость и смерть в Миссолунги (19 апреля 1824 г.); \u0026#171;Разговоры с Гёте\u0026#187; И. П. Эккермана (запись от 5 июля 1827 г., где Гёте прямо называет Эвфориона поэтическим образом Байрона).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Траурная песнь хора описывает жизнь, талант, аристократическое происхождение, дерзкий бунт и преждевременную гибель английского поэта ради свободы Греции.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eБиография Байрона\u003c/span\u003e\u003cspan class=\"chip end\"\u003eРазговоры с Гёте (Эккерман)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r209\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n210\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e210\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 300\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;На мне сбывается реченье старое, / Что счастье с красотой не уживается\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Овидий, \u0026#171;Героиды\u0026#187; (послание XVI, ст. 290: \u003cem\u003eLis est cum forma magna pudicitiae\u003c/em\u003e — \u0026#171;красота и целомудрие в вечной вражде\u0026#187;); Ювенал, \u0026#171;Сатиры\u0026#187; (сатира X, ст. 289–345 — о гибельности исключительной красоты).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Античная гномическая мысль о том, что высшая красота неизбежно влечёт за собой несчастье.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eГероиды (Овидий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eСатиры (Ювенал)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r210\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n211\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e211\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 301\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Средь лугов асфоделевых\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Одиссея\u0026#187; (песнь XI, ст. 539, 573; песнь XXIV, ст. 13).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В гомеровском Аиде тени простых умерших бродят по бледным лугам, заросшим цветком асфоделем (с. 381).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eОдиссея (Гомер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r211\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n212\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e212\u003c/span\u003e\u003cspan\u003eВнутренний двор замка, с. 303\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Открывается народу в шуме празднеств Дионис. / Следом толпы козлоногих и Силена зверь ушастый\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Еврипид, трагедия \u0026#171;Вакханки\u0026#187; (ст. 64–169); Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. IV, 25–30 — шествие Вакха с сатирами и старым Силеном верхом на осле); \u0026#171;Искусство любви\u0026#187; (кн. I, 543–548).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Вакхическая оргия с участием сатиров и пьяного воспитателя Диониса Силена символизирует возврат в стихийную жизнь природы.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eВакханки (Еврипид)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eИскусство любви (Овидий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r212\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003ch3\u003e7. Вторая часть. Акт Четвёртый (с. 303–334)\u003c/h3\u003e\n\u003cdiv class=\"note\" id=\"n213\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e213\u003c/span\u003e\u003cspan\u003eГорная местность, с. 303\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Юнона ль это, Леда ли, Елена ли?\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомер, \u0026#171;Илиада\u0026#187; (песнь I и III); Аполлодор, \u0026#171;Мифологическая библиотека\u0026#187; (кн. III, гл. 10, 7 — Леда и Зевс); Вергилий, \u0026#171;Энеида\u0026#187; (кн. I — Юнона/Гера).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Облако на горном гребне принимает черты античной женской красоты — царственной Юноны (Геры), Леды и Елены.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИлиада (Гомер)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМифологическая библиотека (Аполлодор)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭнеида (Вергилий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r213\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n214\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e214\u003c/span\u003e\u003cspan\u003eГорная местность, с. 304\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;На гору становится семимильный сапог, за ним — другой\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Шарль Перро, сказка \u0026#171;Мальчик-с-пальчик\u0026#187; (\u003cem\u003eLe Petit Poucet\u003c/em\u003e, 1697); братья Гримм, \u0026#171;Детские и семейные сказки\u0026#187; (напр., KHM 56 \u0026#171;Милый Роланд\u0026#187;); Адельберт фон Шамиссо, повесть \u0026#171;Необыкновенная история Петера Шлемиля\u0026#187; (1814).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Сказочные сапоги-скороходы (\u003cem\u003eSiebenmeilenstiefel\u003c/em\u003e), позволяющие шагать через целые страны.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eМальчик-с-пальчик (Перро)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eДетские и семейные сказки (братья Гримм)\u003c/span\u003e\u003cspan class=\"chip\"\u003eПетер Шлемиль (Шамиссо)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r214\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n215\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e215\u003c/span\u003e\u003cspan\u003eГорная местность, с. 304\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Когда за грех один / Господь низверг нас в глубину глубин... Ввели теорию переворотов\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия (Ис. 14:12–15; Откр. 12:7–9 — падение восставших ангелов); Джон Мильтон, \u0026#171;Потерянный рай\u0026#187; (кн. I, ст. 44–53; кн. VI); Жорж Кювье, \u0026#171;Рассуждение о переворотах на поверхности земного шара\u0026#187; (1812); труды геологов-вулканистов Л. фон Буха и А. фон Гумбольдта (письмо А. фон Гумбольдта к Ф. фон Кобеллю, с. 381).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Мефистофель совмещает библейско-мильтоновский миф о падении демонов в центр Земли с научной сатирой на теорию катастроф и вулканизм XIX в.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига пророка Исаии\u003c/span\u003e\u003cspan class=\"chip end\"\u003eОткровение Иоанна Богослова\u003c/span\u003e\u003cspan class=\"chip\"\u003eПотерянный рай (Мильтон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eРассуждение о переворотах (Кювье)\u003c/span\u003e\u003cspan class=\"chip\"\u003eТруды фон Буха и Гумбольдта\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r215\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n216\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e216\u003c/span\u003e\u003cspan\u003eГорная местность, с. 305\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;(Эфес, VI, 12.)\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Новый Завет — Послание к Ефесянам святого апостола Павла (Еф. 6:12).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Прямая авторская сноска на слова апостола: \u0026#171;наша брань не против крови и плоти, но... против духов злобы поднебесной\u0026#187; — Мефистофель буквально иронизирует над \u0026#171;духами поднебесья\u0026#187; на вершине горы.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eПослание к Ефесянам\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r216\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n217\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e217\u003c/span\u003e\u003cspan\u003eГорная местность, с. 305\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Молох ковал утесы на огне / И сыпал стопудовые обломки\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Фридрих Готлиб Клопшток, поэма \u0026#171;Мессиада\u0026#187; (\u003cem\u003eDer Messias\u003c/em\u003e, песнь II, ст. 342–393, 1748); Библия (Лев. 18:21; 3 Цар. 11:7 — аммонитский бог огненных жертв Молох).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В \u0026#171;Мессиаде\u0026#187; (и у Мильтона) демон Молох изображён как свирепый воитель и богоборец, поднимающий и крушащий горные скалы (с. 381).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМессиада (Клопшток)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eКнига Левит\u003c/span\u003e\u003cspan class=\"chip end\"\u003eТретья книга Царств\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r217\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n218\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e218\u003c/span\u003e\u003cspan\u003eГорная местность, с. 305\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;На \u0026#171;чертов мост\u0026#187; глядит в пути скиталец / Или в песке находит \u0026#171;чертов палец\u0026#187;\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Швейцарская легенда о Чёртовом мосте (\u003cem\u003eTeufelsbr\u0026#252;cke\u003c/em\u003e) через реку Ройс на перевале Сен-Готард (записана в путевых заметках И. В. Гёте о Швейцарии 1775/1779 гг. и в \u0026#171;Немецких сагах\u0026#187; братьев Гримм, № 336 \u0026#171;Чёртов мост\u0026#187;); народная геология (ископаемые ростры белемнитов, прозванные \u0026#171;чёртовыми пальцами\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Примеры того, как народное воображение приписывает необычные горные сооружения и окаменелости вмешательству дьявола.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЛегенда о Чёртовом мосте\u003c/span\u003e\u003cspan class=\"chip end\"\u003eНемецкие саги (братья Гримм)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r218\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n219\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e219\u003c/span\u003e\u003cspan\u003eГорная местность, с. 306\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Все царства мира и всю славу их\u0026#187;. (Матф. IV, 8.)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Новый Завет — Евангелие от Матфея (Мф. 4:8).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Прямая цитата и ссылка на третье искушение Иисуса Христа, когда дьявол возвёл Его на весьма высокую гору и показал \u0026#171;все царства мира и славу их\u0026#187;.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Матфея\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r219\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n220\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e220\u003c/span\u003e\u003cspan\u003eГорная местность, с. 306–307\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Так замок я б себе воздвиг... Деревья в прихотливой стрижке... Я выстроил бы павильоны / Для обольстительных подруг\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Архитектурные описания и гравюры дворцово-парковых ансамблей Версаля и Марли эпохи Людовика XIV (напр., \u0026#171;Мемуары\u0026#187; герцога Сен-Симона), а также подражавших им немецких резиденций (Шветцинген, Нимфенбург, Сан-Суси).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Детальное воспроизведение вкусов французского абсолютизма (регулярные парки, фонтаны, уединённые павильоны для фавориток) как модели бездумного властолюбия (с. 381).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eВерсаль и Марли\u003c/span\u003e\u003cspan class=\"chip end\"\u003eМемуары Сен-Симона\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r220\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n221\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e221\u003c/span\u003e\u003cspan\u003eГорная местность, с. 307\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Дань Времени! Сарданапал!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Диодор Сицилийский, \u0026#171;Историческая библиотека\u0026#187; (кн. II, гл. 23–27 — со ссылкой на Ктесия); Юстин, \u0026#171;Эпитома сочинения Помпея Трога\u0026#187; (кн. I, гл. 3); Дж. Г. Байрон, трагедия \u0026#171;Сарданапал\u0026#187; (1821).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Полулегендарный ассирийский царь Сарданапал (восходящий к Ашшурбанипалу) в античных источниках стал эталоном правителя, предавшегося гаремной неге и беспечной роскоши (с. 381).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИсторическая библиотека (Диодор)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭпитома (Юстин)\u003c/span\u003e\u003cspan class=\"chip\"\u003eСарданапал (Байрон)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r221\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n222\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e222\u003c/span\u003e\u003cspan\u003eГорная местность, с. 311–312\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Иных фельдмаршалов-растяп / Спасает генеральный штаб\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u003cem\u003eПредположительная отсылка\u003c/em\u003e к военным запискам И. В. Гёте \u0026#171;Кампания во Франции 1792 года\u0026#187; (изд. 1822) и военной истории Наполеоновских войн — поражениям прусско-австрийской армии под командованием герцога Карла Вильгельма Фердинанда Брауншвейгского при Вальми (1792) и Йене–Ауэрштедте (1806).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Намёк на бездарность аристократических полководцев старой Европы, чьи просчёты вынуждены прикрывать штабные офицеры (с. 381).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКампания во Франции 1792 года (Гёте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r222\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n223\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e223\u003c/span\u003e\u003cspan\u003eГорная местность, с. 312\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я, как Петер Сквенц, в отряд / Из массы выбрал концентрат\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e У. Шекспир, \u0026#171;Сон в летнюю ночь\u0026#187; (акт I, сц. 2 — плотник Питер Квинс/Клин); Андреас Грифиус, комедия \u0026#171;Абсурда комика, или Господин Петер Сквенц\u0026#187; (\u003cem\u003eAbsurda Comica oder Herr Peter Squenz\u003c/em\u003e, 1658).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Персонаж немецкой переработки шекспировской комедии Петер Сквенц отбирал из толпы ремесленников \u0026#171;лучших актёров\u0026#187; для пьесы о Пираме и Фисбе (с. 381).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eСон в летнюю ночь (Шекспир)\u003c/span\u003e\u003cspan class=\"chip\"\u003eГосподин Петер Сквенц (Грифиус)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r223\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n224\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e224\u003c/span\u003e\u003cspan\u003eГорная местность, с. 312\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Входят трое сильных (Кн. царств, II, 23, 8.)\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Вторая книга Царств (2 Цар. 23:8–12; в латинской/протестантской традиции — \u003cem\u003eII Samuelis\u003c/em\u003e 23:8, по-немецки — \u003cem\u003eII Buch der K\u0026#246;nige\u003c/em\u003e у Лютера, хотя точнее 2 Самуила).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Прямая отсылка к трём могучим храбрецам из войска царя Давида (Иесваал, Елеазар и Шамма), прославившимся в битвах с филистимлянами; Гёте превращает их в трёх аллегорий грабежа: Драчуна, Хапугу и Скрягу (с. 381–382).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eВторая книга Царств\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r224\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n225\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e225\u003c/span\u003e\u003cspan\u003eГорная местность, с. 312\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Мечтает малое дитя / Теперь о рыцарском уборе\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Рыцарские романы и пьесы \u0026#171;немецкой школы\u0026#187; (ср. Вальтер Скотт, Л. Тик, Ф. де ла Мотт-Фуке \u0026#171;Волшебное кольцо\u0026#187;, 1813 — культ средневекового рыцарства в позднем романтизме).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Сатирический укол Гёте в адрес романтического увлечения псевдосредневековьем и феодальными атрибутами (с. 382).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eВолшебное кольцо (де ла Мотт-Фуке)\u003c/span\u003e\u003cspan class=\"chip\"\u003eРыцарские романы Вальтера Скотта и Людвига Тика\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r225\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n226\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e226\u003c/span\u003e\u003cspan\u003eНа переднем горном отроге, с. 314\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;А вспыхнет у соседа дом, / Не скажешь: \u0026#171;Наша хата с краю\u0026#187;\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гораций, \u0026#171;Послания\u0026#187; (кн. I, послание 18, ст. 84: \u003cem\u003eNam tua res agitur, paries cum proximus ardet\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Перефразированная цитата из Горация: \u0026#171;Дело касается тебя самого, когда полыхает стена у соседа\u0026#187; (с. 382).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eПослания (Гораций)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r226\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n227\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e227\u003c/span\u003e\u003cspan\u003eНа переднем горном отроге, с. 315\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Рапирою я обруч протыкал\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Средневековые и барочные трактаты о турнирных забавах (напр., \u0026#171;Турнирная книга\u0026#187; Г. Рюкснера, 1530, описание \u0026#171;кольцевого ристания\u0026#187; — \u003cem\u003eRingelrennen\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Придворная потешная игра, заменившая опасные рыцарские турниры: всадник на скаку должен был снять остриём копья или рапиры подвешенное кольцо (с. 382).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eТурнирная книга (Рюкснер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r227\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n228\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e228\u003c/span\u003e\u003cspan\u003eНа переднем горном отроге, с. 315–316\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Нурсийский некромант, Сабинский маг... Был в Риме ужас этот им изведан\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Бенвенуто Челлини, \u0026#171;Жизнь Бенвенуто, сына маэстро Джованни Челлини, флорентийца\u0026#187; (кн. I, гл. 64 — переведена И. В. Гёте в 1796–1803 гг.); легенда о Тангейзере (горы Сибиллы близ Норчи/Нурсии в Сабинских горах).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В мемуарах Челлини рассказывается о сицилийском священнике-некроманте, советовавшем освятить магическую книгу у гор Нурсии; Гёте соединил это с легендой об императоре, спасшем мага от костра инквизиции в Риме (с. 382).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЖизнь Бенвенуто Челлини\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЛегенда о Тангейзере\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r228\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n229\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e229\u003c/span\u003e\u003cspan\u003eНа переднем горном отроге, с. 317\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Чтоб стал его затылок нам подножьем\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Псалтирь (Пс. 109:1 в слав. / Пс. 110:1 в масор.) и Книга Иисуса Навина (Нав. 10:24 — военачальники ставят ноги на шеи побеждённых царей).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Буквальная аллюзия на псалом: \u0026#171;доколе положу врагов Твоих в подножие ног Твоих\u0026#187; (с. 382).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eПсалтирь\u003c/span\u003e\u003cspan class=\"chip end\"\u003eКнига Иисуса Навина\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r229\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n230\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e230\u003c/span\u003e\u003cspan\u003eНа переднем горном отроге, с. 320\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;фата-морганы\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Томас Мэлори, \u0026#171;Смерть Артура\u0026#187; (XV в., фея Моргана, \u003cem\u003eMorgan le Fay\u003c/em\u003e); сицилийские народные сказания о миражах в Мессинском проливе (зафиксированы Афанасием Кирхером в \u0026#171;Ars magna lucis et umbrae\u0026#187;, 1646, и путевых заметках XVIII в.).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Необычные атмосферные миражи в Сицилии (висящие в воздухе города и сады) местные жители считали колдовскими замками феи Морганы.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eСмерть Артура (Мэлори)\u003c/span\u003e\u003cspan class=\"chip\"\u003eArs magna lucis et umbrae (Кирхер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r230\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n231\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e231\u003c/span\u003e\u003cspan\u003eНа переднем горном отроге, с. 320\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Когда бывало море хмуро, / Ниспосылали Диоскуры / Такой же свет на корабли\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гомеровский гимн XXXIII \u0026#171;К Диоскурам\u0026#187;; Плиний Старший, \u0026#171;Естественная история\u0026#187; (кн. II, гл. 37, \u0026#167; 101); Гораций, \u0026#171;Оды\u0026#187; (кн. I, ода 12, ст. 25–32).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Электрические разряды в грозу на мачтах и остриях (\u0026#171;огни святого Эльма\u0026#187;) в античности считались благим знамением близнецов Кастора и Поллукса, спасающих моряков от бури (с. 382).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eГимн к Диоскурам\u003c/span\u003e\u003cspan class=\"chip\"\u003eЕстественная история (Плиний)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОды (Гораций)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r231\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n232\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e232\u003c/span\u003e\u003cspan\u003eНа переднем горном отроге, с. 321\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Орел парит на небосклоне. / Гриф бросился за ним в погоню\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Геральдика Священной Римской империи (имперский орёл, с XV в. двуглавый — герб императора) и геральдические трактаты (напр., Зибмахер, \u0026#171;Гербовник\u0026#187; — грифон как эмблема мятежных земель/Померании или вымышленного контр-императора).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Битва в небе воспроизводит столкновение родовых гербов двух враждующих государей (с. 382).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eГеральдика Священной Римской империи\u003c/span\u003e\u003cspan class=\"chip\"\u003eГербовник (Зибмахер)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r232\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n233\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e233\u003c/span\u003e\u003cspan\u003eНа переднем горном отроге, с. 322\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Мои два ворона, глядите, / Сейчас расскажут ход событий\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Снорри Стурлусон, \u0026#171;Младшая Эдда\u0026#187; (\u0026#171;Видение Гюльви\u0026#187;, гл. 38); \u0026#171;Старшая Эдда\u0026#187; (\u0026#171;Речи Гримнира\u0026#187;, строфа 20); Якоб Гримм, \u0026#171;Немецкая мифология\u0026#187; (гл. VII \u0026#171;Wuotan\u0026#187; и гл. XXXIII \u0026#171;Teufel\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Двое вещих воронов (Хугин и Мунин) сидели на плечах верховного германского бога Вотана/Одина и доносили ему новости со всего света; после христианизации в сказках они стали спутниками дьявола (с. 382).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМладшая Эдда (Снорри Стурлусон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eСтаршая Эдда\u003c/span\u003e\u003cspan class=\"chip\"\u003eНемецкая мифология (Гримм)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r233\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n234\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e234\u003c/span\u003e\u003cspan\u003eНа переднем горном отроге, с. 325\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я, похвалю вас Люциферу\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Книга пророка Исаии (Ис. 14:12, в латинском тексте Вульгаты \u003cem\u003eLucifer\u003c/em\u003e — \u0026#171;Светоносный\u0026#187;); Иероним Стридонский и отцы церкви (толкование \u0026#171;Денницы\u0026#187; как падшего главы ангелов).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Ироническое упоминание верховного владыки ада.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига пророка Исаии\u003c/span\u003e\u003cspan class=\"chip\"\u003eИероним Стридонский\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r234\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n235\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e235\u003c/span\u003e\u003cspan\u003eШатер враждебного императора, с. 329–332\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Я долю уделить хочу вам четырем / В распоряженье царством, домом и двором... И в дополнение... А вот и канцлер\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u0026#171;Золотая булла\u0026#187; императора Карла IV (1356, гл. IV, XXVII — учреждение имперских чинов курфюрстов и порядка наследования по майорату).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Документ точно закрепил высшие придворные должности за семью курфюрстами — три духовных архиканцлера и четыре светских чина (маршал, камерарий, стольник/кравчий и др.), нераздельность их владений (майорат) и широчайшие судебные и налоговые привилегии (с. 382).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЗолотая булла (1356)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r235\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n236\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e236\u003c/span\u003e\u003cspan\u003eШатер враждебного императора, с. 330\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;бокал... Венецианского прозрачного стекла, / ...И менее пьянит, и учит воздержанью\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Средневековые и ренессансные поверья о муранском стекле (упоминаются в трактатах о ядах XVI в., напр., у Пьетро д’Абано и в сборниках \u003cem\u003eHandw\u0026#246;rterbuch des deutschen Aberglaubens\u003c/em\u003e, ст. \u003cem\u003eGift\u003c/em\u003e, \u003cem\u003eGlas\u003c/em\u003e).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Поверье утверждало, что тончайшее венецианское стекло трескается, если в него налить яд, и замедляет опьянение (с. 382).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eТрактаты о ядах Пьетро д\u0026#39;Абано\u003c/span\u003e\u003cspan class=\"chip\"\u003eHandw\u0026#246;rterbuch des deutschen Aberglaubens\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r236\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003ch3\u003e8. Вторая часть. Акт Пятый (с. 334–364)\u003c/h3\u003e\n\u003cdiv class=\"note\" id=\"n237\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e237\u003c/span\u003e\u003cspan\u003eОткрытая местность, с. 334–335\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Бавкида\u0026#187; и \u0026#171;Филемон\u0026#187;, \u0026#171;Да ведь это липы те же!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Овидий, \u0026#171;Метаморфозы\u0026#187; (кн. VIII, ст. 618–724); \u0026#171;Разговоры с Гёте\u0026#187; И. П. Эккермана (запись от 6 июня 1831 г., с. 383).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e У Овидия фригийские старики Филемон и Бавкида единственные радушно приняли странствующих инкогнито Зевса и Гермеса; за это боги спасли их от потопа, превратили хижину в храм и исполнили их мольбу умереть в один миг, обратив их в дуб и липу. Гёте сохранил имена и мотив лип, чтобы подчеркнуть кротость жертв Фауста (с. 382–383).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eМетаморфозы (Овидий)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eРазговоры с Гёте (Эккерман)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r237\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n238\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e238\u003c/span\u003e\u003cspan\u003eДворец, с. 338\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Война, торговля и пиратство — / Три вида сущности одной\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Гийом Тома Рейналь, \u0026#171;Философская и политическая история учреждений и торговли европейцев в обеих Индиях\u0026#187; (\u003cem\u003eHistoire des deux Indes\u003c/em\u003e, 1770) и история Голландской и Британской Ост-Индских компаний XVII–XVIII вв. (практика каперских патентов и вооружённой торговой монополии).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Формула Мефистофеля точно резюмирует историческую практику эпохи раннего колониализма, где торговые экспедиции не отделялись от военного захвата и разбоя.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eИстория обеих Индий (Рейналь)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eИстория Ост-Индских компаний\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r238\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n239\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e239\u003c/span\u003e\u003cspan\u003eДворец, с. 341\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Так отдал в дни, еще древней, / Свой виноградник Навуфей. (Кн. царств, III, 21.)\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Третья книга Царств (3 Цар. 21:1–19; по Вульгате — \u003cem\u003eIII Regum\u003c/em\u003e 21).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Прямая ссылка: израильский царь Ахав возжелал виноградник Навуфея рядом со своим дворцом, но тот отказался уступить наследство отцов; тогда царица Иезавель ложно обвинила Навуфея в богохульстве, его забили камнями, а Ахав получил участок (с. 383).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eТретья книга Царств\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r239\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n240\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e240\u003c/span\u003e\u003cspan\u003eПолночь, с. 343–344\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Появляются четыре седые женщины: Нехватка, Вина, Забота, Нужда\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Вергилий, \u0026#171;Энеида\u0026#187; (кн. VI, ст. 273–281 — аллегорические чудовища и скорби у входа в подземный мир, включая \u003cem\u003eultrices Curae\u003c/em\u003e — \u0026#171;мстительных Забот\u0026#187; и \u003cem\u003eNeed\u003c/em\u003e/\u003cem\u003eEgestas\u003c/em\u003e — Нужду); Гораций, \u0026#171;Оды\u0026#187; (кн. III, ода 1, ст. 40: \u003cem\u003epost equitem sedet atra Cura\u003c/em\u003e — \u0026#171;позади всадника сидит чёрная Забота\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Персонификация душевных и материальных бедствий в античной поэзии; Забота единственная проникает в дом богача через замочную скважину.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЭнеида (Вергилий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eОды (Гораций)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r240\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n241\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e241\u003c/span\u003e\u003cspan\u003eПолночь, с. 347\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;А ты пред смертью потеряешь зренье. (Дует ему в глаза и исчезает.)\u0026#187; / \u0026#171;Но свет внутри меня ведь не погас\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Немецкие народные поверья об ослеплении от дыхания духов/ведьм (\u0026#171;Handw\u0026#246;rterbuch des deutschen Aberglaubens\u0026#187;, ст. \u003cem\u003eAnhauch\u003c/em\u003e, \u003cem\u003eBlindheit\u003c/em\u003e, с. 383); \u003cem\u003eпредположительно\u003c/em\u003e также перекличка с поэмой Д. Мильтона \u0026#171;Потерянный рай\u0026#187; (кн. III, ст. 51–55 — мольба слепого поэта о \u0026#171;внутреннем свете\u0026#187;) и трагедией Софокла \u0026#171;Эдип в Колоне\u0026#187;.\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Физическая слепота от прикосновения сверхъестественного существа контрастирует с духовным прозрением героя.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eHandw\u0026#246;rterbuch des deutschen Aberglaubens\u003c/span\u003e\u003cspan class=\"chip\"\u003eПотерянный рай (Мильтон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eЭдип в Колоне (Софокл)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r241\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n242\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e242\u003c/span\u003e\u003cspan\u003eБольшой двор перед дворцом, с. 348\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Сюда, народ понурый, / Из жил, и связок, и костей / Скроенные лемуры!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Овидий, \u0026#171;Фасты\u0026#187; (кн. V, ст. 419–492 — праздник Лемурий в Риме); Гораций, \u0026#171;Послания\u0026#187; (кн. II, 2, 209); античные геммы с изображением пляшущего скелета (в т. ч. из гётевского эссе \u0026#171;Филипп Хаккерт\u0026#187; / коллекции графа А. фон Кайлуса, ср. примеч. с. 384).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e В римских верованиях лемуры — беспокойные, враждебные призраки умерших (в отличие от мирных ларов), полускелеты-недомерки (с. 384).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eФасты (Овидий)\u003c/span\u003e\u003cspan class=\"chip\"\u003eПослания (Гораций)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eАнтичные геммы с пляшущим скелетом\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r242\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n243\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e243\u003c/span\u003e\u003cspan\u003e350–351, Большой двор перед дворцом / Положение во гроб, с. 348\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Как рыл отец ваш для отца / Кладбищенскую глину...\u0026#187; / \u0026#171;В дни молодости и проказ...\u0026#187; / \u0026#171;Кто строил заступом в песке / Такой барак дырявый?\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e У. Шекспир, трагедия \u0026#171;Гамлет\u0026#187; (акт V, сц. 1 — песня первого могильщика \u0026#171;In youth, when I did love, did love...\u0026#187;, восходящая к балладе Томаса Вокса, и прозаический диалог могильщиков на кладбище).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Прямая, местами почти дословная стилизация под кладбищенскую сцену \u0026#171;Гамлета\u0026#187; (с. 384).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eГамлет (Шекспир)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r243\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n244\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e244\u003c/span\u003e\u003cspan\u003eБольшой двор перед дворцом, с. 349\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Морскому черту, старику Нептуну\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Вергилий, \u0026#171;Энеида\u0026#187; (кн. I, ст. 124–156 — бог морей Нептун, поднимающий и усмиряющий бури).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Стихия моря, с которой ведёт борьбу инженерно-трудовой замысел Фауста.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЭнеида (Вергилий)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r244\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n245\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e245\u003c/span\u003e\u003cspan\u003eПоложение во гроб, с. 351–352\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Пасть адову несите мне сюда!... И город мук, дымящийся в огне\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Средневековый народный кукольный театр о Фаусте (\u0026#171;Адова пасть\u0026#187; / \u003cem\u003eH\u0026#246;llenrachen\u003c/em\u003e как бутафорская декорация); Данте Алигьери, \u0026#171;Божественная комедия\u0026#187; (\u0026#171;Ад\u0026#187;, песни VIII–IX — огненный город Дит); Э. Сведенборг, \u0026#171;О небесах, о мире духов и об аде\u0026#187; (ч. III — \u0026#171;Об аде\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Соединение балаганной иконографии пасти чудовища (в которую сбрасывают грешников) с образом раскалённого города Дита из \u0026#171;Ада\u0026#187; Данте и теологией Сведенборга (с. 384).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКукольный театр о Фаусте\u003c/span\u003e\u003cspan class=\"chip\"\u003eБожественная комедия (Данте)\u003c/span\u003e\u003cspan class=\"chip\"\u003eО небесах, о мире духов и об аде (Сведенборг)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r245\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n246\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e246\u003c/span\u003e\u003cspan\u003eПоложение во гроб, с. 352\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Ту душу, ту крылатую Психею\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Апулей, \u0026#171;Метаморфозы\u0026#187; (\u0026#171;Золотой осёл\u0026#187;, кн. IV–VI — сказка об Амуре и Психее); античная погребальная иконография (изображение души-Психеи в виде бабочки или девушки с крыльями бабочки, вылетающей из тела).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Прямое использование античного образа души-бабочки (\u003cem\u003eψυχή\u003c/em\u003e по-гречески — \u0026#171;душа\u0026#187; и \u0026#171;бабочка\u0026#187;).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eЗолотой осёл (Апулей)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eАнтичная иконография Психеи\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r246\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n247\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e247\u003c/span\u003e\u003cspan\u003eПоложение во гроб, с. 356\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;О, что со мной! Как Иов, весь в нарывах\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Ветхий Завет — Книга Иова (Иов 2:7).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Отсылка к моменту, когда сатана поразил Иова лютой проказой от подошвы ноги его по самое темя, и тот сидел в пепле (кольцевое замыкание с \u0026#171;Прологом на небе\u0026#187;).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eКнига Иова\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r247\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n248\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e248\u003c/span\u003e\u003cspan\u003eПоложение во гроб, с. 356\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;унося бессмертную сущность Фауста\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Аристотель, \u0026#171;О душе\u0026#187; (кн. II, гл. 1, 412a — душа как \u003cem\u003eэнтелехия\u003c/em\u003e тела); Фома Аквинский, \u0026#171;Сумма теологии\u0026#187; (ч. I, вопр. 75–76 — о бессмертии разумной души); Г. В. Лейбниц, \u0026#171;Монадология\u0026#187; (1714).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Средневеково-схоластический и философский термин (в оригинале \u003cem\u003eFaustens Unsterbliches\u003c/em\u003e; в черновиках Гёте называл её \u0026#171;энтелехией Фауста\u0026#187;) для обозначения неуничтожимого духовного ядра личности (с. 384).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eО душе (Аристотель)\u003c/span\u003e\u003cspan class=\"chip\"\u003eСумма теологии (Фома Аквинский)\u003c/span\u003e\u003cspan class=\"chip\"\u003eМонадология (Лейбниц)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r248\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n249\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e249\u003c/span\u003e\u003cspan\u003eс. с. 357\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003eПейзаж сцены \u0026#171;Горные ущелья, лес, скалы, пустыня\u0026#187; (ступенчатые уступы горы, отшельники, кроткие львы)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u003cem\u003eПредположительные источники:\u003c/em\u003e письмо Вильгельма фон Гумбольдта к Гёте (1800, описание отшельников на скалах монастыря Монсеррат в Каталонии); фреска XIV в. \u0026#171;Жития отшельников Фиваиды\u0026#187; (приписывалась Пьетро Лоренцетти / Буонамико Буффальмакко) на кладбище Кампо-Санто в Пизе; Данте, \u0026#171;Чистилище\u0026#187; и \u0026#171;Рай\u0026#187;.\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Вертикальное расположение отшельников и ангелов по уступам горы, ведущих в небеса, соединяет визуальные впечатления от пизанских фресок и рассказов Гумбольдта о Монсеррате с дантовской композицией восхождения к Раю.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eПисьмо В. Гумбольдта к Гёте\u003c/span\u003e\u003cspan class=\"chip end\"\u003eЖития отшельников Фиваиды (фреска Кампо-Санто)\u003c/span\u003e\u003cspan class=\"chip\"\u003eБожественная комедия (Данте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r249\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n250\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e250\u003c/span\u003e\u003cspan\u003eГорные ущелья, с. 357–363\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Pater ecstaticus\u0026#187; (Отец восторженный), \u0026#171;Pater profundus\u0026#187; (Отец углубленный), \u0026#171;Pater seraphicus\u0026#187; (Отец ангелоподобный), \u0026#171;Doctor Marianus\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Средневековые почётные титулы католических богословов и мистиков: \u003cem\u003eDoctor Seraphicus\u003c/em\u003e (св. Бонавентура, XIII в.), \u003cem\u003eDoctor Ecstaticus\u003c/em\u003e (Дионисий Картезианец, XV в.), \u003cem\u003eDoctor Profundus\u003c/em\u003e (Томас Брадвардин, XIV в.), \u003cem\u003eDoctor Marianus\u003c/em\u003e (ср. титул Дунса Скота, защитника Непорочного зачатия); \u0026#171;Разговоры с Гёте\u0026#187; И. П. Эккермана (запись от 6 июня 1831 г., с. 384).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Гёте сам объяснял, что сознательно использовал \u0026#171;резко очерченные образы и представления христианской церкви\u0026#187; для придания ясности мистическому финалу (с. 384).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eПочётные титулы схоластов (Doctor Seraphicus и др.)\u003c/span\u003e\u003cspan class=\"chip end\"\u003eРазговоры с Гёте (Эккерман)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r250\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n251\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e251\u003c/span\u003e\u003cspan\u003eГорные ущелья, с. 358–359\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Хор блаженных младенцев\u0026#187; / \u0026#171;Но в глаза мои войдите, / Я их вам даю взаймы. (Принимает их в себя.)\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Эммануил Сведенборг, трактат \u0026#171;О небесах, о мире духов и об аде\u0026#187; (\u003cem\u003eDe caelo et eius mirabilibus et de inferno\u003c/em\u003e, 1758, \u0026#167;\u0026#167; 329–345 \u0026#171;О младенцах на небесах\u0026#187;, а также о способности высших духов смотреть на мир глазами других или принимать младших духов в себя).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e По Сведенборгу, умершие при рождении дети попадают на небо, но не имеют земного опыта и познают мир через соприкосновение с глазами зрелых духов (с. 384).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eО небесах, о мире духов и об аде (Сведенборг)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r251\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n252\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e252\u003c/span\u003e\u003cspan\u003eГорные ущелья, с. 360\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Одна любовь с высот / Решит и вяжет\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Новый Завет — Евангелие от Матфея (Мф. 16:19; 18:18 — \u0026#171;связывать и разрешать\u0026#187;); Первое послание к Коринфянам (1 Кор. 13:1–13 — гимн любви).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Евангельская формула духовной власти (\u0026#171;развязывать и связывать\u0026#187;) переосмыслена так, что единственным судьёй и освободителем души оказывается Божественная Любовь.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Матфея\u003c/span\u003e\u003cspan class=\"chip end\"\u003eПервое послание к Коринфянам\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r252\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n253\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e253\u003c/span\u003e\u003cspan\u003e364, Горные ущелья, с. 361\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Приснодеву, деву-мать, / Госпожу вселенной... Дева безневестная... Дева, мать, царица!\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Католическая Лоретанская литания (\u003cem\u003eLitaniae Lauretanae\u003c/em\u003e, XVI в.) и византийский Акафист Пресвятой Богородице (VI–VII вв., икос 1–12: \u0026#171;Радуйся, Невесто Неневестная\u0026#187;).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Собрание канонических литургических титулов Богоматери: Дева (\u003cem\u003eVirgo\u003c/em\u003e), Мать (\u003cem\u003eMater\u003c/em\u003e), Царица (\u003cem\u003eRegina\u003c/em\u003e).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЛоретанская литания\u003c/span\u003e\u003cspan class=\"chip end\"\u003eАкафист Пресвятой Богородице\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r253\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n254\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e254\u003c/span\u003e\u003cspan\u003eГорные ущелья, с. 362\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Magna peccatrix / Великая грешница (Ев. от Луки, 7, 36)\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Новый Завет — Евангелие от Луки (Лк. 7:36–50).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Прямая авторская ссылка на эпизод в доме фарисея Симона: грешница (в католической традиции отождествляемая с Марией Магдалиной) со слезами омыла ноги Христа, отерла их своими волосами и помазала миром из алавастрового сосуда, получив прощение \u0026#171;за то, что возлюбила много\u0026#187; (с. 384).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Луки\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r254\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n255\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e255\u003c/span\u003e\u003cspan\u003eГорные ущелья, с. 362\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Mulier Samaritana / Жена Самарянская (Ев. от Иоанна, 4)\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Библия, Новый Завет — Евангелие от Иоанна (Ин. 4:5–26).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Прямая авторская ссылка на беседу Христа с самарянкой у колодца Иакова (близ пастбищ Сихаря), где Иисус просит у неё воды и обещает дать \u0026#171;воду живую\u0026#187;, текущую в жизнь вечную (с. 384).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip end\"\u003eЕвангелие от Иоанна\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r255\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n256\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e256\u003c/span\u003e\u003cspan\u003eГорные ущелья, с. 362\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Maria Aegyptiaca (Acta sanctorum) / Мария Египетская (Жития святых)\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e Свод болландистов \u003cem\u003eActa Sanctorum\u003c/em\u003e (том под 2 апреля — житие преподобной Марии Египетской, греческий оригинал VII в., приписываемый патриарху Софронию Иерусалимскому).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Прямая авторская ссылка на житие александрийской блудницы, которую невидимая сила не пустила в храм Воскресения в Иерусалиме; после раскаяния пред иконой Богоматери она ушла на 47 (или более 40) лет в Заиорданскую пустыню, а перед кончиной начертала на песке предсмертную просьбу к старцу Зосиме о погребении (с. 384).\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eActa Sanctorum\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r256\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n257\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e257\u003c/span\u003e\u003cspan\u003eГорные ущелья, с. 363\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Una poenitentium / Одна из кающихся, прежде называвшаяся Гретхен\u0026#187; (\u0026#171;Направься в высший круг. Объятый / Догадкой, двинется он вслед\u0026#187;)\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u003cem\u003eПредположительная отсылка\u003c/em\u003e к поэме Данте Алигьери \u0026#171;Божественная комедия\u0026#187; (\u0026#171;Рай\u0026#187;, песни I–XXX).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Подобно тому как спасённая Беатриче в \u0026#171;Раю\u0026#187; Данте становится духовной путеводительницей поэта от сферы к сфере к созерцанию Бога, прощённая Гретхен ведёт за собой душу Фауста в высшие небесные круги.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eБожественная комедия (Данте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r257\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"note\" id=\"n258\"\u003e\u003cdiv class=\"hd\"\u003e\u003cspan class=\"num\"\u003e258\u003c/span\u003e\u003cspan\u003eГорные ущелья, с. 364\u003c/span\u003e\u003c/div\u003e\u003cdiv class=\"q\"\u003e\u0026#171;Вечная женственность / Тянет нас к ней\u0026#187;\u003c/div\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eИсточник:\u003c/span\u003e \u003cem\u003eПредположительные философско-литературные истоки:\u003c/em\u003e Платон, диалог \u0026#171;Пир\u0026#187; (210a–212a — речь Диотимы о восхождении Эроса от любви к одному прекрасному телу к созерцанию вечной Красоты); Данте Алигьери, \u0026#171;Новая жизнь\u0026#187; (\u003cem\u003eVita Nuova\u003c/em\u003e, ок. 1294) и \u0026#171;Божественная комедия\u0026#187; (\u0026#171;Рай\u0026#187;, песнь XXXIII — культ Беатриче и Богоматери).\u003c/p\u003e\u003cp\u003e\u003cspan class=\"src\"\u003eОбоснование:\u003c/span\u003e Знаменитый финал \u003cem\u003eDas Ewig-Weibliche\u003c/em\u003e синтезирует платоновское учение о возвышающей силе Эроса и средневековую христианскую мистику любви и материнского милосердия как пути к спасению.\u003c/p\u003e\u003cdiv class=\"nodes\"\u003e\u003cspan class=\"chip\"\u003eПир (Платон)\u003c/span\u003e\u003cspan class=\"chip\"\u003eНовая жизнь (Данте)\u003c/span\u003e\u003cspan class=\"chip\"\u003eБожественная комедия (Данте)\u003c/span\u003e\u003c/div\u003e\u003ca class=\"back\" href=\"#r258\"\u003e↑ К тексту\u003c/a\u003e\u003c/div\u003e\n\u003c/section\u003e\u003c/main\u003e\n\u003cscript\u003e\nfunction go(id){var el=document.getElementById(id);if(!el)return;el.scrollIntoView({behavior:\u0027smooth\u0027,block:id[0]===\u0027r\u0027?\u0027center\u0027:\u0027start\u0027});el.classList.remove(\u0027flash\u0027);void el.offsetWidth;el.classList.add(\u0027flash\u0027);}\ndocument.addEventListener(\u0027click\u0027,function(e){\n  var a=e.target.closest(\u0027a.ref,a.back\u0027);if(!a)return;e.preventDefault();\n  var id=a.getAttribute(\u0027href\u0027).slice(1);\n  history.pushState({id:id},\u0027\u0027,\u0027#\u0027+id);go(id);\n});\nwindow.addEventListener(\u0027popstate\u0027,function(){var id=location.hash.slice(1);if(id)go(id);});\n\u003c/script\u003e\u003c/body\u003e\u003c/html\u003e";
